//! P17: CUDA int8 オフロード (feature = `"cuda"`)。
//!
//! CPU int8 パス ([`crate::tensor`] の `quantize_row_i8` / `matvec_rows_bt_i8`) と
//! **ビット一致**する GPU カーネル群。依存クレートは無し: CUDA Driver API は
//! `dlopen("libcuda.so.1")` で実行時解決するため、feature を外したビルド
//! (CI 等の GPU 無し環境) には一切影響しない。
//!
//! # exactness の設計
//!
//! - アクティベーションの per-token 動的量子化 (maxabs → scale → round → clamp) は
//!   GPU カーネル内で CPU と同一の演算列で実行 (`roundf` = `f32::round`、
//!   max は丸めを伴わないので走査順序に依存しない)。
//! - i8×i8 → i32 累積は整数なので結合則が成立し、warp リダクションの順序に依存
//!   しない = CPU の SIMD カーネル (AVX2/sdot) とビット一致。
//! - スケール乗算は `(float)dot * ascale[i] * scale[j]` を左から順に (CPU と同じ
//!   結合順)。FMA 縮約はカーネルに加算が無いため構造的に発生しない。
//!
//! # 使用方法
//!
//! ```ignore
//! let ctx = CudaCtx::new()?;
//! let w = ctx.upload_i8(&q.w)?;
//! let scale = ctx.upload_f32(&q.scale)?;
//! let out = ctx.linear_bt_i8(&a, &w, &scale, m, k, n)?; // CPU とビット一致
//! ```
//!
//! PTX (`kernels/kernels_int8.ptx`) は compute_75 向けに nvcc で生成したものを
//! コミットしており、ドライバ JIT が以降の全アーキテクチャ (sm_120 を含む) で
//! 実行する。再生成:
//!
//! ```text
//! nvcc -ptx -arch=compute_75 -fmad=false -O3 kernels_int8.cu -o kernels_int8.ptx
//! ```

#![allow(non_snake_case, non_camel_case_types)]

use anyhow::{anyhow, bail, Result};
use std::ffi::c_void;
use std::os::raw::{c_char, c_int};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Mutex, OnceLock};
use std::time::Instant;

type CUresult = i32;
type CUdevice = c_int;
type CUcontext = *mut c_void;
type CUmodule = *mut c_void;
type CUfunction = *mut c_void;
type CUdeviceptr = u64;

const RTLD_NOW: c_int = 2;
const CUDA_SUCCESS: CUresult = 0;

// dlopen/dlsym (glibc 2.34 以降は libc に統合、Ubuntu 22.04 コンテナで使用)
extern "C" {
    fn dlopen(filename: *const c_char, flag: c_int) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const c_char) -> *mut c_void;
}

type FnCuInit = unsafe extern "C" fn(u32) -> CUresult;
type FnCuDeviceGet = unsafe extern "C" fn(*mut CUdevice, c_int) -> CUresult;
type FnCuDeviceGetName = unsafe extern "C" fn(*mut c_char, c_int, CUdevice) -> CUresult;
type FnCuDeviceComputeCapability =
    unsafe extern "C" fn(*mut c_int, *mut c_int, CUdevice) -> CUresult;
type FnCuDevicePrimaryCtxRetain = unsafe extern "C" fn(*mut CUcontext, CUdevice) -> CUresult;
type FnCuCtxSetCurrent = unsafe extern "C" fn(CUcontext) -> CUresult;
type FnCuCtxSynchronize = unsafe extern "C" fn() -> CUresult;
type FnCuDriverGetVersion = unsafe extern "C" fn(*mut c_int) -> CUresult;
type FnCuModuleLoadData = unsafe extern "C" fn(*mut CUmodule, *const c_void) -> CUresult;
type FnCuModuleGetFunction =
    unsafe extern "C" fn(*mut CUfunction, CUmodule, *const c_char) -> CUresult;
type FnCuMemAllocV2 = unsafe extern "C" fn(*mut CUdeviceptr, usize) -> CUresult;
type FnCuMemFreeV2 = unsafe extern "C" fn(CUdeviceptr) -> CUresult;
type FnCuMemsetD32Async = unsafe extern "C" fn(CUdeviceptr, u32, usize, CUstream) -> CUresult;
type FnCuMemGetInfo = unsafe extern "C" fn(*mut usize, *mut usize) -> CUresult;
type FnCuMemcpyHtoDV2 = unsafe extern "C" fn(CUdeviceptr, *const c_void, usize) -> CUresult;
type FnCuMemcpyDtoHV2 = unsafe extern "C" fn(*mut c_void, CUdeviceptr, usize) -> CUresult;
type FnCuMemHostAlloc = unsafe extern "C" fn(*mut *mut c_void, usize, u32) -> CUresult;
type FnCuMemFreeHost = unsafe extern "C" fn(*mut c_void) -> CUresult;
type FnCuMemcpyHtoDAsyncV2 =
    unsafe extern "C" fn(CUdeviceptr, *const c_void, usize, CUstream) -> CUresult;
type FnCuMemcpyDtoHAsyncV2 =
    unsafe extern "C" fn(*mut c_void, CUdeviceptr, usize, CUstream) -> CUresult;
type FnCuMemcpyDtoDAsyncV2 =
    unsafe extern "C" fn(CUdeviceptr, CUdeviceptr, usize, CUstream) -> CUresult;
type FnCuMemcpyDtoD = unsafe extern "C" fn(CUdeviceptr, CUdeviceptr, usize) -> CUresult;
type FnCuDeviceGetAttribute = unsafe extern "C" fn(*mut c_int, c_int, CUdevice) -> CUresult;
type FnCuFuncSetAttribute = unsafe extern "C" fn(CUfunction, c_int, c_int) -> CUresult;
// s167 (P6): h2 の D2H を専用コピーストリームへ載せるための driver API。
// すべて Option で持つ — 古い driver で dlsym に失敗しても全体を落とさず、
// 呼び出し側が従来の同期 D2H へフォールバックする (fail closed)。
type FnCuStreamCreate = unsafe extern "C" fn(*mut CUstream, u32) -> CUresult;
type FnCuStreamDestroy = unsafe extern "C" fn(CUstream) -> CUresult;
type FnCuStreamWaitEvent = unsafe extern "C" fn(CUstream, CUevent, u32) -> CUresult;
type FnCuEventCreate = unsafe extern "C" fn(*mut CUevent, u32) -> CUresult;
type FnCuEventDestroy = unsafe extern "C" fn(CUevent) -> CUresult;
type FnCuEventRecord = unsafe extern "C" fn(CUevent, CUstream) -> CUresult;
type FnCuEventSynchronize = unsafe extern "C" fn(CUevent) -> CUresult;
// s169 (P8): prefill 位相計測 — ストリーム上の 2 点間の経過 (ms) を読む。
type FnCuEventElapsedTime = unsafe extern "C" fn(*mut f32, CUevent, CUevent) -> CUresult;
type FnCuLaunchKernel = unsafe extern "C" fn(
    CUfunction,
    u32,
    u32,
    u32,
    u32,
    u32,
    u32,
    u32,
    CUstream,
    *mut *mut c_void,
    *mut *mut c_void,
) -> CUresult;
type CUstream = *mut c_void;
type CUevent = *mut c_void;

/// Driver API の関数ポインタ群 (dlsym は1度だけ行う)
struct CudaLib {
    cu_init: FnCuInit,
    device_get: FnCuDeviceGet,
    device_name: FnCuDeviceGetName,
    device_cc: FnCuDeviceComputeCapability,
    primary_ctx_retain: FnCuDevicePrimaryCtxRetain,
    ctx_set_current: FnCuCtxSetCurrent,
    ctx_sync: FnCuCtxSynchronize,
    driver_version: FnCuDriverGetVersion,
    module_load_data: FnCuModuleLoadData,
    module_get_function: FnCuModuleGetFunction,
    mem_alloc: FnCuMemAllocV2,
    mem_free: FnCuMemFreeV2,
    mem_get_info: Option<FnCuMemGetInfo>,
    memcpy_htod: FnCuMemcpyHtoDV2,
    memcpy_dtoh: FnCuMemcpyDtoHV2,
    memset_d32_async: FnCuMemsetD32Async,
    mem_host_alloc: FnCuMemHostAlloc,
    mem_host_free: FnCuMemFreeHost,
    memcpy_htod_async: FnCuMemcpyHtoDAsyncV2,
    memcpy_dtoh_async: FnCuMemcpyDtoHAsyncV2,
    memcpy_dtod_async: FnCuMemcpyDtoDAsyncV2,
    // s141b (Task B7c): 同期 D2D (GDN 状態の正本 -> ミラー seed 用)。
    memcpy_dtod: FnCuMemcpyDtoD,
    // s48 (C1-a): 動的 smem の opt-in (cuFuncSetAttribute)。CUDA 9.0 以降に存在
    // するが、dlsym 失敗でも全体を落とさないよう Option (無ければ 48KB 既定のまま)。
    device_get_attribute: Option<FnCuDeviceGetAttribute>,
    func_set_attribute: Option<FnCuFuncSetAttribute>,
    // s167 (P6): 専用コピーストリーム (h2 の D2H を qkv/z GEMM と重ねる)。
    stream_create: Option<FnCuStreamCreate>,
    stream_destroy: Option<FnCuStreamDestroy>,
    stream_wait_event: Option<FnCuStreamWaitEvent>,
    event_create: Option<FnCuEventCreate>,
    event_destroy: Option<FnCuEventDestroy>,
    event_record: Option<FnCuEventRecord>,
    event_sync: Option<FnCuEventSynchronize>,
    // s169 (P8): 位相計測 (cuEventElapsedTime)。無ければ計測は静かに OFF。
    event_elapsed_time: Option<FnCuEventElapsedTime>,
    launch: FnCuLaunchKernel,
}

unsafe fn sym(handle: *mut c_void, name: &'static str) -> Result<*mut c_void> {
    let cname = std::ffi::CString::new(name).unwrap();
    let p = dlsym(handle, cname.as_ptr());
    if p.is_null() {
        bail!("dlsym({name}) が失敗 — driver が古い/不完全の可能性");
    }
    Ok(p)
}

/// dlsym だが失敗を許容する (オプションシンボル用)。
unsafe fn sym_opt(handle: *mut c_void, name: &'static str) -> Option<*mut c_void> {
    let cname = std::ffi::CString::new(name).unwrap();
    let p = dlsym(handle, cname.as_ptr());
    if p.is_null() {
        None
    } else {
        Some(p)
    }
}

// task 138: H2D / D2H の全呼び出しを台帳 (`DENNO_Q4_PROFILE`) へ数える trampoline。
//
// コピーは cuda.rs の数十箇所から素の関数ポインタで呼ばれているので、呼び出し側を
// 触らずに**全部**を数えるため、`CudaLib` に入れるポインタ自体を差し替える。
// 実関数はここに 1 度だけ保存し、trampoline が転送バイト数と所要時間を積む。
// 台帳 off では `stamp()` が `None` を返すだけで、転送そのものは従来と同一。
static REAL_HTOD: std::sync::atomic::AtomicPtr<c_void> =
    std::sync::atomic::AtomicPtr::new(std::ptr::null_mut());
static REAL_DTOH: std::sync::atomic::AtomicPtr<c_void> =
    std::sync::atomic::AtomicPtr::new(std::ptr::null_mut());
static REAL_HTOD_ASYNC: std::sync::atomic::AtomicPtr<c_void> =
    std::sync::atomic::AtomicPtr::new(std::ptr::null_mut());
static REAL_DTOH_ASYNC: std::sync::atomic::AtomicPtr<c_void> =
    std::sync::atomic::AtomicPtr::new(std::ptr::null_mut());

unsafe extern "C" fn ledger_htod(d: CUdeviceptr, s: *const c_void, n: usize) -> CUresult {
    let t = crate::model::q4ledger::stamp();
    let f: FnCuMemcpyHtoDV2 = std::mem::transmute(REAL_HTOD.load(Ordering::Relaxed));
    let r = f(d, s, n);
    crate::model::q4ledger::note_h2d(n, t);
    r
}

unsafe extern "C" fn ledger_dtoh(d: *mut c_void, s: CUdeviceptr, n: usize) -> CUresult {
    let t = crate::model::q4ledger::stamp();
    let f: FnCuMemcpyDtoHV2 = std::mem::transmute(REAL_DTOH.load(Ordering::Relaxed));
    let r = f(d, s, n);
    crate::model::q4ledger::note_d2h(n, t);
    r
}

unsafe extern "C" fn ledger_htod_async(
    d: CUdeviceptr,
    s: *const c_void,
    n: usize,
    st: CUstream,
) -> CUresult {
    let t = crate::model::q4ledger::stamp();
    let f: FnCuMemcpyHtoDAsyncV2 = std::mem::transmute(REAL_HTOD_ASYNC.load(Ordering::Relaxed));
    let r = f(d, s, n, st);
    crate::model::q4ledger::note_h2d(n, t);
    r
}

unsafe extern "C" fn ledger_dtoh_async(
    d: *mut c_void,
    s: CUdeviceptr,
    n: usize,
    st: CUstream,
) -> CUresult {
    let t = crate::model::q4ledger::stamp();
    let f: FnCuMemcpyDtoHAsyncV2 = std::mem::transmute(REAL_DTOH_ASYNC.load(Ordering::Relaxed));
    let r = f(d, s, n, st);
    crate::model::q4ledger::note_d2h(n, t);
    r
}

// ---------------- task 153: decode のイベント時系列 (DENNO_Q4_TLINE) ----------------
//
// `DENNO_Q4_PROFILE` の台帳は「ホストがどこで待ったか」しか見ていない。ここでは
// **ストリームに計時イベントを打って**、区間ごとの GPU 実行時間 (busy) と、GPU が
// ホスト待ちで空いていた時間 (idle) を分けて読む。
//
// - 区間 (`q4ledger::enter`) の入口と出口で 1 本ずつイベントを打ち、その 2 本の
//   `cuEventElapsedTime` を「GPU の span」として積む。
// - `DENNO_Q4_TLINE_K=1` のときは**起動ごと**にも前後 1 本ずつ打ち、その差を
//   カーネルの実行時間として積む (span - busy = その区間の GPU idle)。
// - イベントはプールして伸ばすだけ (grow-only)。読むのはリクエスト終端の 1 回だけ。
//   ホットパスに足すのは `cuEventRecord` の呼び出しだけで、同期は 1 本も足さない。
// - 記録は decode の窓 (`q4ledger::tline_begin` .. `tline_end`) だけ。上限
//   (`MAX_EVENTS`) を超えたら静かに止める (台帳の数字はそのまま残る)。
pub(crate) mod tline {
    use super::*;
    use std::cell::RefCell;

    /// プールの上限 (128 トークンの窓 x 約 3,000 本 = 約 38 万本を収める)。
    ///
    /// task 155: 400_000 だと診断行を足したときに窓の途中で尽きて以後の記録が
    /// 止まる (t155b で発生)。60 万本まで許す。
    const MAX_EVENTS: usize = 600_000;

    struct Pool {
        /// 計時イベント (grow-only)。
        evs: Vec<CUevent>,
        /// この窓で使ったイベント数 (= 次の記録位置)。
        used: usize,
        /// 区間: (item, 入口イベント, 出口イベント)。
        spans: Vec<(u8, u32, u32)>,
        /// 起動: (item, 前イベント, 後イベント)。K ゲートのときだけ積む。
        launch: Vec<(u8, u32, u32)>,
        /// 作れなかった (以後は静かに止める)。
        dead: bool,
    }

    impl Pool {
        const fn new() -> Self {
            Self {
                evs: Vec::new(),
                used: 0,
                spans: Vec::new(),
                launch: Vec::new(),
                dead: false,
            }
        }
    }

    thread_local! {
        static P: RefCell<Pool> = const { RefCell::new(Pool::new()) };
    }

    /// 区間ごとの GPU 時間 (ms)。`span` は入口から出口までの GPU 時間
    /// (ホスト待ちで GPU が空いていた分を含む)、`busy` は起動ごとの実行時間の和。
    #[derive(Clone, Copy, Default, Debug)]
    pub struct Item {
        pub span_ms: f64,
        pub busy_ms: f64,
        pub spans: u64,
        pub launches: u64,
    }

    /// 起動ごとのイベントを打つか (`DENNO_Q4_TLINE_K=1`)。
    pub(super) fn k_on() -> bool {
        static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
        *ON.get_or_init(|| std::env::var_os("DENNO_Q4_TLINE_K").is_some())
    }

    fn grow(p: &mut Pool, want: usize) -> bool {
        let Some(create) = lib().ok().and_then(|l| l.event_create) else {
            return false;
        };
        while p.evs.len() < want {
            let mut ev: CUevent = std::ptr::null_mut();
            // CU_EVENT_DEFAULT (0) = 計時有効。作れなければ計測を諦める。
            if unsafe { create(&mut ev, 0) } != CUDA_SUCCESS || ev.is_null() {
                return false;
            }
            p.evs.push(ev);
        }
        true
    }

    /// 既定ストリームにイベントを 1 本打ち、その通し番号を返す。
    fn mark() -> Option<u32> {
        P.with(|c| {
            let mut p = c.borrow_mut();
            if p.dead {
                return None;
            }
            if p.used >= MAX_EVENTS {
                p.dead = true;
                return None;
            }
            if p.used >= p.evs.len() {
                let want = p.evs.len() + 2048;
                if !grow(&mut p, want) {
                    p.dead = true;
                    return None;
                }
            }
            let Some(rec) = lib().ok().and_then(|l| l.event_record) else {
                p.dead = true;
                return None;
            };
            let ev = p.evs[p.used];
            if unsafe { rec(ev, std::ptr::null_mut()) } != CUDA_SUCCESS {
                p.dead = true;
                return None;
            }
            let i = p.used as u32;
            p.used += 1;
            Some(i)
        })
    }

    /// 区間の入口イベント。時系列が off なら `None` (分岐 1 回)。
    pub fn span_begin() -> Option<u32> {
        if !crate::model::q4ledger::tline_active() {
            return None;
        }
        mark()
    }

    /// 窓の入口で 1 回だけ呼ぶ。イベントは**このスレッドの** current context に
    /// 対して打つので、リクエストのスレッドで context を張っておく
    /// (engine の GPU 入口は毎回 `make_current` するが、最初の `enter` はその前)。
    pub fn prepare() {
        if !crate::model::q4ledger::tline_active() {
            return;
        }
        if let Some(ctx) = shared_ctx() {
            let _ = ctx.make_current();
        }
        // 1 本だけ打って捨てる (作れない構成なら以後の記録を止める)。
        let _ = mark();
        reset();
    }

    /// 区間の出口イベントを打って span を積む。
    pub fn span_end(item: usize, a: u32) {
        if let Some(b) = mark() {
            P.with(|c| c.borrow_mut().spans.push((item as u8, a, b)));
        }
    }

    /// 起動の直前イベント (K ゲートのときだけ)。
    pub fn launch_begin() -> Option<u32> {
        if !crate::model::q4ledger::tline_active() || !k_on() {
            return None;
        }
        mark()
    }

    /// 起動の直後イベントを打って (item, 前, 後) を積む。
    pub fn launch_end(item: usize, a: u32) {
        if let Some(b) = mark() {
            P.with(|c| c.borrow_mut().launch.push((item as u8, a, b)));
        }
    }

    fn elapsed(a: u32, b: u32) -> Option<f32> {
        let f = lib().ok().and_then(|l| l.event_elapsed_time)?;
        P.with(|c| {
            let p = c.borrow();
            let ea = *p.evs.get(a as usize)?;
            let eb = *p.evs.get(b as usize)?;
            let mut ms = 0.0f32;
            if unsafe { f(&mut ms, ea, eb) } != CUDA_SUCCESS || !ms.is_finite() || ms < 0.0 {
                return None;
            }
            Some(ms)
        })
    }

    /// 区間ごとの GPU 時間を読む (区間の数だけ返す)。1 本も打っていなければ `None`。
    pub fn items(n: usize) -> Option<Vec<Item>> {
        P.with(|c| {
            let p = c.borrow();
            if p.spans.is_empty() && p.launch.is_empty() {
                return None;
            }
            let mut out = vec![Item::default(); n];
            for &(item, a, b) in p.spans.iter() {
                let i = (item as usize).min(n.saturating_sub(1));
                if let Some(ms) = elapsed(a, b) {
                    out[i].span_ms += ms as f64;
                    out[i].spans += 1;
                }
            }
            for &(item, a, b) in p.launch.iter() {
                let i = (item as usize).min(n.saturating_sub(1));
                if let Some(ms) = elapsed(a, b) {
                    out[i].busy_ms += ms as f64;
                    out[i].launches += 1;
                }
            }
            Some(out)
        })
    }

    /// 窓の記録を捨てる (イベント自体は次の窓で使い回す)。
    pub fn reset() {
        P.with(|c| {
            let mut p = c.borrow_mut();
            p.used = 0;
            p.spans.clear();
            p.launch.clear();
        });
    }
}

unsafe fn open_libcuda() -> Result<CudaLib> {
    let name = b"libcuda.so.1\0";
    let handle = dlopen(name.as_ptr() as *const c_char, RTLD_NOW);
    if handle.is_null() {
        bail!("libcuda.so.1 を dlopen できません (NVIDIA driver が無い/見えない)");
    }
    Ok(CudaLib {
        cu_init: std::mem::transmute(sym(handle, "cuInit")?),
        device_get: std::mem::transmute(sym(handle, "cuDeviceGet")?),
        device_name: std::mem::transmute(sym(handle, "cuDeviceGetName")?),
        device_cc: std::mem::transmute(sym(handle, "cuDeviceComputeCapability")?),
        primary_ctx_retain: std::mem::transmute(sym(handle, "cuDevicePrimaryCtxRetain")?),
        ctx_set_current: std::mem::transmute(sym(handle, "cuCtxSetCurrent")?),
        ctx_sync: std::mem::transmute(sym(handle, "cuCtxSynchronize")?),
        driver_version: std::mem::transmute(sym(handle, "cuDriverGetVersion")?),
        module_load_data: std::mem::transmute(sym(handle, "cuModuleLoadData")?),
        module_get_function: std::mem::transmute(sym(handle, "cuModuleGetFunction")?),
        mem_alloc: std::mem::transmute(sym(handle, "cuMemAlloc_v2")?),
        mem_free: std::mem::transmute(sym(handle, "cuMemFree_v2")?),
        mem_get_info: sym_opt(handle, "cuMemGetInfo_v2")
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuMemGetInfo>(p) }),
        memcpy_htod: {
            let p: FnCuMemcpyHtoDV2 = std::mem::transmute(sym(handle, "cuMemcpyHtoD_v2")?);
            REAL_HTOD.store(p as *mut c_void, Ordering::Relaxed);
            ledger_htod
        },
        memcpy_dtoh: {
            let p: FnCuMemcpyDtoHV2 = std::mem::transmute(sym(handle, "cuMemcpyDtoH_v2")?);
            REAL_DTOH.store(p as *mut c_void, Ordering::Relaxed);
            ledger_dtoh
        },
        memset_d32_async: std::mem::transmute(sym(handle, "cuMemsetD32Async")?),
        mem_host_alloc: std::mem::transmute(sym(handle, "cuMemHostAlloc")?),
        mem_host_free: std::mem::transmute(sym(handle, "cuMemFreeHost")?),
        memcpy_htod_async: {
            let p: FnCuMemcpyHtoDAsyncV2 =
                std::mem::transmute(sym(handle, "cuMemcpyHtoDAsync_v2")?);
            REAL_HTOD_ASYNC.store(p as *mut c_void, Ordering::Relaxed);
            ledger_htod_async
        },
        memcpy_dtoh_async: {
            let p: FnCuMemcpyDtoHAsyncV2 =
                std::mem::transmute(sym(handle, "cuMemcpyDtoHAsync_v2")?);
            REAL_DTOH_ASYNC.store(p as *mut c_void, Ordering::Relaxed);
            ledger_dtoh_async
        },
        memcpy_dtod_async: std::mem::transmute(sym(handle, "cuMemcpyDtoDAsync_v2")?),
        memcpy_dtod: std::mem::transmute(sym(handle, "cuMemcpyDtoD_v2")?),
        device_get_attribute: sym_opt(handle, "cuDeviceGetAttribute")
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuDeviceGetAttribute>(p) }),
        func_set_attribute: sym_opt(handle, "cuFuncSetAttribute")
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuFuncSetAttribute>(p) }),
        stream_create: sym_opt(handle, "cuStreamCreate")
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuStreamCreate>(p) }),
        // driver は v2 名で公開する (CUDA 3.2 以降)。無ければ無印を試す。
        stream_destroy: sym_opt(handle, "cuStreamDestroy_v2")
            .or_else(|| sym_opt(handle, "cuStreamDestroy"))
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuStreamDestroy>(p) }),
        stream_wait_event: sym_opt(handle, "cuStreamWaitEvent")
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuStreamWaitEvent>(p) }),
        event_create: sym_opt(handle, "cuEventCreate")
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuEventCreate>(p) }),
        event_destroy: sym_opt(handle, "cuEventDestroy_v2")
            .or_else(|| sym_opt(handle, "cuEventDestroy"))
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuEventDestroy>(p) }),
        event_record: sym_opt(handle, "cuEventRecord")
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuEventRecord>(p) }),
        event_sync: sym_opt(handle, "cuEventSynchronize")
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuEventSynchronize>(p) }),
        // s169 (P8): 位相計測用 (無い driver では計測だけが OFF になる)。
        event_elapsed_time: sym_opt(handle, "cuEventElapsedTime")
            .map(|p| unsafe { std::mem::transmute::<*mut c_void, FnCuEventElapsedTime>(p) }),
        launch: std::mem::transmute(sym(handle, "cuLaunchKernel")?),
    })
}

static LIB: OnceLock<CudaLib> = OnceLock::new();

fn lib() -> Result<&'static CudaLib> {
    if let Some(l) = LIB.get() {
        return Ok(l);
    }
    let l = unsafe { open_libcuda()? };
    let _ = LIB.set(l);
    Ok(LIB.get().expect("just set"))
}

/// デバイスの (空き, 総) を MiB で返す。`cuMemGetInfo_v2` が無ければ None。
/// s124 の診断用 (VRAM が戻らない件の切り分け)。
pub fn dev_mem_mb() -> Option<(usize, usize)> {
    let f = lib().ok()?.mem_get_info?;
    let (mut free, mut total) = (0usize, 0usize);
    if unsafe { f(&mut free, &mut total) } != CUDA_SUCCESS {
        return None;
    }
    Some((free >> 20, total >> 20))
}

// ---------------------------------------------------------------------------
// task 152: cuMemGetInfo のキャッシュ
// ---------------------------------------------------------------------------
// task 149 のカード予算 (`DENNO_VRAM_BUDGET_CARD`) は expert を 1 本載せるたびに
// cuMemGetInfo を呼んでいた。lab t149c では 28 token の prefill が +3.3% 悪化して
// おり、その主因と推定された (REPORT_P149.md)。ドライバによっては 1 回が
// 数十〜数百 us かかるので、**64 MiB ぶんの増減か 2 秒経過まで**は同じ値を返す。
//
// 予算は「余裕 (既定 1,024 MiB)」を残して切るので、最大 64 MiB の古さは
// 判定を変えない。確保に失敗したときは従来どおり追い出して再試行する
// (br149 の経路) ので、古い値で足りなくてもラッチしない。

/// キャッシュを捨てる「台帳の増減」の閾値 (MiB)。
pub const MEM_CACHE_DRIFT_MB: usize = 64;
/// キャッシュの最大 age (ミリ秒)。
pub const MEM_CACHE_MAX_MS: u128 = 2000;

struct MemCache {
    free_mb: usize,
    total_mb: usize,
    live_at: usize,
    at: std::time::Instant,
}

static MEM_CACHE: Mutex<Option<MemCache>> = Mutex::new(None);

/// キャッシュを捨てて次の [`dev_mem_mb_cached`] で引き直させる。
pub fn dev_mem_refresh() {
    if let Ok(mut g) = MEM_CACHE.lock() {
        *g = None;
    }
}

/// キャッシュを引き直すかの判定 (純関数)。
///
/// `live_delta` は前回の取得から動いた台帳の合計バイト (絶対値)、`age_ms` は
/// 前回の取得からの経過ミリ秒。どちらかが閾値を超えたら引き直す。
pub fn mem_cache_should_refresh(live_delta: usize, age_ms: u128) -> bool {
    live_delta >= MEM_CACHE_DRIFT_MB << 20 || age_ms >= MEM_CACHE_MAX_MS
}

/// [`dev_mem_mb`] のキャッシュ版 (task 152)。
///
/// 引き直すのは次のいずれか:
/// - まだ 1 度も引いていない / [`dev_mem_refresh`] の後
/// - 前回の取得から台帳の合計が [`MEM_CACHE_DRIFT_MB`] 以上動いた
/// - 前回の取得から [`MEM_CACHE_MAX_MS`] 以上経った
///
/// 引けなかったときは古い値ではなく `None` を返す (未取得のままなら `None`)。
pub fn dev_mem_mb_cached() -> Option<(usize, usize)> {
    let live = crate::mem_audit::live_bytes();
    let mut g = match MEM_CACHE.lock() {
        Ok(g) => g,
        Err(_) => return dev_mem_mb(),
    };
    let refresh = match g.as_ref() {
        None => true,
        Some(c) => mem_cache_should_refresh(
            live.abs_diff(c.live_at),
            c.at.elapsed().as_millis(),
        ),
    };
    if refresh {
        match dev_mem_mb() {
            Some((free, total)) => {
                *g = Some(MemCache {
                    free_mb: free,
                    total_mb: total,
                    live_at: live,
                    at: std::time::Instant::now(),
                });
            }
            None => {
                if g.is_none() {
                    return None;
                }
            }
        }
    }
    g.as_ref().map(|c| (c.free_mb, c.total_mb))
}

/// `DENNO_MEM_DBG=1` のときだけ確保/解放をログる (既定は完全に無効)。
fn mem_dbg() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| matches!(std::env::var("DENNO_MEM_DBG").as_deref(), Ok("1")))
}

/// `DENNO_MEM_BT=1` のときだけ、確保の呼び出し元を 1 行に畳んで返す。
fn mem_bt() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| matches!(std::env::var("DENNO_MEM_BT").as_deref(), Ok("1")))
}

fn bt_hint() -> String {
    let bt = std::backtrace::Backtrace::force_capture().to_string();
    let mut v: Vec<String> = Vec::new();
    for ln in bt.lines() {
        let ln = ln.trim();
        if ln.is_empty() || ln.starts_with("at ") || ln.starts_with("Backtrace") {
            continue;
        }
        // "3: denno_engine::cuda::foo" 形式のフレーム行だけ拾う
        let name = match ln.split_once(": ") {
            Some((_, r)) => r,
            None => continue,
        };
        if !name.starts_with("denno") && !name.contains("denno_engine") {
            continue;
        }
        v.push(name.to_string());
        if v.len() == 6 {
            break;
        }
    }
    v.join(" < ")
}

fn check(res: CUresult, what: &str) -> Result<()> {
    if res != CUDA_SUCCESS {
        bail!("CUDA {what} が失敗: error {res}");
    }
    Ok(())
}

/// デバイスメモリバッファ (RAII: drop で cuMemFree)
pub struct DevBuffer {
    ptr: CUdeviceptr,
    bytes: usize,
    /// s165: false = 他のバッファの一部を指す**非所有**ビュー。drop で解放しない
    /// (所有者は元のバッファ)。重みレジストリの行範囲エイリアス専用。
    owned: bool,
    /// task 149: 台帳のタグ ([`crate::mem_audit`])。解放時に同じタグで戻す。
    tag: &'static str,
}

impl DevBuffer {
    /// task 149: タグ付きの確保。確保に失敗したら expert の LRU を 1 回追い出して
    /// 再試行する (「確保失敗で expert を CPU に固定する」経路を通常経路にしない)。
    ///
    /// ここで `DevBuffer` を一度作ってから詰め替えないこと — `Drop` が
    /// `cuMemFree` を呼ぶので、確保した領域がその場で解放されてしまう
    /// (lab t149a で実際に踏んだ)。`raw_alloc` は生のポインタだけを返す。
    #[track_caller]
    fn alloc_tagged(bytes: usize, tag: &'static str) -> Result<Self> {
        match Self::raw_alloc(bytes) {
            Ok(ptr) => {
                crate::mem_audit::note_alloc(tag, bytes.max(1));
                Ok(Self {
                    ptr,
                    bytes,
                    owned: true,
                    tag,
                })
            }
            Err(e) => {
                // task 149: 他の常駐 (attention のミラー・重み・prefill の
                // 一時バッファ) が原因で落ちたときは、expert を追い出して
                // やり直す。1 回目は要求 + 64 MiB、2 回目は全部追い出す
                // (driver の内部確保ぶんの余裕を残す)。
                let mut last = e;
                for margin in [64usize << 20, usize::MAX] {
                    let want = if margin == usize::MAX {
                        usize::MAX
                    } else {
                        bytes.saturating_add(margin)
                    };
                    let freed = crate::model::expert_vram::emergency_free(want);
                    if freed == 0 {
                        break;
                    }
                    tracing::warn!(
                        "task149: 確保失敗 → expert を {} MiB 追い出して再試行 ({last:#})",
                        freed >> 20
                    );
                    match Self::raw_alloc(bytes) {
                        Ok(ptr) => {
                            crate::mem_audit::note_alloc(tag, bytes.max(1));
                            return Ok(Self {
                                ptr,
                                bytes,
                                owned: true,
                                tag,
                            });
                        }
                        Err(e2) => last = e2,
                    }
                }
                Err(last)
            }
        }
    }

    /// `cuMemAlloc` を 1 回だけ呼ぶ (返すのは生のポインタ。`Drop` を通さない)。
    #[track_caller]
    fn raw_alloc(bytes: usize) -> Result<CUdeviceptr> {
        let mut ptr: CUdeviceptr = 0;
        let res = unsafe { (lib()?.mem_alloc)(&mut ptr, bytes) };
        if res != CUDA_SUCCESS {
            // どの要求が載らなかったかを後から追えるように空き容量を添える。
            match dev_mem_mb() {
                Some((f, t)) => bail!(
                    "CUDA cuMemAlloc が失敗: error {res} (要求 {} MiB / 空き {} MiB / 総 {} MiB)",
                    bytes >> 20,
                    f,
                    t
                ),
                None => bail!("CUDA cuMemAlloc が失敗: error {res} (要求 {} MiB)", bytes >> 20),
            }
        }
        if mem_dbg() {
            if let Some((f, t)) = dev_mem_mb() {
                if bytes >= (1 << 20) && mem_bt() {
                    tracing::info!(target: "denno_engine::mem", "alloc {} KiB free={} MiB total={} MiB at={} bt={}", bytes >> 10, f, t, std::panic::Location::caller(), bt_hint());
                } else {
                    tracing::info!(target: "denno_engine::mem", "alloc {} KiB free={} MiB total={} MiB at={}", bytes >> 10, f, t, std::panic::Location::caller());
                }
            }
        }
        Ok(ptr)
    }

    #[track_caller]
    fn alloc(bytes: usize) -> Result<Self> {
        Self::alloc_tagged(bytes, crate::mem_audit::TAG_OTHER)
    }

    /// task 152: slab のチャンクを 1 本確保する (台帳のタグは expert 側)。
    #[track_caller]
    pub(crate) fn slab_chunk(bytes: usize) -> Result<Self> {
        Self::alloc_tagged(bytes.max(1), crate::mem_audit::TAG_EXPERTS)
    }

    /// task 152: このバッファの一部を指す**非所有**ビュー (drop で解放しない)。
    pub(crate) fn view_at(&self, offset: usize, bytes: usize) -> Self {
        assert!(
            offset.saturating_add(bytes) <= self.bytes,
            "DevBuffer::view_at: 範囲外 (offset={offset}, bytes={bytes}, len={})",
            self.bytes
        );
        Self::view(self.ptr + offset as CUdeviceptr, bytes)
    }

    /// task 152: 同じ領域を指す非所有ビューを作り直す (所有側は drop しない)。
    pub(crate) fn alias(&self) -> Self {
        Self::view(self.ptr, self.bytes)
    }

    /// task 152: `offset` の位置へ pinned staging 経由で H2D する。
    ///
    /// [`from_slice_pinned`] と同じ経路 (ホスト 1 回コピー + `cuMemcpyHtoD`) なので、
    /// slab のスロットへ上げる転送速度は per-expert 確保のときと変わらない。
    pub(crate) fn upload_pinned_at(&self, offset: usize, data: &[u8]) -> Result<()> {
        let bytes = data.len();
        if bytes == 0 {
            return Ok(());
        }
        assert!(
            offset.saturating_add(bytes) <= self.bytes,
            "DevBuffer::upload_pinned_at: 範囲外 (offset={offset}, bytes={bytes}, len={})",
            self.bytes
        );
        EXPERT_PIN.with(|cell| -> Result<()> {
            let mut slot = cell.borrow_mut();
            if slot.as_ref().map(|p| p.bytes).unwrap_or(0) < bytes {
                *slot = Some(PinMem::alloc(bytes)?);
            }
            let pin = slot.as_ref().expect("確保済み");
            unsafe {
                std::ptr::copy_nonoverlapping(
                    data.as_ptr(),
                    pin.ptr as *mut u8,
                    bytes,
                );
                check(
                    (lib()?.memcpy_htod)(
                        self.ptr + offset as CUdeviceptr,
                        pin.ptr,
                        bytes,
                    ),
                    "cuMemcpyHtoD (pinned slab)",
                )?;
            }
            dbg_htod(bytes);
            Ok(())
        })
    }

    /// s165: 既存のデバイス領域の一部を指す**非所有**ビュー。連結重み
    /// (`gate_up_w` など) の行範囲を、元の独立した重みとして見せるために使う
    /// (同じ重みを VRAM へ 2 度上げない)。drop では解放しない。
    /// `bytes` はビュー自身の長さ (所有側の範囲内であることは呼び出し側が保証)。
    fn view(ptr: CUdeviceptr, bytes: usize) -> Self {
        Self { ptr, bytes, owned: false, tag: crate::mem_audit::TAG_OTHER }
    }

    /// ホストのスライスをデバイスへコピーして確保
    #[track_caller]
    pub fn from_slice<T: Copy>(data: &[T]) -> Result<Self> {
        Self::from_slice_tagged(data, crate::mem_audit::TAG_OTHER)
    }

    /// [`DevBuffer::from_slice`] のタグ付き版 (task 149 の台帳用)。
    #[track_caller]
    pub fn from_slice_tagged<T: Copy>(data: &[T], tag: &'static str) -> Result<Self> {
        let bytes = std::mem::size_of_val(data);
        let buf = Self::alloc_tagged(bytes.max(1), tag)?;
        if bytes > 0 {
            unsafe {
                check(
                    (lib()?.memcpy_htod)(buf.ptr, data.as_ptr() as *const c_void, bytes),
                    "cuMemcpyHtoD",
                )?;
            }
            // s166 (P5): 観測のみ (初回アップロード = 定常ステップでは 0 回)
            dbg_htod(bytes);
        }
        Ok(buf)
    }

    /// デバイス → ホスト (len 個の T として読む)
    /// デバイス側だけで 0 にする (f32 の 0.0 はビット 0 なのでゼロ埋めと同じ)。
    /// ホスト Vec を作らないため、小さなバッファを毎回 H2D する経路の負担が消える。
    pub fn fill_zero(&self) -> Result<()> {
        let words = self.bytes / 4;
        if words == 0 {
            return Ok(());
        }
        let rc = unsafe { (lib()?.memset_d32_async)(self.ptr, 0, words, std::ptr::null_mut()) };
        if rc != 0 {
            bail!("cuMemsetD32Async failed: CUresult {}", rc);
        }
        Ok(())
    }

    pub fn to_vec<T: Copy>(&self, len: usize) -> Result<Vec<T>> {
        let bytes = len * std::mem::size_of::<T>();
        assert!(bytes <= self.bytes, "DevBuffer::to_vec: size overflow");
        if bytes == 0 {
            return Ok(Vec::new());
        }
        // s72: ゼロ埋めした Vec を作ってから上書きすると同じ領域を 2 度書く
        // (47MB で数 ms)。未初期化領域へ直接 D2H し、コピー完了後に set_len する
        // (cuMemcpyDtoH は同期コピーなので戻った時点で全要素が埋まっている)。
        let mut out: Vec<T> = Vec::with_capacity(len);
        unsafe {
            check(
                (lib()?.memcpy_dtoh)(out.as_mut_ptr() as *mut c_void, self.ptr, bytes),
                "cuMemcpyDtoH",
            )?;
            out.set_len(len);
        }
        Ok(out)
    }

    /// デバイス → ホスト (呼び出し側のバッファへ直接。毎層 5 MB を
    /// `Vec` に取り直すとページフォルトだけで数 ms かかるため)。
    pub fn to_slice<T: Copy>(&self, out: &mut [T]) -> Result<()> {
        let bytes = std::mem::size_of_val(out);
        assert!(bytes <= self.bytes, "DevBuffer::to_slice: size overflow");
        if bytes > 0 {
            unsafe {
                check(
                    (lib()?.memcpy_dtoh)(out.as_mut_ptr() as *mut c_void, self.ptr, bytes),
                    "cuMemcpyDtoH",
                )?;
            }
        }
        Ok(())
    }

    /// 既存バッファへホストから上書きコピー
    pub fn copy_from<T: Copy>(&self, data: &[T]) -> Result<()> {
        let bytes = std::mem::size_of_val(data);
        assert!(bytes <= self.bytes, "DevBuffer::copy_from: size overflow");
        if bytes > 0 {
            unsafe {
                check(
                    (lib()?.memcpy_htod)(self.ptr, data.as_ptr() as *const c_void, bytes),
                    "cuMemcpyHtoD",
                )?;
            }
        }
        Ok(())
    }

    /// 既存バッファのバイトオフセット位置へホストから上書きコピー (P17g: KV ミラー追記用)
    pub fn copy_from_at<T: Copy>(&self, offset_bytes: usize, data: &[T]) -> Result<()> {
        let bytes = std::mem::size_of_val(data);
        assert!(
            offset_bytes + bytes <= self.bytes,
            "DevBuffer::copy_from_at: size overflow"
        );
        if bytes > 0 {
            unsafe {
                check(
                    (lib()?.memcpy_htod)(
                        self.ptr + offset_bytes as CUdeviceptr,
                        data.as_ptr() as *const c_void,
                        bytes,
                    ),
                    "cuMemcpyHtoD",
                )?;
            }
        }
        Ok(())
    }

    /// s141b (Task B7c): 既存バッファへ**デバイスから**上書きコピー (D2D・同期)。
    /// `src` の先頭 `len` 要素 (f32) をこのバッファの先頭へ移す。同一 GPU 内の
    /// コピーをホスト経由 (D2H + H2D) で往復させないための経路 — 転送は値そのまま
    /// なのでビットは D2H+H2D と同一。
    pub fn copy_from_dev(&self, src: CUdeviceptr, len: usize) -> Result<()> {
        let bytes = len * std::mem::size_of::<f32>();
        assert!(bytes <= self.bytes, "DevBuffer::copy_from_dev: size overflow");
        if bytes > 0 {
            unsafe {
                check(
                    (lib()?.memcpy_dtod)(self.ptr, src, bytes),
                    "cuMemcpyDtoD",
                )?;
            }
        }
        Ok(())
    }

    pub fn bytes(&self) -> usize {
        self.bytes
    }

    /// 生デバイスポインタ (カーネル引数の組み立て用)
    pub fn ptr(&self) -> CUdeviceptr {
        self.ptr
    }
}

impl Drop for DevBuffer {
    fn drop(&mut self) {
        // s165: ビュー (owned=false) は他バッファの一部なので解放しない
        if self.owned && self.ptr != 0 {
            unsafe {
                let _ = (lib().unwrap().mem_free)(self.ptr);
            }
            // task 149: 台帳から戻す (確保と同じタグ・同じバイト数)。
            crate::mem_audit::note_free(self.tag, self.bytes.max(1));
            if mem_dbg() {
                if let Some((f, t)) = dev_mem_mb() {
                    tracing::info!(target: "denno_engine::mem", "free {} KiB free={} MiB total={} MiB", self.bytes >> 10, f, t);
                }
            }
        }
    }
}

/// decode GEMV 1 本ぶんの発行計画 (カーネル・起動形状・行バイト)。
///
/// [`CudaCtx::moe_gemv_dev_with`] から切り出した**選択だけ**の部分で、
/// デバイスメモリには触らない。task 124 の重ね打ち経路
/// ([`shared_gemv_begin`]) と同じカーネル・同じ引数を組むために共有する。
struct MoeGemvPlan {
    f: CUfunction,
    /// 1 ブロックが受け持つ行数
    rows_per_block: usize,
    block_dim: u32,
    shmem: u32,
    lanes: usize,
    /// 1 行のバイト数
    rb: usize,
    grid: u32,
}

/// CUDA コンテキスト + int8 カーネルモジュール。
/// プロセスで1個作り、複数の線形層で共有する。
pub struct CudaCtx {
    device: CUdevice,
    name: String,
    cc: (c_int, c_int),
    driver_ver: c_int,
    #[allow(dead_code)]
    ctx: CUcontext,
    module: CUmodule,
    f_quant: CUfunction,
    f_mv: CUfunction,
    // P17i: prefill 用 tiled GEMM (dno_gemm_i8)
    f_gemm: CUfunction,
    // s123: Q4_0 ネイティブ (GGUF の 4 bit ブロックを再量子化せず積む)
    f_mv_q4: CUfunction,
    f_gemm_q4: CUfunction,
    /// s132 (Task B1): 複数行を 1 block で受ける Q4 GEMV。
    /// コミット済みの `kernels_int8.ptx` に含まれる場合のみ取得でき、無ければ
    /// None で従来の `dno_gemv_q4_0` (1 行 1 block) を使う。古い PTX でも起動を
    /// 壊さないための Option (s89 の `f_gdn_chunk_scan_hoist` と同じ扱い)。
    /// s133 以降は列ブロック版 (`dno_gemv_q4_0c4` など) があると GEMV 経路は
    /// そちらへ行くので、本番経路からは呼ばれない (ビット一致の参照とテスト用)。
    f_mv_q4_mr: Option<CUfunction>,
    /// s133 (Task B1, attempt 2): A の 1 回読みを C 列で使い回す Q4 GEMV。
    /// C = 2 / 4 / 8 の 3 エントリを PTX に入れてあり、[`Q4_GEMV_C`] で選ぶ。
    /// 同じ理由で Option (未再生成の PTX でも従来経路で起動できる)。
    f_mv_q4_c: Option<[CUfunction; 3]>,
    // P17d: 要素演算モジュール (swiglu / add+rmsnorm / expf probe)
    #[allow(dead_code)]
    module_elem: CUmodule,
    f_swiglu: CUfunction,
    // P17k: interleaved swiglu ([m, 2ff] 行ごと [gate|up] → [m, ff])
    f_swiglu_int: CUfunction,
    f_addnorm: CUfunction,
    #[allow(dead_code)]
    f_expf: CUfunction,
    // P17g: decode attention (exactness 緩和・ユーザー承認)
    f_attn: CUfunction,
    // P17j: prefill attention (flash 風 online softmax・exactness 緩和・ユーザー承認)
    f_attn_pf: CUfunction,
    /// task 135: t を分割する decode attention (`dno_attention_decode`) と、
    /// 部分和を畳む `dno_attention_decode_combine`。PTX に無ければ None で
    /// 従来の `dno_attention` 経路に落ちる (fail closed・古い PTX でも起動可)。
    f_attn_dec: Option<CUfunction>,
    f_attn_dec_cb: Option<CUfunction>,
    // s48 (C1-a): dno_attention_prefill の動的 smem 上限 (bytes)。opt-in 成功時は
    // デバイスの opt-in 上限・失敗時は 48KB 既定 (ATTN_PF_DYN_SMEM にも反映)。
    attn_pf_dyn_smem: usize,
    // P17h: qkv rope + bias (CPU rope_row とビット一致)
    f_rope: CUfunction,
    // P17k ステップ 5: prefill 用行並列 rope (qkv→rope→attention 連続化)
    f_rope_pf: CUfunction,
    // B3: b>1 バッチ decode 用 rope (q/k in-place・行ごと独立位置・CPU rope_row とビット一致)
    f_rope_b: CUfunction,
    // P19-A1: GDN 逐次 AR スキャン (prefill バッチ・GDN は bit 一致不要/決定論のみ)
    #[allow(dead_code)]
    module_gdn: CUmodule,
    f_gdn: CUfunction,
    // A1-r2: GDN chunked scan 3 カーネル (長 prefill 用・CPU 参照 gdn::scan_chunked_core)
    f_gdn_chunk_pre: CUfunction,
    /// s239 (P36): pass 1 の 4 レーン版 (DK=128 専用)。PTX に含まれる場合のみ取得し、
    /// `DENNO_GDN_LANES=4` のときだけ使う (既定は旧カーネル)。
    f_gdn_chunk_pre_l4: Option<CUfunction>,
    /// P55: pass 1 の状態配列 (W/M) を共有メモリへ置く版 (`dno_gdn_chunk_pre_sm`)。
    /// 必要 smem が 48 KiB 既定を超えるため、カーネルが PTX にあり、かつ
    /// cuFuncSetAttribute で opt-in できたときだけ Some。`DENNO_GDN_PRE_SM=1`
    /// のときだけ使う (既定 off)。数値は旧版とビット同一 (格納先だけが違う)。
    f_gdn_chunk_pre_sm: Option<CUfunction>,
    /// P55: 上のカーネルに設定できた動的 smem 上限 (bytes)。opt-in 失敗時は
    /// 48 KiB 既定 = dk=128 の必要量 129 KiB を満たさないのでゲートで落ちる。
    gdn_pre_sm_dyn_smem: usize,
    f_gdn_chunk_state: CUfunction,
    f_gdn_chunk_scan: CUfunction,
    /// s89 (P1-1): 状態グラフ常駐版の chunk scan (pass 2 を折りたたんだ 2 launch 版)。
    /// PTX はコミット済みの `kernels_gdn.ptx` に含まれる (再生成済み) 場合のみ
    /// 取得でき、無ければ None で従来の 3 launch 経路を使う。
    f_gdn_chunk_scan_hoist: Option<CUfunction>,
    /// task 128: qwen4exp (sigmoid 出力ゲート) の decode 用 scan
    /// (`dno_gdn_scan_sig`)。task 137 で gdn.cu に追加し `kernels_gdn.ptx` を
    /// 再生成したので、通常は Some になる。読めないとき (旧 PTX) は
    /// [`gdn_decode_submit`] が計測を積まずに CPU 経路へ落ちる (fail-closed)。
    f_gdn_scan_sig: Option<CUfunction>,
    // P-MOE-E1: Flash-Next の expert GEMV (Q8_0 / Q5_1 / Q4_K / Q5_K) を積んだ
    // モジュール。PTX の読み込みに失敗しても起動は壊さず `f_moe = None` にして、
    // 呼び出し側 (`moe_gemv`) が Ok(false) を返して CPU 参照へ落ちる。
    #[allow(dead_code)]
    module_moe: CUmodule,
    f_moe: Option<[CUfunction; 4]>,
    /// P-gemv2: x 先読み版の GEMV (ビット一致)。読めなければ v1 を使う。
    f_moe2: Option<[CUfunction; 4]>,
    /// P-PF-GB: prefill 用の量子 GEMM (Q8_0 / Q5_1 / Q4_K / Q5_K) を積んだ
    /// モジュール。数値契約は prefill のみ解除済み (`-fmad=true` で JIT)。
    /// 読み込みに失敗しても起動は壊さず `f_gemm_q = None` (CPU バッチへ落ちる)。
    #[allow(dead_code)]
    module_gemm_q: CUmodule,
    f_gemm_q: Option<[CUfunction; 4]>,
}

const PTX: &[u8] = include_bytes!("../kernels/kernels_int8.ptx");
const PTX_ELEM: &[u8] = include_bytes!("../kernels/kernels_elem.ptx");
const PTX_GDN: &[u8] = include_bytes!("../kernels/kernels_gdn.ptx");
// P-MOE-E1: Flash-Next の expert GEMV (Q8_0 / Q5_1 / Q4_K / Q5_K)。
// CPU 参照 (`model::moe_expert::expert_gemv`) とビット一致する。
const PTX_MOE: &[u8] = include_bytes!("../kernels/kernels_moe.ptx");
/// P-gemv2: 同じ数値契約のまま x をレジスタへ先読みする版 (`kernels_moe_v2.cu`)。
/// v1 とビット一致する (加算順・丸め順は同一)。`DENNO_GEMV_V2=0` で v1 に戻る。
const PTX_MOE_V2: &[u8] = include_bytes!("../kernels/kernels_moe_v2.ptx");
/// P-PF-GB: prefill 用の量子 GEMM。契約外 (FMA 融合あり) なので
/// `kernels_moe.ptx` (-fmad=false) とは別ファイルにしてある。
const PTX_GEMM_Q: &[u8] = include_bytes!("../kernels/kernels_gemm.ptx");

// 中身は生ハンドル (context / module / function)。CUcontext はスレッドごとに
// current 設定して使うハンドルであり、所有権の移動は伴わないため Send/Sync を
// 与える (primary context 自体は driver がスレッド安全に管理する)。
unsafe impl Send for CudaCtx {}
unsafe impl Sync for CudaCtx {}

impl CudaCtx {
    /// デバイス 0 (または `DENNO_CUDA_DEVICE`) の primary context を初期化し、
    /// int8 カーネルの PTX をロードする。
    pub fn new() -> Result<Self> {
        let lib = lib()?;
        unsafe {
            check((lib.cu_init)(0), "cuInit")?;
            let device: CUdevice = std::env::var("DENNO_CUDA_DEVICE")
                .ok()
                .and_then(|v| v.parse().ok())
                .unwrap_or(0);
            let mut dev: CUdevice = 0;
            check((lib.device_get)(&mut dev, device), "cuDeviceGet")?;

            let mut namebuf = [0u8 as c_char; 128];
            check((lib.device_name)(namebuf.as_mut_ptr(), 127, dev), "cuDeviceGetName")?;
            let name = std::ffi::CStr::from_ptr(namebuf.as_ptr())
                .to_string_lossy()
                .into_owned();

            let (mut maj, mut min) = (0 as c_int, 0 as c_int);
            check((lib.device_cc)(&mut maj, &mut min, dev), "cuDeviceComputeCapability")?;

            let mut drv = 0 as c_int;
            let _ = (lib.driver_version)(&mut drv);

            let mut ctx: CUcontext = std::ptr::null_mut();
            check((lib.primary_ctx_retain)(&mut ctx, dev), "cuDevicePrimaryCtxRetain")?;
            check((lib.ctx_set_current)(ctx), "cuCtxSetCurrent")?;

            // PTX は NUL 終端が必要
            let mut image = PTX.to_vec();
            image.push(0);
            let mut module: CUmodule = std::ptr::null_mut();
            check(
                (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void),
                "cuModuleLoadData (PTX JIT)",
            )?;

            let mut f_quant: CUfunction = std::ptr::null_mut();
            let mut f_mv: CUfunction = std::ptr::null_mut();
            let mut f_gemm: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_quant, module, b"dno_quantize_rows\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_quantize_rows)",
            )?;
            check(
                (lib.module_get_function)(&mut f_mv, module, b"dno_matvec_rows_bt_i8\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_matvec_rows_bt_i8)",
            )?;
            // P17i: prefill 用 tiled GEMM (m が大きいときの GEMV 型カーネル置き換え)
            check(
                (lib.module_get_function)(&mut f_gemm, module, b"dno_gemm_i8\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_gemm_i8)",
            )?;
            // s123: Q4_0 ネイティブ経路 (同じモジュールに同居)
            let mut f_mv_q4: CUfunction = std::ptr::null_mut();
            let mut f_gemm_q4: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_mv_q4, module, b"dno_gemv_q4_0\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_gemv_q4_0)",
            )?;
            check(
                (lib.module_get_function)(&mut f_gemm_q4, module, b"dno_gemm_q4_0\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_gemm_q4_0)",
            )?;
            // s132 (Task B1): 複数行 1 block の GEMV は「あれば使う」。古い PTX
            // (未再生成) でも起動を壊さず 1 行 1 block 経路へ落ちるよう、
            // 取得失敗は None として扱う。
            let mut f_mv_q4_mr: CUfunction = std::ptr::null_mut();
            let mv_mr_r = (lib.module_get_function)(
                &mut f_mv_q4_mr,
                module,
                b"dno_gemv_q4_0mr\0".as_ptr() as *const c_char,
            );
            let f_mv_q4_mr = if mv_mr_r == CUDA_SUCCESS {
                Some(f_mv_q4_mr)
            } else {
                None
            };
            // s133 (Task B1, attempt 2): 列ブロック版 GEMV (C = 2 / 4 / 8)。
            // 3 本そろって初めて Some。1 本でも取れなければ None で従来経路。
            let mut fc: [CUfunction; 3] = [std::ptr::null_mut(); 3];
            let mut c_ok = true;
            for (k, name) in [b"dno_gemv_q4_0c2\0", b"dno_gemv_q4_0c4\0", b"dno_gemv_q4_0c8\0"]
                .iter()
                .enumerate()
            {
                let r = (lib.module_get_function)(
                    &mut fc[k],
                    module,
                    name.as_ptr() as *const c_char,
                );
                if r != CUDA_SUCCESS {
                    c_ok = false;
                    break;
                }
            }
            let f_mv_q4_c = if c_ok { Some(fc) } else { None };

            // P17d: 要素演算モジュール (-fmad=false でコンパイル済み。FMA 縮約は
            // CPU とビット一致しないため禁止)
            let mut module_elem: CUmodule = std::ptr::null_mut();
            let mut image_elem = PTX_ELEM.to_vec();
            image_elem.push(0);
            check(
                (lib.module_load_data)(&mut module_elem, image_elem.as_ptr() as *const c_void),
                "cuModuleLoadData (elem PTX JIT)",
            )?;
            let mut f_swiglu: CUfunction = std::ptr::null_mut();
            let mut f_addnorm: CUfunction = std::ptr::null_mut();
            let mut f_expf: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_swiglu, module_elem, b"dno_swiglu\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_swiglu)",
            )?;
            let mut f_swiglu_int: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_swiglu_int, module_elem, b"dno_swiglu_int\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_swiglu_int)",
            )?;
            // s170: DENNO_FAST_REDUCE=1 なら二乗和を固定木で並列縮約する版を使う
            // (引数・動的 smem は同一。丸め順だけが変わる)。PTX に無ければ逐次版へ戻す。
            if fast_reduce_enabled()
                && (lib.module_get_function)(
                    &mut f_addnorm,
                    module_elem,
                    b"dno_add_rmsnorm_r\0".as_ptr() as *const c_char,
                ) == 0
            {
                // 並列版を取得できた
            } else {
                check(
                    (lib.module_get_function)(&mut f_addnorm, module_elem, b"dno_add_rmsnorm\0".as_ptr() as *const c_char),
                    "cuModuleGetFunction(dno_add_rmsnorm)",
                )?;
            }
            check(
                (lib.module_get_function)(&mut f_expf, module_elem, b"dno_expf_probe\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_expf_probe)",
            )?;
            let mut f_attn: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_attn, module_elem, b"dno_attention\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_attention)",
            )?;
            // P17j: prefill attention
            let mut f_attn_pf: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_attn_pf, module_elem, b"dno_attention_prefill\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_attention_prefill)",
            )?;
            // task 135: t 分割の decode attention。古い PTX (未再生成) でも
            // CudaCtx 生成を壊さないよう Option (無ければ従来の decode 経路)。
            let mut f_attn_dec: CUfunction = std::ptr::null_mut();
            let mut f_attn_dec_cb: CUfunction = std::ptr::null_mut();
            let f_attn_dec = if (lib.module_get_function)(
                &mut f_attn_dec,
                module_elem,
                b"dno_attention_decode\0".as_ptr() as *const c_char,
            ) == 0
                && (lib.module_get_function)(
                    &mut f_attn_dec_cb,
                    module_elem,
                    b"dno_attention_decode_combine\0".as_ptr() as *const c_char,
                ) == 0
            {
                Some((f_attn_dec, f_attn_dec_cb))
            } else {
                None
            };
            // s48 (C1-a): 動的 smem の opt-in 試行。デバイスの opt-in 上限を取得し、
            // 48KB を超えるなら dno_attention_prefill へ設定する (qwen35 dh=256 =
            // 84.8KB を通すため)。失敗しても ctx 生成は続行 (48KB 既定のまま =
            // qwen35 prefill attention はゲートで CPU へ静かにフォールバック)。
            let mut attn_pf_dyn_smem: usize = ATTN_PF_SMEM_DEFAULT;
            if let (Some(dev_attr), Some(fn_attr)) = (lib.device_get_attribute, lib.func_set_attribute) {
                let mut optin: c_int = 0;
                if (dev_attr)(&mut optin, CU_DEV_ATTR_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN, dev) == 0
                    && optin as usize > attn_pf_dyn_smem
                    && (fn_attr)(f_attn_pf, CU_FUNC_ATTR_MAX_DYNAMIC_SHARED_SIZE_BYTES, optin) == 0
                {
                    attn_pf_dyn_smem = optin as usize;
                }
            }
            ATTN_PF_DYN_SMEM.store(attn_pf_dyn_smem, std::sync::atomic::Ordering::Relaxed);
            // s169 (P10): SM 数を 1 回だけ取る (GEMV の launch 形状を n から選ぶ
            // ためだけに使う。取れなければ 0 のまま = 形状選択は従来の固定 C)。
            if let Some(dev_attr) = lib.device_get_attribute {
                let mut sms: c_int = 0;
                if (dev_attr)(&mut sms, CU_DEV_ATTR_MULTIPROCESSOR_COUNT, dev) == 0 && sms > 0 {
                    GEMV_SM_COUNT.store(sms as usize, std::sync::atomic::Ordering::Relaxed);
                }
            }
            let mut f_rope: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_rope, module_elem, b"dno_rope_qkv\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_rope_qkv)",
            )?;
            // P17k ステップ 5: prefill 用行並列 rope
            let mut f_rope_pf: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_rope_pf, module_elem, b"dno_rope_qkv_pf\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_rope_qkv_pf)",
            )?;
            // B3: b>1 バッチ decode 用 rope
            let mut f_rope_b: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_rope_b, module_elem, b"dno_rope_qk_batch\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_rope_qk_batch)",
            )?;

            // P19-A1: GDN 逐次スキャンモジュール
            let mut module_gdn: CUmodule = std::ptr::null_mut();
            let mut image_gdn = PTX_GDN.to_vec();
            image_gdn.push(0);
            check(
                (lib.module_load_data)(&mut module_gdn, image_gdn.as_ptr() as *const c_void),
                "cuModuleLoadData (gdn PTX JIT)",
            )?;
            let mut f_gdn: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_gdn, module_gdn, b"dno_gdn_scan\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_gdn_scan)",
            )?;
            // A1-r2: chunked scan 3 カーネル
            let mut f_gdn_chunk_pre: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_gdn_chunk_pre, module_gdn, b"dno_gdn_chunk_pre\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_gdn_chunk_pre)",
            )?;
            let mut f_gdn_chunk_state: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_gdn_chunk_state, module_gdn, b"dno_gdn_chunk_state\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_gdn_chunk_state)",
            )?;
            let mut f_gdn_chunk_scan: CUfunction = std::ptr::null_mut();
            check(
                (lib.module_get_function)(&mut f_gdn_chunk_scan, module_gdn, b"dno_gdn_chunk_scan\0".as_ptr() as *const c_char),
                "cuModuleGetFunction(dno_gdn_chunk_scan)",
            )?;
            // s89 (P1-1): 状態常駐版は「あれば使う」。古い PTX (未再生成) でも
            // 起動を壊さず 3 launch 経路へ落ちるよう、取得失敗は None として扱う。
            let mut f_gdn_chunk_scan_hoist: CUfunction = std::ptr::null_mut();
            let hoist_r = (lib.module_get_function)(
                &mut f_gdn_chunk_scan_hoist,
                module_gdn,
                b"dno_gdn_chunk_scan_hoist\0".as_ptr() as *const c_char,
            );
            // (隣接フィールドと同じく CUresult == 0 が成功。非 0 は None)
            let f_gdn_chunk_scan_hoist = if hoist_r == CUDA_SUCCESS {
                Some(f_gdn_chunk_scan_hoist)
            } else {
                None
            };

            // task 128: qwen4exp の decode 用 scan (sigmoid 出力ゲート) も
            // 「あれば使う」。task 137 で PTX を再生成したので通常は取れる。
            // 取れないとき (旧 PTX) は GPU decode scan 経路を発動させない
            // (fail-closed = CPU 経路)。
            let mut f_gdn_scan_sig: CUfunction = std::ptr::null_mut();
            let sig_r = (lib.module_get_function)(
                &mut f_gdn_scan_sig,
                module_gdn,
                b"dno_gdn_scan_sig\0".as_ptr() as *const c_char,
            );
            // task 137: 取れただけでは足りない。ホストは 23 引数を渡すので、
            // PTX 側の引数個数が dno_gdn_scan と違えば起動しない (ABI 検査)。
            let sig_abi_ok = std::str::from_utf8(PTX_GDN)
                .map(gdn_scan_sig_abi_ok)
                .unwrap_or(false);
            let f_gdn_scan_sig = if sig_r == CUDA_SUCCESS && sig_abi_ok {
                Some(f_gdn_scan_sig)
            } else {
                if sig_r == CUDA_SUCCESS && !sig_abi_ok {
                    tracing::warn!(
                        "[gdn-gpu-scan] dno_gdn_scan_sig の引数個数が dno_gdn_scan と違う \
                         (PTX とホストの不整合) → CPU 経路"
                    );
                }
                None
            };

            // s239 (P36): 4 レーン版 pass 1 も「あれば使う」(同じ理由)。
            let mut f_gdn_chunk_pre_l4: CUfunction = std::ptr::null_mut();
            let l4_r = (lib.module_get_function)(
                &mut f_gdn_chunk_pre_l4,
                module_gdn,
                b"dno_gdn_chunk_pre_l4\0".as_ptr() as *const c_char,
            );
            let f_gdn_chunk_pre_l4 = if l4_r == CUDA_SUCCESS {
                Some(f_gdn_chunk_pre_l4)
            } else {
                None
            };

            // P55: pass 1 の状態配列 (W/M) を共有メモリへ置く版 (dk=128 で 129 KiB)。
            // 「あれば使う」+ 動的 smem の opt-in の 2 段。どちらかが失敗すれば
            // None / 48 KiB 既定のままになり、ゲート (`gdn_pre_sm_gate`) が
            // 旧カーネルを選ぶ (fail-closed)。.cu を先に足して PTX を後から
            // 再生成する運用でも、起動は壊れない。
            let mut f_gdn_chunk_pre_sm: CUfunction = std::ptr::null_mut();
            let sm_r = (lib.module_get_function)(
                &mut f_gdn_chunk_pre_sm,
                module_gdn,
                b"dno_gdn_chunk_pre_sm\0".as_ptr() as *const c_char,
            );
            let (f_gdn_chunk_pre_sm, gdn_pre_sm_dyn_smem) = if sm_r == CUDA_SUCCESS {
                let mut limit = GDN_PRE_SM_SMEM_DEFAULT;
                if let (Some(dev_attr), Some(fn_attr)) = (lib.device_get_attribute, lib.func_set_attribute) {
                    let mut optin: c_int = 0;
                    if (dev_attr)(&mut optin, CU_DEV_ATTR_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN, dev) == 0
                        && optin as usize > limit
                        && (fn_attr)(f_gdn_chunk_pre_sm, CU_FUNC_ATTR_MAX_DYNAMIC_SHARED_SIZE_BYTES, optin) == 0
                    {
                        limit = optin as usize;
                    }
                }
                (Some(f_gdn_chunk_pre_sm), limit)
            } else {
                (None, GDN_PRE_SM_SMEM_DEFAULT)
            };

            // P-MOE-E1: expert GEMV のモジュール (Q8_0 / Q5_1 / Q4_K / Q5_K)。
            // 4 本そろって初めて Some。1 本でも欠ければ None (CPU 参照へ落ちる)。
            let mut module_moe: CUmodule = std::ptr::null_mut();
            let mut f_moe: Option<[CUfunction; 4]> = None;
            {
                let mut image = PTX_MOE.to_vec();
                image.push(0);
                if (lib.module_load_data)(&mut module_moe, image.as_ptr() as *const c_void) == CUDA_SUCCESS {
                    let mut fs: [CUfunction; 4] = [std::ptr::null_mut(); 4];
                    let names: [&[u8]; 4] = [
                        b"dno_gemv_q8_0_w\0",
                        b"dno_gemv_q5_1_w\0",
                        b"dno_gemv_q4k_w\0",
                        b"dno_gemv_q5k_w\0",
                    ];
                    let mut ok = true;
                    for (k, n) in names.iter().enumerate() {
                        if (lib.module_get_function)(&mut fs[k], module_moe, n.as_ptr() as *const c_char)
                            != CUDA_SUCCESS
                        {
                            ok = false;
                            break;
                        }
                    }
                    if ok {
                        f_moe = Some(fs);
                    }
                }
            }

            // P-gemv2: 数値契約は v1 と同一で、x をレジスタへ先読みする版。
            let mut module_moe2: CUmodule = std::ptr::null_mut();
            let mut f_moe2: Option<[CUfunction; 4]> = None;
            {
                let mut image = PTX_MOE_V2.to_vec();
                image.push(0);
                if (lib.module_load_data)(&mut module_moe2, image.as_ptr() as *const c_void) == CUDA_SUCCESS {
                    let mut fs: [CUfunction; 4] = [std::ptr::null_mut(); 4];
                    let names: [&[u8]; 4] = [
                        b"dno_gemv_q8_0_v2\0",
                        b"dno_gemv_q5_1_v2\0",
                        b"dno_gemv_q4k_v2\0",
                        b"dno_gemv_q5k_v2\0",
                    ];
                    let mut ok = true;
                    for (k, n) in names.iter().enumerate() {
                        if (lib.module_get_function)(&mut fs[k], module_moe2, n.as_ptr() as *const c_char)
                            != CUDA_SUCCESS
                        {
                            ok = false;
                            break;
                        }
                    }
                    if ok {
                        f_moe2 = Some(fs);
                    }
                }
            }

            // P-PF-GB: prefill 用の量子 GEMM のモジュール。同じ規約 (4 本そろって初めて Some)。
            let mut module_gemm_q: CUmodule = std::ptr::null_mut();
            let mut f_gemm_q: Option<[CUfunction; 4]> = None;
            {
                let mut image = PTX_GEMM_Q.to_vec();
                image.push(0);
                if (lib.module_load_data)(&mut module_gemm_q, image.as_ptr() as *const c_void) == CUDA_SUCCESS {
                    let mut fs: [CUfunction; 4] = [std::ptr::null_mut(); 4];
                    let names: [&[u8]; 4] = [
                        b"dno_gemm_q8_0_w\0",
                        b"dno_gemm_q5_1_w\0",
                        b"dno_gemm_q4k_w\0",
                        b"dno_gemm_q5k_w\0",
                    ];
                    let mut ok = true;
                    for (k, n) in names.iter().enumerate() {
                        if (lib.module_get_function)(&mut fs[k], module_gemm_q, n.as_ptr() as *const c_char)
                            != CUDA_SUCCESS
                        {
                            ok = false;
                            break;
                        }
                    }
                    if ok {
                        f_gemm_q = Some(fs);
                    }
                }
            }

            // task 149: どのモジュールをどれだけの PTX から JIT したかを台帳に残す
            // (JIT 後のコード量はドライバが公開しないので、ここでは PTX の大きさ)。
            crate::mem_audit::note_module("int8", PTX.len());
            crate::mem_audit::note_module("elem", PTX_ELEM.len());
            crate::mem_audit::note_module("gdn", PTX_GDN.len());
            crate::mem_audit::note_module("moe", PTX_MOE.len());
            crate::mem_audit::note_module("moe_v2", PTX_MOE_V2.len());
            crate::mem_audit::note_module("gemm_q", PTX_GEMM_Q.len());

            Ok(Self {
                device: dev,
                name,
                cc: (maj, min),
                driver_ver: drv,
                ctx,
                module,
                f_quant,
                f_mv,
                f_gemm,
                f_mv_q4,
                f_gemm_q4,
                f_mv_q4_mr,
                f_mv_q4_c,
                module_elem,
                f_swiglu,
                f_swiglu_int,
                f_addnorm,
                f_expf,
                f_attn,
                f_attn_pf,
                f_attn_dec: f_attn_dec.map(|(a, _)| a),
                f_attn_dec_cb: f_attn_dec.map(|(_, b)| b),
                attn_pf_dyn_smem,
                f_rope,
                f_rope_pf,
                f_rope_b,
                module_gdn,
                f_gdn,
                f_gdn_chunk_pre,
                f_gdn_chunk_pre_l4,
                f_gdn_chunk_pre_sm,
                gdn_pre_sm_dyn_smem,
                f_gdn_chunk_state,
                f_gdn_chunk_scan,
                f_gdn_chunk_scan_hoist,
                f_gdn_scan_sig,
                module_moe,
                f_moe,
                f_moe2,
                module_gemm_q,
                f_gemm_q,
            })
        }
    }

    /// "NVIDIA GeForce RTX 5090 (sm_120, driver 13010)" 形式の情報
    pub fn info(&self) -> String {
        format!(
            "{} (sm_{}{}, driver {}, attn_pf dyn smem {}KB)",
            self.name,
            self.cc.0,
            self.cc.1,
            self.driver_ver,
            self.attn_pf_dyn_smem / 1024
        )
    }

    pub fn device(&self) -> c_int {
        self.device
    }

    /// カーネル起動のみ (同期しない — デフォルトストリームにエンキュー)。
    /// P17b: 固定オーバーヘッド削減のため launch/sync を分離。
    unsafe fn launch_async(
        &self,
        f: CUfunction,
        grid: (u32, u32, u32),
        block: (u32, u32, u32),
        shmem: u32,
        args: &mut [*mut c_void],
    ) -> Result<()> {
        self.launch_async_on(
            std::ptr::null_mut(),
            f,
            grid,
            block,
            shmem,
            args,
        )
    }

    /// [`Self::launch_async`] のストリーム指定版 (task 124 の重ね打ち経路)。
    ///
    /// `stream` が null のときの挙動は従来と完全に同じ (同じ `dbg_launch` の
    /// 計数・同じ `cuLaunchKernel` 引数)。
    #[allow(clippy::too_many_arguments)]
    unsafe fn launch_async_on(
        &self,
        stream: CUstream,
        f: CUfunction,
        grid: (u32, u32, u32),
        block: (u32, u32, u32),
        shmem: u32,
        args: &mut [*mut c_void],
    ) -> Result<()> {
        let lib = lib()?;
        // s166 (P5): decode 1 ステップの launch 件数 (DENNO_DECODE_DBG=1・既定 OFF)
        dbg_launch(f);
        // task 138: 台帳 (DENNO_Q4_PROFILE) への発行 1 件の計上。off は stamp が None。
        let tl = crate::model::q4ledger::stamp();
        // task 153: イベント時系列 (DENNO_Q4_TLINE + _K)。off は None で分岐 1 回。
        let ev0 = tline::launch_begin();
        let r = check(
            (lib.launch)(
                f,
                grid.0,
                grid.1,
                grid.2,
                block.0,
                block.1,
                block.2,
                shmem,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            ),
            "cuLaunchKernel",
        );
        if let Some(a) = ev0 {
            tline::launch_end(crate::model::q4ledger::current(), a);
        }
        crate::model::q4ledger::note_launch(tl);
        r
    }

    /// デフォルトストリームの同期 (エンキュー済み全操作の完了待ち)
    pub fn sync(&self) -> Result<()> {
        let lib = lib()?;
        // task 138: 台帳へ待ち時間を積む (off は stamp が None で計測しない)。
        let t = crate::model::q4ledger::stamp();
        let r = unsafe { check((lib.ctx_sync)(), "cuCtxSynchronize") };
        crate::model::q4ledger::note_sync(t);
        r
    }
    /// 呼び出しスレッドに primary context を current として設定する。
    /// CUDA の current context は**スレッドローカル** (P17c の教訓: libtest は
    /// テスト毎に新スレッドを立てるため、初期化スレッドで 1 回だけ設定したのでは
    /// 他スレッドの cuMemAlloc が error 201 INVALID_CONTEXT で落ちる)。共有
    /// CudaCtx を複数スレッドから触るため、GPU 操作の入口で毎回張り直す
    /// (cuCtxSetCurrent は冪等かつ軽量)。
    pub fn make_current(&self) -> Result<()> {
        let lib = lib()?;
        unsafe { check((lib.ctx_set_current)(self.ctx), "cuCtxSetCurrent") }
    }

    /// `tensor::quantize_row_i8` の GPU 版 (m 行一括)。
    /// 戻り値: (量子化済みアクティベーション [m*k] i8, ascale [m] f32) の
    /// デバイスバッファ (後続の `matvec_rows_bt_i8_dev` にそのまま渡せる)。
    pub fn quantize_rows(&self, a: &[f32], m: usize, k: usize) -> Result<(DevBuffer, DevBuffer)> {
        assert_eq!(a.len(), m * k, "quantize_rows: a size mismatch");
        let dev_a = DevBuffer::from_slice(a)?;
        let dev_aq = DevBuffer::alloc(m * k)?;
        let dev_asc = DevBuffer::alloc(m * 4)?;
        unsafe {
            let (mut pa, mut paq, mut pasc) = (dev_a.ptr, dev_aq.ptr, dev_asc.ptr);
            let (mut mc, mut kc) = (m as c_int, k as c_int);
            let mut args = [
                &mut pa as *mut _ as *mut c_void,
                &mut paq as *mut _ as *mut c_void,
                &mut pasc as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
            ];
            // 1 block per row, 256 threads, shmem 256*4 bytes
            self.launch_async(
                self.f_quant,
                (m as u32, 1, 1),
                (256, 1, 1),
                256 * 4,
                &mut args,
            )?;
            self.sync()?;
        }
        Ok((dev_aq, dev_asc))
    }

    /// int8 GEMV/GEMM (nn.Linear 形式 q: [n,k]) をデバイスバッファで実行。
    /// `tensor::matvec_rows_bt_i8` とビット一致する [m,n] f32 を返す。
    pub fn matvec_rows_bt_i8_dev(
        &self,
        aq: &DevBuffer,
        asc: &DevBuffer,
        w: &DevBuffer,
        scale: &DevBuffer,
        m: usize,
        k: usize,
        n: usize,
    ) -> Result<Vec<f32>> {
        let dev_out = DevBuffer::alloc(m * n * 4)?;
        unsafe {
            let (mut paq, mut pasc, mut pw, mut psc, mut pout) =
                (aq.ptr, asc.ptr, w.ptr, scale.ptr, dev_out.ptr);
            let (mut mc, mut kc, mut nc) = (m as c_int, k as c_int, n as c_int);
            let mut args = [
                &mut paq as *mut _ as *mut c_void,
                &mut pasc as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut psc as *mut _ as *mut c_void,
                &mut pout as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            // 1 warp per (i,j): block 256 = 8 warps
            let total = (m * n) as u64;
            let blocks = total.div_ceil(8) as u32;
            self.launch_async(self.f_mv, (blocks, 1, 1), (256, 1, 1), 0, &mut args)?;
            self.sync()?;
        }
        dev_out.to_vec::<f32>(m * n)
    }

    /// ホストのアクティベーションから一括で実行する高レベル API
    /// (量子化 + GEMV)。重み/scale は事前に `upload_i8` / `upload_f32` で
    /// VRAM 常駐させておく。戻り値は `tensor::matvec_rows_bt_i8` とビット一致。
    pub fn linear_bt_i8(
        &self,
        a: &[f32],
        w: &DevBuffer,
        scale: &DevBuffer,
        m: usize,
        k: usize,
        n: usize,
    ) -> Result<Vec<f32>> {
        debug_assert_eq!(w.bytes(), k * gemm_pad_n(n));
        debug_assert_eq!(scale.bytes(), n * 4);
        let (aq, asc) = self.quantize_rows(a, m, k)?;
        self.matvec_rows_bt_i8_dev(&aq, &asc, w, scale, m, k, n)
    }

    /// P17i: tiled GEMM (dno_gemm_i8) で実行。`linear_bt_i8` とビット一致。
    /// テストとベンチ用 (本番経路は `linear_gemm` を使う)。
    pub fn linear_gemm_i8_dev(
        &self,
        aq: &DevBuffer,
        asc: &DevBuffer,
        w: &DevBuffer,
        scale: &DevBuffer,
        m: usize,
        k: usize,
        n: usize,
    ) -> Result<Vec<f32>> {
        let dev_out = DevBuffer::alloc(m * n * 4)?;
        unsafe {
            let (mut paq, mut pasc, mut pw, mut psc, mut pout) =
                (aq.ptr, asc.ptr, w.ptr, scale.ptr, dev_out.ptr);
            let (mut mc, mut kc, mut nc) = (m as c_int, k as c_int, n as c_int);
            let mut args = [
                &mut paq as *mut _ as *mut c_void,
                &mut pasc as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut psc as *mut _ as *mut c_void,
                &mut pout as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            let gmx = m.div_ceil(GEMM_TILE) as u32;
            let gmy = n.div_ceil(GEMM_TILE_N) as u32;
            self.launch_async(self.f_gemm, (gmx, gmy, 1), (GEMM_BX, GEMM_BY, 1), 0, &mut args)?;
            self.sync()?;
        }
        dev_out.to_vec::<f32>(m * n)
    }

    /// P17i: ホストのアクティベーションから tiled GEMM を実行 (量子化込み)。
    pub fn linear_gemm_i8(
        &self,
        a: &[f32],
        w: &DevBuffer,
        scale: &DevBuffer,
        m: usize,
        k: usize,
        n: usize,
    ) -> Result<Vec<f32>> {
        debug_assert_eq!(w.bytes(), k * gemm_pad_n(n));
        debug_assert_eq!(scale.bytes(), n * 4);
        let (aq, asc) = self.quantize_rows(a, m, k)?;
        self.linear_gemm_i8_dev(&aq, &asc, w, scale, m, k, n)
    }

    /// 重みを VRAM へアップロード (起動時に1度)
    pub fn upload_i8(&self, data: &[i8]) -> Result<DevBuffer> {
        DevBuffer::from_slice(data)
    }

    /// scale などを VRAM へアップロード (起動時に1度)
    pub fn upload_f32(&self, data: &[f32]) -> Result<DevBuffer> {
        DevBuffer::from_slice(data)
    }

    /// P-MOE-E1: Flash-Next の expert GEMV。CPU 参照
    /// (`crate::model::moe_expert::expert_gemv`) とビット一致する。
    ///
    /// 対象は実ファイルで使う 4 型のみ (Q8_0 / Q5_1 / Q4_K / Q5_K)。未対応の型、
    /// PTX 不在、カーネル取得失敗では `Ok(false)` を返し、呼び出し側が CPU 経路へ
    /// 落ちる (fail-closed。別経路の数値を黙って返さない)。
    ///
    /// カーネルは 1 block = 4 出力行 (64 スレッド/行)。行の生バイトを共有メモリへ
    /// コアレスで読み、その後 1 スレッドが i の昇順に f32 で累積する。
    pub fn moe_gemv(
        &self,
        ty: crate::kquant::GgmlType,
        w: &[u8],
        x: &[f32],
        n_in: usize,
        n_out: usize,
        out: &mut [f32],
    ) -> Result<bool> {
        use crate::kquant::GgmlType as T;
        let fs = match self.f_moe {
            Some(f) => f,
            None => return Ok(false),
        };
        let (f, rb) = match ty {
            T::Q8_0 => (fs[0], (n_in / 32) * 34),
            T::Q5_1 => (fs[1], (n_in / 32) * 24),
            T::Q4K => (fs[2], (n_in / 256) * 144),
            T::Q5K => (fs[3], (n_in / 256) * 176),
            _ => return Ok(false),
        };
        let bs = ty.blck_size();
        if n_in == 0 || n_out == 0 || n_in % bs != 0 {
            bail!("moe_gemv: 形状が不正 (n_in={n_in}, n_out={n_out}, block={bs})");
        }
        if w.len() != n_out * rb {
            bail!(
                "moe_gemv: w の長さ {} が n_out * row_bytes = {} と違う",
                w.len(),
                n_out * rb
            );
        }
        if x.len() != n_in {
            bail!("moe_gemv: x の長さ {} が n_in={n_in} と違う", x.len());
        }
        if out.len() != n_out {
            bail!("moe_gemv: out の長さ {} が n_out={n_out} と違う", out.len());
        }

        self.make_current()?;
        let dev_w = DevBuffer::from_slice(w)?;
        let used = self.moe_gemv_dev(ty, &dev_w, x, n_in, n_out, out)?;
        Ok(used)
    }

    /// P-gemv2: 使う GEMV カーネル一式を選ぶ。
    ///
    /// `DENNO_GEMV_V2=0` で v1 (従来) に固定できる。v2 が読めていなければ v1。
    /// v1 と v2 は**同じ数値契約** (i 昇順・f32 逐次加算・-fmad=false) なので、
    /// どちらを選んでも出力ビットは一致する。
    fn pick_moe_kernels(&self) -> Option<[CUfunction; 4]> {
        if moe_gemv_v2_on() {
            if let Some(f) = self.f_moe2 {
                return Some(f);
            }
        }
        self.f_moe
    }

    /// P-MOE-E5: 既に VRAM に載っている重み (`dev_w`) で GEMV する。
    /// 重みの H2D を含まないので、常駐キャッシュ越しに毎トークン呼べる。
    /// 引数検査は [`Self::moe_gemv`] と同じ (重みのバイト長は検査できない)。
    pub fn moe_gemv_dev(
        &self,
        ty: crate::kquant::GgmlType,
        dev_w: &DevBuffer,
        x: &[f32],
        n_in: usize,
        n_out: usize,
        out: &mut [f32],
    ) -> Result<bool> {
        // P-fp16 (task 108): fast mode (`DENNO_GEMV_FP16=1`) が最優先。off なら
        // 従来どおり v3 (`DENNO_GEMV_V3=1`) → v2 の順。env 未指定では V2 のまま
        // で 1 バイトも挙動が変わらない。
        let mode = gemv_kernel_mode();
        self.moe_gemv_dev_with(ty, dev_w, x, n_in, n_out, out, mode)
    }

    /// [`Self::moe_gemv_dev`] の実体。`mode` で使うカーネル一式を選ぶ。
    ///
    /// - [`GemvKernelMode::V2`]: ビット一致契約の既定経路。
    /// - [`GemvKernelMode::V3`]: レーン分割版 (`kernels_moe_v3.cu`)。k が 64 の
    ///   倍数でない / v3 の PTX が読めない / PTX が旧 ABI (引数 6 本) のときは
    ///   v2 へ落ちる。
    /// - [`GemvKernelMode::Fp16`]: fast mode (`kernels_moe_fp16.cu`)。対応型
    ///   (Q8_0 / Q5_1 / Q4_K) 以外・k が 64 の倍数でない・PTX が読めない /
    ///   旧 ABI のときは v3 (on なら) → v2 と同じ降下経路へ落ちる。
    ///
    /// 戻り値は「GPU で走ったか」(降下しても true)。fp16 / v3 が実際に走ったかは
    /// 呼び出し側のテストが「v2 とビット一致しないこと」で確かめる。
    /// decode GEMV 1 本ぶんの発行計画 (カーネル・起動形状・行バイト)。
    ///
    /// [`CudaCtx::moe_gemv_dev_with`] から切り出した**選択だけ**の部分で、
    /// デバイスメモリには触らない。task 124 の重ね打ち経路
    /// ([`shared_gemv_begin`]) と同じカーネル・同じ引数を組むために共有する。

    /// `ty` / `n_in` / `n_out` からカーネルと起動形状を決める (選択のみ)。
    ///
    /// 対象外の型・PTX が読めないときは `Ok(None)` (呼び出し側は CPU へ落ちる)。
    fn plan_moe_gemv(
        &self,
        ty: crate::kquant::GgmlType,
        n_in: usize,
        n_out: usize,
        mode: GemvKernelMode,
    ) -> Result<Option<MoeGemvPlan>> {
        use crate::kquant::GgmlType as T;
        let fs_v12 = match self.pick_moe_kernels() {
            Some(f) => f,
            None => return Ok(None),
        };
        let (ki, rb) = match ty {
            T::Q8_0 => (0usize, (n_in / 32) * 34),
            T::Q5_1 => (1usize, (n_in / 32) * 24),
            T::Q4K => (2usize, (n_in / 256) * 144),
            T::Q5K => (3usize, (n_in / 256) * 176),
            _ => return Ok(None),
        };
        // P-gemv3: 1 行を lanes レーン (4 or 2) で分担する版 (kernels_moe_v3.cu)。
        // P-fp16 (task 108): fast mode は v3 と同じ 8 引数 ABI・同じレーン分割で、
        // 中の演算だけ fp16 dequant + half2 FMA に変える。
        let fp16 = match mode {
            GemvKernelMode::Fp16 if gemv_fp16_ty_ok(ty) => {
                let lanes = moe_gemv_v3_lanes(n_in);
                if lanes == 0 {
                    None
                } else {
                    gemv_fp16_kernels().map(|k| (k.f[ki], lanes))
                }
            }
            _ => None,
        };
        let v3 = if fp16.is_none() && matches!(mode, GemvKernelMode::V3 | GemvKernelMode::Fp16) {
            let lanes = moe_gemv_v3_lanes(n_in);
            if lanes == 0 {
                None
            } else {
                gemv_v3_kernels().map(|k| (k.f[ki], lanes))
            }
        } else {
            None
        };
        const MOE_ROWS_PER_BLOCK: usize = 4; // kernels_moe.cu の MOE_ROWS と一致
        // fp16 / v3 の blockDim は rows*lanes (既定 rows=8/lanes=4 で 32)。v2 は 256 固定。
        // rows は DENNO_GEMV_V3_ROWS を共有する (起動形状の意味は同じ)。
        let (f, rows_per_block, block_dim, shmem, lanes) = match (fp16, v3) {
            (Some((f, lanes)), _) => {
                let rows = moe_gemv_v3_rows();
                (f, rows, (rows * lanes) as u32, 0u32, lanes)
            }
            (None, Some((f3, lanes))) => {
                let rows = moe_gemv_v3_rows();
                (f3, rows, (rows * lanes) as u32, 0u32, lanes)
            }
            (None, None) => (
                fs_v12[ki],
                MOE_ROWS_PER_BLOCK,
                256u32,
                (MOE_ROWS_PER_BLOCK * rb) as u32,
                1usize,
            ),
        };
        let grid = ((n_out + rows_per_block - 1) / rows_per_block) as u32;
        Ok(Some(MoeGemvPlan {
            f,
            rows_per_block,
            block_dim,
            shmem,
            lanes,
            rb,
            grid,
        }))
    }

    /// decode GEMV を 1 本積む (task 124 の重ね打ち経路)。
    ///
    /// 引数の並びは [`Self::moe_gemv_dev_with`] が組むものと同一
    /// (w, x, out, n_in, n_out, row_bytes, [rows_per_block, lanes])。
    /// `stream` が null なら従来と同じ既定ストリーム。
    fn launch_moe_gemv_on(
        &self,
        plan: &MoeGemvPlan,
        w: CUdeviceptr,
        x: CUdeviceptr,
        o: CUdeviceptr,
        n_in: usize,
        n_out: usize,
        stream: CUstream,
    ) -> Result<()> {
        let (mut pw, mut px, mut po) = (w, x, o);
        let (mut n_in_c, mut n_out_c, mut rb_c) =
            (n_in as c_int, n_out as c_int, plan.rb as c_int);
        let (mut rows_c, mut lanes_c) = (plan.rows_per_block as c_int, plan.lanes as c_int);
        let mut args = [
            &mut pw as *mut _ as *mut c_void,
            &mut px as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut n_in_c as *mut _ as *mut c_void,
            &mut n_out_c as *mut _ as *mut c_void,
            &mut rb_c as *mut _ as *mut c_void,
            &mut rows_c as *mut _ as *mut c_void,
            &mut lanes_c as *mut _ as *mut c_void,
        ];
        let nargs = if plan.lanes > 1 { 8 } else { 6 };
        unsafe {
            self.launch_async_on(
                stream,
                plan.f,
                (plan.grid, 1, 1),
                (plan.block_dim, 1, 1),
                plan.shmem,
                &mut args[..nargs],
            )
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn moe_gemv_dev_with(
        &self,
        ty: crate::kquant::GgmlType,
        dev_w: &DevBuffer,
        x: &[f32],
        n_in: usize,
        n_out: usize,
        out: &mut [f32],
        mode: GemvKernelMode,
    ) -> Result<bool> {
        let bs = ty.blck_size();
        if n_in == 0 || n_out == 0 || n_in % bs != 0 {
            bail!("moe_gemv_dev: 形状が不正 (n_in={n_in}, n_out={n_out}, block={bs})");
        }
        if x.len() != n_in {
            bail!("moe_gemv_dev: x の長さ {} が n_in={n_in} と違う", x.len());
        }
        if out.len() != n_out {
            bail!("moe_gemv_dev: out の長さ {} が n_out={n_out} と違う", out.len());
        }
        // カーネルの選択 (従来は `pick_moe_kernels` が先頭、fp16/v3 の選択が
        // 引数検査の後だった。PTX を読む順序だけが変わり、選ばれるカーネル・
        // 引数・丸め順は 1 つも変わらない)。
        let Some(plan) = self.plan_moe_gemv(ty, n_in, n_out, mode)? else {
            return Ok(false);
        };
        let MoeGemvPlan {
            f,
            rows_per_block,
            block_dim,
            shmem,
            lanes,
            rb,
            grid,
        } = plan;
        if dev_w.bytes() != n_out * rb {
            bail!(
                "moe_gemv_dev: 重みのデバイスバイト数 {} が n_out * row_bytes = {} と違う",
                dev_w.bytes(),
                n_out * rb
            );
        }

        self.make_current()?;
        // P-pf-moe-scratch: 入出力の一時バッファは thread_local の grow-only
        // スクラッチから取る (従来は 1 呼び出しごとに cuMemAlloc 2 本 +
        // cuMemFree 2 本を回していた。decode 中に数万回)。
        // 数値は不変: カーネル・引数・発行順はそのままで、x は n_in 要素・
        // out は n_out 要素の範囲しか読み書きしない (前回の残りは読まない)。
        MOE_SCRATCH.with(|cell| -> Result<()> {
            let mut s = cell.borrow_mut();
            let s: &mut MoeScratch = &mut s;
            MoeScratch::ensure_tagged(&mut s.x, n_in * 4, crate::mem_audit::TAG_GEMV)?;
            MoeScratch::ensure_tagged(&mut s.o, n_out * 4, crate::mem_audit::TAG_GEMV)?;
            let async_on = gemv_async_on();
            if async_on {
                MoeScratch::ensure_pin(&mut s.pin_x, n_in * 4)?;
                MoeScratch::ensure_pin(&mut s.pin_o, n_out * 4)?;
            }
            let xb = s.x.as_ref().expect("x は ensure 済み");
            let ob = s.o.as_ref().expect("o は ensure 済み");
            let tr = gemv_trace_allow();
            let t0 = tr.then(std::time::Instant::now);
            if async_on {
                // P-async: pinned → dev の H2D を非同期で積み、カーネルを積み、
                // dev → pinned の D2H を非同期で積んで、**最後に 1 回だけ**同期する。
                // 従来は「同期 H2D / カーネル / 明示 sync / 同期 D2H」で暗黙の同期が
                // 3 回入っていた。カーネル・引数・発行順・丸め順は従来と同一。
                {
                    let px = s.pin_x.as_mut().expect("pin_x は ensure 済み");
                    px.as_mut_slice::<f32>()[..n_in].copy_from_slice(x);
                    let lib = lib()?;
                    unsafe {
                        check(
                            (lib.memcpy_htod_async)(
                                xb.ptr,
                                px.ptr as *const c_void,
                                n_in * 4,
                                std::ptr::null_mut(),
                            ),
                            "cuMemcpyHtoDAsync (moe gemv)",
                        )?;
                    }
                }
                dbg_htod(n_in * 4);
                let t1 = t0.map(|_| std::time::Instant::now());
                let t_sync = crate::model::devprof::sync_start();
                unsafe {
                    let (mut pw, mut px, mut po) = (dev_w.ptr, xb.ptr, ob.ptr);
                    let (mut n_in_c, mut n_out_c, mut rb_c) =
                        (n_in as c_int, n_out as c_int, rb as c_int);
                    // v3 は rows_per_block と lanes を余分に渡す (v2 は 6 本のまま)。
                    let (mut rows_c, mut lanes_c) = (rows_per_block as c_int, lanes as c_int);
                    let mut args = [
                        &mut pw as *mut _ as *mut c_void,
                        &mut px as *mut _ as *mut c_void,
                        &mut po as *mut _ as *mut c_void,
                        &mut n_in_c as *mut _ as *mut c_void,
                        &mut n_out_c as *mut _ as *mut c_void,
                        &mut rb_c as *mut _ as *mut c_void,
                        &mut rows_c as *mut _ as *mut c_void,
                        &mut lanes_c as *mut _ as *mut c_void,
                    ];
                    let nargs = if lanes > 1 { 8 } else { 6 };
                    self.launch_async(
                        f,
                        (grid, 1, 1),
                        (block_dim, 1, 1),
                        shmem,
                        &mut args[..nargs],
                    )?;
                }
                let t2 = t0.map(|_| std::time::Instant::now());
                {
                    let po = s.pin_o.as_mut().expect("pin_o は ensure 済み");
                    let lib = lib()?;
                    unsafe {
                        check(
                            (lib.memcpy_dtoh_async)(
                                po.ptr,
                                ob.ptr,
                                n_out * 4,
                                std::ptr::null_mut(),
                            ),
                            "cuMemcpyDtoHAsync (moe gemv)",
                        )?;
                    }
                }
                self.sync()?;
                let t3 = t0.map(|_| std::time::Instant::now());
                if let Some(t) = t_sync {
                    crate::model::devprof::note_sync(t.elapsed().as_nanos() as u64);
                }
                let po = s.pin_o.as_ref().expect("pin_o は ensure 済み");
                out.copy_from_slice(&po.as_slice::<f32>()[..n_out]);
                if let (Some(a), Some(b), Some(c), Some(d)) = (t0, t1, t2, t3) {
                    eprintln!(
                        "[gemvt] {}x{} async=1 h2d={} launch={} sync={} copy={}us",
                        n_out,
                        n_in,
                        (b - a).as_micros(),
                        (c - b).as_micros(),
                        (d - c).as_micros(),
                        std::time::Instant::now().duration_since(d).as_micros()
                    );
                }
                return Ok(());
            }
            xb.copy_from(x)?;
            // H2D の計上は従来の `from_slice` と同じ (1 呼び出し = n_in * 4 B)。
            dbg_htod(n_in * 4);
            let t1 = t0.map(|_| std::time::Instant::now());
            // devprof: 起動後の待ち (sync) + 結果読み出し (同期コピー) の実測。
            // off なら `None` で Instant を取らない。
            let t_sync = crate::model::devprof::sync_start();
            unsafe {
                let (mut pw, mut px, mut po) = (dev_w.ptr, xb.ptr, ob.ptr);
                let (mut n_in_c, mut n_out_c, mut rb_c) =
                    (n_in as c_int, n_out as c_int, rb as c_int);
                // v3 は rows_per_block と lanes を余分に渡す (v2 は 6 本のまま)。
                let (mut rows_c, mut lanes_c) = (rows_per_block as c_int, lanes as c_int);
                let mut args = [
                    &mut pw as *mut _ as *mut c_void,
                    &mut px as *mut _ as *mut c_void,
                    &mut po as *mut _ as *mut c_void,
                    &mut n_in_c as *mut _ as *mut c_void,
                    &mut n_out_c as *mut _ as *mut c_void,
                    &mut rb_c as *mut _ as *mut c_void,
                    &mut rows_c as *mut _ as *mut c_void,
                    &mut lanes_c as *mut _ as *mut c_void,
                ];
                let nargs = if lanes > 1 { 8 } else { 6 };
                self.launch_async(
                    f,
                    (grid, 1, 1),
                    (block_dim, 1, 1),
                    shmem,
                    &mut args[..nargs],
                )?;
                self.sync()?;
            }
            let got: Vec<f32> = ob.to_vec(n_out)?;
            let t3 = t0.map(|_| std::time::Instant::now());
            if let Some(t) = t_sync {
                crate::model::devprof::note_sync(t.elapsed().as_nanos() as u64);
            }
            out.copy_from_slice(&got);
            if let (Some(a), Some(b), Some(c)) = (t0, t1, t3) {
                eprintln!(
                    "[gemvt] {}x{} async=0 h2d={} launch+sync+d2h={}us",
                    n_out,
                    n_in,
                    (b - a).as_micros(),
                    (c - b).as_micros()
                );
            }
            Ok(())
        })?;
        Ok(true)
    }

    /// P39: expert の VRAM 常駐 GEMV 用の口。`shared_ctx` を隠したまま
    /// 既に VRAM にある `DevBuffer` 1 本で GEMV する。
    ///
    /// `weights_for_gguf` (dense の uid 登録簿) は**通さない**ので、常駐の
    /// 置き場所が 2 か所に分かれることはない。
    ///
    /// `Ok(false)` は「この型・この環境では GPU で回せない」。呼び出し側は
    /// CPU へ落ちること (fail closed)。
    #[allow(clippy::too_many_arguments)]
    pub fn moe_gemv_dev_buf(
        ty: crate::kquant::GgmlType,
        dev_w: &DevBuffer,
        x: &[f32],
        n_in: usize,
        n_out: usize,
        out: &mut [f32],
    ) -> Result<bool> {
        let Some(ctx) = shared_ctx() else {
            return Ok(false);
        };
        if let Err(e) = ctx.make_current() {
            tracing::error!("CUDA cuCtxSetCurrent failed (expert gemv): {e:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            return Ok(false);
        }
        ctx.moe_gemv_dev(ty, dev_w, x, n_in, n_out, out)
    }


    /// P39: expert を VRAM に載せてよいか (カーネルと型が対応しているか)。
    ///
    /// 載せてから `false` で落ちると VRAM が無駄に埋まるので、**載せる前**に
    /// これを確かめる。`DENNO_CUDA` が無効なら false。
    pub fn moe_gemv_dev_ready(ty: crate::kquant::GgmlType, k: usize) -> bool {
        if !cuda_enabled() || gguf_row_bytes(ty, k).is_none() {
            return false;
        }
        shared_ctx()
            .map(|c| c.f_moe.is_some())
            .unwrap_or(false)
    }

    /// P-PF-GB: prefill 用の量子 GEMM (nt トークン一括, `kernels_gemm.ptx`)。
    ///
    /// 数値契約は **解除済み** (2026-10-28 のオペレーター指示)。`-fmad=true` で
    /// JIT するので FMA 融合が入る。prefill の比較は argmax / 出力 md5 で行う。
    ///
    /// `false` を返したら呼び出し側は CPU バッチへ落ちること (fail closed)。
    /// 落ちる条件: 未対応の型 / nt が 1 か 128 超 / 共有メモリが 46 KiB 超 /
    /// GPU 無効 / `DENNO_GPU_GEMM=0`。
    pub fn moe_gemm_dev(
        &self,
        ty: crate::kquant::GgmlType,
        dev_w: &DevBuffer,
        x: &[f32],
        nt: usize,
        n_in: usize,
        n_out: usize,
        out: &mut [f32],
    ) -> Result<bool> {
        use crate::kquant::GgmlType as T;
        const ROWS: usize = 16; // kernels_gemm.cu の GEMM_ROWS
        const NTG_MAX: usize = 8; // kernels_gemm.cu の GEMM_NTG_MAX
        let Some(fs) = self.f_gemm_q else {
            return Ok(false);
        };
        if nt <= 1 || nt > ROWS * NTG_MAX {
            return Ok(false);
        }
        let (f, rb, blk) = match ty {
            T::Q8_0 => (fs[0], (n_in / 32) * 34, 32usize),
            T::Q5_1 => (fs[1], (n_in / 32) * 24, 32usize),
            T::Q4K => (fs[2], (n_in / 256) * 144, 256usize),
            T::Q5K => (fs[3], (n_in / 256) * 176, 256usize),
            _ => return Ok(false),
        };
        if n_in == 0 || n_out == 0 || n_in % blk != 0 {
            return Ok(false);
        }
        if x.len() != nt * n_in || out.len() != nt * n_out {
            bail!(
                "moe_gemm_dev: 形状が不正 (nt={nt}, n_in={n_in}, n_out={n_out}, \
                 x={}, out={})",
                x.len(),
                out.len()
            );
        }
        if dev_w.bytes() != n_out * rb {
            bail!(
                "moe_gemm_dev: 重みのデバイスバイト数 {} が n_out * row_bytes = {} と違う",
                dev_w.bytes(),
                n_out * rb
            );
        }
        // 動的共有メモリ: 1 ブロックぶんのデコード済み f32 (ROWS × blk) だけ。
        // 行の生バイトはカーネルが global から直接読む (丸ごと載せると k=5120 で
        // 62 KiB になり 48 KiB の既定を超える = 実モデルで 1 度も発火しなかった原因)。
        let shmem = ROWS * blk * 4;
        if shmem > 46_000 {
            return Ok(false);
        }
        self.make_current()?;
        let grid = ((n_out + ROWS - 1) / ROWS) as u32;
        MOE_SCRATCH.with(|cell| -> Result<()> {
            let mut s = cell.borrow_mut();
            MoeScratch::ensure_tagged(&mut s.x, nt * n_in * 4, crate::mem_audit::TAG_GEMV)?;
            MoeScratch::ensure_tagged(&mut s.o, nt * n_out * 4, crate::mem_audit::TAG_GEMV)?;
            let xb = s.x.as_ref().expect("x は ensure 済み");
            let ob = s.o.as_ref().expect("o は ensure 済み");
            xb.copy_from(x)?;
            dbg_htod(nt * n_in * 4);
            // devprof: 起動後の待ち (sync) + 結果読み出し (同期コピー) の実測。
            let t_sync = crate::model::devprof::sync_start();
            unsafe {
                let (mut pw, mut px, mut po) = (dev_w.ptr, xb.ptr, ob.ptr);
                let (mut nt_c, mut ni_c, mut no_c, mut rb_c) =
                    (nt as c_int, n_in as c_int, n_out as c_int, rb as c_int);
                let mut args = [
                    &mut pw as *mut _ as *mut c_void,
                    &mut px as *mut _ as *mut c_void,
                    &mut po as *mut _ as *mut c_void,
                    &mut nt_c as *mut _ as *mut c_void,
                    &mut ni_c as *mut _ as *mut c_void,
                    &mut no_c as *mut _ as *mut c_void,
                    &mut rb_c as *mut _ as *mut c_void,
                ];
                self.launch_async(f, (grid, 1, 1), (ROWS as u32, 16, 1), shmem as u32, &mut args)?;
                self.sync()?;
            }
            let got: Vec<f32> = ob.to_vec(nt * n_out)?;
            if let Some(t) = t_sync {
                crate::model::devprof::note_sync(t.elapsed().as_nanos() as u64);
            }
            out[..nt * n_out].copy_from_slice(&got);
            Ok(())
        })?;
        Ok(true)
    }
}

// ---------------------------------------------------------------------------
// P-pf-moe-scratch: `moe_gemv_dev` の入出力スクラッチ (thread_local, grow-only)
// ---------------------------------------------------------------------------
//
// 背景 (pf_arena の調査 = 85cd04d8): `--max-ctx` を上げると初回リクエストの
// 重み登録が失敗する (`要求 644 MiB / 空き 7 MiB`)。max_ctx は GPU 側の確保に
// 入っていないので、残る原因は「1 GEMV = cuMemAlloc 2 本 + cuMemFree 2 本」を
// decode 中に数万回繰り返すことによる断片化。行列の形はモデルで固定なので、
// スレッドごとに grow-only で持ち回す (既存 `Scratch` と同じ規約)。
//
// - 確保するのは「今の容量 < 今回の要求」のときだけ。より大きい 1 本に
//   置き換え、古い方はその場で drop = cuMemFree する (毎回は free しない)。
// - 数値は不変: カーネル・引数・発行順・丸め順は 1 つも変えない。x は毎回
//   `n_in` 要素を先頭から書き、out は `n_out` 要素だけ読む (前回の残りは読まない)。
// - スレッド終了時の解放はベストエフォート (`Scratch` と同じ規約)。
struct MoeScratch {
    x: Option<DevBuffer>, // >= n_in * 4 B
    o: Option<DevBuffer>, // >= n_out * 4 B
    // P-async: pinned の staging (H2D / D2H を async にするため)。
    // [`gemv_async_on`] が真のときだけ確保する (既定 on、`DENNO_GEMV_ASYNC=0` で off)。
    pin_x: Option<PinMem>,
    pin_o: Option<PinMem>,
}

thread_local! {
    static MOE_SCRATCH: std::cell::RefCell<MoeScratch> =
        std::cell::RefCell::new(MoeScratch { x: None, o: None, pin_x: None, pin_o: None });
}

/// P-async: decode の GEMV を「pinned staging + async コピー + 同期 1 回」で回すか。
///
/// 既定 **on** (`DENNO_GEMV_ASYNC=0` で従来の同期経路に戻る)。従来経路は
/// `copy_from` (同期 H2D) → カーネル → `sync` → `to_vec` (同期 D2H) で、
/// **カーネル・引数・発行順・丸め順は同じ**、コピーの API だけが変わる
/// (バイト列は同一)。実測 2026-10-30: 26.15 -> 25.66 s (118 tok)、
/// 出力 md5 は v1 と一致 (`3b77a3b996fd`、12 ラン全部同じ)。
pub fn gemv_async_on() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        !matches!(
            std::env::var("DENNO_GEMV_ASYNC").ok().as_deref(),
            Some("0") | Some("off") | Some("false")
        )
    })
}

/// P-gemv2: x 先読み版の GEMV カーネルを使うか (既定 **on**)。
///
/// `DENNO_GEMV_V2=0` で v1 に戻る。v1 と v2 は同じ数値契約なので、切り替えても
/// 出力ビットは一致する (速度だけが変わる)。
pub fn moe_gemv_v2_on() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        !matches!(
            std::env::var("DENNO_GEMV_V2").ok().as_deref(),
            Some("0") | Some("off") | Some("false")
        )
    })
}

/// decode GEMV のレーン分割版 (`kernels_moe_v3.cu`、4 レーンまたは 2 レーン) を
/// 使うか (既定 **off**)。
///
/// `DENNO_GEMV_V3=1` のときだけ v3。未設定 / `0` / `off` / `false` では v2 (既定
/// 経路) のままで、1 バイトも挙動が変わらない。
///
/// v3 は 1 行の累積を lanes レーンで分担するので **v2 とビット一致しない** (加算順が
/// 変わる。prefill の GPU バッチ GEMM と同じ扱い = 契約の外)。既定で使わない理由。
pub fn moe_gemv_v3_on() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        matches!(
            std::env::var("DENNO_GEMV_V3").ok().as_deref(),
            Some("1") | Some("on") | Some("true")
        )
    })
}

/// v3 のレーン数 (4 / 2 / 0 = v2)。純関数なので GPU 無しで検証できる。
///
/// v3 のレーン l は k を lanes 等分した連続区間 `[l*k/lanes, (l+1)*k/lanes)` を
/// 持ち、区間の中で量子ブロック (最小 32 要素) を丸ごと読む。したがって区間長
/// k/lanes が 32 の倍数であることが要る:
///
/// - k が 128 の倍数 → 4 レーン (区間長 k/4 が 32 の倍数)
/// - k が 64 の倍数で 128 の倍数でない → 2 レーン (区間長 k/2 が 32 の倍数)
/// - それ以外 → 0 (= v2 へ落ちる。panic しない)
///
/// 実形: 2560 / 5120 / 6144 は 4 レーン、320 (`output_hc_up` の k) は 2 レーン、
/// 1000 は v2。2 レーン経路はカーネル引数 `lanes` で切り替える (カーネルは 1 組のまま)。
pub fn moe_gemv_v3_lanes(k: usize) -> usize {
    if k >= 128 && k % 128 == 0 {
        4
    } else if k >= 64 && k % 64 == 0 {
        2
    } else {
        0
    }
}

/// v3 (4 レーン版または 2 レーン版) が使える k か。
pub fn moe_gemv_v3_k_ok(k: usize) -> bool {
    moe_gemv_v3_lanes(k) > 0
}

/// v3 の 1 ブロックあたりの行数 (`DENNO_GEMV_V3_ROWS`、既定 8)。
///
/// 8 / 16 / 32 / 64 のどれか。それ以外 (未設定・空・数値でない・対象外の値) は 64。
/// blockDim = rows * lanes、grid = ceil(n_out / rows) になる。n_out=2560 の形状では
/// rows=64 で 40 block、rows=8 で 320 block (5090 の 170 SM を埋める)。
/// 既定 8 は main の実測 (rows 8 が最良) による。kernels_moe_v3.cu の MOE_V3_ROWS_DEFAULT は引数の既定値なので、実際の値はホスト側が渡す。
pub fn moe_gemv_v3_rows() -> usize {
    // テストが rows を振って 1 プロセスで全組み合わせを回すための上書き
    // (0 = env を見る)。env は OnceLock で 1 回しか読めないため。
    #[cfg(test)]
    {
        let f = V3_ROWS_FORCE.load(std::sync::atomic::Ordering::Relaxed);
        if f != 0 {
            return f;
        }
    }
    static ROWS: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *ROWS.get_or_init(|| {
        let raw = std::env::var("DENNO_GEMV_V3_ROWS").ok();
        let rows = parse_v3_rows(raw.as_deref());
        if let Some(v) = raw.as_deref() {
            if !matches!(v.trim(), "8" | "16" | "32" | "64") {
                eprintln!("[gemv-v3] DENNO_GEMV_V3_ROWS={v:?} は 8/16/32/64 以外 → {rows} を使う");
            }
        }
        rows
    })
}

/// テストが rows/block を強制するための上書き (0 で env の値に戻る)。
#[cfg(test)]
static V3_ROWS_FORCE: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// テストから rows/block を固定する (`0` で env に戻す)。
#[cfg(test)]
pub(crate) fn set_v3_rows_for_test(rows: usize) {
    assert!(rows == 0 || matches!(rows, 8 | 16 | 32 | 64));
    V3_ROWS_FORCE.store(rows, std::sync::atomic::Ordering::Relaxed);
}

/// `DENNO_GEMV_V3_ROWS` の生値 → rows/block (純関数。真理値表はテストで固定)。
///
/// 既定は 8 (main の実測: rows 8 / 16 / 32 / 64 で decode 122.6 / 142.3 / 135.0 /
/// 132.3 ms/token。8 は blockDim = 8 x 4 = 32 = 1 warp で、n_out=2560 でも
/// grid が 320 block になり 170 SM を埋められるため)。
pub fn parse_v3_rows(raw: Option<&str>) -> usize {
    match raw.map(str::trim) {
        Some("8") => 8,
        Some("16") => 16,
        Some("32") => 32,
        Some("64") => 64,
        _ => 8,
    }
}

/// v3 カーネルの引数の数 (w, x, out, n_in, n_out, row_bytes, rows_per_block, lanes)。
/// 旧版 (task 66) は 6 本。数を取り違えたまま起動すると **黙って別の行を書く**ので、
/// PTX を読む前に `.param` を数えて弾く (`ptx_entry_params`)。
const V3_NARGS: usize = 8;

/// v3 のカーネル名 (PTX から取る順 = `ki` の順 = 量子型の順)。
const V3_KERNEL_NAMES: [&str; 4] = [
    "dno_gemv_q8_0_v3",
    "dno_gemv_q5_1_v3",
    "dno_gemv_q4k_v3",
    "dno_gemv_q5k_v3",
];

/// PTX テキストの entry `name` の引数の個数 (`.param` 行を数える)。
///
/// nvcc は引数名を `NAME_param_N` にするので、`.visible .entry NAME(` の次から
/// `)` の行までの `.param` 行を数えれば個数が分かる。GPU 無しで検証できる
/// (テスト `v3_ptx_param_count_matches_nvcc_output` がコミット済みの
/// `kernels_moe_v2.ptx` で 6 本を数えて、nvcc の実出力で成立することを固定する)。
fn ptx_entry_params(ptx: &str, name: &str) -> Option<usize> {
    let mut lines = ptx.lines();
    while let Some(l) = lines.next() {
        let head = l.trim_start();
        let after = match head.strip_prefix(".visible .entry ") {
            Some(rest) => rest,
            None => match head.strip_prefix(".entry ") {
                Some(rest) => rest,
                None => continue,
            },
        };
        if !after.starts_with(name) || !after[name.len()..].trim_start().starts_with('(') {
            continue;
        }
        let mut n = 0usize;
        for body in lines.by_ref() {
            let t = body.trim();
            if t.starts_with(')') {
                return Some(n);
            }
            if t.starts_with(".param ") {
                n += 1;
            }
        }
        return None;
    }
    None
}

/// task 137: `dno_gdn_scan_sig` の ABI (引数の個数) が `dno_gdn_scan` と
/// 同じであること。両者はゲート式 1 行以外が同一のカーネルなので、引数の
/// 個数も同じでなければならない (現状 23)。
///
/// 個数が食い違う PTX を cuLaunchKernel で起動すると、足りない引数は**不定**の
/// まま読まれ、エラーも NaN も出ずに別の行を書く。ホストの起動コードと PTX が
/// ずれたとき (PTX 再生成の取り違え) に黙って壊れないよう、モジュールロード時に
/// ここで弾いて CPU 経路へ落とす。GPU 無しでテストできる
/// (`gdn_scan_sig_abi_matches_scan_in_committed_ptx`)。
fn gdn_scan_sig_abi_ok(ptx: &str) -> bool {
    match (
        ptx_entry_params(ptx, "dno_gdn_scan"),
        ptx_entry_params(ptx, "dno_gdn_scan_sig"),
    ) {
        (Some(base), Some(sig)) => sig == base,
        _ => false,
    }
}

/// v3 のカーネル一式。4 本そろって初めて `Some`。
struct V3Kernels {
    #[allow(dead_code)]
    module: CUmodule,
    f: [CUfunction; 4],
}

// 生ハンドル (CudaCtx / GroupedKernels と同じ規約)。
unsafe impl Send for V3Kernels {}
unsafe impl Sync for V3Kernels {}

static V3_KERNELS: OnceLock<Option<V3Kernels>> = OnceLock::new();

/// v3 の PTX の置き場所。`DENNO_GEMV_V3_PTX` があればそれ、無ければビルド時の
/// クレートディレクトリ配下 `kernels/kernels_moe_v3.ptx`。
fn gemv_v3_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_GEMV_V3_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_moe_v3.ptx"),
    }
}

/// v3 のカーネルを取得する (初回だけ PTX を読む)。
///
/// 失敗は `None` をキャッシュする (= 二度と試さない)。読めなかったときは
/// **1 行だけ**警告を出し、呼び出し側は v2 へ落ちる。呼ぶ前に必ず context を
/// current にしておくこと (cuModuleLoadData は current context に入る)。
fn gemv_v3_kernels() -> Option<&'static V3Kernels> {
    V3_KERNELS
        .get_or_init(|| {
            let path = gemv_v3_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(e) => {
                    eprintln!(
                        "[gemv-v3] PTX が読めない ({}) : {e} → v2 へ",
                        path.display()
                    );
                    return None;
                }
            };
            // 引数の数が合わない PTX (task 66 の旧版 = 6 引数) を読むと、
            // cuLaunchKernel が rows_per_block / lanes を渡さないまま起動して
            // 黙って別の行を書く。**モジュールを読む前に** ABI を確かめて弾く。
            let text = String::from_utf8_lossy(&image);
            let mut short: Vec<&str> = Vec::new();
            for name in V3_KERNEL_NAMES {
                if ptx_entry_params(&text, name) != Some(V3_NARGS) {
                    short.push(name);
                }
            }
            if !short.is_empty() {
                eprintln!(
                    "[gemv-v3] PTX の引数が {} 本でない ({}) → v2 へ。\
                     `bash build_ptx.sh moe_v3` で再生成する",
                    V3_NARGS,
                    short.join(", ")
                );
                return None;
            }
            image.push(0); // cuModuleLoadData は NUL 終端の PTX を期待する
            let lib = lib().ok()?;
            unsafe {
                let mut module: CUmodule = std::ptr::null_mut();
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    eprintln!("[gemv-v3] cuModuleLoadData 失敗 → v2 へ");
                    return None;
                }
                let mut f: [CUfunction; 4] = [std::ptr::null_mut(); 4];
                for (k, name) in V3_KERNEL_NAMES.iter().enumerate() {
                    let mut cname = name.as_bytes().to_vec();
                    cname.push(0); // cuModuleGetFunction は NUL 終端の名前を期待する
                    if (lib.module_get_function)(&mut f[k], module, cname.as_ptr() as *const c_char)
                        != CUDA_SUCCESS
                    {
                        eprintln!("[gemv-v3] PTX に {name} が無い → v2 へ");
                        return None;
                    }
                }
                Some(V3Kernels { module, f })
            }
        })
        .as_ref()
}

/// v3 の PTX が読めているか (テスト専用。**context を current にしてから**呼ぶこと。
/// 失敗を `OnceLock` に焼き付けるので、本番経路からは呼ばない)。
#[cfg(test)]
pub(crate) fn moe_gemv_v3_loaded() -> bool {
    gemv_v3_kernels().is_some()
}

// ---------------------------------------------------------------------------
// P-fp16 (task 108): fast mode の fp16 GEMV (`kernels_moe_fp16.cu`)
// ---------------------------------------------------------------------------

/// decode GEMV で使うカーネルの選択 (テストが 1 経路に固定するための口も兼ねる)。
///
/// - [`GemvKernelMode::V2`]: ビット一致契約の既定経路 (CPU と 1 bit も違わない)。
/// - [`GemvKernelMode::V3`]: レーン分割 (`DENNO_GEMV_V3=1`)。加算順が変わるが
///   dequant は f32 のまま (契約の外 = prefill のバッチ GEMM と同じ扱い)。
/// - [`GemvKernelMode::Fp16`]: fast mode (`DENNO_GEMV_FP16=1`)。fp16 dequant +
///   half2 FMA で **丸めも精度も変える** (2026-11-01 オペレーター承認の契約変更)。
///   品質基準と誤差しきい値 (行列全体の相対 2e-2) は REPORT_P108.md。
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) enum GemvKernelMode {
    V2,
    V3,
    Fp16,
}

/// `DENNO_GEMV_FP16` の生値 → fast mode の on/off (純関数。真理値表はテストで固定)。
fn parse_gemv_fp16(raw: Option<&str>) -> bool {
    matches!(raw, Some("1") | Some("on") | Some("true"))
}

/// decode GEMV が使うカーネル一式を env から決める (`moe_gemv_dev` と
/// task 124 の重ね打ち経路で共有する)。優先順は fp16 → v3 → v2。
pub(crate) fn gemv_kernel_mode() -> GemvKernelMode {
    if moe_gemv_fp16_on() {
        GemvKernelMode::Fp16
    } else if moe_gemv_v3_on() {
        GemvKernelMode::V3
    } else {
        GemvKernelMode::V2
    }
}

/// fast mode (`kernels_moe_fp16.cu`、fp16 dequant + half2 FMA) を使うか (既定 **off**)。
///
/// `DENNO_GEMV_FP16=1` のときだけ有効。v3 と同じ降下経路に乗る: 対応型は
/// Q8_0 / Q5_1 / Q4_K の 3 つ (Q5_K は対象外)、k が 64 の倍数でない、PTX が
/// 読めない / 旧 ABI のときは v3 (on なら) → v2 へ落ちる。env 未指定では
/// 1 バイトも挙動が変わらない。
pub fn moe_gemv_fp16_on() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| parse_gemv_fp16(std::env::var("DENNO_GEMV_FP16").ok().as_deref()))
}

/// fp16 カーネルが対応する型か (純関数。Q5_K とそれ以外は v3 / v2 へ落ちる)。
fn gemv_fp16_ty_ok(ty: crate::kquant::GgmlType) -> bool {
    use crate::kquant::GgmlType as T;
    matches!(ty, T::Q8_0 | T::Q5_1 | T::Q4K)
}

/// fp16 カーネルの引数の数 (v3 と同じ 8 本: w, x, out, n_in, n_out, row_bytes,
/// rows_per_block, lanes)。検査は v3 と同じ `ptx_entry_params` を使う。
const FP16_NARGS: usize = 8;

/// fp16 カーネル名 (`ki` の順 = Q8_0 / Q5_1 / Q4_K。Q5_K は対象外)。
const FP16_KERNEL_NAMES: [&str; 3] = [
    "dno_gemv_q8_0_fp16",
    "dno_gemv_q5_1_fp16",
    "dno_gemv_q4k_fp16",
];

/// fp16 カーネル一式。3 本そろって初めて `Some`。
struct Fp16Kernels {
    #[allow(dead_code)]
    module: CUmodule,
    f: [CUfunction; 3],
}

// 生ハンドル (V3Kernels と同じ規約)。
unsafe impl Send for Fp16Kernels {}
unsafe impl Sync for Fp16Kernels {}

static FP16_KERNELS: OnceLock<Option<Fp16Kernels>> = OnceLock::new();

/// fp16 の PTX の置き場所。`DENNO_GEMV_FP16_PTX` があればそれ、無ければビルド時の
/// クレートディレクトリ配下 `kernels/kernels_moe_fp16.ptx`。
fn gemv_fp16_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_GEMV_FP16_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_moe_fp16.ptx"),
    }
}

/// fp16 カーネルを取得する (初回だけ PTX を読む)。
///
/// 失敗は `None` をキャッシュする (= 二度と試さない)。読めなかったときは
/// **1 行だけ**警告を出し、呼び出し側は v3 / v2 へ落ちる。呼ぶ前に必ず context を
/// current にしておくこと (cuModuleLoadData は current context に入る)。
fn gemv_fp16_kernels() -> Option<&'static Fp16Kernels> {
    FP16_KERNELS
        .get_or_init(|| {
            let path = gemv_fp16_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(e) => {
                    eprintln!(
                        "[gemv-fp16] PTX が読めない ({}) : {e} → v3/v2 へ。\
                         `bash build_ptx.sh moe_fp16` で再生成する",
                        path.display()
                    );
                    return None;
                }
            };
            // 引数の数が合わない PTX を読むと、cuLaunchKernel が余分な引数を無視 /
            // 足りない引数を不定のまま起動して**黙って別の行を書く**。モジュールを
            // 読む前に ABI を確かめて弾く (v3 と同じ規約)。
            let text = String::from_utf8_lossy(&image);
            let mut short: Vec<&str> = Vec::new();
            for name in FP16_KERNEL_NAMES {
                if ptx_entry_params(&text, name) != Some(FP16_NARGS) {
                    short.push(name);
                }
            }
            if !short.is_empty() {
                eprintln!(
                    "[gemv-fp16] PTX の引数が {} 本でない ({}) → v3/v2 へ。\
                     `bash build_ptx.sh moe_fp16` で再生成する",
                    FP16_NARGS,
                    short.join(", ")
                );
                return None;
            }
            image.push(0); // cuModuleLoadData は NUL 終端の PTX を期待する
            let lib = lib().ok()?;
            unsafe {
                let mut module: CUmodule = std::ptr::null_mut();
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    eprintln!("[gemv-fp16] cuModuleLoadData 失敗 → v3/v2 へ");
                    return None;
                }
                let mut f: [CUfunction; 3] = [std::ptr::null_mut(); 3];
                for (k, name) in FP16_KERNEL_NAMES.iter().enumerate() {
                    let mut cname = name.as_bytes().to_vec();
                    cname.push(0); // cuModuleGetFunction は NUL 終端の名前を期待する
                    if (lib.module_get_function)(&mut f[k], module, cname.as_ptr() as *const c_char)
                        != CUDA_SUCCESS
                    {
                        eprintln!("[gemv-fp16] PTX に {name} が無い → v3/v2 へ");
                        return None;
                    }
                }
                Some(Fp16Kernels { module, f })
            }
        })
        .as_ref()
}

/// fp16 の PTX が読めているか (テスト専用。**context を current にしてから**呼ぶこと。
/// 失敗を `OnceLock` に焼き付けるので、本番経路からは呼ばない)。
#[cfg(test)]
pub(crate) fn moe_gemv_fp16_loaded() -> bool {
    gemv_fp16_kernels().is_some()
}

/// 一時診断: 最初の N 回だけ GEMV の内訳 (H2D / 起動 / 同期 / D2H) を stderr に出す。
/// `DENNO_GEMV_TRACE=N` (未設定 = 無効)。
fn gemv_trace_allow() -> bool {
    use std::sync::atomic::{AtomicUsize, Ordering};
    static LEFT: std::sync::OnceLock<AtomicUsize> = std::sync::OnceLock::new();
    let left = LEFT.get_or_init(|| {
        let n = std::env::var("DENNO_GEMV_TRACE")
            .ok()
            .and_then(|s| s.parse::<usize>().ok())
            .unwrap_or(0);
        AtomicUsize::new(n)
    });
    left.fetch_update(Ordering::Relaxed, Ordering::Relaxed, |v| {
        if v == 0 {
            None
        } else {
            Some(v - 1)
        }
    })
    .is_ok()
}

/// スクラッチの確保サイズを決める純関数 (GPU 無しで検証できる)。
///
/// - `cur >= want` -> `None` (確保しない = 同じサイズの繰り返しで増えない)
/// - `cur <  want` -> `Some(want)` (そのサイズへ grow。0 バイトは確保しない)
///
/// 返す値は `want` に対して単調 (要求が増えれば返る値も増える)。
fn moe_scratch_alloc_bytes(cur: usize, want: usize) -> Option<usize> {
    if cur >= want {
        None
    } else {
        Some(want.max(1))
    }
}

impl MoeScratch {
    fn ensure(cap: &mut Option<DevBuffer>, want: usize) -> Result<()> {
        Self::ensure_tagged(cap, want, crate::mem_audit::TAG_OTHER)
    }
    /// task 149: 台帳のタグ付き [`Self::ensure`]。
    fn ensure_tagged(cap: &mut Option<DevBuffer>, want: usize, tag: &'static str) -> Result<()> {
        let cur = cap.as_ref().map(|b| b.bytes()).unwrap_or(0);
        if let Some(bytes) = moe_scratch_alloc_bytes(cur, want) {
            *cap = Some(DevBuffer::alloc_tagged(bytes, tag)?);
        }
        Ok(())
    }

    /// P-async: pinned staging の grow-only 確保。
    fn ensure_pin(cap: &mut Option<PinMem>, bytes: usize) -> Result<()> {
        if cap.as_ref().map(|b| b.bytes).unwrap_or(0) < bytes {
            *cap = Some(PinMem::alloc(bytes)?);
        }
        Ok(())
    }
}

// ===========================================================================
// P40: grouped expert GEMM (可変 m・1 起動) — `kernels_gemm_grouped.cu`
// ===========================================================================
//
// 目的: prefill で expert ごとに回している GEMM (expert × 3 行列) を、
// 「層全体の segment 表 + パック済み重み」の 2 起動 (gate+up+silu / down) に
// まとめる。重みは `model::moe_grouped::pack_expert_weights` の
// `[gate(e0..eN)][up(e0..eN)][down(e0..eN)]` をそのまま渡す。
//
// 既定 off (`DENNO_MOE_GROUPED_GPU=1` で有効)。off のとき呼び出し側はこの節に
// 入らないので、既存の per-expert 経路は 1 バイトも変わらない。
//
// PTX を `include_bytes!` しない理由: `kernels_gemm_grouped.ptx` の生成は
// メインセッションの担当で、このコンテナには nvcc が無い。埋め込むと PTX が
// 置かれるまで `cargo check --lib` が通らない。起動時に 1 回だけファイルから
// 読む (`DENNO_MOE_GROUPED_PTX` で差し替え可)。読めなければ None を返して
// CPU へ落ちる (fail closed)。
//
// 数値: prefill はビット一致契約の外 (2026-10-28)。カーネルは FMA 融合と
// 共有メモリ経由のデコードを使うので、CPU 参照とは丸め順が違う。差は呼び出し側
// (`model::moe_grouped_gpu`) が argmax / max abs diff で出す。

/// パック済み重みの 1 ブロック (gate / up / down のどれか) の形。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GroupedMatrix {
    pub ty: crate::kquant::GgmlType,
    /// 行長 (量子型のブロック長で割り切れること)
    pub n_in: usize,
    /// 行数
    pub n_out: usize,
    /// 1 行のバイト数 ([`crate::model::moe_expert::row_bytes`] と同じ値)
    pub row_bytes: usize,
    /// パック済みバッファ内のこのブロックの先頭バイト
    pub w_off: usize,
}

impl GroupedMatrix {
    /// カーネルに渡す (量子型 id, ブロック要素数, ブロックバイト数)。
    /// 未対応の型は `None` (呼び出し側は CPU へ落ちる)。
    pub fn kernel_layout(&self) -> Option<(i32, usize, usize)> {
        use crate::kquant::GgmlType as T;
        // kernels_gemm_grouped.cu の dno_gr_deq の分岐と 1:1 で対応する。
        match self.ty {
            T::Q8_0 => Some((0, 32, 34)),
            T::Q5_1 => Some((1, 32, 24)),
            T::Q4K => Some((2, 256, 144)),
            T::Q5K => Some((3, 256, 176)),
            _ => None,
        }
    }

    /// 1 expert ぶんのバイト数 (パック済みブロック内のストライド)。
    pub fn expert_bytes(&self) -> Option<usize> {
        self.n_out.checked_mul(self.row_bytes)
    }

    /// 形の検査 (起動前)。`Ok(())` 以外は起動しない。
    pub fn check(&self) -> Result<()> {
        let Some((_, blkj, _)) = self.kernel_layout() else {
            bail!("grouped GEMM の対象外の量子型 {:?}", self.ty);
        };
        if self.n_in == 0 || self.n_out == 0 || self.row_bytes == 0 {
            bail!(
                "grouped GEMM: 形に 0 がある (n_in={}, n_out={}, row_bytes={})",
                self.n_in,
                self.n_out,
                self.row_bytes
            );
        }
        if self.n_in % blkj != 0 {
            bail!(
                "grouped GEMM: n_in={} がブロック長 {blkj} で割り切れない",
                self.n_in
            );
        }
        let want_rb = self.n_in / blkj * match self.ty {
            crate::kquant::GgmlType::Q8_0 => 34,
            crate::kquant::GgmlType::Q5_1 => 24,
            crate::kquant::GgmlType::Q4K => 144,
            crate::kquant::GgmlType::Q5K => 176,
            _ => 0,
        };
        if want_rb != self.row_bytes {
            bail!(
                "grouped GEMM: row_bytes={} が型から決まる {want_rb} と違う",
                self.row_bytes
            );
        }
        Ok(())
    }
}

/// 1 起動ぶんの grid / block / 動的共有メモリ (GPU 無しで検証できる純関数)。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GroupedLaunch {
    pub grid: (u32, u32, u32),
    pub block: (u32, u32, u32),
    pub smem: u32,
}

/// groupd GEMM の起動形を決める。`None` = この形では起動しない (CPU へ)。
///
/// - grid.x = segment 数、grid.y = 行タイル (ceil(n_out / 16))、
///   grid.z = トークンタイル (ceil(m_max / 16))。
/// - 1 ブロックは 16 行 × 16 トークン。m < 16 の expert では z の余分なブロックが
///   即 return する (実形の平均 m は 10 なので 1 タイルで足りる)。
/// - 共有メモリは「デコード済み f32 の 1 ブロックぶん」だけ。
///   `nmat` 本の行列を同時にデコードするので `16 * blkj * 4 * nmat` バイト。
pub fn grouped_launch_plan(
    nseg: usize,
    m_max: usize,
    n_out: usize,
    blkj: usize,
    nmat: usize,
) -> Result<Option<GroupedLaunch>> {
    const ROWS: usize = 16; // kernels_gemm_grouped.cu の GR_ROWS
    const TG: usize = 16; // 同 GR_TG
    if nseg == 0 || m_max == 0 || n_out == 0 || blkj == 0 || nmat == 0 {
        return Ok(None);
    }
    let tiles_y = n_out.div_ceil(ROWS);
    let tiles_z = m_max.div_ceil(TG);
    // grid の上限 (y/z は 65535)。実形 (n_out 2560 / m_max 128) では届かない。
    if nseg > u32::MAX as usize || tiles_y > 65535 || tiles_z > 65535 {
        return Ok(None);
    }
    let smem = ROWS
        .checked_mul(blkj)
        .and_then(|v| v.checked_mul(4))
        .and_then(|v| v.checked_mul(nmat))
        .ok_or_else(|| anyhow::anyhow!("grouped GEMM: 共有メモリ量が usize を溢れる"))?;
    // 48 KiB の既定を超えると起動できない (実績: 62 KiB で全滅)。
    if smem > 46_000 {
        return Ok(None);
    }
    Ok(Some(GroupedLaunch {
        grid: (nseg as u32, tiles_y as u32, tiles_z as u32),
        block: (ROWS as u32, TG as u32, 1),
        smem: smem as u32,
    }))
}

/// `DENNO_MOE_GROUPED_GPU` の値の解釈 (純関数。env を読むのは 1 箇所だけ)。
pub fn moe_grouped_gpu_from_value(v: Option<&str>) -> bool {
    matches!(v, Some("1") | Some("on") | Some("true"))
}

/// grouped expert GEMM を試すか (既定 off)。
///
/// `DENNO_MOE_GROUPED_GPU=1` / `on` / `true` のときだけ true。値はプロセスで
/// 1 回だけ読む (テストは [`moe_grouped_gpu_from_value`] を直接叩く)。
pub fn moe_grouped_gpu_enabled() -> bool {
    static GATE: OnceLock<bool> = OnceLock::new();
    *GATE.get_or_init(|| {
        moe_grouped_gpu_from_value(std::env::var("DENNO_MOE_GROUPED_GPU").ok().as_deref())
    })
}

/// grouped GEMM のカーネル (PTX を起動時に 1 回だけ読む)。
struct GroupedKernels {
    #[allow(dead_code)]
    module: CUmodule,
    gate_up: CUfunction,
    down: CUfunction,
}

// 生ハンドル (context / module / function)。CUcontext はスレッドごとに current を
// 設定して使うハンドルで、所有権の移動を伴わない (CudaCtx と同じ規約)。
unsafe impl Send for GroupedKernels {}
unsafe impl Sync for GroupedKernels {}

static GROUPED_KERNELS: OnceLock<Option<GroupedKernels>> = OnceLock::new();

/// PTX の置き場所。`DENNO_MOE_GROUPED_PTX` があればそれ、無ければビルド時の
/// クレートディレクトリ配下 `kernels/kernels_gemm_grouped.ptx`。
fn grouped_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_MOE_GROUPED_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_gemm_grouped.ptx"),
    }
}

/// カーネルを取得する (初回だけ PTX を読む)。失敗は None をキャッシュする
/// (`moe_gemm_dev` の `f_gemm_q = None` と同じ扱い = 二度と試さない)。
fn grouped_kernels() -> Option<&'static GroupedKernels> {
    GROUPED_KERNELS
        .get_or_init(|| {
            let path = grouped_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(e) => {
                    eprintln!(
                        "[moe-grouped] PTX が読めない ({}) : {e} → CPU へ",
                        path.display()
                    );
                    return None;
                }
            };
            image.push(0); // cuModuleLoadData は NUL 終端の PTX を期待する
            let lib = lib().ok()?;
            let mut module: CUmodule = std::ptr::null_mut();
            unsafe {
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    eprintln!("[moe-grouped] cuModuleLoadData 失敗 → CPU へ");
                    return None;
                }
                let mut gate_up: CUfunction = std::ptr::null_mut();
                let mut down: CUfunction = std::ptr::null_mut();
                let rc1 = (lib.module_get_function)(
                    &mut gate_up,
                    module,
                    b"dno_moe_grouped_gate_up\0".as_ptr() as *const c_char,
                );
                let rc2 = (lib.module_get_function)(
                    &mut down,
                    module,
                    b"dno_moe_grouped_down\0".as_ptr() as *const c_char,
                );
                if rc1 != CUDA_SUCCESS || rc2 != CUDA_SUCCESS {
                    eprintln!(
                        "[moe-grouped] PTX に dno_moe_grouped_gate_up / dno_moe_grouped_down が無い → CPU へ"
                    );
                    return None;
                }
                Some(GroupedKernels {
                    module,
                    gate_up,
                    down,
                })
            }
        })
        .as_ref()
}

/// grouped GEMM 用のスレッド局所スクラッチ (grow-only)。
///
/// `packed` だけは「層の重み」なので key (層 id) が変わったら作り直す。
/// それ以外 (seg / x / act / h) は要求サイズが増えたときだけ確保し直す。
struct GroupedScratch {
    /// `packed` の持ち主 (層) の識別子
    key: u64,
    packed: Option<DevBuffer>,
    packed_len: usize,
    /// P43: パック済み重みが予算から借りている分 (drop で返る)。
    reserved: Option<crate::model::expert_vram::ExternalReserve>,
    /// P43: この呼び出しで予算が足りず載せられなかった (呼び出し側は CPU へ)
    denied: bool,
    seg: Option<DevBuffer>,
    /// down 用の segment 表 (w_off のストライドが gate と違う)
    seg_dn: Option<DevBuffer>,
    x: Option<DevBuffer>,
    act: Option<DevBuffer>,
    h: Option<DevBuffer>,
}

impl GroupedScratch {
    const fn new() -> Self {
        Self {
            key: u64::MAX,
            packed: None,
            packed_len: 0,
            reserved: None,
            denied: false,
            seg: None,
            seg_dn: None,
            x: None,
            act: None,
            h: None,
        }
    }
}

thread_local! {
    static GROUPED_SCRATCH: std::cell::RefCell<GroupedScratch> =
        std::cell::RefCell::new(GroupedScratch::new());
}

/// P40: grouped expert GEMM を 1 層ぶん走らせる。
///
/// 2 起動で expert FFN を終わらせる:
///   1. `dno_moe_grouped_gate_up` — act = silu(gate·x) * (up·x)
///   2. `dno_moe_grouped_down`    — h = down·act
///
/// 引数:
/// - `key`: パック済み重みの持ち主 (層 id)。変わったら VRAM を作り直す。
/// - `packed`: `[gate(e0..eN)][up(e0..eN)][down(e0..eN)]` のパック済み重み。
/// - `seg_gu` / `seg_dn`: 5 個で 1 segment (`[eid, m, w_off, e_off, ff_off]`。
///   `e_off` / `ff_off` は `m * n_in` / `m * n_out` の累積)。空 (`nseg == 0`) は
///   `Ok(false)`。
/// - `seg_gu` は gate/up 用、`seg_dn` は down 用。**down は 1 expert あたりの
///   バイト数が gate と違う**ので `w_off` のストライドが別 (P50)。1 枚の表を
///   使い回すと 2 体目以降が別の expert の重みを読む。
/// - `xin`: segment の並びに詰め直した入力 (m_total × gate.n_in)。
/// - `h`: 出力 (m_total × down.n_out)。成功時のみ全要素を書く。
///
/// 戻り値 `Ok(false)` は「GPU でやらなかった」= 呼び出し側は CPU 経路へ。
/// 環境 (env / CUDA / PTX / 形 / 共有メモリ) のどれかが欠ければ false。
#[allow(clippy::too_many_arguments)]
pub fn moe_grouped_gemm_layer(
    key: u64,
    packed: &[u8],
    seg_gu: &[u32],
    seg_dn: &[u32],
    gate: GroupedMatrix,
    up: GroupedMatrix,
    down: GroupedMatrix,
    xin: &[f32],
    h: &mut [f32],
) -> Result<bool> {
    if !moe_grouped_gpu_enabled() || !cuda_enabled() || !gpu_gemm_enabled() {
        return Ok(false);
    }
    if seg_gu.is_empty() || seg_gu.len() % 5 != 0 {
        return Ok(false);
    }
    // down 用の表は同じ segment 数でなければならない (eid/m の並びは同じ)。
    if seg_dn.len() != seg_gu.len() {
        return Ok(false);
    }
    // gate と up は同形 (同じ x を読み、同じ形の act を書く)。
    if (gate.ty, gate.n_in, gate.n_out, gate.row_bytes) != (up.ty, up.n_in, up.n_out, up.row_bytes)
    {
        return Ok(false);
    }
    // down は gate の転置 (n_in = ff、n_out = e)。
    if down.n_in != gate.n_out || down.n_out != gate.n_in {
        return Ok(false);
    }
    gate.check()?;
    down.check()?;
    let (ty_g, blkj_g, blkb_g) = gate.kernel_layout().expect("check 済み");
    let (ty_d, blkj_d, blkb_d) = down.kernel_layout().expect("check 済み");
    let Some(gb) = gate.expert_bytes() else {
        return Ok(false);
    };
    let Some(db) = down.expert_bytes() else {
        return Ok(false);
    };

    let nseg = seg_gu.len() / 5;
    // ブロックの範囲: gate は [gate.w_off, up.w_off)、down は [down.w_off, 末尾)。
    // w_off がこの範囲を出ると隣のブロック (別の行列) を重みとして読む。
    let Some(gate_block) = up.w_off.checked_sub(gate.w_off) else {
        return Ok(false);
    };
    let Some(down_block) = packed.len().checked_sub(down.w_off) else {
        return Ok(false);
    };
    let mut m_max = 0usize;
    let mut m_total = 0usize;
    for (s, sd) in seg_gu.chunks_exact(5).zip(seg_dn.chunks_exact(5)) {
        if s[0] != sd[0] || s[1] != sd[1] || s[3] != sd[3] || s[4] != sd[4] {
            bail!("moe_grouped_gemm_layer: seg_gu と seg_dn の segment が違う");
        }
        let m = s[1] as usize;
        if m == 0 {
            return Ok(false); // 空タスクは積まない (呼び出し側の契約)
        }
        let wg_off = s[2] as usize;
        if wg_off + gb > gate_block {
            bail!(
                "moe_grouped_gemm_layer: gate の w_off {wg_off} + {gb} B が \
                 gate ブロック {gate_block} B を超える"
            );
        }
        let wd_off = sd[2] as usize;
        if wd_off + db > down_block {
            bail!(
                "moe_grouped_gemm_layer: down の w_off {wd_off} + {db} B が \
                 down ブロック {down_block} B を超える"
            );
        }
        m_max = m_max.max(m);
        m_total += m;
    }
    if xin.len() != m_total * gate.n_in {
        bail!(
            "moe_grouped_gemm_layer: x の長さ {} が m_total({m_total}) * n_in({}) と違う",
            xin.len(),
            gate.n_in
        );
    }
    if h.len() != m_total * down.n_out {
        bail!(
            "moe_grouped_gemm_layer: h の長さ {} が m_total({m_total}) * n_out({}) と違う",
            h.len(),
            down.n_out
        );
    }
    let Some(p_gu) = grouped_launch_plan(nseg, m_max, gate.n_out, blkj_g, 2)? else {
        return Ok(false);
    };
    let Some(p_d) = grouped_launch_plan(nseg, m_max, down.n_out, blkj_d, 1)? else {
        return Ok(false);
    };

    let Some(ctx) = shared_ctx() else {
        return Ok(false);
    };
    ctx.make_current()?;
    let Some(k) = grouped_kernels() else {
        return Ok(false);
    };

    let seg_words = seg_gu.len();
    let n_x = xin.len();
    let n_act = m_total * up.n_out;
    let n_h = h.len();
    let mut out_buf: Option<Vec<f32>> = None;
    GROUPED_SCRATCH.with(|cell| -> Result<()> {
        let mut sc = cell.borrow_mut();
        sc.denied = false;
        // 1. パック済み重み (層が変わったら作り直す)
        //
        // P43: 確保の前に予算 (`DENNO_EXPERT_VRAM_MB`) から借りる。借りるために
        // LRU の expert は追い出される。予算が無いときは会計なしで素通りするので
        // 既定の挙動は変わらない。入れないときは CPU へ落とす (fail closed)。
        if sc.key != key || sc.packed_len != packed.len() || sc.packed.is_none() {
            // 先に手放してから借りる (手放した分がそのまま予約に回る)。
            sc.packed = None;
            sc.reserved = None;
            match crate::model::expert_vram::reserve_external(packed.len()) {
                Some(r) => {
                    sc.packed = Some(DevBuffer::alloc_tagged(
                        packed.len().max(1),
                        crate::mem_audit::TAG_GROUPED_PACKED,
                    )?);
                    sc.reserved = Some(r);
                    sc.key = key;
                    sc.packed_len = packed.len();
                }
                None => {
                    static WARNED: std::sync::atomic::AtomicBool =
                        std::sync::atomic::AtomicBool::new(false);
                    if !WARNED.swap(true, std::sync::atomic::Ordering::Relaxed) {
                        eprintln!(
                            "[moe-grouped] パック済み {} MiB が expert の VRAM 予算に載らない \
                             (DENNO_EXPERT_VRAM_MB) → この層は CPU へ",
                            packed.len() >> 20
                        );
                    }
                    sc.denied = true;
                    return Ok(());
                }
            }
        }
        {
            let pb = sc.packed.as_ref().expect("確保済み");
            pb.copy_from(packed)?;
            dbg_htod(packed.len());
        }
        // 2. segment 表 / 入力 / 中間 / 出力
        MoeScratch::ensure_tagged(&mut sc.seg, seg_words * 4, crate::mem_audit::TAG_GROUPED)?;
        MoeScratch::ensure_tagged(&mut sc.seg_dn, seg_words * 4, crate::mem_audit::TAG_GROUPED)?;
        MoeScratch::ensure_tagged(&mut sc.x, n_x * 4, crate::mem_audit::TAG_GROUPED)?;
        MoeScratch::ensure_tagged(&mut sc.act, n_act * 4, crate::mem_audit::TAG_GROUPED)?;
        MoeScratch::ensure_tagged(&mut sc.h, n_h * 4, crate::mem_audit::TAG_GROUPED)?;
        {
            let sb = sc.seg.as_ref().expect("確保済み");
            sb.copy_from(seg_gu)?;
            dbg_htod(seg_words * 4);
            let sd = sc.seg_dn.as_ref().expect("確保済み");
            sd.copy_from(seg_dn)?;
            dbg_htod(seg_words * 4);
            let xb = sc.x.as_ref().expect("確保済み");
            xb.copy_from(xin)?;
            dbg_htod(n_x * 4);
        }
        let packed_buf = sc.packed.as_ref().expect("確保済み");
        let seg_buf = sc.seg.as_ref().expect("確保済み");
        let seg_dn_buf = sc.seg_dn.as_ref().expect("確保済み");
        let x_buf = sc.x.as_ref().expect("確保済み");
        let act_buf = sc.act.as_ref().expect("確保済み");
        let h_buf = sc.h.as_ref().expect("確保済み");
        unsafe {
            // 3. gate + up + silu 積
            {
                let mut pwg = packed_buf.ptr + gate.w_off as u64;
                let mut pwu = packed_buf.ptr + up.w_off as u64;
                let mut px = x_buf.ptr;
                let mut pa = act_buf.ptr;
                let mut ps = seg_buf.ptr;
                let (mut ns, mut ni, mut no, mut rb) = (
                    nseg as c_int,
                    gate.n_in as c_int,
                    gate.n_out as c_int,
                    gate.row_bytes as c_int,
                );
                let (mut wt, mut blkj, mut blkb) =
                    (ty_g, blkj_g as c_int, blkb_g as c_int);
                let mut args = [
                    &mut pwg as *mut _ as *mut c_void,
                    &mut pwu as *mut _ as *mut c_void,
                    &mut px as *mut _ as *mut c_void,
                    &mut pa as *mut _ as *mut c_void,
                    &mut ps as *mut _ as *mut c_void,
                    &mut ns as *mut _ as *mut c_void,
                    &mut ni as *mut _ as *mut c_void,
                    &mut no as *mut _ as *mut c_void,
                    &mut rb as *mut _ as *mut c_void,
                    &mut wt as *mut _ as *mut c_void,
                    &mut blkj as *mut _ as *mut c_void,
                    &mut blkb as *mut _ as *mut c_void,
                ];
                ctx.launch_async(k.gate_up, p_gu.grid, p_gu.block, p_gu.smem, &mut args)?;
            }
            // 4. down (act はデバイス上に残っている)
            {
                let mut pwd = packed_buf.ptr + down.w_off as u64;
                let mut px = act_buf.ptr;
                let mut po = h_buf.ptr;
                let mut ps = seg_dn_buf.ptr;
                let (mut ns, mut ni, mut no, mut rb) = (
                    nseg as c_int,
                    down.n_in as c_int,
                    down.n_out as c_int,
                    down.row_bytes as c_int,
                );
                let (mut wt, mut blkj, mut blkb) = (ty_d, blkj_d as c_int, blkb_d as c_int);
                let mut args = [
                    &mut pwd as *mut _ as *mut c_void,
                    &mut px as *mut _ as *mut c_void,
                    &mut po as *mut _ as *mut c_void,
                    &mut ps as *mut _ as *mut c_void,
                    &mut ns as *mut _ as *mut c_void,
                    &mut ni as *mut _ as *mut c_void,
                    &mut no as *mut _ as *mut c_void,
                    &mut rb as *mut _ as *mut c_void,
                    &mut wt as *mut _ as *mut c_void,
                    &mut blkj as *mut _ as *mut c_void,
                    &mut blkb as *mut _ as *mut c_void,
                ];
                ctx.launch_async(k.down, p_d.grid, p_d.block, p_d.smem, &mut args)?;
            }
            ctx.sync()?;
        }
        out_buf = Some(h_buf.to_vec::<f32>(n_h)?);
        dbg_d2h(n_h * 4);
        // P43: 予算下では層の終わりに手放す。予算 (`DENNO_EXPERT_VRAM_MB`) は
        // decode の LRU と共有なので、prefill が持ち回ると decode が載せられない
        // (P39 の実測: 10,372 MiB で cuMemAlloc 失敗)。予算が無いときは従来どおり
        // 持ち回る (同じ層をもう一度呼ぶときに H2D を省く)。
        if sc.reserved.as_ref().map(|r| r.is_guarded()).unwrap_or(false) {
            sc.packed = None;
            sc.reserved = None;
        }
        Ok(())
    })?;
    let Some(got) = out_buf else {
        // P43: 予算が埋まっていてパック済み重みを載せられなかった → CPU へ。
        return Ok(false);
    };
    h.copy_from_slice(&got);
    Ok(true)
}

// ===========================================================================
// P43: 層一括 expert GEMV (decode) — `kernels_moe_batch.cu`
// ===========================================================================
//
// decode の expert FFN は 1 トークン = 480 expert x 3 行列 = 1,440 起動 +
// 1,440 同期だった (実測 382 ms/token の主因。CPU は 189 ms/token)。
// 1 層ぶん (top-k = 10 expert) を segment 表 + デバイスポインタ表でまとめ、
// **gate 1 + up 1 + down 1 = 3 起動 / 2 同期**にする。
//
// 数値: 1 行の累積は `kernels_moe.cu` と同じ「1 スレッドが i の昇順に f32 で
// 加算」。同じ expert・同じ入力なら per-expert 版とビット一致する。gate と up は
// 同じ同期で受け取り、ホストで `silu(g) * u` を作る (これも per-expert 版の
// `silu_inplace` + 積と同じ式・同じ順)。したがって寄与 h は 10 回起動版と
// 1 ビットも変わらない。
//
// PTX は起動時に 1 回だけファイルから読む (`DENNO_MOE_BATCH_PTX` で差し替え可)。
// 読めなければ `false` を返して呼び出し側は per-expert 経路へ落ちる (fail closed)。

/// カーネル (PTX を起動時に 1 回だけ読む)。
struct MoeBatchKernels {
    #[allow(dead_code)]
    module: CUmodule,
    /// Q8_0 / Q5_1 / Q4_K / Q5_K の 4 本
    fns: [CUfunction; 4],
}

// 生ハンドル (context / module / function)。CudaCtx と同じ規約。
unsafe impl Send for MoeBatchKernels {}
unsafe impl Sync for MoeBatchKernels {}

static MOE_BATCH_KERNELS: OnceLock<Option<MoeBatchKernels>> = OnceLock::new();

/// カーネル名 (添字は [`moe_batch_slot`] の順)。
const MOE_BATCH_NAMES: [&[u8]; 4] = [
    b"dno_moe_gemv_seg_q8_0\0",
    b"dno_moe_gemv_seg_q5_1\0",
    b"dno_moe_gemv_seg_q4k\0",
    b"dno_moe_gemv_seg_q5k\0",
];

/// 型 → カーネル添字。未対応は `None` (呼び出し側は CPU へ)。
fn moe_batch_slot(ty: crate::kquant::GgmlType) -> Option<usize> {
    use crate::kquant::GgmlType as T;
    match ty {
        T::Q8_0 => Some(0),
        T::Q5_1 => Some(1),
        T::Q4K => Some(2),
        T::Q5K => Some(3),
        _ => None,
    }
}

/// PTX の置き場所。`DENNO_MOE_BATCH_PTX` があればそれ、無ければクレート配下
/// `kernels/kernels_moe_batch.ptx`。
fn moe_batch_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_MOE_BATCH_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_moe_batch.ptx"),
    }
}

/// カーネルを取得する (初回だけ PTX を読む)。失敗は None をキャッシュする
/// (grouped と同じ扱い = 二度と試さない)。
fn moe_batch_kernels() -> Option<&'static MoeBatchKernels> {
    MOE_BATCH_KERNELS
        .get_or_init(|| {
            let path = moe_batch_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(e) => {
                    eprintln!(
                        "[moe-batch] PTX が読めない ({}) : {e} → per-expert 経路へ",
                        path.display()
                    );
                    return None;
                }
            };
            image.push(0); // cuModuleLoadData は NUL 終端の PTX を期待する
            let lib = lib().ok()?;
            let mut module: CUmodule = std::ptr::null_mut();
            unsafe {
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    eprintln!("[moe-batch] cuModuleLoadData 失敗 → per-expert 経路へ");
                    return None;
                }
            }
            let mut fns: [CUfunction; 4] = [std::ptr::null_mut(); 4];
            for (i, name) in MOE_BATCH_NAMES.iter().enumerate() {
                unsafe {
                    if (lib.module_get_function)(&mut fns[i], module, name.as_ptr() as *const c_char)
                        != CUDA_SUCCESS
                    {
                        eprintln!(
                            "[moe-batch] PTX に {} が無い → per-expert 経路へ",
                            String::from_utf8_lossy(&name[..name.len() - 1])
                        );
                        return None;
                    }
                }
            }
            Some(MoeBatchKernels { module, fns })
        })
        .as_ref()
}

/// 層一括 GEMV が使えるか (`false` なら呼び出し側は per-expert 経路へ)。
///
/// `DENNO_CUDA` 無効・未対応の型・PTX 不在のいずれでも false。**載せる前**の
/// 判定に使う (載せてから落ちると VRAM が無駄に埋まる)。
pub fn moe_gemv_seg_ready(ty: crate::kquant::GgmlType, k: usize) -> bool {
    if !cuda_enabled() || gguf_row_bytes(ty, k).is_none() {
        return false;
    }
    moe_batch_slot(ty).is_some() && moe_batch_kernels().is_some()
}

/// 1 層ぶんの行列 1 本 (segment 表と組み合わせて 1 起動になる)。
struct SegJob<'a> {
    ty: crate::kquant::GgmlType,
    /// segment ごとの重み先頭 (デバイスアドレス)。長さ = nseg。
    wptrs: &'a [u64],
    n_in: usize,
    n_out: usize,
    row_bytes: usize,
    out: &'a mut [f32],
}

/// スレッド局所のスクラッチ (grow-only)。`MoeScratch` と同じ規約。
struct SegScratch {
    /// segment ごとの重みポインタ表 (デバイス)
    ptr: [Option<DevBuffer>; 2],
    /// segment 表 (4 語 x nseg)
    seg: Option<DevBuffer>,
    /// 入力 (segment の x_off を足して読む)
    x: Option<DevBuffer>,
    /// 出力 (segment の out_off を足して書く)
    out: [Option<DevBuffer>; 2],
}

impl SegScratch {
    fn new() -> Self {
        SegScratch {
            ptr: [None, None],
            seg: None,
            x: None,
            out: [None, None],
        }
    }
}

thread_local! {
    static SEG_SCRATCH: std::cell::RefCell<SegScratch> =
        std::cell::RefCell::new(SegScratch::new());
}

/// 1 回の同期で終わる層一括 GEMV。`jobs` は 1 本か 2 本 (gate, up)。
///
/// 前提 (呼び出し側が検査済み): 全 job が同じ `n_out` / `row_bytes` / segment 表。
/// 発行順は job の並び順で、**同期は最後に 1 回だけ**。
fn moe_gemv_seg_run(jobs: &mut [SegJob<'_>], seg: &[u32], m_max: usize, x: &[f32]) -> Result<()> {
    if jobs.is_empty() || jobs.len() > 2 {
        bail!("moe_gemv_seg_run: job 数 {} が 1..=2 でない", jobs.len());
    }
    if !seg.len().is_multiple_of(4) {
        bail!("moe_gemv_seg_run: segment 表の長さ {} が 4 の倍数でない", seg.len());
    }
    let nseg = seg.len() / 4;
    let (n_out, row_bytes) = (jobs[0].n_out, jobs[0].row_bytes);
    for (i, j) in jobs.iter().enumerate() {
        if j.n_out != n_out || j.row_bytes != row_bytes {
            bail!(
                "moe_gemv_seg_run: job {i} の形が揃っていない (n_out={}/{n_out}, row_bytes={}/{row_bytes})",
                j.n_out,
                j.row_bytes
            );
        }
        if j.wptrs.len() != nseg {
            bail!(
                "moe_gemv_seg_run: job {i} のポインタ表 {} が segment 数 {nseg} と違う",
                j.wptrs.len()
            );
        }
        let (mx, mo) = crate::model::expert_batch::seg_extents(seg, j.n_in, j.n_out)?;
        if x.len() < mx {
            bail!(
                "moe_gemv_seg_run: job {i} の入力長 {} が segment の最大 x 範囲 {mx} より短い",
                x.len()
            );
        }
        if j.out.len() < mo {
            bail!(
                "moe_gemv_seg_run: job {i} の出力長 {} が segment の最大 out 範囲 {mo} より短い",
                j.out.len()
            );
        }
    }
    let Some(plan) = crate::model::expert_batch::seg_launch_plan(nseg, m_max, n_out, row_bytes) else {
        bail!("moe_gemv_seg_run: 起動形が作れない (nseg={nseg}, m_max={m_max}, n_out={n_out})");
    };
    let Some(ctx) = shared_ctx() else {
        bail!("moe_gemv_seg_run: CUDA コンテキストが無い");
    };
    ctx.make_current()?;
    let Some(kernels) = moe_batch_kernels() else {
        bail!("moe_gemv_seg_run: カーネルが無い");
    };

    SEG_SCRATCH.with(|cell| -> Result<()> {
        let mut sc = cell.borrow_mut();
        // 1. ポインタ表 / segment 表 / 入力 (すべて起動より前に H2D)
        for (i, job) in jobs.iter().enumerate() {
            MoeScratch::ensure_tagged(&mut sc.ptr[i], job.wptrs.len() * 8, crate::mem_audit::TAG_SEG)?;
            let pb = sc.ptr[i].as_ref().expect("確保済み");
            pb.copy_from(job.wptrs)?;
            dbg_htod(job.wptrs.len() * 8);
        }
        MoeScratch::ensure_tagged(&mut sc.seg, seg.len() * 4, crate::mem_audit::TAG_SEG)?;
        MoeScratch::ensure_tagged(&mut sc.x, x.len() * 4, crate::mem_audit::TAG_SEG)?;
        {
            let sb = sc.seg.as_ref().expect("確保済み");
            sb.copy_from(seg)?;
            dbg_htod(seg.len() * 4);
            let xb = sc.x.as_ref().expect("確保済み");
            xb.copy_from(x)?;
            dbg_htod(x.len() * 4);
        }
        for (i, job) in jobs.iter().enumerate() {
            MoeScratch::ensure_tagged(&mut sc.out[i], job.out.len() * 4, crate::mem_audit::TAG_SEG)?;
        }
        // 2. 起動 (job ごと。まだ同期しない)
        let seg_buf = sc.seg.as_ref().expect("確保済み");
        let x_buf = sc.x.as_ref().expect("確保済み");
        unsafe {
            for (i, job) in jobs.iter().enumerate() {
                let slot = moe_batch_slot(job.ty)
                    .ok_or_else(|| anyhow::anyhow!("未対応の量子型 {:?}", job.ty))?;
                let mut pw = sc.ptr[i].as_ref().expect("確保済み").ptr;
                let mut px = x_buf.ptr;
                let mut po = sc.out[i].as_ref().expect("確保済み").ptr;
                let mut ps = seg_buf.ptr;
                let (mut ns, mut ni, mut no, mut rb) = (
                    nseg as c_int,
                    job.n_in as c_int,
                    job.n_out as c_int,
                    job.row_bytes as c_int,
                );
                let mut args = [
                    &mut pw as *mut _ as *mut c_void,
                    &mut px as *mut _ as *mut c_void,
                    &mut po as *mut _ as *mut c_void,
                    &mut ps as *mut _ as *mut c_void,
                    &mut ns as *mut _ as *mut c_void,
                    &mut ni as *mut _ as *mut c_void,
                    &mut no as *mut _ as *mut c_void,
                    &mut rb as *mut _ as *mut c_void,
                ];
                ctx.launch_async(
                    kernels.fns[slot],
                    plan.grid,
                    plan.block,
                    plan.smem,
                    &mut args,
                )?;
            }
            // 3. 同期は 1 回だけ (gate と up が同じ同期で終わる)
            ctx.sync()?;
        }
        // 4. D2H
        for (i, job) in jobs.iter_mut().enumerate() {
            let got: Vec<f32> = sc.out[i].as_ref().expect("確保済み").to_vec(job.out.len())?;
            dbg_d2h(job.out.len() * 4);
            job.out.copy_from_slice(&got);
        }
        Ok(())
    })
}

/// gate と up を **2 起動 + 1 同期**で回し、両方の出力を返す (P43)。
///
/// `seg` は gate/up 用 (全 segment が同じ入力 x を読むので `x_off = 0`)。
/// `Ok(false)` は「GPU でやらなかった」= 呼び出し側は per-expert 経路へ。
#[allow(clippy::too_many_arguments)]
pub fn moe_gemv_seg_pair(
    ty_g: crate::kquant::GgmlType,
    ty_u: crate::kquant::GgmlType,
    wptrs_g: &[u64],
    wptrs_u: &[u64],
    seg: &[u32],
    m_max: usize,
    x: &[f32],
    n_in: usize,
    n_out: usize,
    out_g: &mut [f32],
    out_u: &mut [f32],
) -> Result<bool> {
    let (Some(rb_g), Some(rb_u)) = (gguf_row_bytes(ty_g, n_in), gguf_row_bytes(ty_u, n_in)) else {
        return Ok(false);
    };
    if rb_g != rb_u || moe_batch_slot(ty_g).is_none() || moe_batch_slot(ty_u).is_none() {
        return Ok(false);
    }
    if !moe_gemv_seg_ready(ty_g, n_in) || !moe_gemv_seg_ready(ty_u, n_in) {
        return Ok(false);
    }
    let mut jobs = [
        SegJob {
            ty: ty_g,
            wptrs: wptrs_g,
            n_in,
            n_out,
            row_bytes: rb_g,
            out: out_g,
        },
        SegJob {
            ty: ty_u,
            wptrs: wptrs_u,
            n_in,
            n_out,
            row_bytes: rb_u,
            out: out_u,
        },
    ];
    moe_gemv_seg_run(&mut jobs, seg, m_max, x)?;
    Ok(true)
}

/// 1 本だけ (down) を **1 起動 + 1 同期**で回す (P43)。
///
/// `seg` は down 用 (`x_off = s * n_in`, `out_off = s * n_out`)。
/// `Ok(false)` は「GPU でやらなかった」= 呼び出し側は per-expert 経路へ。
#[allow(clippy::too_many_arguments)]
pub fn moe_gemv_seg_one(
    ty: crate::kquant::GgmlType,
    wptrs: &[u64],
    seg: &[u32],
    m_max: usize,
    x: &[f32],
    n_in: usize,
    n_out: usize,
    out: &mut [f32],
) -> Result<bool> {
    let Some(rb) = gguf_row_bytes(ty, n_in) else {
        return Ok(false);
    };
    if moe_batch_slot(ty).is_none() || !moe_gemv_seg_ready(ty, n_in) {
        return Ok(false);
    }
    let mut jobs = [SegJob {
        ty,
        wptrs,
        n_in,
        n_out,
        row_bytes: rb,
        out,
    }];
    moe_gemv_seg_run(&mut jobs, seg, m_max, x)?;
    Ok(true)
}

// ===========================================================================
// task 144: IQ 系 expert の層一括 GEMV (`kernels_exp_iq.cu` → `kernels_exp_iq.ptx`)
// ===========================================================================
//
// # なぜ要るか
//
// P39/P43 の VRAM 常駐経路は `gguf_row_bytes` が返す 4 型 (Q8_0 / Q5_1 / Q4_K /
// Q5_K) しか GPU で読めない。本番の expert は IQ2_S / IQ3_XXS / IQ3_S / IQ4_XS /
// IQ4_NL / Q2_0 なので `moe_gemv_dev_ready` が**型の判定で** false になり、
// `expert_vram::acquire` は 1 本も載せず、480 expert 全部が CPU で回っていた
// (実測 99〜108 ms/tok、VRAM 使用 0 MiB)。`f_moe` (PTX モジュール) は正常だった。
//
// # 何をするか
//
// 1 層ぶんの expert FFN を **4 起動 + 1 同期**で回す:
//
//   gate 1 起動 → up 1 起動 → silu_mul 1 起動 → down 1 起動 → sync → D2H(h)
//
// 1 行 = 1 warp (32 レーン) で k 方向を分割して足すので、CPU とは丸め順が違う
// (task 144 はビット一致を要求しない)。起動形が同じなら値は決定的。
//
// ゲート `DENNO_EXPERT_IQ_GPU` が off のときは [`moe_gemv_iq_ready`] が false を
// 返すので、この経路は選ばれない (md5 はベースラインと一致する)。

/// カーネル一式 (PTX を起動時に 1 回だけ読む)。
struct ExpIqKernels {
    #[allow(dead_code)]
    module: CUmodule,
    /// 型ごとの GEMV ([`crate::model::exp_iq::slot`] の順)
    fns: [CUfunction; crate::model::exp_iq::SLOTS],
    /// silu(g) * u
    silu: CUfunction,
}

// 生ハンドル (context / module / function)。CudaCtx と同じ規約。
unsafe impl Send for ExpIqKernels {}
unsafe impl Sync for ExpIqKernels {}

static EXP_IQ_KERNELS: OnceLock<Option<ExpIqKernels>> = OnceLock::new();

/// PTX の置き場所。`DENNO_EXP_IQ_PTX` があればそれ、無ければクレート配下
/// `kernels/kernels_exp_iq.ptx`。
fn exp_iq_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_EXP_IQ_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_exp_iq.ptx"),
    }
}

/// カーネルを取得する (初回だけ PTX を読む)。失敗は None を焼き付ける
/// (= 二度と試さない。呼び出し側は CPU へ落ちる)。
fn exp_iq_kernels() -> Option<&'static ExpIqKernels> {
    EXP_IQ_KERNELS
        .get_or_init(|| {
            let path = exp_iq_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(e) => {
                    eprintln!(
                        "[exp-iq] PTX が読めない ({}) : {e} → CPU 経路へ",
                        path.display()
                    );
                    return None;
                }
            };
            image.push(0);
            let lib = lib().ok()?;
            let mut module: CUmodule = std::ptr::null_mut();
            unsafe {
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    eprintln!("[exp-iq] cuModuleLoadData 失敗 → CPU 経路へ");
                    return None;
                }
            }
            let mut fns: [CUfunction; crate::model::exp_iq::SLOTS] =
                [std::ptr::null_mut(); crate::model::exp_iq::SLOTS];
            for (i, f) in fns.iter_mut().enumerate() {
                let name = crate::model::exp_iq::kernel_name(i)?;
                let mut cname = name.as_bytes().to_vec();
                cname.push(0);
                unsafe {
                    if (lib.module_get_function)(f, module, cname.as_ptr() as *const c_char)
                        != CUDA_SUCCESS
                    {
                        eprintln!("[exp-iq] PTX に {name} が無い → CPU 経路へ");
                        return None;
                    }
                }
            }
            let mut silu: CUfunction = std::ptr::null_mut();
            let mut cname = crate::model::exp_iq::SILU_KERNEL.as_bytes().to_vec();
            cname.push(0);
            unsafe {
                if (lib.module_get_function)(&mut silu, module, cname.as_ptr() as *const c_char)
                    != CUDA_SUCCESS
                {
                    eprintln!("[exp-iq] PTX に silu が無い → CPU 経路へ");
                    return None;
                }
            }
            Some(ExpIqKernels { module, fns, silu })
        })
        .as_ref()
}

/// この型・この k を GPU で回せるか。
///
/// `DENNO_EXPERT_IQ_GPU` が off・未対応の型・PTX 不在のいずれでも false。
/// **載せる前**の判定 (`expert_vram::acquire`) に使う (載せてから落ちると VRAM が
/// 無駄に埋まる)。
pub fn moe_gemv_iq_ready(ty: crate::kquant::GgmlType, k: usize) -> bool {
    if !cuda_enabled() || !crate::model::exp_iq::iq_gpu_enabled() {
        return false;
    }
    if !crate::model::exp_iq::supported(ty)
        || crate::model::exp_iq::row_bytes(ty, k).is_none()
    {
        return false;
    }
    exp_iq_kernels().is_some()
}

/// 1 層ぶんの作業域 (grow-only。スレッドローカル)。
struct IqScratch {
    x: Option<DevBuffer>,
    g: Option<DevBuffer>,
    u: Option<DevBuffer>,
    act: Option<DevBuffer>,
    h: Option<DevBuffer>,
    pg: Option<DevBuffer>,
    pu: Option<DevBuffer>,
    pd: Option<DevBuffer>,
    sgu: Option<DevBuffer>,
    sgd: Option<DevBuffer>,
    /// task 150: `h` の D2H を非同期で受ける pinned staging (overlap 経路だけ)。
    hpin: Option<PinMem>,
}

impl IqScratch {
    fn new() -> Self {
        IqScratch {
            x: None,
            g: None,
            u: None,
            act: None,
            h: None,
            pg: None,
            pu: None,
            pd: None,
            sgu: None,
            sgd: None,
            hpin: None,
        }
    }
}

thread_local! {
    static IQ_SCRATCH: std::cell::RefCell<IqScratch> =
        std::cell::RefCell::new(IqScratch::new());
}

/// 1 層ぶんの expert FFN を GPU で回す (gate/up は IQ, down は IQ4_NL/Q2_0)。
///
/// `pg` / `pu` / `pd` は segment ごとの重み先頭 (デバイスアドレス)、
/// `seg_gu` は gate/up 用 (`x_off = 0`)、`seg_d` は down 用 (`x_off = s*ff`)。
/// `out_h` は `nseg * e` 要素。呼び出し側は結果を expert index 昇順で足し込む。
///
/// `Ok(false)` は「GPU でやらなかった」= 呼び出し側は CPU 経路へ (fail closed)。
#[allow(clippy::too_many_arguments)]
pub fn moe_experts_iq_layer(
    ty_g: crate::kquant::GgmlType,
    ty_u: crate::kquant::GgmlType,
    ty_d: crate::kquant::GgmlType,
    pg: &[u64],
    pu: &[u64],
    pd: &[u64],
    seg_gu: &[u32],
    seg_d: &[u32],
    x: &[f32],
    n_in: usize,
    ff: usize,
    e: usize,
    out_h: &mut [f32],
) -> Result<bool> {
    iq_layer_run(
        ty_g, ty_u, ty_d, pg, pu, pd, seg_gu, seg_d, x, n_in, ff, e, out_h, false, || Ok(()),
    )
}

/// task 150: [`moe_experts_iq_layer`] の**重ね打ち版**。
///
/// 発行するカーネル・引数・順序・値は逐次版と 1 つも変わらない。違うのは待ち方だけで、
/// **D2H を非同期で出してから `cpu_miss` を実行し、最後に 1 回だけ同期する**。
/// decode では 1 層あたり GPU 5〜6 ms 待つのに CPU ミスが 57 ms あるので (lab t148b)、
/// 待ちを CPU の仕事の裏へ隠せる。`cpu_miss` は GPU の作業域に触れてはいけない
/// (呼び出し側はミス expert の CPU 寄与だけを書く)。
///
/// `Ok(false)` = GPU でやらなかった (どの起動よりも前に落ちた)。このとき
/// `cpu_miss` は**呼ばれない**ので、呼び出し側は従来どおり全 expert を CPU で
/// 計算し直せる。`cpu_miss` が `Err` を返したときは**そのまま Err を返す**
/// (起動済みで `out_h` の一部が確定しているため CPU 経路へは戻さない)。
#[allow(clippy::too_many_arguments)]
pub fn moe_experts_iq_layer_overlap<F>(
    ty_g: crate::kquant::GgmlType,
    ty_u: crate::kquant::GgmlType,
    ty_d: crate::kquant::GgmlType,
    pg: &[u64],
    pu: &[u64],
    pd: &[u64],
    seg_gu: &[u32],
    seg_d: &[u32],
    x: &[f32],
    n_in: usize,
    ff: usize,
    e: usize,
    out_h: &mut [f32],
    cpu_miss: F,
) -> Result<bool>
where
    F: FnOnce() -> Result<()>,
{
    iq_layer_run(
        ty_g, ty_u, ty_d, pg, pu, pd, seg_gu, seg_d, x, n_in, ff, e, out_h, true, cpu_miss,
    )
}

/// [`moe_experts_iq_layer`] と [`moe_experts_iq_layer_overlap`] の共通本体。
/// `overlap == false` のときの順序・API 呼び出しは task 144 の実装と同一。
#[allow(clippy::too_many_arguments)]
fn iq_layer_run<F>(
    ty_g: crate::kquant::GgmlType,
    ty_u: crate::kquant::GgmlType,
    ty_d: crate::kquant::GgmlType,
    pg: &[u64],
    pu: &[u64],
    pd: &[u64],
    seg_gu: &[u32],
    seg_d: &[u32],
    x: &[f32],
    n_in: usize,
    ff: usize,
    e: usize,
    out_h: &mut [f32],
    overlap: bool,
    middle: F,
) -> Result<bool>
where
    F: FnOnce() -> Result<()>,
{
    let nseg = pg.len();
    if nseg == 0
        || pu.len() != nseg
        || pd.len() != nseg
        || !seg_gu.len().is_multiple_of(4)
        || !seg_d.len().is_multiple_of(4)
        || seg_gu.len() / 4 != nseg
        || seg_d.len() / 4 != nseg
    {
        return Ok(false);
    }
    if !moe_gemv_iq_ready(ty_g, n_in)
        || !moe_gemv_iq_ready(ty_u, n_in)
        || !moe_gemv_iq_ready(ty_d, ff)
    {
        return Ok(false);
    }
    let (Some(plan_g), Some(plan_d)) = (
        crate::model::exp_iq::launch_plan(nseg, ff),
        crate::model::exp_iq::launch_plan(nseg, e),
    ) else {
        return Ok(false);
    };
    if x.len() < n_in || out_h.len() < nseg * e {
        bail!(
            "moe_experts_iq_layer: 入出力長が足りない (x={}/{n_in}, out={}/{})",
            x.len(),
            out_h.len(),
            nseg * e
        );
    }
    let Some(ctx) = shared_ctx() else {
        return Ok(false);
    };
    let Some(kernels) = exp_iq_kernels() else {
        return Ok(false);
    };
    let (Some(slot_g), Some(slot_u), Some(slot_d)) = (
        crate::model::exp_iq::slot(ty_g),
        crate::model::exp_iq::slot(ty_u),
        crate::model::exp_iq::slot(ty_d),
    ) else {
        return Ok(false);
    };
    ctx.make_current()?;

    let ng = nseg * ff;
    let nh = nseg * e;
    IQ_SCRATCH.with(|cell| -> Result<()> {
        let mut sc = cell.borrow_mut();
        MoeScratch::ensure_tagged(&mut sc.x, n_in * 4, crate::mem_audit::TAG_GDN_SC)?;
        MoeScratch::ensure_tagged(&mut sc.g, ng * 4, crate::mem_audit::TAG_GDN_SC)?;
        MoeScratch::ensure_tagged(&mut sc.u, ng * 4, crate::mem_audit::TAG_GDN_SC)?;
        MoeScratch::ensure_tagged(&mut sc.act, ng * 4, crate::mem_audit::TAG_GDN_SC)?;
        MoeScratch::ensure_tagged(&mut sc.h, nh * 4, crate::mem_audit::TAG_GDN_SC)?;
        MoeScratch::ensure_tagged(&mut sc.pg, nseg * 8, crate::mem_audit::TAG_GDN_SC)?;
        MoeScratch::ensure_tagged(&mut sc.pu, nseg * 8, crate::mem_audit::TAG_GDN_SC)?;
        MoeScratch::ensure_tagged(&mut sc.pd, nseg * 8, crate::mem_audit::TAG_GDN_SC)?;
        MoeScratch::ensure_tagged(&mut sc.sgu, seg_gu.len() * 4, crate::mem_audit::TAG_GDN_SC)?;
        MoeScratch::ensure_tagged(&mut sc.sgd, seg_d.len() * 4, crate::mem_audit::TAG_GDN_SC)?;
        // task 150: overlap 経路だけ pinned staging を用意する (grow-only)。
        if overlap {
            Scratch::ensure_pin(&mut sc.hpin, nh * 4)?;
        }
        {
            let xb = sc.x.as_ref().expect("確保済み");
            xb.copy_from(&x[..n_in])?;
            dbg_htod(n_in * 4);
            sc.pg.as_ref().expect("確保済み").copy_from(pg)?;
            sc.pu.as_ref().expect("確保済み").copy_from(pu)?;
            sc.pd.as_ref().expect("確保済み").copy_from(pd)?;
            dbg_htod(nseg * 8 * 3);
            sc.sgu.as_ref().expect("確保済み").copy_from(seg_gu)?;
            sc.sgd.as_ref().expect("確保済み").copy_from(seg_d)?;
            dbg_htod((seg_gu.len() + seg_d.len()) * 4);
        }
        let xb = sc.x.as_ref().expect("確保済み");
        let g = sc.g.as_ref().expect("確保済み");
        let u = sc.u.as_ref().expect("確保済み");
        let act = sc.act.as_ref().expect("確保済み");
        let h = sc.h.as_ref().expect("確保済み");
        unsafe {
            // 1. gate と up (同じ segment 表 = 同じ入力 x)
            let rb_g = crate::model::exp_iq::row_bytes(ty_g, n_in).unwrap_or(0);
            let rb_u = crate::model::exp_iq::row_bytes(ty_u, n_in).unwrap_or(0);
            for (f, ptrs, buf, rb) in [
                (kernels.fns[slot_g], sc.pg.as_ref().expect("確保済み"), g, rb_g),
                (kernels.fns[slot_u], sc.pu.as_ref().expect("確保済み"), u, rb_u),
            ] {
                let mut pw = ptrs.ptr;
                let mut px = xb.ptr;
                let mut po = buf.ptr;
                let mut ps = sc.sgu.as_ref().expect("確保済み").ptr;
                let (mut ns, mut ni, mut no, mut rb) = (
                    nseg as c_int,
                    n_in as c_int,
                    ff as c_int,
                    rb as c_int,
                );
                let mut args = [
                    &mut pw as *mut _ as *mut c_void,
                    &mut px as *mut _ as *mut c_void,
                    &mut po as *mut _ as *mut c_void,
                    &mut ps as *mut _ as *mut c_void,
                    &mut ns as *mut _ as *mut c_void,
                    &mut ni as *mut _ as *mut c_void,
                    &mut no as *mut _ as *mut c_void,
                    &mut rb as *mut _ as *mut c_void,
                ];
                ctx.launch_async(f, plan_g.grid, plan_g.block, 0, &mut args)?;
            }
            // 2. act = silu(g) * u
            {
                let n = ng as c_int;
                let threads = 256usize;
                let blocks = ng.div_ceil(threads) as u32;
                let mut pgg = g.ptr;
                let mut puu = u.ptr;
                let mut paa = act.ptr;
                let mut pn = n;
                let mut args = [
                    &mut pgg as *mut _ as *mut c_void,
                    &mut puu as *mut _ as *mut c_void,
                    &mut paa as *mut _ as *mut c_void,
                    &mut pn as *mut _ as *mut c_void,
                ];
                ctx.launch_async(
                    kernels.silu,
                    (blocks.max(1), 1, 1),
                    (threads as u32, 1, 1),
                    0,
                    &mut args,
                )?;
            }
            // 3. down (expert ごとの act を読む)
            {
                let mut pw = sc.pd.as_ref().expect("確保済み").ptr;
                let mut px = act.ptr;
                let mut po = h.ptr;
                let mut ps = sc.sgd.as_ref().expect("確保済み").ptr;
                let (mut ns, mut ni, mut no, mut rb) = (
                    nseg as c_int,
                    ff as c_int,
                    e as c_int,
                    crate::model::exp_iq::row_bytes(ty_d, ff).unwrap_or(0) as c_int,
                );
                let mut args = [
                    &mut pw as *mut _ as *mut c_void,
                    &mut px as *mut _ as *mut c_void,
                    &mut po as *mut _ as *mut c_void,
                    &mut ps as *mut _ as *mut c_void,
                    &mut ns as *mut _ as *mut c_void,
                    &mut ni as *mut _ as *mut c_void,
                    &mut no as *mut _ as *mut c_void,
                    &mut rb as *mut _ as *mut c_void,
                ];
                ctx.launch_async(
                    kernels.fns[slot_d],
                    plan_d.grid,
                    plan_d.block,
                    0,
                    &mut args,
                )?;
            }
            // 4. 同期は 1 回だけ (層あたり)。task 150 の overlap 経路では D2H を
            //    非同期で先に出し、`middle` (CPU ミス) を挟んでから同期する。
            //    カーネル・引数・発行順は逐次版と同一 (変わるのは待つ位置だけ)。
            if overlap {
                // `h` の借用をここで切る (pinned は別 field なので `sc` を丸ごと
                // 借り直さないよう、アドレスを先に写す)。
                let h_ptr = h.ptr;
                let pin = sc.hpin.as_mut().expect("確保済み");
                check(
                    (lib()?.memcpy_dtoh_async)(pin.ptr, h_ptr, nh * 4, std::ptr::null_mut()),
                    "cuMemcpyDtoHAsync (iq layer overlap)",
                )?;
                crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
            } else {
                // task 155: 逐次版も null ストリームぶんだけをイベントで待つ。
                sync_default_or_ctx(ctx, dec_overlap_enabled())?;
            }
        }
        if overlap {
            // ここから下はデバイスの完了を待たずに走る (GPU と CPU の重ね打ち)。
            middle()?;
            // task 155: 待つのは null ストリーム (この層の expert GEMV と D2H)
            // だけ。shared expert のサイドストリームは join まで待たない。
            sync_default_or_ctx(ctx, dec_overlap_enabled())?;
            let pin = sc.hpin.as_ref().expect("確保済み");
            out_h[..nh].copy_from_slice(&pin.as_slice::<f32>()[..nh]);
        } else {
            let got: Vec<f32> = sc.h.as_ref().expect("確保済み").to_vec(nh)?;
            out_h[..nh].copy_from_slice(&got);
            middle()?;
        }
        dbg_d2h(nh * 4);
        Ok(())
    })?;
    Ok(true)
}

// ===========================================================================
// task 148: prefill の m 行 expert GEMV (`kernels_exp_iq_pf.cu`)
// ===========================================================================
//
// decode の層一括 GEMV (`kernels_exp_iq`) は 1 起動 = 1 行。prefill は 512 トークンの
// チャンクで 1 expert あたり平均 20 行を受けるので、**同じ重みの読みで 16 行ずつ
// まとめて**積むカーネルを別モジュールに持つ (`exp_pf::ROWS_PER_LAUNCH`)。
//
//   gate 1 起動 → up 1 起動 → silu_mul 1 起動 → down 1 起動 → sync 1 回 → D2H(h)
//
// 1 行ぶんの累積順は decode と同一なので、同じ行を m=1 と m 行で回すとビット一致
// する。行の対応は `seg` (m / rows の先頭) と `rows` (行 → トークン番号) で決まる。
//
// 予算: 作業域は層ごとに grow-only で使い回す。確保に失敗したら **そのプロセスでは
// 以後この経路を試さない** (PF_DEAD)。prefill の途中で毎層 cuMemAlloc を叩いて
// attention 用の領域を削る、という事故を避ける (t147a の 26 GB で起きたのはこれ)。

/// カーネル一式 (PTX を起動時に 1 回だけ読む)。
struct ExpPfKernels {
    #[allow(dead_code)]
    module: CUmodule,
    /// 型ごとの m 行 GEMV ([`crate::model::exp_pf::kernel_name`] の順)
    fns: [CUfunction; crate::model::exp_pf::SLOTS],
    /// silu(g) * u
    silu: CUfunction,
    /// task 162: 行の加重和 (`dno_exp_pf_accum`)。task 151 で未使用に戻した
    /// カーネルで、PTX には定義だけ残っている。ストリーミング経路だけが使う。
    accum: Option<CUfunction>,
}

unsafe impl Send for ExpPfKernels {}
unsafe impl Sync for ExpPfKernels {}

static EXP_PF_KERNELS: OnceLock<Option<ExpPfKernels>> = OnceLock::new();

/// 確保に失敗したら立てる (以後このプロセスでは prefill の GPU 経路を使わない)。
static PF_DEAD: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// PTX の置き場所。`DENNO_EXP_PF_PTX` があればそれ、無ければクレート配下
/// `kernels/kernels_exp_iq_pf.ptx`。
fn exp_pf_ptx_path() -> std::path::PathBuf {
    match std::env::var("DENNO_EXP_PF_PTX") {
        Ok(p) if !p.is_empty() => std::path::PathBuf::from(p),
        _ => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("kernels")
            .join("kernels_exp_iq_pf.ptx"),
    }
}

/// カーネルを取得する (初回だけ PTX を読む)。失敗は None を焼き付ける。
fn exp_pf_kernels() -> Option<&'static ExpPfKernels> {
    EXP_PF_KERNELS
        .get_or_init(|| {
            let path = exp_pf_ptx_path();
            let mut image = match std::fs::read(&path) {
                Ok(b) => b,
                Err(e) => {
                    eprintln!(
                        "[exp-pf] PTX が読めない ({}) : {e} → CPU 経路へ",
                        path.display()
                    );
                    return None;
                }
            };
            image.push(0);
            let lib = lib().ok()?;
            let mut module: CUmodule = std::ptr::null_mut();
            unsafe {
                if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void)
                    != CUDA_SUCCESS
                {
                    eprintln!("[exp-pf] cuModuleLoadData 失敗 → CPU 経路へ");
                    return None;
                }
            }
            let mut fns: [CUfunction; crate::model::exp_pf::SLOTS] =
                [std::ptr::null_mut(); crate::model::exp_pf::SLOTS];
            for (i, f) in fns.iter_mut().enumerate() {
                let name = crate::model::exp_pf::kernel_name(i)?;
                let mut cname = name.as_bytes().to_vec();
                cname.push(0);
                unsafe {
                    if (lib.module_get_function)(f, module, cname.as_ptr() as *const c_char)
                        != CUDA_SUCCESS
                    {
                        eprintln!("[exp-pf] PTX に {name} が無い → CPU 経路へ");
                        return None;
                    }
                }
            }
            let mut silu: CUfunction = std::ptr::null_mut();
            let mut cname = crate::model::exp_pf::SILU_KERNEL.as_bytes().to_vec();
            cname.push(0);
            unsafe {
                if (lib.module_get_function)(&mut silu, module, cname.as_ptr() as *const c_char)
                    != CUDA_SUCCESS
                {
                    eprintln!("[exp-pf] PTX に silu が無い → CPU 経路へ");
                    return None;
                }
            }
            // task 162: 行の加重和カーネル。無くても通常の prefill は動くので
            // 任意 (ストリーミング経路だけが `None` を見て CPU へ落ちる)。
            let mut accum: CUfunction = std::ptr::null_mut();
            let mut cname = crate::model::exp_pf::ACCUM_KERNEL.as_bytes().to_vec();
            cname.push(0);
            let accum = unsafe {
                if (lib.module_get_function)(&mut accum, module, cname.as_ptr() as *const c_char)
                    == CUDA_SUCCESS
                {
                    Some(accum)
                } else {
                    None
                }
            };
            Some(ExpPfKernels {
                module,
                fns,
                silu,
                accum,
            })
        })
        .as_ref()
}

/// この型・この k を m 行カーネルで回せるか (`DENNO_EXPERT_IQ_GPU_PF` と
/// `DENNO_EXPERT_IQ_GPU` の両方が on のときだけ真)。
pub fn moe_gemv_iq_pf_ready(ty: crate::kquant::GgmlType, k: usize) -> bool {
    if !cuda_enabled() || !crate::model::exp_pf::pf_enabled() {
        return false;
    }
    if !crate::model::exp_pf::supported(ty) || crate::model::exp_pf::row_bytes(ty, k).is_none() {
        return false;
    }
    exp_pf_kernels().is_some()
}

use crate::model::exp_pf;

/// 1 層ぶんの作業域 (grow-only。スレッドローカル)。
struct PfScratch {
    x: Option<DevBuffer>,
    g: Option<DevBuffer>,
    u: Option<DevBuffer>,
    act: Option<DevBuffer>,
    h: Option<DevBuffer>,
    pg: Option<DevBuffer>,
    pu: Option<DevBuffer>,
    pd: Option<DevBuffer>,
    seg: Option<DevBuffer>,
    rows_gu: Option<DevBuffer>,
    rows_id: Option<DevBuffer>,
    /// task 162: 行の加重和 (ストリーミング経路) 用。
    prow: Option<DevBuffer>,
    wrow: Option<DevBuffer>,
    oacc: Option<DevBuffer>,
}

impl PfScratch {
    fn new() -> Self {
        PfScratch {
            x: None,
            g: None,
            u: None,
            act: None,
            h: None,
            pg: None,
            pu: None,
            pd: None,
            seg: None,
            rows_gu: None,
            rows_id: None,
            prow: None,
            wrow: None,
            oacc: None,
        }
    }
}

thread_local! {
    static PF_SCRATCH: std::cell::RefCell<PfScratch> =
        std::cell::RefCell::new(PfScratch::new());
}

/// 1 層ぶんの expert FFN を m 行カーネルで回す。
///
/// `seg` は 4 語 × nseg (m / rows の先頭 / 0 / 0)、`rows_gu` は行 → トークン番号
/// (`exp_pf::build_plan`)、`out_h` は `total_rows * e` 要素 (GPU の行を**そのまま**
/// 返す)。
/// 呼び出し側は「トークンごとに expert index 昇順で 1 本ずつ」足し込む
/// ([`crate::model::qwen4exp`] の `exp_pf_add_all`)。
///
/// task 151: 以前は加重和を GPU (`dno_exp_pf_accum`) で閉じて `nt × e` だけ
/// 返していたが、**和の順序がヒット/ミスの内訳に依存する**ため、同じ入力でも
/// VRAM の中身が違うと出力が変わった (lab t148b/t148c の `a1 != a2`)。丸めを
/// 一致させるには 1 本ずつ同じ順で足す必要があるので、行を返す形へ戻した。
///
/// `Ok(false)` は「GPU でやらなかった」= 呼び出し側は CPU 経路へ (fail closed)。
#[allow(clippy::too_many_arguments)]
pub fn moe_experts_iq_pf_layer(
    ty_g: crate::kquant::GgmlType,
    ty_u: crate::kquant::GgmlType,
    ty_d: crate::kquant::GgmlType,
    pg: &[u64],
    pu: &[u64],
    pd: &[u64],
    seg: &[u32],
    rows_gu: &[u32],
    xs: &[f32],
    n_in: usize,
    ff: usize,
    e: usize,
    out_h: &mut [f32],
    cpu_miss: &mut dyn FnMut() -> Result<()>,
) -> Result<bool> {
    if PF_DEAD.load(std::sync::atomic::Ordering::Relaxed) {
        return Ok(false);
    }
    let nseg = pg.len();
    let total_rows = rows_gu.len();
    let nh = total_rows * e;
    if nseg == 0
        || total_rows == 0
        || pu.len() != nseg
        || pd.len() != nseg
        || seg.len() != nseg * 4
        || xs.len() % n_in != 0
        || out_h.len() < nh
    {
        return Ok(false);
    }
    if !moe_gemv_iq_pf_ready(ty_g, n_in)
        || !moe_gemv_iq_pf_ready(ty_u, n_in)
        || !moe_gemv_iq_pf_ready(ty_d, ff)
    {
        return Ok(false);
    }
    let (Some(slot_g), Some(slot_u), Some(slot_d)) = (
        exp_pf::slot(ty_g),
        exp_pf::slot(ty_u),
        exp_pf::slot(ty_d),
    ) else {
        return Ok(false);
    };
    let (Some(plan_g), Some(plan_d)) = (
        exp_pf::launch_plan(slot_g, nseg, ff),
        exp_pf::launch_plan(slot_d, nseg, e),
    ) else {
        return Ok(false);
    };
    let Some(ctx) = shared_ctx() else {
        return Ok(false);
    };
    let Some(kernels) = exp_pf_kernels() else {
        return Ok(false);
    };
    ctx.make_current()?;

    // 行の総数 × 行列の幅。g / u / act は total_rows × ff、h は total_rows × e。
    let ng = total_rows * ff;
    // CPU ミス (呼び出し側の flat) が落ちたか。落ちた場合は `out` が途中まで
    // 書かれているので **CPU 経路へ戻してはいけない** (Err で伝える)。
    let cpu_failed = std::cell::Cell::new(false);
    let mut alloc = || -> Result<bool> {
        PF_SCRATCH.with(|cell| -> Result<bool> {
            let mut sc = cell.borrow_mut();
            MoeScratch::ensure(&mut sc.x, xs.len() * 4)?;
            MoeScratch::ensure(&mut sc.g, ng * 4)?;
            MoeScratch::ensure(&mut sc.u, ng * 4)?;
            MoeScratch::ensure(&mut sc.act, ng * 4)?;
            MoeScratch::ensure(&mut sc.h, nh * 4)?;
            MoeScratch::ensure(&mut sc.pg, nseg * 8)?;
            MoeScratch::ensure(&mut sc.pu, nseg * 8)?;
            MoeScratch::ensure(&mut sc.pd, nseg * 8)?;
            MoeScratch::ensure(&mut sc.seg, nseg * 16)?;
            MoeScratch::ensure(&mut sc.rows_gu, total_rows * 4)?;
            MoeScratch::ensure(&mut sc.rows_id, total_rows * 4)?;
            {
                let xb = sc.x.as_ref().expect("確保済み");
                xb.copy_from(xs)?;
                sc.pg.as_ref().expect("確保済み").copy_from(pg)?;
                sc.pu.as_ref().expect("確保済み").copy_from(pu)?;
                sc.pd.as_ref().expect("確保済み").copy_from(pd)?;
                sc.seg.as_ref().expect("確保済み").copy_from(seg)?;
                sc.rows_gu.as_ref().expect("確保済み").copy_from(rows_gu)?;
                let id: Vec<u32> = exp_pf::identity_rows(total_rows);
                sc.rows_id.as_ref().expect("確保済み").copy_from(&id)?;
                dbg_htod(
                    xs.len() * 4
                        + nseg * 8 * 3
                        + nseg * 16
                        + total_rows * 4 * 2,
                );
            }
            let segb = sc.seg.as_ref().expect("確保済み");
            let rg = sc.rows_gu.as_ref().expect("確保済み");
            let rid = sc.rows_id.as_ref().expect("確保済み");
            let xb = sc.x.as_ref().expect("確保済み");
            let g = sc.g.as_ref().expect("確保済み");
            let u = sc.u.as_ref().expect("確保済み");
            let act = sc.act.as_ref().expect("確保済み");
            let h = sc.h.as_ref().expect("確保済み");
            let t_launch = std::time::Instant::now();
            unsafe {
                // gate と up (同じ行表・同じ入力)。
                let rb_g = exp_pf::row_bytes(ty_g, n_in).unwrap_or(0);
                let rb_u = exp_pf::row_bytes(ty_u, n_in).unwrap_or(0);
                for (f, ptrs, buf, rb, plan) in [
                    (
                        kernels.fns[slot_g],
                        sc.pg.as_ref().expect("確保済み"),
                        g,
                        rb_g,
                        plan_g,
                    ),
                    (
                        kernels.fns[slot_u],
                        sc.pu.as_ref().expect("確保済み"),
                        u,
                        rb_u,
                        plan_g,
                    ),
                ] {
                    let mut pw = ptrs.ptr;
                    let mut px = xb.ptr;
                    let mut po = buf.ptr;
                    let mut ps = segb.ptr;
                    let mut pr = rg.ptr;
                    let (mut ns, mut ni, mut no, mut rb) = (
                        nseg as c_int,
                        n_in as c_int,
                        ff as c_int,
                        rb as c_int,
                    );
                    let mut args = [
                        &mut pw as *mut _ as *mut c_void,
                        &mut px as *mut _ as *mut c_void,
                        &mut po as *mut _ as *mut c_void,
                        &mut ps as *mut _ as *mut c_void,
                        &mut pr as *mut _ as *mut c_void,
                        &mut ns as *mut _ as *mut c_void,
                        &mut ni as *mut _ as *mut c_void,
                        &mut no as *mut _ as *mut c_void,
                        &mut rb as *mut _ as *mut c_void,
                    ];
                    ctx.launch_async(f, plan.grid, plan.block, 0, &mut args)?;
                }
                // act = silu(g) * u
                {
                    let n = ng as c_int;
                    let threads = 256usize;
                    let blocks = ng.div_ceil(threads) as u32;
                    let mut pgg = g.ptr;
                    let mut puu = u.ptr;
                    let mut paa = act.ptr;
                    let mut pn = n;
                    let mut args = [
                        &mut pgg as *mut _ as *mut c_void,
                        &mut puu as *mut _ as *mut c_void,
                        &mut paa as *mut _ as *mut c_void,
                        &mut pn as *mut _ as *mut c_void,
                    ];
                    ctx.launch_async(
                        kernels.silu,
                        (blocks.max(1), 1, 1),
                        (threads as u32, 1, 1),
                        0,
                        &mut args,
                    )?;
                }
                // down (入力は act の行が詰まった形 = rows_id)
                {
                    let mut pw = sc.pd.as_ref().expect("確保済み").ptr;
                    let mut px = act.ptr;
                    let mut po = h.ptr;
                    let mut ps = segb.ptr;
                    let mut pr = rid.ptr;
                    let (mut ns, mut ni, mut no, mut rb) = (
                        nseg as c_int,
                        ff as c_int,
                        e as c_int,
                        exp_pf::row_bytes(ty_d, ff).unwrap_or(0) as c_int,
                    );
                    let mut args = [
                        &mut pw as *mut _ as *mut c_void,
                        &mut px as *mut _ as *mut c_void,
                        &mut po as *mut _ as *mut c_void,
                        &mut ps as *mut _ as *mut c_void,
                        &mut pr as *mut _ as *mut c_void,
                        &mut ns as *mut _ as *mut c_void,
                        &mut ni as *mut _ as *mut c_void,
                        &mut no as *mut _ as *mut c_void,
                        &mut rb as *mut _ as *mut c_void,
                    ];
                    ctx.launch_async(
                        kernels.fns[slot_d],
                        plan_d.grid,
                        plan_d.block,
                        0,
                        &mut args,
                    )?;
                }
            }
            exp_pf::note_kernel_ns(t_launch.elapsed().as_nanos() as u64);
            // GPU の計算が走っている間に CPU のミスを計算する (重ねる)。
            // 層あたり GPU 5.6 ms / CPU 57 ms なので、待ちはほぼ消える。
            if let Err(e) = (cpu_miss)() {
                cpu_failed.set(true);
                return Err(e);
            }
            let t_sync = std::time::Instant::now();
            unsafe { ctx.sync()?; }
            exp_pf::note_kernel_ns(t_sync.elapsed().as_nanos() as u64);
            let t_d2h = std::time::Instant::now();
            h.to_slice(&mut out_h[..nh])?;
            exp_pf::note_d2h_ns(t_d2h.elapsed().as_nanos() as u64);
            dbg_d2h(nh * 4);
            Ok(true)
        })
    };
    match alloc() {
        Ok(v) => Ok(v),
        Err(e) => {
            if cpu_failed.get() {
                // CPU ミスの失敗は隠さない (out は途中まで書かれている)。
                return Err(e);
            }
            // 確保失敗はこのプロセスで 1 回だけ記録し、以後は CPU に固定する。
            if !PF_DEAD.swap(true, std::sync::atomic::Ordering::Relaxed) {
                tracing::error!("[exp-pf] 作業域を確保できないので以後 CPU 経路: {e:#}");
            }
            Ok(false)
        }
    }
}

// ---------------------------------------------------------------------------
// task 162: prefill のミス expert を載せるステージング (2 枚 + pinned + 別ストリーム)
// ---------------------------------------------------------------------------
//
// task 156 のステージングを、新型ホスト (PCIe Gen5 x16、H2D 52.6 GB/s pinned /
// 19.6 GB/s pageable) 向けに作り直したもの。task 156 との違いは 3 つ。
//
// 1. 2 枚のステージング (ダブルバッファ) に分け、グループ i+1 の H2D を
//    グループ i の計算と重ねる。上げは専用の**非ブロッキング**ストリームへ積む
//    (blocking にすると legacy の null ストリームと暗黙に同期して 1 バイトも
//    重ならない)。計算側は自分のグループの完了イベントだけを待つ。
// 2. pinned のバウンスバッファ経由 (`DENNO_PF_STREAM_PIN=1`、既定)。ホストの
//    写しは rayon で並列化する (`0` は pageable の同期コピー = task 156 と同じ)。
//    **注意**: pinned 経由は「ページキャッシュ → pinned」の写しがホストの
//    DRAM 帯域を食うので、pageable の driver staging より速いとは限らない。
//    実測は `[exp-pf-stream] probe_GBs=` (最初のグループを同期で測った実速度) で見る。
// 3. ステージングは `cuMemAlloc` を直接叩き、**decode の LRU を 1 本も動かさない**。
//    `DevBuffer::alloc_tagged` の確保失敗フォールバックは expert を追い出すので
//    ここでは使わない。空きが 768 MiB を切らない範囲だけ使う (t156b の事故)。

/// ステージングの行列先頭のアラインメント (カーネルの読み出しに十分な 256 B)。
const PF_STAGE_ALIGN: usize = 256;

/// カードに残す余裕 (MiB)。ステージングはこれを食い潰さない。
const PF_STAGE_RESERVE_MB: usize = 768;

/// ステージング 1 枚の最小サイズ (MiB)。これ未満しか取れないなら諦める。
const PF_STAGE_MIN_MB: usize = 16;

/// ステージングの枚数 (ダブルバッファ)。
const PF_STAGE_SLOTS: usize = 2;

fn pf_stage_align_up(x: usize) -> usize {
    x.div_ceil(PF_STAGE_ALIGN) * PF_STAGE_ALIGN
}

/// ステージング 1 枚。
struct PfSlot {
    buf: Option<DevBuffer>,
    cap: usize,
    /// 一度でも H2D を発行したか (`ev_use` の有効性)。
    used: bool,
    /// この枚への H2D の完了。
    ev_up: Option<CopyEvent>,
    /// この枚を読むカーネルの完了 (再利用の前に待つ)。
    ev_use: Option<CopyEvent>,
}

impl PfSlot {
    fn new() -> Self {
        PfSlot {
            buf: None,
            cap: 0,
            used: false,
            ev_up: None,
            ev_use: None,
        }
    }
}

/// スレッドごとのステージング一式。
struct PfStream {
    slot: [PfSlot; PF_STAGE_SLOTS],
    /// スロットごとの pinned バウンスバッファ (grow-only)。
    pin: [Option<PinMem>; PF_STAGE_SLOTS],
    /// H2D 専用の非ブロッキングストリーム。
    up: Option<CopyStream>,
    /// 実 H2D を 1 回だけ測る。
    probed: bool,
}

impl PfStream {
    fn new() -> Self {
        PfStream {
            slot: [PfSlot::new(), PfSlot::new()],
            pin: [None, None],
            up: None,
            probed: false,
        }
    }
}

thread_local! {
    static PF_STREAM: std::cell::RefCell<PfStream> =
        std::cell::RefCell::new(PfStream::new());
}

/// ステージングを解放する (prefill の終端)。
///
/// decode のあいだ抱えたままだと expert の LRU がその分だけ狭くなるので、
/// リクエストの終わりに必ず返す。
pub fn pf_stream_release() {
    let _ = PF_STREAM.try_with(|cell| {
        let mut st = cell.borrow_mut();
        for s in st.slot.iter_mut() {
            *s = PfSlot::new();
        }
        for p in st.pin.iter_mut() {
            *p = None;
        }
        st.up = None;
        st.probed = false;
    });
}

/// ステージングの現在の使用量 (確保バイト, 残り空き MiB)。診断用。
pub fn pf_stage_usage() -> (usize, usize) {
    PF_STREAM.with(|cell| {
        let st = cell.borrow();
        let cap: usize = st.slot.iter().map(|s| s.cap).sum();
        (cap, dev_mem_mb().map(|(f, _)| f).unwrap_or(0))
    })
}

/// 空き VRAM から余裕を引いた範囲で確保する (半分ずつ落とす)。
///
/// `DevBuffer::alloc_tagged` は失敗すると expert を追い出すので**使わない**
/// (decode の在庫を動かさないのがこの経路の前提)。
fn pf_stage_alloc(want: usize) -> Option<DevBuffer> {
    if want == 0 {
        return None;
    }
    let free_mb = dev_mem_mb().map(|(f, _)| f).unwrap_or(0);
    let room = free_mb.saturating_sub(PF_STAGE_RESERVE_MB) << 20;
    let mut want = want.min(room);
    while want >= (PF_STAGE_MIN_MB << 20) {
        if let Ok(ptr) = DevBuffer::raw_alloc(want) {
            crate::mem_audit::note_alloc(crate::mem_audit::TAG_EXPERTS, want.max(1));
            return Some(DevBuffer {
                ptr,
                bytes: want,
                owned: true,
                tag: crate::mem_audit::TAG_EXPERTS,
            });
        }
        want /= 2;
    }
    None
}

/// 1 グループの上げの結果。
struct PfPump {
    /// グループ内の expert の (gate, up, down) デバイスポインタ (items と同じ順)。
    ptrs: Vec<[u64; 3]>,
    /// 上げたバイト数。
    bytes: usize,
    /// ホスト側の写しの時間。
    copy_ns: u64,
    /// 最初の 1 回だけ測った H2D (バイト, 時間)。
    probe: Option<(usize, u64)>,
}

/// グループ `g` をスロット `g % 2` へ上げる。
///
/// `items` は (expert 番号, [gate, up, down] のホストバイト列)。
/// **同じスロットを使った 2 つ前のグループの計算完了を待ってから**書き込む。
fn pf_pump_in(
    st: &mut PfStream,
    g: u64,
    items: &[(u16, [&[u8]; 3])],
    pinned: bool,
) -> Result<PfPump> {
    let s = (g as usize) % PF_STAGE_SLOTS;
    let mut lens: Vec<[usize; 3]> = Vec::with_capacity(items.len());
    let mut need = 0usize;
    for (_, b) in items {
        let l = [b[0].len(), b[1].len(), b[2].len()];
        need += l
            .iter()
            .map(|&x| pf_stage_align_up(x))
            .sum::<usize>();
        lens.push(l);
    }
    // 1. 再利用の前に、このスロットを読んだ計算の完了を待つ。
    if st.slot[s].used {
        if let Some(ev) = st.slot[s].ev_use.as_ref() {
            let Some(es) = lib()?.event_sync else {
                bail!("cuEventSynchronize が無い");
            };
            unsafe {
                check(es(ev.0), "cuEventSynchronize (stage use)")?;
            }
        }
    }
    // 2. 確保 (足りなければこの 1 回だけ広げる)。
    if st.slot[s].cap < need {
        let want = need.max(PF_STAGE_MIN_MB << 20);
        match pf_stage_alloc(want) {
            Some(b) => {
                st.slot[s].cap = b.bytes();
                st.slot[s].buf = Some(b);
            }
            None => bail!(
                "ステージング {} MiB を確保できない (空き {} MiB)",
                want >> 20,
                dev_mem_mb().map(|(f, _)| f).unwrap_or(0)
            ),
        }
    }
    // 確保できたサイズが必要量に足りないなら、このグループは上げない
    // (呼び出し側が従来経路へ落ちる)。
    if st.slot[s].cap < need {
        bail!(
            "ステージングが足りない (必要 {} MiB / 確保 {} MiB)",
            need >> 20,
            st.slot[s].cap >> 20
        );
    }
    let base = st.slot[s].buf.as_ref().expect("確保済み").ptr();
    // 3. デバイス側の置き場所を決める。
    let mut cursor = 0usize;
    let mut ptrs: Vec<[u64; 3]> = Vec::with_capacity(items.len());
    for l in &lens {
        let mut p = [0u64; 3];
        for m in 0..3 {
            p[m] = base + cursor as u64;
            cursor += pf_stage_align_up(l[m]);
        }
        ptrs.push(p);
    }
    let t_copy = std::time::Instant::now();
    let mut probe: Option<(usize, u64)> = None;
    if pinned {
        // 4a. pinned へ並列に写してから、非同期で H2D を積む。
        let up = match st.up.as_ref() {
            Some(u) => u.0,
            None => {
                let l = lib()?;
                let (Some(create), Some(ec)) = (l.stream_create, l.event_create) else {
                    bail!("cuStreamCreate / cuEventCreate が無い");
                };
                let mut h: CUstream = std::ptr::null_mut();
                const CU_STREAM_NON_BLOCKING: u32 = 0x01;
                unsafe {
                    if create(&mut h, CU_STREAM_NON_BLOCKING) != CUDA_SUCCESS {
                        bail!("cuStreamCreate が失敗");
                    }
                }
                st.up = Some(CopyStream(h));
                // イベントはスロットごとに 1 本ずつ。
                for i in 0..PF_STAGE_SLOTS {
                    if st.slot[i].ev_up.is_none() {
                        let mut ev: CUevent = std::ptr::null_mut();
                        const CU_EVENT_DISABLE_TIMING: u32 = 0x02;
                        unsafe {
                            if ec(&mut ev, CU_EVENT_DISABLE_TIMING) != CUDA_SUCCESS {
                                bail!("cuEventCreate が失敗");
                            }
                        }
                        st.slot[i].ev_up = Some(CopyEvent(ev));
                    }
                    if st.slot[i].ev_use.is_none() {
                        let mut ev: CUevent = std::ptr::null_mut();
                        const CU_EVENT_DISABLE_TIMING: u32 = 0x02;
                        unsafe {
                            if ec(&mut ev, CU_EVENT_DISABLE_TIMING) != CUDA_SUCCESS {
                                bail!("cuEventCreate (use) が失敗");
                            }
                        }
                        st.slot[i].ev_use = Some(CopyEvent(ev));
                    }
                }
                h
            }
        };
        {
            let cap = st.pin[s].as_ref().map(|p| p.bytes).unwrap_or(0);
            if cap < need {
                st.pin[s] = Some(PinMem::alloc(need.max(1))?);
            }
        }
        let pin = st.pin[s].as_ref().expect("確保済み");
        let pin_base = pin.ptr as usize;
        // (dst オフセット, バイト列) を並べる。
        let mut parts: Vec<(usize, &[u8])> = Vec::with_capacity(items.len() * 3);
        let mut cursor = 0usize;
        for (i, (_, b)) in items.iter().enumerate() {
            for m in 0..3 {
                if !b[m].is_empty() {
                    parts.push((cursor, b[m]));
                }
                cursor += pf_stage_align_up(lens[i][m]);
            }
        }
        #[cfg(feature = "par")]
        {
            use rayon::prelude::*;
            parts.par_iter().for_each(|&(off, bytes)| unsafe {
                std::ptr::copy_nonoverlapping(
                    bytes.as_ptr(),
                    (pin_base + off) as *mut u8,
                    bytes.len(),
                );
            });
        }
        #[cfg(not(feature = "par"))]
        {
            for &(off, bytes) in parts.iter() {
                unsafe {
                    std::ptr::copy_nonoverlapping(
                        bytes.as_ptr(),
                        (pin_base + off) as *mut u8,
                        bytes.len(),
                    );
                }
            }
        }
        let copy_ns = t_copy.elapsed().as_nanos() as u64;
        // 5a. 1 本の非同期コピーとして積む (行列ごとに分かれているので 3 回)。
        let l = lib()?;
        let t_dma = std::time::Instant::now();
        let mut cursor = 0usize;
        for (i, _) in items.iter().enumerate() {
            for m in 0..3 {
                let n = lens[i][m];
                if n > 0 {
                    unsafe {
                        check(
                            (l.memcpy_htod_async)(
                                base + cursor as u64,
                                (pin_base + cursor) as *const c_void,
                                n,
                                up,
                            ),
                            "cuMemcpyHtoDAsync (stage)",
                        )?;
                    }
                }
                cursor += pf_stage_align_up(n);
            }
        }
        dbg_htod(need);
        // 6a. 完了イベントを積む。
        let Some(record) = l.event_record else {
            bail!("cuEventRecord が無い");
        };
        if let Some(ev) = st.slot[s].ev_up.as_ref() {
            unsafe {
                check(record(ev.0, up), "cuEventRecord (stage up)")?;
            }
        }
        // 7a. 最初の 1 回だけ実速度を測る (同期して待つ)。
        if !st.probed {
            st.probed = true;
            if let Some(ev) = st.slot[s].ev_up.as_ref() {
                let Some(es) = l.event_sync else {
                    bail!("cuEventSynchronize が無い");
                };
                unsafe {
                    check(es(ev.0), "cuEventSynchronize (probe)")?;
                }
            }
            let ns = t_dma.elapsed().as_nanos() as u64;
            probe = Some((need, ns));
        }
        st.slot[s].used = true;
        Ok(PfPump {
            ptrs,
            bytes: need,
            copy_ns,
            probe,
        })
    } else {
        // 4b. pageable の同期コピー (task 156 と同じ)。重なりは無い。
        let buf = st.slot[s].buf.as_ref().expect("確保済み");
        let mut cursor = 0usize;
        for (i, (_, b)) in items.iter().enumerate() {
            for m in 0..3 {
                if !b[m].is_empty() {
                    buf.copy_from_at(cursor, b[m])?;
                }
                cursor += pf_stage_align_up(lens[i][m]);
            }
        }
        let copy_ns = t_copy.elapsed().as_nanos() as u64;
        dbg_htod(need);
        st.slot[s].used = true;
        Ok(PfPump {
            ptrs,
            bytes: need,
            copy_ns,
            probe: None,
        })
    }
}

/// グループ `g` の H2D 完了を待つ (ホスト)。待ち時間 (ns) を返す。
fn pf_wait_up_in(st: &mut PfStream, g: u64, pinned: bool) -> Result<u64> {
    if !pinned {
        return Ok(0);
    }
    let s = (g as usize) % PF_STAGE_SLOTS;
    let Some(ev) = st.slot[s].ev_up.as_ref() else {
        return Ok(0);
    };
    let Some(es) = lib()?.event_sync else {
        return Ok(0);
    };
    let t = std::time::Instant::now();
    unsafe {
        check(es(ev.0), "cuEventSynchronize (stage up)")?;
    }
    Ok(t.elapsed().as_nanos() as u64)
}

/// グループ `g` の計算を積んだ後に呼ぶ (スロットの再利用判定用)。
fn pf_mark_used_in(st: &mut PfStream, g: u64, pinned: bool) {
    if !pinned {
        return;
    }
    let s = (g as usize) % PF_STAGE_SLOTS;
    if let Some(ev) = st.slot[s].ev_use.as_ref() {
        if let Ok(l) = lib() {
            if let Some(record) = l.event_record {
                unsafe {
                    let _ = record(ev.0, std::ptr::null_mut());
                }
            }
        }
    }
}

/// 1 グループぶんの m 行カーネルを起動する (gate, up, silu, down)。
///
/// `seg` は**グループの先頭**を指し、`nseg` はそのグループの segment 数。
/// `rows` は全体表のまま (row_off が絶対添字なので offsets を足さない)。
/// 出力 (g / u / act / h) も絶対の行添字で書かれる。
#[allow(clippy::too_many_arguments)]
unsafe fn pf_launch_group(
    ctx: &CudaCtx,
    kernels: &ExpPfKernels,
    slot_g: usize,
    slot_u: usize,
    slot_d: usize,
    pg: CUdeviceptr,
    pu: CUdeviceptr,
    pd: CUdeviceptr,
    xb: CUdeviceptr,
    gb: CUdeviceptr,
    ub: CUdeviceptr,
    act: CUdeviceptr,
    hb: CUdeviceptr,
    seg: CUdeviceptr,
    rows_gu: CUdeviceptr,
    rows_id: CUdeviceptr,
    nseg: usize,
    ro_start: usize,
    ro_end: usize,
    n_in: usize,
    ff: usize,
    e: usize,
    rb_g: usize,
    rb_u: usize,
    rb_d: usize,
) -> Result<()> {
    let plan_g = exp_pf::launch_plan(slot_g, nseg, ff)
        .ok_or_else(|| anyhow::anyhow!("gate の起動形が作れない (nseg={nseg}, ff={ff})"))?;
    let plan_d = exp_pf::launch_plan(slot_d, nseg, e)
        .ok_or_else(|| anyhow::anyhow!("down の起動形が作れない (nseg={nseg}, e={e})"))?;
    // gate と up (同じ行表・同じ入力)。
    for (f, pw0, pb, rb) in [
        (kernels.fns[slot_g], pg, gb, rb_g),
        (kernels.fns[slot_u], pu, ub, rb_u),
    ] {
        let mut pw = pw0;
        let mut px = xb;
        let mut po = pb;
        let mut ps = seg;
        let mut pr = rows_gu;
        let (mut ns, mut ni, mut no, mut rbb) = (
            nseg as c_int,
            n_in as c_int,
            ff as c_int,
            rb as c_int,
        );
        let mut args = [
            &mut pw as *mut _ as *mut c_void,
            &mut px as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut ps as *mut _ as *mut c_void,
            &mut pr as *mut _ as *mut c_void,
            &mut ns as *mut _ as *mut c_void,
            &mut ni as *mut _ as *mut c_void,
            &mut no as *mut _ as *mut c_void,
            &mut rbb as *mut _ as *mut c_void,
        ];
        ctx.launch_async(f, plan_g.grid, plan_g.block, 0, &mut args)?;
    }
    // act = silu(g) * u (このグループの行の範囲だけ)。
    {
        let rows_here = ro_end.saturating_sub(ro_start);
        if rows_here > 0 {
            let n = rows_here * ff;
            let threads = 256usize;
            let blocks = n.div_ceil(threads) as u32;
            let mut pgg = gb + (ro_start * ff * 4) as u64;
            let mut puu = ub + (ro_start * ff * 4) as u64;
            let mut paa = act + (ro_start * ff * 4) as u64;
            let mut pn = n as c_int;
            let mut args = [
                &mut pgg as *mut _ as *mut c_void,
                &mut puu as *mut _ as *mut c_void,
                &mut paa as *mut _ as *mut c_void,
                &mut pn as *mut _ as *mut c_void,
            ];
            ctx.launch_async(
                kernels.silu,
                (blocks.max(1), 1, 1),
                (threads as u32, 1, 1),
                0,
                &mut args,
            )?;
        }
    }
    // down (入力は act の行が詰まった形 = rows_id)。
    {
        let mut pw = pd;
        let mut px = act;
        let mut po = hb;
        let mut ps = seg;
        let mut pr = rows_id;
        let (mut ns, mut ni, mut no, mut rb) = (
            nseg as c_int,
            ff as c_int,
            e as c_int,
            rb_d as c_int,
        );
        let mut args = [
            &mut pw as *mut _ as *mut c_void,
            &mut px as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut ps as *mut _ as *mut c_void,
            &mut pr as *mut _ as *mut c_void,
            &mut ns as *mut _ as *mut c_void,
            &mut ni as *mut _ as *mut c_void,
            &mut no as *mut _ as *mut c_void,
            &mut rb as *mut _ as *mut c_void,
        ];
        ctx.launch_async(
            kernels.fns[slot_d],
            plan_d.grid,
            plan_d.block,
            0,
            &mut args,
        )?;
    }
    Ok(())
}

/// 1 層ぶんのストリーミング入力 (plan 順)。
///
/// `dev` は VRAM 常駐 (ヒット) のポインタ、`host` はミスのホストバイト列。
/// どちらか一方だけが `Some`。
pub struct PfStreamEntry<'a> {
    pub expert: u16,
    pub dev: Option<[u64; 3]>,
    pub host: Option<[&'a [u8]; 3]>,
}

/// task 162: 1 層ぶんの expert FFN を、ミスをステージングへ上げながら回す。
///
/// - ミスは `DENNO_PF_STREAM_GROUP` 本ずつのグループに切り、2 枚のステージングを
///   交互に使って H2D と計算を重ねる。H2D は専用ストリーム、計算は null ストリーム。
/// - 行の加重和は GPU の `dno_exp_pf_accum` で閉じ、D2H は `ntok × e` だけ。
///   **和の順序は (トークン, j 昇順) の 1 本**で、CPU 経路とは丸めが変わる
///   (FMA の縮約。task 162 で許容。decode はこの経路を通らない)。
/// - 載せられなかったミス (容量外・確保失敗) は呼び出し側が CPU で足す。
///
/// `Ok(None)` = 使わなかった (`out` は触っていない)。呼び出し側は従来経路へ。
#[allow(clippy::too_many_arguments)]
pub fn moe_experts_iq_pf_layer_stream(
    ty_g: crate::kquant::GgmlType,
    ty_u: crate::kquant::GgmlType,
    ty_d: crate::kquant::GgmlType,
    entries: &[PfStreamEntry<'_>],
    seg: &[u32],
    rows_gu: &[u32],
    xs: &[f32],
    n_in: usize,
    ff: usize,
    e: usize,
    ntok: usize,
    k: usize,
    prow: &[u32],
    wrow: &[f32],
    group: usize,
    out: &mut [f32],
) -> Result<Option<u32>> {
    if PF_DEAD.load(std::sync::atomic::Ordering::Relaxed) {
        return Ok(None);
    }
    let nseg = entries.len();
    let total_rows = rows_gu.len();
    if nseg == 0
        || total_rows == 0
        || ntok == 0
        || k == 0
        || seg.len() != nseg * 4
        || xs.len() != ntok * n_in
        || prow.len() != ntok * k
        || wrow.len() < ntok * k
        || out.len() < ntok * e
    {
        return Ok(None);
    }
    if !moe_gemv_iq_pf_ready(ty_g, n_in)
        || !moe_gemv_iq_pf_ready(ty_u, n_in)
        || !moe_gemv_iq_pf_ready(ty_d, ff)
    {
        return Ok(None);
    }
    let (Some(slot_g), Some(slot_u), Some(slot_d)) = (
        exp_pf::slot(ty_g),
        exp_pf::slot(ty_u),
        exp_pf::slot(ty_d),
    ) else {
        return Ok(None);
    };
    let Some(ctx) = shared_ctx() else {
        return Ok(None);
    };
    let Some(kernels) = exp_pf_kernels() else {
        return Ok(None);
    };
    let Some(accum) = kernels.accum else {
        return Ok(None);
    };
    if ctx.make_current().is_err() {
        return Ok(None);
    }
    let (rb_g, rb_u, rb_d) = match (
        exp_pf::row_bytes(ty_g, n_in),
        exp_pf::row_bytes(ty_u, n_in),
        exp_pf::row_bytes(ty_d, ff),
    ) {
        (Some(a), Some(b), Some(c)) => (a, b, c),
        _ => return Ok(None),
    };
    let pinned = exp_pf::stream_pin() == 1;
    let ng = total_rows * ff;
    let nh = total_rows * e;

    let mut work = || -> Result<Option<u32>> {
        PF_SCRATCH.with(|cell| -> Result<Option<u32>> {
            let mut sc = cell.borrow_mut();
            MoeScratch::ensure(&mut sc.x, xs.len() * 4)?;
            MoeScratch::ensure(&mut sc.g, ng * 4)?;
            MoeScratch::ensure(&mut sc.u, ng * 4)?;
            MoeScratch::ensure(&mut sc.act, ng * 4)?;
            MoeScratch::ensure(&mut sc.h, nh * 4)?;
            MoeScratch::ensure(&mut sc.pg, nseg * 8)?;
            MoeScratch::ensure(&mut sc.pu, nseg * 8)?;
            MoeScratch::ensure(&mut sc.pd, nseg * 8)?;
            MoeScratch::ensure(&mut sc.seg, nseg * 16)?;
            MoeScratch::ensure(&mut sc.rows_gu, total_rows * 4)?;
            MoeScratch::ensure(&mut sc.rows_id, total_rows * 4)?;
            MoeScratch::ensure(&mut sc.prow, ntok * k * 4)?;
            MoeScratch::ensure(&mut sc.wrow, ntok * k * 4)?;
            MoeScratch::ensure(&mut sc.oacc, ntok * e * 4)?;
            {
                let xb = sc.x.as_ref().expect("確保済み");
                xb.copy_from(xs)?;
                sc.seg.as_ref().expect("確保済み").copy_from(seg)?;
                sc.rows_gu.as_ref().expect("確保済み").copy_from(rows_gu)?;
                let id: Vec<u32> = exp_pf::identity_rows(total_rows);
                sc.rows_id.as_ref().expect("確保済み").copy_from(&id)?;
                sc.prow.as_ref().expect("確保済み").copy_from(prow)?;
                sc.wrow
                    .as_ref()
                    .expect("確保済み")
                    .copy_from(&wrow[..ntok * k])?;
            }
            dbg_htod(xs.len() * 4 + nseg * 16 + total_rows * 4 * 2 + ntok * k * 8);
            let xb = sc.x.as_ref().expect("確保済み").ptr();
            let gb = sc.g.as_ref().expect("確保済み").ptr();
            let ub = sc.u.as_ref().expect("確保済み").ptr();
            let act = sc.act.as_ref().expect("確保済み").ptr();
            let hb = sc.h.as_ref().expect("確保済み").ptr();
            let segb = sc.seg.as_ref().expect("確保済み").ptr();
            let rg = sc.rows_gu.as_ref().expect("確保済み").ptr();
            let rid = sc.rows_id.as_ref().expect("確保済み").ptr();

            // 1. ミスの本数を数え、グループ分けを決める。
            //    容量は「2 枚に分けたステージング 1 枚ぶん」。実際に確保できる
            //    サイズで切るので、載せられない expert は出ない (spill 0)。
            let mut needs = vec![0usize; nseg];
            let mut miss_total = 0usize;
            for (i, en) in entries.iter().enumerate() {
                if en.dev.is_some() {
                    continue;
                }
                let Some(h) = en.host else {
                    return Ok(None);
                };
                let need = h
                    .iter()
                    .map(|b| pf_stage_align_up(b.len()))
                    .sum::<usize>();
                if need == 0 {
                    return Ok(None);
                }
                needs[i] = need;
                miss_total += need;
            }
            if miss_total == 0 {
                return Ok(None);
            }
            let want_slot = miss_total.min((exp_pf::stream_bytes() / PF_STAGE_SLOTS).max(1 << 20));
            // 1 枚ぶんの容量を先に確保して、その実サイズでグループを切る。
            let mut slot_cap = 0usize;
            PF_STREAM.with(|cell| -> Result<()> {
                let mut st = cell.borrow_mut();
                if st.slot[0].cap < want_slot {
                    match pf_stage_alloc(want_slot) {
                        Some(b) => {
                            st.slot[0].cap = b.bytes();
                            st.slot[0].buf = Some(b);
                        }
                        None => return Ok(()),
                    }
                }
                slot_cap = st.slot[0].cap;
                Ok(())
            })?;
            if slot_cap == 0 {
                return Ok(None);
            }
            // 2 枚目も同じ容量で確保する (片方だけ小さいと交互に使えない)。
            PF_STREAM.with(|cell| -> Result<()> {
                let mut st = cell.borrow_mut();
                if st.slot[1].cap < slot_cap {
                    match pf_stage_alloc(slot_cap) {
                        Some(b) => {
                            st.slot[1].cap = b.bytes();
                            st.slot[1].buf = Some(b);
                        }
                        None => {
                            slot_cap = st.slot[0].cap.min(st.slot[1].cap);
                        }
                    }
                }
                if st.slot[1].cap < slot_cap {
                    slot_cap = st.slot[1].cap;
                }
                Ok(())
            })?;
            if slot_cap == 0 {
                return Ok(None);
            }
            let Some(bounds) = exp_pf::group_bounds(&needs, slot_cap, group) else {
                return Ok(None);
            };
            // 2. グループごとに上げて計算する。`pg/pu/pd` の表は全体を 1 本で持ち、
            //    グループの先頭を指して起動する。
            let pg_tab = sc.pg.as_ref().expect("確保済み");
            let pu_tab = sc.pu.as_ref().expect("確保済み");
            let pd_tab = sc.pd.as_ref().expect("確保済み");
            for (gi, &(a, b)) in bounds.iter().enumerate() {
                // (a) ミスの items を作って上げる (g = グローバル通し番号)。
                let g = gi as u64;
                let items: Vec<(u16, [&[u8]; 3])> = entries[a..b]
                    .iter()
                    .filter_map(|en| en.host.map(|h| (en.expert, h)))
                    .collect();
                let pump = if items.is_empty() {
                    PfPump {
                        ptrs: Vec::new(),
                        bytes: 0,
                        copy_ns: 0,
                        probe: None,
                    }
                } else {
                    PF_STREAM.with(|cell| -> Result<PfPump> {
                        let mut st = cell.borrow_mut();
                        pf_pump_in(&mut st, g, &items, pinned)
                    })?
                };
                // (b) デバイスポインタの表を書く (ミスはステージング、ヒットは常駐)。
                let mut ip = 0usize;
                {
                    let mut vg = vec![0u64; b - a];
                    let mut vu = vec![0u64; b - a];
                    let mut vd = vec![0u64; b - a];
                    for (j, en) in entries[a..b].iter().enumerate() {
                        if let Some(d) = en.dev {
                            vg[j] = d[0];
                            vu[j] = d[1];
                            vd[j] = d[2];
                        } else if ip < pump.ptrs.len() {
                            vg[j] = pump.ptrs[ip][0];
                            vu[j] = pump.ptrs[ip][1];
                            vd[j] = pump.ptrs[ip][2];
                            ip += 1;
                        } else {
                            // 表が足りない = 内部の不整合。この層は従来経路へ。
                            return Ok(None);
                        }
                    }
                    pg_tab.copy_from_at(a * 8, &vg)?;
                    pu_tab.copy_from_at(a * 8, &vu)?;
                    pd_tab.copy_from_at(a * 8, &vd)?;
                }
                // (c) 自分のグループの H2D 完了を待つ (ホスト)。
                let w = PF_STREAM.with(|cell| -> Result<u64> {
                    let mut st = cell.borrow_mut();
                    pf_wait_up_in(&mut st, g, pinned)
                })?;
                // (d) カーネルを積む。
                let ro_start = seg[a * 4 + 1] as usize;
                let ro_end = if b > a {
                    let last = b - 1;
                    seg[last * 4 + 1] as usize + seg[last * 4] as usize
                } else {
                    ro_start
                };
                unsafe {
                    pf_launch_group(
                        ctx,
                        kernels,
                        slot_g,
                        slot_u,
                        slot_d,
                        pg_tab.ptr() + (a * 8) as u64,
                        pu_tab.ptr() + (a * 8) as u64,
                        pd_tab.ptr() + (a * 8) as u64,
                        xb,
                        gb,
                        ub,
                        act,
                        hb,
                        segb + (a * 16) as u64,
                        rg,
                        rid,
                        b - a,
                        ro_start,
                        ro_end,
                        n_in,
                        ff,
                        e,
                        rb_g,
                        rb_u,
                        rb_d,
                    )?;
                }
                PF_STREAM.with(|cell| {
                    let mut st = cell.borrow_mut();
                    pf_mark_used_in(&mut st, g, pinned);
                });
                let rows_here = ro_end.saturating_sub(ro_start);
                exp_pf::note_stream_group(
                    pump.bytes,
                    rows_here,
                    items.len(),
                    pump.copy_ns,
                    w,
                );
                if let Some((pb, pn)) = pump.probe {
                    exp_pf::note_stream_probe(pb, pn);
                }
            }
            // 3. 行の加重和を GPU で閉じる。
            {
                let prowb = sc.prow.as_ref().expect("確保済み").ptr();
                let wb = sc.wrow.as_ref().expect("確保済み").ptr();
                let oacc = sc.oacc.as_ref().expect("確保済み");
                let threads = 256usize;
                let mut ph = hb;
                let mut pp = prowb;
                let mut pw = wb;
                let mut po = oacc.ptr();
                let (mut kk, mut ee, mut nn) = (k as c_int, e as c_int, ntok as c_int);
                let mut args = [
                    &mut ph as *mut _ as *mut c_void,
                    &mut pp as *mut _ as *mut c_void,
                    &mut pw as *mut _ as *mut c_void,
                    &mut po as *mut _ as *mut c_void,
                    &mut kk as *mut _ as *mut c_void,
                    &mut ee as *mut _ as *mut c_void,
                    &mut nn as *mut _ as *mut c_void,
                ];
                let t_k = std::time::Instant::now();
                unsafe {
                    ctx.launch_async(
                        accum,
                        (ntok as u32, 1, 1),
                        (threads as u32, 1, 1),
                        0,
                        &mut args,
                    )?;
                }
                exp_pf::note_kernel_ns(t_k.elapsed().as_nanos() as u64);
                let t_sync = std::time::Instant::now();
                ctx.sync()?;
                exp_pf::note_kernel_ns(t_sync.elapsed().as_nanos() as u64);
                let t_d2h = std::time::Instant::now();
                oacc.to_slice(&mut out[..ntok * e])?;
                exp_pf::note_d2h_ns(t_d2h.elapsed().as_nanos() as u64);
                dbg_d2h(ntok * e * 4);
            }
            exp_pf::note_stream_layer();
            Ok(Some(nseg as u32))
        })
    };
    match work() {
        Ok(v) => Ok(v),
        Err(e) => {
            // 確保失敗・形の不整合はこのプロセスで 1 回だけ記録し、以後 CPU に固定する。
            if !PF_DEAD.swap(true, std::sync::atomic::Ordering::Relaxed) {
                tracing::error!("[exp-pf-stream] 使えないので以後 CPU 経路: {e:#}");
            }
            Ok(None)
        }
    }
}

#[cfg(test)]
mod pf_stream_tests {
    //! task 162: ストリーミング経路の**契約**を GPU 無しで固定する。

    use super::*;
    use crate::kquant::GgmlType;

    /// GPU が無い (このコンテナ) ときは起動前に `Ok(None)` を返し、`out` を
    /// 1 要素も書かない (呼び出し側は従来経路をそのまま回せる)。
    #[test]
    fn stream_declines_without_gpu_and_leaves_out_untouched() {
        let host: Vec<u8> = vec![0u8; 256];
        let entries = vec![PfStreamEntry {
            expert: 3,
            dev: None,
            host: Some([host.as_slice(), host.as_slice(), host.as_slice()]),
        }];
        let seg = [1u32, 0, 0, 0];
        let rows = [0u32];
        let xs = vec![0.0f32; 8];
        let prow = [0u32];
        let wrow = [1.0f32];
        let mut out = vec![7.0f32; 4];
        let r = moe_experts_iq_pf_layer_stream(
            GgmlType::IQ3S,
            GgmlType::IQ3S,
            GgmlType::IQ3S,
            &entries,
            &seg,
            &rows,
            &xs,
            8,
            16,
            4,
            1,
            1,
            &prow,
            &wrow,
            32,
            &mut out,
        )
        .expect("GPU 無しでもエラーにしない");
        assert!(r.is_none(), "GPU が無いのに起動した");
        assert!(out.iter().all(|&v| v == 7.0), "out を書いてしまった: {out:?}");
        // 形が合わないときも同じ (fail closed)。
        let r2 = moe_experts_iq_pf_layer_stream(
            GgmlType::IQ3S,
            GgmlType::IQ3S,
            GgmlType::IQ3S,
            &entries,
            &[1u32, 0, 0],
            &rows,
            &xs,
            8,
            16,
            4,
            1,
            1,
            &prow,
            &wrow,
            32,
            &mut out,
        );
        assert!(r2.is_err() || r2.expect("shape").is_none());
    }

    /// ステージングは decode の LRU を追い出さない: 確保は `pf_stage_alloc`
    /// (cuMemAlloc 直) だけで、`DevBuffer::alloc_tagged` のフォールバックを
    /// 通らない。ここでは確保要求 0 で何も取らないことを固定する。
    #[test]
    fn stage_alloc_is_a_noop_for_zero() {
        assert!(pf_stage_alloc(0).is_none());
    }
}

#[cfg(test)]
mod iq_overlap_tests {
    //! task 150: 重ね打ち経路の**契約**を GPU 無しで固定する。
    use super::*;
    use crate::kquant::GgmlType;

    /// 形状が不正なら起動前に `Ok(false)` を返し、**CPU ミスのコールバックを
    /// 呼ばない** (呼び出し側は全 expert を CPU で計算し直せる)。呼んでしまうと
    /// 二重計算になるうえ、`out_h` が途中まで書かれた状態で CPU 経路へ戻すことになる。
    #[test]
    fn overlap_skips_cpu_miss_when_it_does_not_launch() {
        let called = std::cell::Cell::new(0u32);
        let mut out = vec![0.0f32; 4];
        // seg_gu の長さが 4 の倍数でない → 起動計画より前に落ちる。
        let r = moe_experts_iq_layer_overlap(
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            &[0u64],
            &[0u64],
            &[0u64],
            &[0u32, 1, 0, 0, 0],
            &[0u32, 1, 0, 0, 0, 0, 0, 0],
            &[0.0f32; 8],
            8,
            16,
            4,
            &mut out,
            || {
                called.set(called.get() + 1);
                Ok(())
            },
        )
        .expect("形状検査は Err ではなく Ok(false)");
        assert!(!r, "不正な形状で GPU 経路を選んではいけない");
        assert_eq!(called.get(), 0, "起動しないのに CPU ミスを走らせた");
        assert!(out.iter().all(|&v| v == 0.0), "out を書いてはいけない");
    }

    /// 逐次版と重ね打ち版は同じ入口 (`iq_layer_run`) を通る。GPU の無い環境では
    /// どちらも `Ok(false)` で、値は 1 つも書かれない。
    #[test]
    fn both_entries_fall_back_without_cuda() {
        let mut out_a = vec![7.0f32; 4];
        let mut out_b = vec![7.0f32; 4];
        let a = moe_experts_iq_layer(
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            &[0u64],
            &[0u64],
            &[0u64],
            &[0u32, 0, 0, 0],
            &[0u32, 0, 0, 0],
            &[0.0f32; 8],
            8,
            16,
            4,
            &mut out_a,
        )
        .expect("逐次版");
        let b = moe_experts_iq_layer_overlap(
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            GgmlType::IQ2S,
            &[0u64],
            &[0u64],
            &[0u64],
            &[0u32, 0, 0, 0],
            &[0u32, 0, 0, 0],
            &[0.0f32; 8],
            8,
            16,
            4,
            &mut out_b,
            || Ok(()),
        )
        .expect("重ね打ち版");
        assert_eq!(a, b, "同じ入口なのに戻り値が違う");
        assert_eq!(out_a, out_b, "out の扱いが違う");
    }
}

#[cfg(test)]
mod grouped_tests {
    //! P40: 起動形の純関数 (GPU 無しでも検証できる部分)。
    use super::*;

    #[test]
    fn launch_plan_sizes_smem_for_two_matrices() {
        // Q4_K (blkj=256) の gate+up: 16 行 × 256 × 4 B × 2 本 = 32 KiB
        let p = grouped_launch_plan(86, 60, 640, 256, 2)
            .expect("plan")
            .expect("some");
        assert_eq!(p.grid, (86, 40, 4)); // 640/16 = 40 行タイル、ceil(60/16) = 4
        assert_eq!(p.block, (16, 16, 1));
        assert_eq!(p.smem, 16 * 256 * 4 * 2);
        assert!(p.smem < 46_000, "48 KiB 既定を超えないこと");
        // Q5_1 (blkj=32) の down: 16 × 32 × 4 = 2 KiB
        let q = grouped_launch_plan(86, 60, 2560, 32, 1)
            .expect("plan")
            .expect("some");
        assert_eq!(q.grid, (86, 160, 4));
        assert_eq!(q.smem, 16 * 32 * 4);
    }

    #[test]
    fn launch_plan_rejects_oversized_smem_and_empty() {
        assert!(grouped_launch_plan(0, 10, 640, 256, 2)
            .expect("plan")
            .is_none());
        assert!(grouped_launch_plan(8, 0, 640, 256, 2)
            .expect("plan")
            .is_none());
        // 3 本同時 (Q4_K) は 48 KiB で既定を超える = 過去に全滅した形
        assert!(grouped_launch_plan(8, 10, 640, 256, 3)
            .expect("plan")
            .is_none());
        // 32 行タイル x 256 要素 x 4 B x 2 = 64 KiB も落ちる
        assert!(grouped_launch_plan(8, 10, 640, 512, 2)
            .expect("plan")
            .is_none());
    }

    #[test]
    fn env_value_parsing() {
        assert!(moe_grouped_gpu_from_value(Some("1")));
        assert!(moe_grouped_gpu_from_value(Some("on")));
        assert!(moe_grouped_gpu_from_value(Some("true")));
        assert!(!moe_grouped_gpu_from_value(None));
        assert!(!moe_grouped_gpu_from_value(Some("0")));
        assert!(!moe_grouped_gpu_from_value(Some("off")));
        assert!(!moe_grouped_gpu_from_value(Some("")));
    }
}

// ===========================================================================
// P17b: エンジン統合 (重み VRAM 常駐 + ピン留め/非同期パイプライン)
// ===========================================================================
//
// `quant::Linear` の int8 パス (apply_bt / apply_batch_bt / apply) から呼ばれ、
// `DENNO_CUDA=1` + feature `cuda` のとき int8 線形層を GPU にオフロードする。
// - 数値は CPU カーネルとビット一致 (同一カーネル = P17 の exactness 契約そのまま)
// - 重みは初回呼び出し時に VRAM へアップロードして常駐 (Quant8Linear のバッファ
//   ポインタをキーにしたレジストリ。ロード後の重みは不変であることが前提)
// - 固定オーバーヘッド削減: ピン留めホストメモリ + 非同期コピー/起動で
//   **1 線形層 = 1 同期** (P17 マイクロベンチでは起動+同期+コピーで約40µs/呼び出し)
// - 初期化失敗/実行時エラーは CPU パスへフォールバック (両者は同一仕様なので
//   出力は不変。実行時エラー後は二度と試さない)

/// ピン留めホストメモリ (非同期コピーの転送元/転送先)。
struct PinMem {
    ptr: *mut c_void,
    bytes: usize,
}

// 生ポインタを保持するだけ (スレッド局所で共有しない)
unsafe impl Send for PinMem {}

impl PinMem {
    fn alloc(bytes: usize) -> Result<Self> {
        let mut ptr: *mut c_void = std::ptr::null_mut();
        // PORTABLE: どのコンテキストからでも有効 (保険)
        const CU_MEMHOSTALLOC_PORTABLE: u32 = 0x01;
        unsafe {
            check(
                (lib()?.mem_host_alloc)(&mut ptr, bytes.max(1), CU_MEMHOSTALLOC_PORTABLE),
                "cuMemHostAlloc",
            )?;
        }
        Ok(Self { ptr, bytes: bytes.max(1) })
    }

    fn as_slice<T>(&self) -> &[T] {
        unsafe { std::slice::from_raw_parts(self.ptr as *const T, self.bytes / std::mem::size_of::<T>()) }
    }

    fn as_mut_slice<T>(&mut self) -> &mut [T] {
        unsafe { std::slice::from_raw_parts_mut(self.ptr as *mut T, self.bytes / std::mem::size_of::<T>()) }
    }
}

impl Drop for PinMem {
    fn drop(&mut self) {
        unsafe {
            let _ = (lib().unwrap().mem_host_free)(self.ptr);
        }
    }
}

thread_local! {
    /// task 144: expert の H2D 用の pinned staging (1 本ぶん。grow-only)。
    static EXPERT_PIN: std::cell::RefCell<Option<PinMem>> =
        const { std::cell::RefCell::new(None) };
}

/// `DENNO_EXPERT_PIN_H2D=1`: expert の H2D を pinned staging 経由にするか。
///
/// 既定 **off**。lab t144d の実測では、この環境の pageable `cuMemcpyHtoD` の方が
/// 速かった (1 本 2.05 MB で pinned 0.34〜0.42 ms / pageable 0.27〜0.30 ms。
/// driver が内部で staging を持つため、自前で pinned へ写すと memcpy が余分)。
/// 転送するバイト列はどちらも同じ (モデルの数値には触らない)。
pub fn expert_pin_h2d() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        matches!(
            std::env::var("DENNO_EXPERT_PIN_H2D").ok().as_deref(),
            Some("1") | Some("true") | Some("on")
        )
    })
}

/// pinned staging 経由でホストのスライスを VRAM へ上げる (task 144)。
///
/// ページャブルなメモリからの `cuMemcpyHtoD` は driver が内部で staging するため、
/// lab t144b の実測では **2.4 GB/s** しか出なかった (expert 1 本 2.05 MB で
/// 0.86 ms)。pinned メモリへ 1 回コピーしてから H2D すると速い。
/// デバイスへ渡るバイト列は [`DevBuffer::from_slice`] と同一 (1 bit も変えない)。
pub fn from_slice_pinned<T: Copy>(data: &[T]) -> Result<DevBuffer> {
    let bytes = std::mem::size_of_val(data);
    let buf = DevBuffer::alloc_tagged(bytes.max(1), crate::mem_audit::TAG_EXPERTS)?;
    if bytes == 0 {
        return Ok(buf);
    }
    EXPERT_PIN.with(|cell| -> Result<()> {
        let mut slot = cell.borrow_mut();
        if slot.as_ref().map(|p| p.bytes).unwrap_or(0) < bytes {
            *slot = Some(PinMem::alloc(bytes)?);
        }
        let pin = slot.as_ref().expect("確保済み");
        unsafe {
            // ホスト側の 1 回コピー (pinned は DMA 可能な常駐メモリ)。
            std::ptr::copy_nonoverlapping(data.as_ptr() as *const u8, pin.ptr as *mut u8, bytes);
            check(
                (lib()?.memcpy_htod)(buf.ptr, pin.ptr, bytes),
                "cuMemcpyHtoD (pinned)",
            )?;
        }
        dbg_htod(bytes);
        Ok(())
    })?;
    Ok(buf)
}

/// s167 (P6): 専用コピーストリーム (h2 の D2H を qkv/z GEMM と重ねる)。
/// driver オブジェクトはコンテキストに属するので Drop で明示的に破棄する
/// (スレッド終了時に解放。`stream_destroy` が無い driver ではリークするだけで、
/// コンテキスト破棄時に回収される)。
struct CopyStream(CUstream);

impl Drop for CopyStream {
    fn drop(&mut self) {
        if let Ok(l) = lib() {
            if let Some(f) = l.stream_destroy {
                unsafe {
                    let _ = f(self.0);
                }
            }
        }
    }
}

/// s167 (P6): コピーストリームの順序付け/完了待ちに使うイベント (RAII)。
struct CopyEvent(CUevent);

impl Drop for CopyEvent {
    fn drop(&mut self) {
        if let Ok(l) = lib() {
            if let Some(f) = l.event_destroy {
                unsafe {
                    let _ = f(self.0);
                }
            }
        }
    }
}

thread_local! {
    /// task 155: 既定 (null) ストリームの完了待ちに使うイベント (スレッドごとに 1 本)。
    static DEF_EV: std::cell::RefCell<Option<CopyEvent>> = const { std::cell::RefCell::new(None) };
}

/// task 155: `cuEventCreate` の `CU_EVENT_DISABLE_TIMING`。
const CU_EVENT_DISABLE_TIMING: u32 = 0x02;

/// task 155: 既定 (null) ストリームの完了だけを**イベント 1 本**で待つ。
///
/// [`CudaCtx::sync`] の `cuCtxSynchronize` はコンテキスト**全体**を待つので、
/// 重ね打ち用のサイドストリーム (shared expert の gate/up) まで待ってしまう。
/// ホストがその結果を要るのは層のずっと後 (shared の join) なので、ここでは
/// null ストリームに打ったイベントだけを待つ。発行済みのカーネル・引数・順序は
/// 1 つも変えない (変わるのは待つ範囲だけ)。
///
/// 実測 (GPU ラボ t155a、swift15-abl IQ3_S、14T、plain = TLINE なし、全ゲート on と
/// off の A/B): decode 46 → 42 ms/tok (短い) / 44 → 38 (3,954) / 47 → 41 (14,139)、
/// prefill +1.1%、md5 は 6 本とも SAME、errors 0。14,139 の台帳は
/// router 4.09 → 1.61 ms/tok (48 層で 52 us/層の同期固定費が消えた)、
/// experts 10.37 → 10.18。**この待ちはモデルの値を 1 ビットも変えない。**
///
/// t155c (TLINE=1 / TLINE_K=1 を両条件に): token 47.06 → 42.29 (3,954) /
/// 49.83 → 44.50 (14,139)。host_wait 25.09 → 22.32 / 29.11 → 26.39 (router の
/// wait が 2.68 → 0.97 / 2.72 → 0.99)、gpu_idle 28.61 → 24.17 / 27.33 → 22.32、
/// gpu_busy は 18.44 → 18.12 / 22.50 → 22.18 で**動かない** (仕事量は同じ)。
///
/// 戻り値 `false` = イベントが使えない。呼び出し側は従来どおり `ctx.sync()` に
/// 落ちること (待たずに進んではいけない)。
pub fn sync_default_stream() -> bool {
    let Ok(l) = lib() else { return false };
    let (Some(create), Some(record), Some(esync)) =
        (l.event_create, l.event_record, l.event_sync)
    else {
        return false;
    };
    DEF_EV.with(|cell| {
        let mut slot = cell.borrow_mut();
        if slot.is_none() {
            let mut ev: CUevent = std::ptr::null_mut();
            if unsafe { create(&mut ev, CU_EVENT_DISABLE_TIMING) } != CUDA_SUCCESS {
                return false;
            }
            *slot = Some(CopyEvent(ev));
        }
        let ev = slot.as_ref().expect("直前に作った").0;
        let t = crate::model::q4ledger::stamp();
        let ok = unsafe { record(ev, std::ptr::null_mut()) } == CUDA_SUCCESS
            && unsafe { esync(ev) } == CUDA_SUCCESS;
        if ok {
            crate::model::q4ledger::note_sync(t);
        }
        ok
    })
}

/// [`sync_default_stream`] が使えない環境用の包み (失敗したら `ctx.sync()`)。
///
/// `scoped == false` (`DENNO_DEC_OVERLAP=0` / `DENNO_ROUTER_FUSED=0`) は従来どおり
/// コンテキスト全体を待つ。
fn sync_default_or_ctx(ctx: &CudaCtx, scoped: bool) -> Result<()> {
    if scoped && sync_default_stream() {
        return Ok(());
    }
    ctx.sync()
}

/// task 155: `DENNO_ROUTER_FUSED` の値解釈 (純関数・テスト用)。
/// **既定 on**、`0` / `off` / `false` でルータの待ちを従来 (cuCtxSynchronize) に戻す。
pub fn router_fused_from_value(v: Option<&str>) -> bool {
    !matches!(v, Some("0") | Some("off") | Some("false"))
}

/// task 155: ルータの待ちを null ストリームのイベントに絞るか (`DENNO_ROUTER_FUSED`)。
pub fn router_fused_enabled() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| router_fused_from_value(std::env::var("DENNO_ROUTER_FUSED").ok().as_deref()))
}

/// task 155: `DENNO_DEC_OVERLAP` の値解釈 (純関数・テスト用)。
/// **既定 on**、`0` / `off` / `false` で expert の待ちを従来に戻す。
pub fn dec_overlap_from_value(v: Option<&str>) -> bool {
    !matches!(v, Some("0") | Some("off") | Some("false"))
}

/// task 155: expert の完了待ちを null ストリームに絞るか (`DENNO_DEC_OVERLAP`)。
pub fn dec_overlap_enabled() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| dec_overlap_from_value(std::env::var("DENNO_DEC_OVERLAP").ok().as_deref()))
}

/// 1 スレッド分の再利用スクラッチ (grow-only)。scheduler ワーカーは単一スレッド
/// のため thread_local で競合なし。スレッド終了時の解放はベストエフォート
/// (コンテキストは static で生き続けるため、失敗してもリークはワーカー寿命分)。
struct Scratch {
    x: Option<DevBuffer>,   // [m*k] f32 入力
    aq: Option<DevBuffer>,  // [m*k] i8 量子化済み
    asc: Option<DevBuffer>, // [m] f32 ascale
    out: Option<DevBuffer>, // [m*n] f32 出力
    hx: Option<PinMem>,     // x の転送元 (ピン留め)
    ho: Option<PinMem>,     // out の転送先 (ピン留め)
    // P17k: FFN デバイス常駐 (maybe_gpu_ffn)
    act: Option<DevBuffer>,  // [m*ff] f32 swiglu 出力
    aq2: Option<DevBuffer>,  // [m*ff] i8 (act の量子化)
    asc2: Option<DevBuffer>, // [m] f32 (act の ascale)
    out2: Option<DevBuffer>, // [m*e] f32 (down 出力)
}

thread_local! {
    static SCRATCH: std::cell::RefCell<Scratch> = std::cell::RefCell::new(Scratch {
        x: None, aq: None, asc: None, out: None, hx: None, ho: None,
        act: None, aq2: None, asc2: None, out2: None,
    });
}

impl Scratch {
    fn ensure(cap: &mut Option<DevBuffer>, bytes: usize) -> Result<()> {
        Self::ensure_tagged(cap, bytes, crate::mem_audit::TAG_OTHER)
    }
    /// task 149: 台帳のタグ付き [`Self::ensure`]。
    fn ensure_tagged(cap: &mut Option<DevBuffer>, bytes: usize, tag: &'static str) -> Result<()> {
        if cap.as_ref().map(|b| b.bytes()).unwrap_or(0) < bytes {
            *cap = Some(DevBuffer::alloc_tagged(bytes, tag)?);
        }
        Ok(())
    }
    fn ensure_pin(cap: &mut Option<PinMem>, bytes: usize) -> Result<()> {
        if cap.as_ref().map(|b| b.bytes).unwrap_or(0) < bytes {
            *cap = Some(PinMem::alloc(bytes)?);
        }
        Ok(())
    }

    /// P58-3: arena から切り出す版の [`Self::ensure`]。既に十分な容量を持つ
    /// バッファが入っていれば何もしない (arena のビューでも個別確保でも同じ)。
    /// arena が無効・確保に失敗したときは従来どおり個別に確保する (fail-open)。
    fn ensure_arena(cap: &mut Option<DevBuffer>, key: u32, bytes: usize, tag: &'static str) -> Result<()> {
        if cap.as_ref().map(|b| b.bytes()).unwrap_or(0) >= bytes {
            return Ok(());
        }
        *cap = Some(match arena_alloc(key, bytes, tag) {
            Some(b) => b,
            None => DevBuffer::alloc_tagged(bytes, tag)?,
        });
        Ok(())
    }
}

// ---------------------------------------------------------------------------
// P58-3: prefill スクラッチの arena 化
//
// 背景 (与えられた実測): 本番 serve の OOM は prefill の途中で起きる —
//   `CUDA cuMemAlloc が失敗: error 2 (要求 779 MiB / 空き 315 MiB / 総 32110 MiB)`
//   → `chat failed: prefill residual chain: qkv chain failed`
// 779 MiB は `CH_QKV` (57,344 B/行 = (q 12,288 + k 1,024 + v 1,024) 列 x 4 B、
// n = 14,245..14,262 で 779 MiB) と一致する (CH_GA は 1,892.8 MiB・CH_ACT は
// 946.4 MiB なので一致しない = 失敗したのは qkv の出力 1 本)。つまり「直前の
// リクエストで確保した小さめの領域を解放した直後に、より大きい領域を要求する」
// 形で、個別の
// cuMemAlloc / cuMemFree を繰り返すことの (a) 断片化 (b) 失敗経路の解放漏れが
// 効いている。
//
// 方針: prefill の一時バッファを 1 本の arena から切り出す。
//   - arena は**チャンクのリスト**。チャンクは確保後に移動しない (成長時に
//     内容をコピーしない) ので、既に配ったポインタは常に有効。
//   - 予約は (スレッド ID, キー) ごとに保持し、同じキーで同じサイズ以下なら
//     **同じオフセット**を返す。リクエストごとの cuMemAlloc / cuMemFree が消える。
//   - 数値は不変: どのバッファに何を書くか・カーネル引数・発行順・丸め順は
//     1 つも変えない。変わるのは「同じ大きさの領域をどこから取るか」だけ。
//   - リクエスト境界 (`pf_scratch_begin`) では、中身が全て死んでいることを
//     利用して**古いチャンクを解放してから**新しいサイズを確保する
//     (ピークが「旧 + 新」にならない)。前回の 1 行あたり使用量から今回の
//     必要量を推定するので、プロンプト長が伸びた直後の 1 回もここで吸収できる。
//   - `DENNO_SCRATCH_ARENA=0` で従来の個別確保へ戻る (比較・切り戻し用)。
//   - arena の確保に失敗したら `None` を返し、呼び出し側が従来の
//     `DevBuffer::alloc` を使う (fail-open・数値不変)。
// ---------------------------------------------------------------------------

/// arena の成長単位 (1,024 MiB)。
pub(crate) const ARENA_CHUNK: usize = 1 << 30;
/// チャンク内オフセットのアライン。cuMemAlloc の返す境界 (256 B) に合わせる。
const ARENA_ALIGN: usize = 256;
/// 予約キー: デバイス常駐チェーンのスロット (`CH_*`)。
const ARENA_KEY_CHAIN: u32 = 0x0100_0000;
/// 予約キー: `q4_dispatch_tile` の入力 staging。
const ARENA_KEY_Q4_X: u32 = 0x0200_0001;
/// 予約キー: `q4_dispatch_tile` の出力 staging。
const ARENA_KEY_Q4_OUT: u32 = 0x0200_0002;

/// [`arena_enabled`] の純粋な判定 (`DENNO_SCRATCH_ARENA`)。未設定 = 有効。
fn parse_scratch_arena(raw: Option<&str>) -> bool {
    !matches!(raw.map(|v| v.trim()), Some("0") | Some("false") | Some("off"))
}

/// arena を使うか (既定 ON・`DENNO_SCRATCH_ARENA=0` で従来の個別確保)。
fn arena_enabled() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| parse_scratch_arena(std::env::var("DENNO_SCRATCH_ARENA").ok().as_deref()))
}

/// `DENNO_SCRATCH_ARENA_DBG=1` で成長・境界の 1 行ログを出す (恒久診断・
/// 未指定時 no-op)。
fn arena_dbg() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| std::env::var("DENNO_SCRATCH_ARENA_DBG").ok().as_deref() == Some("1"))
}

/// arena の確保計画 (GPU を持たない純粋な部分 = ホストだけで検証できる)。
#[derive(Default)]
struct ArenaPlan {
    /// チャンクごとの (容量, 使用済み)。確保順に埋める。
    chunks: Vec<(usize, usize)>,
    /// (スレッド ID, キー) → (チャンク index, オフセット, 予約バイト数)。
    slots: std::collections::HashMap<(u8, u32), (usize, usize, usize)>,
    /// いまのリクエストで切り出した合計 (推定用)。
    cur_bytes: usize,
    /// 過去のリクエストで切り出した合計の最大 (次回の事前確保量の推定用)。
    high_water: usize,
}

impl ArenaPlan {
    /// チャンク内オフセットのアライン。
    fn align_up(n: usize) -> usize {
        (n + ARENA_ALIGN - 1) & !(ARENA_ALIGN - 1)
    }

    /// 予約を取る。既存の予約で足りれば**同じ位置**を返す (再利用)。
    /// 足りない場合は `Err(必要なチャンクのバイト数)` を返し、**状態は変えない**
    /// (呼び出し側がチャンクを確保して `add_chunk` してから再試行する)。
    fn reserve(&mut self, tid: u8, key: u32, bytes: usize) -> std::result::Result<(usize, usize), usize> {
        if let Some(&(c, off, have)) = self.slots.get(&(tid, key)) {
            if have >= bytes {
                return Ok((c, off));
            }
        }
        let need = Self::align_up(bytes.max(1));
        for li in 0..self.chunks.len() {
            let (cap, used) = self.chunks[li];
            if cap - used >= need {
                let off = used;
                self.chunks[li].1 = used + need;
                self.slots.insert((tid, key), (li, off, bytes));
                self.cur_bytes += need;
                self.high_water = self.high_water.max(self.cur_bytes);
                return Ok((li, off));
            }
        }
        // チャンクは 1,024 MiB 単位 (要求が 1 GiB を超えるときはその倍数)。
        let chunk = need.max(ARENA_CHUNK);
        Err(chunk.div_ceil(ARENA_CHUNK) * ARENA_CHUNK)
    }

    /// チャンクを 1 本足す (中身は未初期化 = 呼び出し側が全要素を書く前提)。
    fn add_chunk(&mut self, bytes: usize) {
        self.chunks.push((bytes, 0));
    }

    /// 全チャンクと予約を捨てる (リクエスト境界・中身は全て死んでいる)。
    fn reset(&mut self) {
        self.chunks.clear();
        self.slots.clear();
        self.cur_bytes = 0;
    }

    /// チャンクは残したまま使用位置と予約だけ捨てる (同じ容量で足りるとき)。
    fn reset_keep_chunks(&mut self) {
        for c in self.chunks.iter_mut() {
            c.1 = 0;
        }
        self.slots.clear();
        self.cur_bytes = 0;
    }

    /// チャンクの総容量。
    fn capacity(&self) -> usize {
        self.chunks.iter().map(|(c, _)| *c).sum()
    }

    /// 次のリクエストで事前確保するバイト数の推定 (純関数)。
    ///
    /// 前回の「1 行あたり使用量 x 今回の行数 x 1.1」を 1 GiB 単位に切り上げる。
    /// 前回の実績が無ければ 0 (= 推定なし・最初の切り出しでチャンクを足す)。
    fn target_for(prev_rows: usize, prev_high: usize, rows: usize) -> usize {
        if prev_rows == 0 || prev_high == 0 || rows == 0 {
            return 0;
        }
        let per_row = prev_high / prev_rows + 1;
        let want = per_row.saturating_mul(rows).saturating_mul(11) / 10;
        want.saturating_add(ARENA_CHUNK - 1) & !(ARENA_CHUNK - 1)
    }
}

/// arena の実体 (チャンクの `DevBuffer` と計画)。
struct ArenaState {
    plan: ArenaPlan,
    /// `plan.chunks` と同順。チャンクは移動しない (再確保時にコピーしない)。
    bufs: Vec<DevBuffer>,
    /// チャンクを足した回数 (診断)。
    grows: usize,
    /// 切り出した回数 (診断)。
    carves: usize,
    /// 直近のリクエストの行数 (事前確保量の推定用)。
    last_rows: usize,
}

static ARENA: OnceLock<std::sync::Mutex<ArenaState>> = OnceLock::new();
/// スレッド ID の採番 (thread_local のスロットを (tid, key) で区別するため)。
static ARENA_TID_NEXT: std::sync::atomic::AtomicU16 = std::sync::atomic::AtomicU16::new(0);

/// このスレッドの arena ID (0..255)。スレッドごとに 1 回だけ採番する。
fn arena_tid() -> u8 {
    thread_local! {
        static TID: u8 = (ARENA_TID_NEXT
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed) & 0xff) as u8;
    }
    TID.with(|t| *t)
}

fn arena_state() -> &'static std::sync::Mutex<ArenaState> {
    ARENA.get_or_init(|| {
        std::sync::Mutex::new(ArenaState {
            plan: ArenaPlan::default(),
            bufs: Vec::new(),
            grows: 0,
            carves: 0,
            last_rows: 0,
        })
    })
}

/// arena から `bytes` バイトを切り出し、**非所有ビュー**として返す。
/// `None` = arena 無効・チャンク確保失敗 (呼び出し側は従来の `DevBuffer::alloc`)。
fn arena_alloc(key: u32, bytes: usize, tag: &'static str) -> Option<DevBuffer> {
    if !arena_enabled() {
        return None;
    }
    let tid = arena_tid();
    let mut g = arena_state().lock().ok()?;
    let (ci, off) = match g.plan.reserve(tid, key, bytes) {
        Ok(v) => v,
        Err(want) => {
            let want = want.max(ARENA_CHUNK);
            let buf = match DevBuffer::alloc_tagged(want, crate::mem_audit::TAG_ARENA) {
                Ok(b) => b,
                Err(e) => {
                    if arena_dbg() {
                        eprintln!("scratch arena: チャンク確保に失敗 ({want} B): {e}");
                    }
                    return None;
                }
            };
            if arena_dbg() {
                eprintln!(
                    "scratch arena: チャンク {want} B を追加 (key=0x{key:08x} 要求 {bytes} B)"
                );
            }
            g.bufs.push(buf);
            g.plan.add_chunk(want);
            g.grows += 1;
            g.plan.reserve(tid, key, bytes).ok()?
        }
    };
    g.carves += 1;
    let base = g.bufs.get(ci)?.ptr();
    Some(DevBuffer::view(base + off as u64, bytes))
}

/// arena のビューを保持している thread_local スロットを落とす。
///
/// **呼び出し位置の契約**: [`pf_scratch_begin`] の中だけで呼ぶ。ここで落とす
/// スロットは「使う直前に必ず `chain_ensure_buf` / `ensure_arena` で確保される」
/// ものだけで、リクエスト境界の外では内容を保持しない (CH_PF_RES の残差も、
/// 境界の直後に `chain_pf_res_upload` で入れ直す)。
fn drop_arena_views() {
    CHAIN.with(|cell| {
        let mut s = cell.borrow_mut();
        for b in s.bufs.iter_mut() {
            *b = None;
        }
    });
    SCRATCH.with(|cell| {
        let mut s = cell.borrow_mut();
        s.x = None;
        s.out = None;
    });
}

/// P58-3: prefill のリクエスト境界で arena を切り直す。
///
/// 境界では一時領域の中身が全て死んでいる (残差は直後に H2D で入れ直す) ので、
/// **古いチャンクを解放してから**新しいサイズを確保する。個別確保のままだと
/// 「旧領域を保持したまま新領域を要求」してピークが 2 倍になり、779 MiB が
/// 315 MiB の空きに載らない。容量が今回の推定と同程度なら解放せずに
/// オフセットを 0 に戻すだけ (チャーンを作らない)。
///
/// 他スレッドの予約が残っているときは何もしない (並行リクエストのビューを
/// 壊さない)。数値には触らない。
pub fn pf_scratch_begin(rows: usize) {
    if !arena_enabled() {
        return;
    }
    let tid = arena_tid();
    let arena = match ARENA.get() {
        Some(a) => a,
        None => return,
    };
    let mut g = match arena.lock() {
        Ok(g) => g,
        Err(_) => return,
    };
    if g.plan.slots.keys().any(|(t, _)| *t != tid) {
        return;
    }
    // 先にビューを落としてから解放する (dangling を作らない)。
    drop_arena_views();
    let prev_rows = g.last_rows;
    let prev_high = g.plan.high_water;
    let target = ArenaPlan::target_for(prev_rows, prev_high, rows);
    let cap = g.plan.capacity();
    let keep = cap > 0 && target <= cap && target.saturating_mul(2) >= cap;
    let (freed, alloc) = if keep {
        g.plan.reset_keep_chunks();
        (0usize, 0usize)
    } else {
        // 解放の前に GPU を止める (前のリクエストの非同期コピーが残っていても
        // 解放済み領域を読まない)。境界の 1 回だけ・所要は µs 級。
        if let Some(ctx) = shared_ctx() {
            if ctx.make_current().is_ok() {
                let _ = ctx.sync();
            }
        }
        let freed = g.bufs.len();
        g.bufs.clear(); // 古い方を先に解放する (cuMemFree)
        g.plan.reset();
        let alloc = if target > 0 {
            match DevBuffer::alloc_tagged(target, crate::mem_audit::TAG_ARENA) {
                Ok(b) => {
                    g.bufs.push(b);
                    g.plan.add_chunk(target);
                    g.grows += 1;
                    target
                }
                Err(e) => {
                    if arena_dbg() {
                        eprintln!("scratch arena: 事前確保 {target} B に失敗: {e}");
                    }
                    0
                }
            }
        } else {
            0
        };
        (freed, alloc)
    };
    g.last_rows = rows;
    if arena_dbg() {
        eprintln!(
            "scratch arena: 境界 rows={rows} 解放 {freed} 本 / 事前確保 {alloc} B (推定 {target} B)"
        );
    }
}

/// task 149: `DENNO_SCRATCH_FREE` の解釈。既定 **off** (明示的に 1/true/on で有効)。
///
/// lab t149c の flash では arena が 1 度も確保されず (tag `scratch arena` が
/// 表に出ない)、解放しても 1 MiB も変わらなかった。qwen35 側の経路には効く
/// 可能性があるが未測定なので、既定では従来どおり保持する。
fn parse_scratch_free(raw: Option<&str>) -> bool {
    matches!(
        raw.map(|v| v.trim().to_ascii_lowercase()).as_deref(),
        Some("1") | Some("true") | Some("on")
    )
}

/// task 149: `DENNO_SCRATCH_FREE` が有効か (プロセスで 1 回読む)。
fn scratch_free_enabled() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| parse_scratch_free(std::env::var("DENNO_SCRATCH_FREE").ok().as_deref()))
}

/// task 149: リクエスト終了時に prefill の arena チャンクを**解放する**。
///
/// prefill の一時領域はリクエストを跨いで内容を保持しない (`pf_scratch_begin` の
/// 契約と同じ) ので、decode の間に何 GiB も抱えたままにしない。次に prefill が
/// 走るときは `pf_scratch_begin` / `arena_alloc` が同じ手順で確保し直すため、
/// **ピークは変わらない** (従来も境界で「解放してから確保」していた)。
///
/// 他スレッドの予約が残っているときは何もしない (並行リクエストのビューを壊さない)。
/// 数値には触らない。
pub fn pf_scratch_release() -> usize {
    if !arena_enabled() || !scratch_free_enabled() {
        return 0;
    }
    let tid = arena_tid();
    let Some(arena) = ARENA.get() else {
        return 0;
    };
    let Ok(mut g) = arena.lock() else {
        return 0;
    };
    if g.plan.slots.keys().any(|(t, _)| *t != tid) {
        return 0;
    }
    if g.bufs.is_empty() {
        return 0;
    }
    // ビューを先に落としてから解放する (dangling を作らない)。非同期コピーが
    // 残っていても解放済み領域を読まないよう、境界の 1 回だけ GPU を止める。
    drop_arena_views();
    if let Some(ctx) = shared_ctx() {
        if ctx.make_current().is_ok() {
            let _ = ctx.sync();
        }
    }
    let n = g.bufs.len();
    let bytes = g.plan.capacity();
    g.bufs.clear(); // ここで cuMemFree
    g.plan.reset();
    if arena_dbg() {
        eprintln!("scratch arena: リクエスト終了で {n} 本 / {bytes} B を解放");
    }
    if crate::mem_audit::audit_on() {
        let free = dev_mem_mb().map(|(f, _)| f).unwrap_or(0);
        tracing::info!(
            "[mem-audit] prefill arena を {n} 本 {} MiB 解放 (dev free {} MiB)",
            bytes >> 20,
            free
        );
    }
    bytes
}

/// arena の現在値 (診断・テスト用): (チャンク本数, 総容量, 切り出し回数, 成長回数)。
pub fn scratch_arena_stats() -> (usize, usize, usize, usize) {
    match ARENA.get().and_then(|a| a.lock().ok()) {
        Some(g) => (g.bufs.len(), g.plan.capacity(), g.carves, g.grows),
        None => (0, 0, 0, 0),
    }
}

/// s67: GDN スキャン (chunked) の作業領域。**層をまたいで再利用する** (grow-only)。
///
/// 動機 (s64/s66 の計測): prefill の `gdn_scan` 3.15 s のうち **alloc 1.04 s** は
/// 層ごとに 16 本 (計 ≈180MB) を `DevBuffer::from_slice` で作り直していた分で、
/// 形はモデルで固定 (n はリクエスト内で一定) なのに毎回 cuMemAlloc/cuMemFree
/// していた。確保を初回だけにし、以降は `copy_from` で上書きする。
///
/// 数値は不変 — バッファの寿命が延びるだけで、書き込む内容・カーネル引数・
/// 演算順は 1 つも変えない (scheduler ワーカーは単一スレッドなので thread_local
/// で競合しない・`SCRATCH` と同じ規約)。
struct GdnScratch {
    q: Option<DevBuffer>,        // [n, conv_dim]
    z: Option<DevBuffer>,        // [n, vd]
    beta: Option<DevBuffer>,     // [n, nv]
    alpha: Option<DevBuffer>,    // [n, nv]
    conv_in: Option<DevBuffer>,  // [conv_dim, cs]
    ssm_in: Option<DevBuffer>,   // [nv, dk, dv]
    wc: Option<DevBuffer>,       // 重み 4 本 (層ごとに差し替え)
    wa: Option<DevBuffer>,
    wd: Option<DevBuffer>,
    wn: Option<DevBuffer>,
    w: Option<DevBuffer>,     // [n_chunks, nv, dk, dv] chunk ローカル遷移
    m: Option<DevBuffer>,     // [n_chunks, nv, dk, dk]
    sinit: Option<DevBuffer>, // [n_chunks, nv, dk, dv]
    y: Option<DevBuffer>,     // [n, vd]
    conv_out: Option<DevBuffer>,
    ssm_out: Option<DevBuffer>,
}

/// カーネル引数用の生ポインタ束 (バッファ本体は thread_local が保持し続ける)。
#[derive(Clone, Copy)]
struct GdnPtrs {
    q: CUdeviceptr,
    z: CUdeviceptr,
    beta: CUdeviceptr,
    alpha: CUdeviceptr,
    conv_in: CUdeviceptr,
    ssm_in: CUdeviceptr,
    wc: CUdeviceptr,
    wa: CUdeviceptr,
    wd: CUdeviceptr,
    wn: CUdeviceptr,
    w: CUdeviceptr,
    m: CUdeviceptr,
    sinit: CUdeviceptr,
    y: CUdeviceptr,
    conv_out: CUdeviceptr,
    ssm_out: CUdeviceptr,
}

#[derive(Clone, Copy)]
enum GdnBuf {
    Y,
    ConvOut,
    SsmOut,
}

// ---------------------------------------------------------------------------
// s89 (P1-1): GDN スキャンのデバイス常駐状態
//
// 動機: s88 の計測で prefill の `d2h_state` が大きいのは GDN 状態の往復
// (`ssm_out` の D2H + 次層の `ssm_in` の H2D・1 層 2MB ずつ) を含むため。
// ここでは「層のスキャン状態の正本」をデバイスに置き、ホスト側の
// `KvCache::gdn` は**実行境界 (forward の切れ目) でだけ**一致させる。
//
// s90 の状態 (重要・偽らない):
//   この構造体は **まだどの経路からも使われていない**。tl の `GDN_STATE` に
//   確保・seed・無効化の関数は用意してあるが、`gdn_scan_chunked_impl` は
//   (i) 2 launch 経路が現状の forward では成立しない (→ gdn/scan_schedule.rs)
//   (ii) y をデバイスに残す oproj 経路 (s72) は 2 層目以降の conv 入力を
//        ホストから捨てる形になっており、ホスト状態が層ごとにしか確定しない
//   の 2 点により、従来どおり層ごとに ssm を H2D / D2H している。
//   `f_gdn_chunk_scan_hoist` のカーネルと Optional 取得は「古い PTX でも起動を
//   壊さない」性質ごと残してある (Next: 上記 (i)(ii) を解いて配線する)。
//
// 無効化の契約 (将来 配線したときに効くもの — 先に用意しておく):
//   ホストの `KvCache::gdn` を書き換える経路 (セッション reset / エントリ復元 /
//   デコードチェーンの遅延フラッシュ / CPU フォールバック) は
//   [`gdn_scan_state_invalidate`] を呼ぶ。呼ばれたら次の実行でホストから
//   再 seed する (数値不変・余分な H2D が 1 回増えるだけ)。**古い正本を読むと
//   出力が変わる**ので、新しい書き換え経路を足すときは必ずここを通すこと。
// ---------------------------------------------------------------------------
struct GdnStateCache {
    conv: Vec<Option<DevBuffer>>, // [layer] conv [conv_dim, cs] (デバイス正本)
    conv_len: usize,              // conv の要素数
    cur_kv: Option<u64>,          // この正本が属する KV キャッシュ ID (None = 未使用)
    ssm: Vec<Option<DevBuffer>>, // [layer] ssm [nv, dk, dv] (デバイス正本)
    valid: Vec<bool>,            // [layer] = ホスト KvCache::gdn と一致している
    srows: Option<DevBuffer>,    // [n, nv, dk, dv] hoist 経路の境界行
    srows_n: usize,              // srows がいま表現している n (0 = 未初期化)
    rows: usize,                 // 行数 (= nk*dk = vd)
    cols: usize,                 // 列数 (= dk*dv)
}

impl GdnStateCache {
    const fn empty() -> Self {
        Self {
            conv: Vec::new(),
            conv_len: 0,
            cur_kv: None,
            ssm: Vec::new(),
            valid: Vec::new(),
            srows: None,
            srows_n: 0,
            rows: 0,
            cols: 0,
        }
    }
    fn ensure_layers(&mut self, n_layers: usize) {
        // `Option<DevBuffer>` は Clone でない (DevBuffer は RAII の所有権型) →
        // resize_with で伸ばす。縮む場合は末尾を落とす (drop = cuMemFree)。
        if self.ssm.len() < n_layers {
            self.ssm.resize_with(n_layers, || None);
            self.conv.resize_with(n_layers, || None);
        } else {
            self.ssm.truncate(n_layers);
            self.conv.truncate(n_layers);
        }
        self.valid.resize(n_layers, false);
    }
    /// 全層を「ホストが正」に戻す (次の実行で再 seed)。ホストの GDN 状態を
    /// 書き換える経路 (セッション reset / エントリ復元 / デコードチェーンの
    /// 遅延フラッシュ / CPU フォールバック) は必ずこれを呼ぶ。
    fn invalidate(&mut self) {
        for v in self.valid.iter_mut() {
            *v = false;
        }
        self.srows_n = 0;
    }
    /// 層ベクタを `li` まで伸ばす (層数は初回利用時に確定する)。
    fn touch_layer(&mut self, li: usize) {
        if self.ssm.len() <= li {
            let n = li + 1;
            self.ssm.resize_with(n, || None);
            self.conv.resize_with(n, || None);
            self.valid.resize(n, false);
        }
    }
    /// 層 1 本の確保。形が変わったら全層を無効化する (別モデル/別形状)。
    fn ensure_layer(&mut self, li: usize, rows: usize, cols: usize) -> Result<()> {
        const F: usize = std::mem::size_of::<f32>();
        self.touch_layer(li);
        if (self.rows != 0 && (self.rows != rows || self.cols != cols)) || self.rows != rows {
            self.invalidate();
            self.srows_n = 0;
        }
        self.rows = rows;
        self.cols = cols;
        GdnScratch::grow(&mut self.ssm[li], rows * cols * F)?;
        Ok(())
    }
    /// 層 1 本の conv 状態を確保。
    fn ensure_conv(&mut self, li: usize, len: usize) -> Result<()> {
        const F: usize = std::mem::size_of::<f32>();
        self.touch_layer(li);
        GdnScratch::grow(&mut self.conv[li], len * F)?;
        self.conv_len = len;
        Ok(())
    }
    /// hoist 経路の境界行バッファ [n, nv, dk, dv] を確保 (n が同じなら再利用)。
    fn ensure_srows(&mut self, n: usize, rows: usize, cols: usize) -> Result<CUdeviceptr> {
        const F: usize = std::mem::size_of::<f32>();
        let bytes = n
            .checked_mul(rows)
            .and_then(|v| v.checked_mul(cols))
            .and_then(|v| v.checked_mul(F))
            .ok_or_else(|| anyhow::anyhow!("srows size overflow"))?;
        GdnScratch::grow(&mut self.srows, bytes)?;
        if self.srows_n != n {
            self.srows_n = n;
        }
        Ok(self.srows.as_ref().expect("srows 未確保").ptr())
    }
}

impl GdnScratch {
    const fn empty() -> Self {
        Self {
            q: None,
            z: None,
            beta: None,
            alpha: None,
            conv_in: None,
            ssm_in: None,
            wc: None,
            wa: None,
            wd: None,
            wn: None,
            w: None,
            m: None,
            sinit: None,
            y: None,
            conv_out: None,
            ssm_out: None,
        }
    }
    fn grow(cap: &mut Option<DevBuffer>, bytes: usize) -> Result<()> {
        if cap.as_ref().map(|b| b.bytes()).unwrap_or(0) < bytes {
            *cap = Some(DevBuffer::alloc(bytes.max(1))?);
        }
        Ok(())
    }
    /// 形が変わらない限り何もしない (prefill の 24 層は全て同じ形)。
    fn ensure(
        &mut self,
        n: usize,
        conv_dim: usize,
        vd: usize,
        nv: usize,
        dk: usize,
        dv: usize,
        cs: usize,
        n_chunks: usize,
    ) -> Result<()> {
        const F: usize = std::mem::size_of::<f32>();
        Self::grow(&mut self.q, n * conv_dim * F)?;
        Self::grow(&mut self.z, n * vd * F)?;
        Self::grow(&mut self.beta, n * nv * F)?;
        Self::grow(&mut self.alpha, n * nv * F)?;
        Self::grow(&mut self.conv_in, conv_dim * cs * F)?;
        Self::grow(&mut self.ssm_in, nv * dk * dv * F)?;
        Self::grow(&mut self.wc, conv_dim * 4 * F)?; // d_conv == 4 (chunked 前提)
        Self::grow(&mut self.wa, nv * F)?;
        Self::grow(&mut self.wd, nv * F)?;
        Self::grow(&mut self.wn, dv * F)?;
        Self::grow(&mut self.w, n_chunks * nv * dk * dv * F)?;
        Self::grow(&mut self.m, n_chunks * nv * dk * dk * F)?;
        Self::grow(&mut self.sinit, n_chunks * nv * dk * dv * F)?;
        Self::grow(&mut self.y, n * vd * F)?;
        Self::grow(&mut self.conv_out, conv_dim * cs * F)?;
        Self::grow(&mut self.ssm_out, nv * dk * dv * F)?;
        Ok(())
    }
    fn ptrs(&self) -> GdnPtrs {
        let p = |b: &Option<DevBuffer>| b.as_ref().expect("GdnScratch: 未確保").ptr();
        GdnPtrs {
            q: p(&self.q),
            z: p(&self.z),
            beta: p(&self.beta),
            alpha: p(&self.alpha),
            conv_in: p(&self.conv_in),
            ssm_in: p(&self.ssm_in),
            wc: p(&self.wc),
            wa: p(&self.wa),
            wd: p(&self.wd),
            wn: p(&self.wn),
            w: p(&self.w),
            m: p(&self.m),
            sinit: p(&self.sinit),
            y: p(&self.y),
            conv_out: p(&self.conv_out),
            ssm_out: p(&self.ssm_out),
        }
    }
    fn buf(&self, which: GdnBuf) -> &DevBuffer {
        let b = match which {
            GdnBuf::Y => &self.y,
            GdnBuf::ConvOut => &self.conv_out,
            GdnBuf::SsmOut => &self.ssm_out,
        };
        b.as_ref().expect("GdnScratch: 未確保")
    }
}

thread_local! {
    static GDN_SCRATCH: std::cell::RefCell<GdnScratch> =
        std::cell::RefCell::new(GdnScratch::empty());
    /// s89 (P1-1): GDN スキャン状態のデバイス正本 (scheduler ワーカーは単一
    /// スレッドなので thread_local で競合しない・`GDN_SCRATCH` と同じ規約)。
    static GDN_STATE: std::cell::RefCell<GdnStateCache> =
        std::cell::RefCell::new(GdnStateCache::empty());
}

/// s89 (P1-1): GDN スキャン状態のデバイス正本を「ホストが正」に戻す。
///
/// ホストの `KvCache::gdn` を書き換える経路 (セッション reset / エントリ復元 /
/// デコードチェーンの遅延フラッシュ / CPU フォールバック) は、その後にこの
/// 関数を呼ぶ。呼ばれた層は次の prefill でホストから再 seed する (数値不変・
/// 余分な H2D が 1 回増えるだけ)。**古い正本を読むと出力が変わる**ので、
/// 新しい書き換え経路を足すときは必ずここを通すこと。
pub fn gdn_scan_state_invalidate() {
    GDN_STATE.with(|c| c.borrow_mut().invalidate());
}

/// task 154: prefill の GPU スキャンが確保した層状態のバッファを VRAM へ返す。
///
/// 36 層ぶん (conv 172 KB + ssm 10.5 MB) で約 385 MB。prefill が終わったら
/// ホスト側の状態が正本なので、デバイス側を持ち続ける理由が無い (expert の
/// カード予算を圧迫して decode のヒット率を落とす)。次に使うときは
/// `gdn_state_begin` がホストから seed し直す。
pub fn gdn_state_release() {
    GDN_STATE.with(|c| {
        let mut c = c.borrow_mut();
        c.invalidate();
        c.ensure_layers(0);
        c.cur_kv = None;
        c.rows = 0;
        c.cols = 0;
        c.conv_len = 0;
    });
}

// s131: デバイス正本を使うか。`DENNO_GDN_DEVSTATE=0` で従来動作 (毎回ホストと
// 往復) に戻す。切り分け用で、既定は有効。
fn gdn_devstate() -> bool {
    !matches!(
        std::env::var("DENNO_GDN_DEVSTATE").ok().as_deref(),
        Some("0")
    )
}

// 従来動作のホスト書き戻し (デバイス正本を使わないときだけ)。
fn gdn_host_writeback(conv_st: &mut [f32], ssm_st: &mut [f32]) -> Result<()> {
    GDN_SCRATCH.with(|cell| -> Result<()> {
        let s = cell.borrow();
        let cv = s.buf(GdnBuf::ConvOut).to_vec::<f32>(conv_st.len())?;
        let sm = s.buf(GdnBuf::SsmOut).to_vec::<f32>(ssm_st.len())?;
        conv_st.copy_from_slice(&cv);
        ssm_st.copy_from_slice(&sm);
        Ok(())
    })
}

// s131: デバイス正本の入り口。層の状態が未確定ならホストから 1 回だけ seed し、
// 以後はデバイスの値をそのままカーネルへ渡す。
fn gdn_state_begin(
    kv: u64,
    li: usize,
    conv: &[f32],
    ssm: &[f32],
    conv_len: usize,
    rows: usize,
    cols: usize,
) -> Result<(CUdeviceptr, CUdeviceptr)> {
    GDN_STATE.with(|cell| -> Result<(CUdeviceptr, CUdeviceptr)> {
        let mut c = cell.borrow_mut();
        // 別スロット/別セッションの状態を混ぜない (層番号だけでは足りない)。
        if c.cur_kv != Some(kv) {
            c.invalidate();
            c.cur_kv = Some(kv);
        }
        let devstate = gdn_devstate();
        c.ensure_layer(li, rows, cols)?;
        c.ensure_conv(li, conv_len)?;
        if !c.valid[li] || !devstate {
            c.conv[li].as_ref().unwrap().copy_from(conv)?;
            c.ssm[li].as_ref().unwrap().copy_from(ssm)?;
            c.valid[li] = devstate;
        }
        let pc = c.conv[li].as_ref().unwrap().ptr();
        let ps = c.ssm[li].as_ref().unwrap().ptr();
        Ok((pc, ps))
    })
}

// s131: スキャン結果をデバイス正本へ D2D で戻す (ホストへは落とさない)。
fn gdn_state_commit(
    li: usize,
    conv_out: CUdeviceptr,
    ssm_out: CUdeviceptr,
    conv_len: usize,
    rows: usize,
    cols: usize,
) -> Result<()> {
    let (pc, ps) = GDN_STATE
        .with(|cell| -> Option<(CUdeviceptr, CUdeviceptr)> {
            let c = cell.borrow();
            Some((c.conv.get(li)?.as_ref()?.ptr(), c.ssm.get(li)?.as_ref()?.ptr()))
        })
        .ok_or_else(|| anyhow::anyhow!("gdn_state_commit: 状態バッファ未確保 (layer {li})"))?;
    let lib = lib()?;
    unsafe {
        check(
            (lib.memcpy_dtod_async)(pc, conv_out, conv_len * 4, std::ptr::null_mut()),
            "cuMemcpyDtoDAsync (gdn conv)",
        )?;
        check(
            (lib.memcpy_dtod_async)(ps, ssm_out, rows * cols * 4, std::ptr::null_mut()),
            "cuMemcpyDtoDAsync (gdn ssm)",
        )?;
    }
    Ok(())
}

/// s131: デバイス正本をホストへ戻す (層指定)。戻した層は無効化するので、
/// 次にその層を使うときはホストから 1 回 seed し直す。
/// ホストの `KvCache::gdn` を読む前に必ず通すこと。
///
/// s141 (Task B7): 返す 2 本は **thread_local のホスト一時領域の借り物**。
/// 従来は層ごとに `to_vec` (= `Vec::with_capacity`) で 2 本確保していたため、
/// 27B q4 の decode 1 ステップで 48 層 x 2 本 = 96 本 / 564 KiB の確保と解放を
/// 毎回払っていた。転送・内容は同一 (同じ D2H を同じ長さで 1 回) で、変わるのは
/// 「毎回確保するか、伸ばすだけの 1 本を使い回すか」だけ。
/// 借り物なので、**次の呼び出しで中身が変わる** — 呼び出し側はその場で読み終わること
/// (`KvCache::flush_gdn_device_state` はその場で copy_from_slice する)。
pub fn gdn_state_take<'a>(kv: u64, li: usize, reuse: &'a mut GdnHostStage) -> Option<(&'a [f32], &'a [f32])> {
    let (pc, ps, conv_len, ssm_len) =
        GDN_STATE.with(|cell| -> Option<(CUdeviceptr, CUdeviceptr, usize, usize)> {
            let mut c = cell.borrow_mut();
            if c.cur_kv != Some(kv) || li >= c.valid.len() || !c.valid[li] {
                return None;
            }
            let (conv_len, rows, cols) = (c.conv_len, c.rows, c.cols);
            let pc = c.conv[li].as_ref()?.ptr();
            let ps = c.ssm[li].as_ref()?.ptr();
            // 戻した層は無効化 (従来どおり・成功時のみ)。
            c.valid[li] = false;
            Some((pc, ps, conv_len, rows * cols))
        })?;
    // 借り物を 2 本同時に返すので、転送は 2 回とも先に済ませる。
    // conv / ssm は別々の領域なので、2 本の借用は同時に成立する。
    let conv = d2h_raw(&mut reuse.conv, pc, conv_len)?;
    let ssm = d2h_raw(&mut reuse.ssm, ps, ssm_len)?;
    Some((conv, ssm))
}

/// s141 (Task B7): `gdn_state_take` に渡す呼び出し側所有の受け皿 1 組。
/// 呼び出し元のループの外で 1 回だけ作り、層ごとに使い回す (grow-only)。
/// 中身は「前の層の値」なので、**返り値をその場で読み終えること**。
pub struct GdnHostStage {
    conv: Vec<f32>,
    ssm: Vec<f32>,
}

impl GdnHostStage {
    /// 空の受け皿 (初回の D2H で必要な分だけ伸びる)。
    pub fn new() -> Self {
        Self { conv: Vec::new(), ssm: Vec::new() }
    }
    /// 確保済みの要素数 (テストが「ステップ数に対して増えない」ことを見る口)。
    pub fn capacities(&self) -> (usize, usize) {
        (self.conv.capacity(), self.ssm.capacity())
    }
}

impl Default for GdnHostStage {
    fn default() -> Self {
        Self::new()
    }
}

/// s141: 再利用領域 `dst` の先頭 `len` 要素へ D2H し、その部分を**借りて**返す。
/// `DevBuffer::to_vec` と転送は同一 (同じ `cuMemcpyDtoH` を同じ長さで 1 回) で、
/// 違いは「確保しない」ことだけ。容量が足りないときだけ `reserve_exact` で伸ばす
/// (`mem::take` のように領域を奪い返さない = 次の層でも同じ領域を使う)。
fn d2h_raw<'a>(dst: &'a mut Vec<f32>, ptr: CUdeviceptr, len: usize) -> Option<&'a [f32]> {
    unsafe {
        reserve_exact_grow(dst, len);
        let p = dst.as_mut_ptr() as *mut c_void;
        let lib = lib().ok()?;
        if check((lib.memcpy_dtoh)(p, ptr, len * 4), "cuMemcpyDtoH").is_err() {
            return None;
        }
        dst.set_len(len);
    }
    Some(&dst[..])
}

/// s141 (Task B7): `dst` を「長さ `len` を書ける」状態にする。**伸ばすだけ** —
/// 容量が足りていれば確保しない (これが「層ごとに確保しない」の実体)。
/// 実転送 (`d2h_raw`) とテストが同じ関数を通るので、テストは写しではなく
/// 本物の確保規則を検証している。
fn reserve_exact_grow(dst: &mut Vec<f32>, len: usize) {
    dst.clear();
    if len > dst.capacity() {
        dst.reserve_exact(len - dst.len());
    }
}

/// s141b (Task B7c): デバイス正本の 1 層を「デバイス正本から読む」ために取り出す。
///
/// s131 の `gdn_state_take` はホストへ D2H する版 (ホストの `KvCache::gdn` を
/// 復帰させる用途)。こちらは decode chain の seed 用で、返すのは移し元の
/// デバイスポインタだけ — ホストを経由しないので層あたり ~3.2 MiB の PCIe 往復が
/// 消える。返す値は (conv ポインタ, ssm ポインタ)。
///
/// 取り出した層は**無効化しない** (正本の値はそのまま有効 — 読むだけ)。ただし
/// 読み手は「ミラーへコピーした後」に scan カーネルがその面を更新するので、正本と
/// ミラーの内容は今後ずれる → 戻した層は valid=false にする (従来の
/// `gdn_state_take` と同じ規則: 次に scan 経路で使うときは必ず seed し直す)。
fn gdn_state_take_dev(
    kv: u64,
    li: usize,
    c: &mut GdnStateCache,
) -> Option<(CUdeviceptr, CUdeviceptr)> {
    if c.cur_kv != Some(kv) || li >= c.valid.len() || !c.valid[li] {
        return None;
    }
    let pc = c.conv.get(li)?.as_ref()?.ptr();
    let ps = c.ssm.get(li)?.as_ref()?.ptr();
    c.valid[li] = false;
    Some((pc, ps))
}

/// s141b (Task B7c): 遅延フラッシュの「D2H が要るか」の判定 (純関数 — テストが
/// 実物を通す)。
///
/// 規則: **ホストが古い可能性がある層** (= `stale`) と **位置が合っている層**
/// (= `pos == Some(target)` / `Some(target+1)`) の両方を満たす層だけ D2H する。
///
/// - stale でない層はホストが既に最新 (このステップで面 0 を上から書いた) →
///   読み直さなくてよい。これが「何も要らないステップでホストバイトをコピー
///   しない」の実体。
/// - stale でも位置が合っていない層 (chain 未走 / 不整合) は従来どおり判定へ回し、
///   呼び出し側がバグ時 None を返す経路をそのまま踏ませる。
///
/// 戻り値: (D2H するか, 位置が合っているか)。
fn gdn_flush_step(is_gdn_layer: bool, stale: bool, target: usize, pos: Option<usize>) -> (bool, bool) {
    if !is_gdn_layer {
        return (false, false);
    }
    // 成功ステップ後: 位置は target (= cache.len()) に一致し、その面は**書き込んだ
    // 状態** = ホストが遅れている層だけが読み直しの対象。
    if pos == Some(target) {
        return (stale, true);
    }
    // 層途中で失敗したステップ: 位置は target+1 で、書いた面は「次」の状態。
    // 現在の状態 (target) は反対の面にあり、その面は前回の seed 直後に書かれた
    // = **ホストと一致している** (= stale が偽) ので、stale の層は読んでも
    // 意味が無い (古いホストを書き戻すだけ)。一律で「読まない」。
    if pos == Some(target + 1) {
        return (false, true);
    }
    (false, false)
}

static GPU_CTX: OnceLock<Option<CudaCtx>> = OnceLock::new();
static GPU_BROKEN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// 集計用 (gpu_budget): 重みの失敗などで GPU 経路が恒久停止しているか。
/// 読み取りのみ・状態は変えない。
pub(crate) fn gpu_broken_flag() -> bool {
    GPU_BROKEN.load(std::sync::atomic::Ordering::Relaxed)
}

#[cfg(test)]
static GPU_FORCE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// CUDA 経路が有効か (`DENNO_CUDA=1` かつ初期化が壊れていない)。
///
/// テストから「逐次経路が GPU カーネルか CPU 参照か」を判定するのにも使う。
pub fn cuda_enabled() -> bool {
    if GPU_BROKEN.load(std::sync::atomic::Ordering::Relaxed) {
        return false;
    }
    #[cfg(test)]
    if GPU_FORCE.load(std::sync::atomic::Ordering::Relaxed) {
        return true;
    }
    static GATE: OnceLock<bool> = OnceLock::new();
    *GATE.get_or_init(|| {
        matches!(
            std::env::var("DENNO_CUDA").as_deref(),
            Ok("1") | Ok("true") | Ok("on")
        )
    })
}

/// テスト用: env を介さず GPU 経路を強制有効化 (ignored テストでのみ使用)。
#[cfg(test)]
pub fn enable_for_tests() {
    GPU_FORCE.store(true, std::sync::atomic::Ordering::Relaxed);
}

/// テスト用: GPU 関連テストの直列化ロック (P17j)。
/// `set_gpu_attention_enabled` でグローバルフラグを差し替えるテストと、フラグ
/// 状態に依存するテスト (attention ON/OFF でビット一致/近似一致が変わる) が
/// 並列実行で競合し、片方の失敗が GPU_BROKEN 経由で他テストにも連鎖していた
/// (P17g から潜在・テスト数増加で顕在化)。フラグを扱う/依存するテストは
/// このロックを取得する。
#[cfg(test)]
#[doc(hidden)]
pub fn test_lock() -> &'static std::sync::Mutex<()> {
    static L: std::sync::OnceLock<std::sync::Mutex<()>> = std::sync::OnceLock::new();
    L.get_or_init(|| std::sync::Mutex::new(()))
}

/// 共有 CudaCtx (遅延初期化)。無効 or 初期化失敗なら None (CPU フォールバック)。
fn shared_ctx() -> Option<&'static CudaCtx> {
    GPU_CTX
        .get_or_init(|| match CudaCtx::new() {
            Ok(ctx) => {
                tracing::info!("CUDA int8 offload enabled: {}", ctx.info());
                Some(ctx)
            }
            Err(e) => {
                tracing::warn!("CUDA int8 offload unavailable, using CPU int8: {e:#}");
                // テスト/ベンチは tracing を出さないので、1 回だけ stderr にも書く
                // (「緑 = 経路が発動した証拠ではない」の取りこぼしを防ぐ)。
                eprintln!("[cuda] CudaCtx::new 失敗 → CPU へ: {e:#}");
                None
            }
        })
        .as_ref()
}

/// このスレッドの current context を共有 CudaCtx にする (必要なら初期化もする)。
///
/// CUDA の current context は**スレッドローカル**なので、推論スレッド以外
/// (起動時の事前ロードなど) から `DevBuffer` を確保するには、そのスレッドで
/// 1 回これを呼ぶ必要がある。呼ばないと `cuMemAlloc` が error 201
/// (INVALID_CONTEXT) で落ちる (P17c と同じ穴)。
///
/// 戻り値: 設定できたら true。CUDA が無効・初期化失敗なら false。
pub fn make_current_on_this_thread() -> bool {
    match shared_ctx() {
        Some(ctx) => match ctx.make_current() {
            Ok(()) => true,
            Err(e) => {
                tracing::warn!("CUDA cuCtxSetCurrent failed (このスレッド): {e:#}");
                false
            }
        },
        None => false,
    }
}

/// int8 重みの VRAM レジストリ (キー = Quant8Linear.uid)。
/// uid は Linear 構築時に採番されるため、Vec アドレスの再利用で別内容の重みが
/// 同一キーに現れることはない。Clone は uid を共有するが内容が同一なので安全。
/// エントリは解放しない (実運用は 1 モデル = 約 2GB、テストは微小)。
struct GpuW {
    w: DevBuffer,
    sc: DevBuffer,
    k: usize,
    n: usize,
    /// s74: `w` の行数 (n を GEMM_PAD_N の倍数に切り上げた値)。dno_gemm_i8 は
    /// j 方向を 256 列単位で処理するため、重みは 256 行に 0 パディングして渡す。
    /// カーネル自身は `n` (実列数) で epilogue を打ち切るので `sc` は n 本のまま。
    npad: usize,
}

/// s74: `gemm_pad_n(n)` を通した**パディング済み**行数 (`w` の行数)。
const GEMM_PAD_N: usize = 256;
/// s74: dno_gemm_i8 のタイル寸法 (kernels_int8.cu の GEMM_TILE / GEMM_TILE_N と
/// 同期すること)。i 方向 128 行 × j 方向 256 列・block 16x16 (1 thread 8x16 出力)。
const GEMM_TILE: usize = 128;
const GEMM_TILE_N: usize = 256;
/// s75: カーネルのブロック形状 (kernels_int8.cu の GEMM_BX / GEMM_BY)。
/// 1 thread 8 行 x 16 列・block 16x16 = 256 thread なので
/// `GEMM_BY * 8 == GEMM_TILE` / `GEMM_BX * 16 == GEMM_TILE_N` が成り立つ。
/// s74 は (16,4) = 64 thread で 32 行しか覆えていなかった (タイル 128 行と
/// 食い違い、残り 96 行が未書き込みのまま返っていた)。
const GEMM_BX: u32 = 16;
const GEMM_BY: u32 = 16;

/// s74 (T6 候補 1): dno_gemm_i8 の j 方向タイル (256) に合わせた重み行の切り上げ。
/// 旧 128 タイル版は端をカーネル側で 0 埋めしていたが、新カーネルは A 行を
/// 2 枚の B タイルで共有するため A/B の pad を非対称にできる重み側だけを
/// ホストで 0 埋めする (i8 の 0 は積に寄与しない → dot は厳密に不変)。
pub(crate) fn gemm_pad_n(n: usize) -> usize {
    n.div_ceil(GEMM_PAD_N) * GEMM_PAD_N
}

/// s74: 重み [n,k] i8 (row-major) を `gemm_pad_n` 行までラッパ行で 0 埋めする。
/// 既に倍数なら複製しない (VRAM/RAM の余分なコピーを避ける)。
fn gemm_pad_apply(qw: &[i8], k: usize, n: usize) -> std::borrow::Cow<'_, [i8]> {
    debug_assert_eq!(qw.len(), k * n);
    let npad = gemm_pad_n(n);
    if npad == n {
        return std::borrow::Cow::Borrowed(qw);
    }
    let mut w = vec![0i8; k * npad];
    // パディング行はブロックごとに連続した全域に置く (行内は k 要素で連続)。
    for r in 0..n {
        w[r * k..(r + 1) * k].copy_from_slice(&qw[r * k..(r + 1) * k]);
    }
    std::borrow::Cow::Owned(w)
}

fn weights_for(uid: u64, qw: &[i8], scale: &[f32], k: usize, n: usize) -> Result<&'static GpuW> {
    use std::collections::HashMap;
    use std::sync::Mutex;
    static REG: OnceLock<Mutex<HashMap<u64, Box<GpuW>>>> = OnceLock::new();
    let reg = REG.get_or_init(|| Mutex::new(HashMap::new()));
    let mut map = reg.lock().expect("weights registry poisoned");
    if !map.contains_key(&uid) {
        let w = DevBuffer::from_slice(&gemm_pad_apply(qw, k, n))?;
        let sc = DevBuffer::from_slice(scale)?;
        tracing::info!(
            "CUDA weight upload (uid={uid}): k={k} n={n} ({:.1} MB)",
            (k * n + n * 4) as f64 / 1e6
        );
        map.insert(uid, Box::new(GpuW { w, sc, k, n, npad: gemm_pad_n(n) }));
    }
    let e = map.get(&uid).expect("just inserted");
    debug_assert_eq!((e.k, e.n), (k, n), "uid 重複: 同一 uid に異なる形状");
    // &'static 化: REG は static、Box の中身は移動しない
    Ok(unsafe { std::mem::transmute::<&GpuW, &'static GpuW>(e.as_ref()) })
}

/// GPU オフロードする最大の m (行数)。decode / バッチ decode (m≤閾値) のみ
/// オフロードし、prefill (m が大きい GEMM) は CPU のまま — GEMV 型カーネルは
/// 行数に比例して重み再読みが増えるため m が大きいと CPU sgemm に負ける
/// (P17b 実測: m=128 で 0.39x)。閾値は `DENNO_CUDA_MAX_M` で変更可能。
fn max_m() -> usize {
    static MAX_M: OnceLock<usize> = OnceLock::new();
    *MAX_M.get_or_init(|| {
        std::env::var("DENNO_CUDA_MAX_M")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(16)
    })
}

use crate::quant::Quant8Linear;

/// P17i: 大きい m (prefill) 用の tiled GEMM 経路を有効にするか。
/// `DENNO_CUDA_GEMM=0` で無効化 (従来どおり CPU へ)。
fn gemm_enabled() -> bool {
    std::env::var("DENNO_CUDA_GEMM").ok().as_deref() != Some("0")
}

/// P17i: tiled GEMM を発動する最小の m。小さい m では GEMM 経路の層あたり
/// sync (H2D/quantize/gemm/D2H × 4 層/層) が CPU GEMM より高くつくため、
/// ある程度大きい m から発動させる (m=38 の短文 prefill は CPU が速い)。
/// `DENNO_CUDA_GEMM_MIN_M` で変更可。0 にすると m>max_m() で常に発動。
fn gemm_min_m() -> usize {
    std::env::var("DENNO_CUDA_GEMM_MIN_M")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(256)
}

/// P17c: 複数の int8 Linear を 1 回の GPU 呼び出しに融合する (QKV / gate+up 用)。
/// 同じ入力を消費する線形層群の重み行を**パート順に連結**した 1 つのバッファとして
/// 登録・計算する。各行の演算 (量子化スケール・i32 累積・スケール乗算) は個別
/// 呼び出しと完全に同一なので、出力をパート幅で切り分ければビット一致する。
/// 1 線形層 1 同期の固定オーバーヘッド (約 28µs) がパート数 → 1 になる効果:
/// 実測で qkv は 3 呼び出し分の 96µs/層 → 約 40µs/層。
///
/// 戻り値 None = CPU パス (無効/初期化失敗/実行時エラー/m>閾値/一部が Q8 でない)。
pub fn maybe_gpu_linear_grouped(parts: &[&Quant8Linear], a: &[f32], m: usize) -> Option<Vec<f32>> {
    if !cuda_enabled() || parts.is_empty() {
        return None;
    }
    let use_gemm = m > max_m() && m >= gemm_min_m() && gemm_enabled();
    // m が GEMV 経路の上限を超えて GEMM も発動しないなら CPU へ
    if m > max_m() && !use_gemm {
        return None;
    }
    let k = parts[0].k;
    let n: usize = parts.iter().map(|p| p.n).sum();
    let uids: Vec<u64> = parts.iter().map(|p| p.uid).collect();
    let ctx = shared_ctx()?;
    if let Err(e) = ctx.make_current() {
        tracing::error!("CUDA cuCtxSetCurrent failed, using CPU int8: {e:#}");
        GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
        return None;
    }
    let gw = match weights_for_group(&uids, parts, k, n) {
        Ok(g) => g,
        Err(e) => {
            tracing::error!("CUDA grouped weight upload failed, using CPU int8: {e:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            return None;
        }
    };
    // P17i: m が大きい (prefill) ときは tiled GEMM、小さいときは GEMV 型
    let r = if use_gemm {
        linear_gemm(ctx, a, gw, m, k, n)
    } else {
        linear_pinned(ctx, a, gw, m, k, n)
    };
    match r {
        Ok(out) => {
            // s61: 融合経路も実行先ラベルに計上する (PROFILE の via 列用)。
            // これが無いと llama の qkv/gate_up 融合 call が `via=cpu` と誤記される。
            set_last_linear_ran_on_gpu(true);
            Some(out)
        }
        Err(e) => {
            tracing::error!("CUDA grouped linear failed, falling back to CPU permanently: {e:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            None
        }
    }
}

/// P17k: FFN 線形ブロック (gate_up GEMM → swiglu → down GEMM) をデバイス常駐で実行。
/// h [m, e] から down 出力 [m, e] を返す。中間の [m, 2ff] (13k tok で 949MB) を
/// ホストに落とさないため、従来経路の D2H + to_vec + gate/up 分割コピー +
/// swiglu (CPU f64 expf) + H2D が全て消える。
///
/// ビット一致: gate_up/down は dno_gemm_i8 (整数累積で順序不変)、swiglu は
/// dno_swiglu_int (dno_swiglu と同一演算列) → CPU 経路と出力は完全一致。
/// 失敗時 None (呼び出し側で従来経路: gate/up Vec + CPU swiglu + down)。
/// m が GEMM 閾値未満なら None (小さい m は従来どおり CPU が最速)。
#[allow(clippy::too_many_arguments)]
pub fn maybe_gpu_ffn(
    gate: &Quant8Linear,
    up: &Quant8Linear,
    down: &Quant8Linear,
    h: &[f32],
    m: usize,
    ff: usize,
    li: usize,
) -> Option<Vec<f32>> {
    if !cuda_enabled() {
        return None;
    }
    if !(m > max_m() && m >= gemm_min_m() && gemm_enabled()) {
        return None;
    }
    let e = gate.k;
    debug_assert_eq!(up.k, e);
    debug_assert_eq!(down.k, ff);
    debug_assert_eq!(down.n, e);
    let ctx = shared_ctx()?;
    if let Err(err) = ctx.make_current() {
        tracing::error!("CUDA cuCtxSetCurrent failed, using CPU int8: {err:#}");
        GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
        return None;
    }
    let gw1 = match weights_for_group(&[gate.uid, up.uid], &[gate, up], e, 2 * ff) {
        Ok(g) => g,
        Err(err) => {
            tracing::error!("CUDA FFN weight upload failed, using CPU: {err:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            return None;
        }
    };
    let gw2 = match weights_for(down.uid, &down.w, &down.scale, ff, e) {
        Ok(g) => g,
        Err(err) => {
            tracing::error!("CUDA FFN down weight upload failed, using CPU: {err:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            return None;
        }
    };
    let lib = lib().ok()?;
    let r = SCRATCH.with(|cell| -> Result<Vec<f32>> {
        let mut s = cell.borrow_mut();
        let Scratch {
            x,
            aq,
            asc,
            out,
            hx,
            ho,
            act,
            aq2,
            asc2,
            out2,
        } = &mut *s;
        let bytes_x = m * e * 4;
        Scratch::ensure(x, bytes_x)?;
        Scratch::ensure(aq, m * e)?;
        Scratch::ensure(asc, m * 4)?;
        Scratch::ensure(out, m * 2 * ff * 4)?;
        Scratch::ensure(act, m * ff * 4)?;
        Scratch::ensure(aq2, m * ff)?;
        Scratch::ensure(asc2, m * 4)?;
        Scratch::ensure(out2, m * e * 4)?;
        Scratch::ensure_pin(hx, bytes_x)?;
        Scratch::ensure_pin(ho, m * e * 4)?;
        let (dx, daq, dasc, dout, dact, daq2, dasc2, dout2) = (
            x.as_ref().unwrap(),
            aq.as_ref().unwrap(),
            asc.as_ref().unwrap(),
            out.as_ref().unwrap(),
            act.as_ref().unwrap(),
            aq2.as_ref().unwrap(),
            asc2.as_ref().unwrap(),
            out2.as_ref().unwrap(),
        );
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        hx.as_mut_slice::<f32>()[..m * e].copy_from_slice(h);
        unsafe {
            check(
                (lib.memcpy_htod_async)(dx.ptr(), hx.ptr as *const c_void, bytes_x, std::ptr::null_mut()),
                "cuMemcpyHtoDAsync",
            )?;
            // 1) gate_up GEMM: [m, e] → [m, 2ff] (デバイス上に保持)
            crate::prof::time_layer(crate::prof::GATE_UP, li, || -> Result<()> {
                let (mut px, mut paq, mut pasc) = (dx.ptr(), daq.ptr(), dasc.ptr());
                let (mut mc, mut kc) = (m as c_int, e as c_int);
                let mut args = [
                    &mut px as *mut _ as *mut c_void,
                    &mut paq as *mut _ as *mut c_void,
                    &mut pasc as *mut _ as *mut c_void,
                    &mut mc as *mut _ as *mut c_void,
                    &mut kc as *mut _ as *mut c_void,
                ];
                ctx.launch_async(ctx.f_quant, (m as u32, 1, 1), (256, 1, 1), 256 * 4, &mut args)?;
                let (mut paqi, mut pasci, mut pw, mut psc, mut pout) =
                    (daq.ptr(), dasc.ptr(), gw1.w.ptr(), gw1.sc.ptr(), dout.ptr());
                let (mut mc, mut kc, mut nc) = (m as c_int, e as c_int, (2 * ff) as c_int);
                let mut args = [
                    &mut paqi as *mut _ as *mut c_void,
                    &mut pasci as *mut _ as *mut c_void,
                    &mut pw as *mut _ as *mut c_void,
                    &mut psc as *mut _ as *mut c_void,
                    &mut pout as *mut _ as *mut c_void,
                    &mut mc as *mut _ as *mut c_void,
                    &mut kc as *mut _ as *mut c_void,
                    &mut nc as *mut _ as *mut c_void,
                ];
                let gmx = m.div_ceil(GEMM_TILE) as u32;
                let gmy = (2 * ff).div_ceil(GEMM_TILE_N) as u32;
                ctx.launch_async(ctx.f_gemm, (gmx, gmy, 1), (GEMM_BX, GEMM_BY, 1), 0, &mut args)?;
                Ok(())
            })?;
            // 2) swiglu (interleaved): [m, 2ff] → act [m, ff] (デバイス上に保持)
            crate::prof::time_layer(crate::prof::SWIGLU, li, || -> Result<()> {
                let (mut pg, mut po) = (dout.ptr(), dact.ptr());
                let (mut pff, mut pw, mut pt) = (ff as c_int, (2 * ff) as c_int, (m * ff) as i64);
                let mut args = [
                    &mut pg as *mut _ as *mut c_void,
                    &mut po as *mut _ as *mut c_void,
                    &mut pff as *mut _ as *mut c_void,
                    &mut pw as *mut _ as *mut c_void,
                    &mut pt as *mut _ as *mut c_void,
                ];
                let grid = (m * ff).div_ceil(256) as u32;
                ctx.launch_async(ctx.f_swiglu_int, (grid, 1, 1), (256, 1, 1), 0, &mut args)?;
                Ok(())
            })?;
            // 3) down GEMM: act [m, ff] → out2 [m, e] + D2H。キュー待ちの実態を
            // DOWN に帰属させるため同期をこのタイマー内に入れる。
            crate::prof::time_layer(crate::prof::DOWN, li, || -> Result<()> {
                let (mut px, mut paq, mut pasc) = (dact.ptr(), daq2.ptr(), dasc2.ptr());
                let (mut mc, mut kc) = (m as c_int, ff as c_int);
                let mut args = [
                    &mut px as *mut _ as *mut c_void,
                    &mut paq as *mut _ as *mut c_void,
                    &mut pasc as *mut _ as *mut c_void,
                    &mut mc as *mut _ as *mut c_void,
                    &mut kc as *mut _ as *mut c_void,
                ];
                ctx.launch_async(ctx.f_quant, (m as u32, 1, 1), (256, 1, 1), 256 * 4, &mut args)?;
                let (mut paqi, mut pasci, mut pw, mut psc, mut pout) =
                    (daq2.ptr(), dasc2.ptr(), gw2.w.ptr(), gw2.sc.ptr(), dout2.ptr());
                let (mut mc, mut kc, mut nc) = (m as c_int, ff as c_int, e as c_int);
                let mut args = [
                    &mut paqi as *mut _ as *mut c_void,
                    &mut pasci as *mut _ as *mut c_void,
                    &mut pw as *mut _ as *mut c_void,
                    &mut psc as *mut _ as *mut c_void,
                    &mut pout as *mut _ as *mut c_void,
                    &mut mc as *mut _ as *mut c_void,
                    &mut kc as *mut _ as *mut c_void,
                    &mut nc as *mut _ as *mut c_void,
                ];
                let gmx = m.div_ceil(GEMM_TILE) as u32;
                let gmy = e.div_ceil(GEMM_TILE_N) as u32;
                ctx.launch_async(ctx.f_gemm, (gmx, gmy, 1), (GEMM_BX, GEMM_BY, 1), 0, &mut args)?;
                check(
                    (lib.memcpy_dtoh_async)(ho.ptr, dout2.ptr(), m * e * 4, std::ptr::null_mut()),
                    "cuMemcpyDtoHAsync",
                )?;
                // s65: 発行元の件数分類 (表示専用・時間は d2h_state バケット側)
                crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
                ctx.sync()?;
                Ok(())
            })?;
        }
        crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        Ok(ho.as_slice::<f32>()[..m * e].to_vec())
    });
    match r {
        Ok(out) => Some(out),
        Err(err) => {
            tracing::error!("CUDA FFN block failed, falling back to CPU: {err:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            None
        }
    }
}

/// B1: prefill デバイス常駐チェーン用 FFN ブロック — maybe_gpu_ffn と同一の
/// カーネル列 (gate_up GEMM → swiglu_int → down GEMM) を、入力 `in_slot`
/// (chain_rmsnorm が書いた h2・デバイス常駐) から出力 CH_DOWN (デバイス常駐) へ
/// **同期・ホスト往復なし**で実行する。h2 の H2D (81MB/層) と down の D2H
/// (81MB/層) を廃止。全段ビット一致 (GEMM: 整数累積・swiglu: dno_swiglu_int と
/// 同一演算)。戻り None = チェーン全体を従来経路でやり直し。
pub fn maybe_gpu_ffn_dev(
    gate: &Quant8Linear,
    up: &Quant8Linear,
    down: &Quant8Linear,
    in_slot: usize,
    m: usize,
    ff: usize,
    li: usize,
) -> Option<()> {
    if !(m > max_m() && m >= gemm_min_m() && gemm_enabled()) {
        return None;
    }
    let e = gate.k;
    debug_assert_eq!(up.k, e);
    debug_assert_eq!(down.k, ff);
    debug_assert_eq!(down.n, e);
    let ctx = chain_ctx()?;
    let gw1 = match weights_for_group(&[gate.uid, up.uid], &[gate, up], e, 2 * ff) {
        Ok(g) => g,
        Err(err) => {
            tracing::error!("CUDA FFN weight upload failed, using CPU: {err:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            return None;
        }
    };
    let gw2 = match weights_for(down.uid, &down.w, &down.scale, ff, e) {
        Ok(g) => g,
        Err(err) => {
            tracing::error!("CUDA FFN down weight upload failed, using CPU: {err:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            return None;
        }
    };
    ok(chain_ensure_buf(in_slot, m * e * 4))?;
    ok(chain_ensure_buf(CH_DOWN, m * e * 4))?;
    CHAIN.with(|cell| -> Option<()> {
        let s = cell.borrow();
        let dptr_in = s.bufs[in_slot].as_ref().unwrap().ptr();
        let dptr_out = s.bufs[CH_DOWN].as_ref().unwrap().ptr();
        SCRATCH.with(|c2| -> Option<()> {
            let mut s2 = c2.borrow_mut();
            ok(Scratch::ensure(&mut s2.aq, m * e))?;
            ok(Scratch::ensure(&mut s2.asc, m * 4))?;
            ok(Scratch::ensure(&mut s2.out, m * 2 * ff * 4))?;
            ok(Scratch::ensure(&mut s2.act, m * ff * 4))?;
            ok(Scratch::ensure(&mut s2.aq2, m * ff))?;
            ok(Scratch::ensure(&mut s2.asc2, m * 4))?;
            let (daq, dasc, dout, dact, daq2, dasc2) = (
                s2.aq.as_ref().unwrap(),
                s2.asc.as_ref().unwrap(),
                s2.out.as_ref().unwrap(),
                s2.act.as_ref().unwrap(),
                s2.aq2.as_ref().unwrap(),
                s2.asc2.as_ref().unwrap(),
            );
            unsafe {
                // 1) gate_up GEMM: [m, e] → [m, 2ff] (デバイス上に保持)
                crate::prof::time_layer(crate::prof::GATE_UP, li, || -> Option<()> {
                    let (mut px, mut paq, mut pasc) = (dptr_in, daq.ptr(), dasc.ptr());
                    let (mut mc, mut kc) = (m as c_int, e as c_int);
                    let mut args = [
                        &mut px as *mut _ as *mut c_void,
                        &mut paq as *mut _ as *mut c_void,
                        &mut pasc as *mut _ as *mut c_void,
                        &mut mc as *mut _ as *mut c_void,
                        &mut kc as *mut _ as *mut c_void,
                    ];
                    ok(ctx.launch_async(ctx.f_quant, (m as u32, 1, 1), (256, 1, 1), 256 * 4, &mut args))?;
                    let (mut paqi, mut pasci, mut pw, mut psc, mut pout) =
                        (daq.ptr(), dasc.ptr(), gw1.w.ptr(), gw1.sc.ptr(), dout.ptr());
                    let (mut mc, mut kc, mut nc) = (m as c_int, e as c_int, (2 * ff) as c_int);
                    let mut args = [
                        &mut paqi as *mut _ as *mut c_void,
                        &mut pasci as *mut _ as *mut c_void,
                        &mut pw as *mut _ as *mut c_void,
                        &mut psc as *mut _ as *mut c_void,
                        &mut pout as *mut _ as *mut c_void,
                        &mut mc as *mut _ as *mut c_void,
                        &mut kc as *mut _ as *mut c_void,
                        &mut nc as *mut _ as *mut c_void,
                    ];
                    let gmx = m.div_ceil(GEMM_TILE) as u32;
                    let gmy = (2 * ff).div_ceil(GEMM_TILE_N) as u32;
                    ok(ctx.launch_async(ctx.f_gemm, (gmx, gmy, 1), (GEMM_BX, GEMM_BY, 1), 0, &mut args))
                })?;
                // 2) swiglu (interleaved): [m, 2ff] → act [m, ff] (デバイス上に保持)
                crate::prof::time_layer(crate::prof::SWIGLU, li, || -> Option<()> {
                    let (mut pg, mut po) = (dout.ptr(), dact.ptr());
                    let (mut pff, mut pw, mut pt) = (ff as c_int, (2 * ff) as c_int, (m * ff) as i64);
                    let mut args = [
                        &mut pg as *mut _ as *mut c_void,
                        &mut po as *mut _ as *mut c_void,
                        &mut pff as *mut _ as *mut c_void,
                        &mut pw as *mut _ as *mut c_void,
                        &mut pt as *mut _ as *mut c_void,
                    ];
                    let grid = (m * ff).div_ceil(256) as u32;
                    ok(ctx.launch_async(ctx.f_swiglu_int, (grid, 1, 1), (256, 1, 1), 0, &mut args))
                })?;
                // 3) down GEMM: act [m, ff] → CH_DOWN [m, e] (デバイス常駐・同期なし)
                crate::prof::time_layer(crate::prof::DOWN, li, || -> Option<()> {
                    let (mut px, mut paq, mut pasc) = (dact.ptr(), daq2.ptr(), dasc2.ptr());
                    let (mut mc, mut kc) = (m as c_int, ff as c_int);
                    let mut args = [
                        &mut px as *mut _ as *mut c_void,
                        &mut paq as *mut _ as *mut c_void,
                        &mut pasc as *mut _ as *mut c_void,
                        &mut mc as *mut _ as *mut c_void,
                        &mut kc as *mut _ as *mut c_void,
                    ];
                    ok(ctx.launch_async(ctx.f_quant, (m as u32, 1, 1), (256, 1, 1), 256 * 4, &mut args))?;
                    let (mut paqi, mut pasci, mut pw, mut psc, mut pout) =
                        (daq2.ptr(), dasc2.ptr(), gw2.w.ptr(), gw2.sc.ptr(), dptr_out);
                    let (mut mc, mut kc, mut nc) = (m as c_int, ff as c_int, e as c_int);
                    let mut args = [
                        &mut paqi as *mut _ as *mut c_void,
                        &mut pasci as *mut _ as *mut c_void,
                        &mut pw as *mut _ as *mut c_void,
                        &mut psc as *mut _ as *mut c_void,
                        &mut pout as *mut _ as *mut c_void,
                        &mut mc as *mut _ as *mut c_void,
                        &mut kc as *mut _ as *mut c_void,
                        &mut nc as *mut _ as *mut c_void,
                    ];
                    let gmx = m.div_ceil(GEMM_TILE) as u32;
                    let gmy = e.div_ceil(GEMM_TILE_N) as u32;
                    ok(ctx.launch_async(ctx.f_gemm, (gmx, gmy, 1), (GEMM_BX, GEMM_BY, 1), 0, &mut args))
                })
            }
        })
    })
}

fn weights_for_group(
    uids: &[u64],
    parts: &[&Quant8Linear],
    k: usize,
    n: usize,
) -> Result<&'static GpuW> {
    use std::collections::HashMap;
    use std::sync::Mutex;
    static REG: OnceLock<Mutex<HashMap<Vec<u64>, Box<GpuW>>>> = OnceLock::new();
    let reg = REG.get_or_init(|| Mutex::new(HashMap::new()));
    let mut map = reg.lock().expect("weights registry poisoned");
    if !map.contains_key(uids) {
        // パート順にホスト側で行連結してから 1 回でアップロードする
        // (ホスト連結バッファはアップロード後 immediately drop → RAM 定常増なし)
        let mut w = Vec::with_capacity(k * n);
        let mut sc = Vec::with_capacity(n);
        for p in parts {
            debug_assert_eq!(p.k, k, "融合グループ内で k が不一致");
            if p.k != k {
                bail!("CUDA grouped linear: k mismatch ({} vs {})", p.k, k);
            }
            w.extend_from_slice(&p.w);
            sc.extend_from_slice(&p.scale);
        }
        debug_assert_eq!(w.len(), k * n);
        let w = DevBuffer::from_slice(&gemm_pad_apply(&w, k, n))?;
        let sc = DevBuffer::from_slice(&sc)?;
        tracing::info!(
            "CUDA grouped weight upload ({} parts, uids={}..): k={k} n={n} ({:.1} MB)",
            parts.len(),
            uids[0],
            (k * n + n * 4) as f64 / 1e6
        );
        map.insert(uids.to_vec(), Box::new(GpuW { w, sc, k, n, npad: gemm_pad_n(n) }));
    }
    let e = map.get(uids).expect("just inserted");
    Ok(unsafe { std::mem::transmute::<&GpuW, &'static GpuW>(e.as_ref()) })
}

// s57 (T4): PROFILE の実行先ラベル用に「直近の GPU 線形呼び出しが実際に GPU で
// 走ったか」を記録する thread-local。**計測のみ** — `maybe_gpu_linear` が結果を
// 返す直前に書くだけで、数値・分岐・GPU 状態には触れない。値は次の線形呼び出し
// まで古いまま (呼び出し側は同じ区間の計測にしか使わない)。
#[cfg(feature = "cuda")]
thread_local! {
    static LINEAR_RAN_ON_GPU: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    /// s61: 区間内で「一度でも GPU 線形が走ったか」の集積フラグ。ネストした
    /// `Probe` を許すため深さも持つ (最深の scope が閉じたときに外側へ引き継ぐ)。
    static LINEAR_SCOPE: (std::cell::Cell<u32>, std::cell::Cell<bool>) =
        const { (std::cell::Cell::new(0), std::cell::Cell::new(false)) };
}

/// 直近の `maybe_gpu_linear` が GPU で走りきったか (PROFILE の実行先ラベル用)。
/// PROFILE 無効時はプロファイラ側が参照しないため、この記録は無害な no-op に
/// 近い (Cell 書き込み 1 回)。
#[cfg(feature = "cuda")]
#[inline]
pub fn last_linear_ran_on_gpu() -> bool {
    LINEAR_RAN_ON_GPU.with(|c| c.get())
}

#[cfg(feature = "cuda")]
#[inline]
pub(crate) fn set_last_linear_ran_on_gpu(v: bool) {
    LINEAR_RAN_ON_GPU.with(|c| c.set(v));
    // s61: 開いている区間 (Probe) があれば OR で集積する (計測のみ)
    if v {
        LINEAR_SCOPE.with(|(depth, any)| {
            if depth.get() > 0 {
                any.set(true);
            }
        });
    }
}

/// s61 (T5a 撤回の知見): 区間の実行先ラベルを「区間内の **いずれか** の線形
/// 呼び出しが GPU で走ったか」で取るためのスコープ。
///
/// `last_linear_ran_on_gpu()` は **直近 1 回** の `maybe_gpu_linear` しか
/// 見ないため、1 区間で複数の線形を呼ぶバケット (qkv = q/k/v の 3 本、
/// gate_up = gate + up) では最後の 1 本の結果に引きずられる (v が GEMV で
/// GPU、k が CPU のような場合に cb が誤る)。`Probe` は区間中に
/// `maybe_gpu_linear` が **OR で** 記録した値を読み、`Drop` で必ず閉じる。
///
/// **計測のみ** — 記録するのは `Cell<bool>` だけで、分岐・数値・GPU 状態には
/// 一切触れない。PROFILE 無効時も呼ばれるが cost は Cell 2 回。
#[cfg(feature = "cuda")]
pub struct Probe {
    _not_send: std::marker::PhantomData<*const ()>,
}

#[cfg(feature = "cuda")]
impl Probe {
    #[inline]
    pub fn begin() -> Self {
        LINEAR_SCOPE.with(|(depth, any)| {
            if depth.get() == 0 {
                any.set(false);
            }
            depth.set(depth.get() + 1);
        });
        Probe { _not_send: std::marker::PhantomData }
    }

    /// この区間中に GPU 線形が 1 回でも走ったか。
    #[inline]
    pub fn any_on_gpu(&self) -> bool {
        LINEAR_SCOPE.with(|(_, any)| any.get())
    }
}

#[cfg(feature = "cuda")]
impl Drop for Probe {
    #[inline]
    fn drop(&mut self) {
        LINEAR_SCOPE.with(|(depth, any)| {
            let d = depth.get().saturating_sub(1);
            depth.set(d);
            // 最深 scope が閉じた時点でフラグは外側 scope の集積に残る
            // (外側 scope がまだ open ならその値に OR 済み)。
            if d == 0 {
                // 最外を閉じたら次回 begin() が false から始める
                any.set(false);
            }
        });
    }
}

/// s61 (T5a 撤回): GPU 線形層の入口 (`maybe_gpu_linear`) が呼ばれた回数の
/// **診断用カウンタ**。既定経路が入口を迂回していないことを GPU 無し環境でも
/// 検査できるようにする (083218d はゲート未指定で `matmul_bt_i8` を直呼びし、
/// この入口に一度も到達しなかった)。
///
/// 値の読み書きは Relaxed の加算 1 回のみで、分岐・戻り値・数値経路には触れない。
static LINEAR_SEAM_CALLS: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

/// s61: `maybe_gpu_linear` の入口に到達した累計回数 (回帰テスト用)。
#[cfg(feature = "cuda")]
#[inline]
pub fn linear_seam_calls() -> u64 {
    LINEAR_SEAM_CALLS.load(std::sync::atomic::Ordering::Relaxed)
}

// ---------------------------------------------------------------------------
// s138 (Task B6・計測のみ): decode chain のステップ分割 (表 A) と、線形ラッパの
// 分割 (表 B) のための小道具。**表示専用** (prof.rs の SPLIT_* にしか積まない)。
//
// 前提: chain (CUDA 部分) は 1 ステップで使う GPU 資源が 1 本の stream に直列で、
// 呼び出しスレッドも 1 本。したがって「段」は thread-local の 1 個の状態で足りる
// (BF/多セッションの chain はスレッドごとに別 state = 混ざらない)。
// ---------------------------------------------------------------------------

thread_local! {
    /// 現在走っている chain の段 (prof.rs の CHAIN_*)。0 = 計測していない。
    static CHAIN_SEG: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    /// 1 ステップ分の積算 (秒)。`take` で取り出す。
    static CHAIN_ACC: std::cell::RefCell<[f64; crate::prof::SPLIT_ROWS]> =
        const { std::cell::RefCell::new([0.0; crate::prof::SPLIT_ROWS]) };
    /// 段の切り替え時刻。
    static CHAIN_TICK: std::cell::Cell<Option<Instant>> = const { std::cell::Cell::new(None) };
    /// どの段からも取れなかった sync の残余 (秒)。ステップ終端で待ち行へ入れる。
    static CHAIN_RESID: std::cell::Cell<f64> = const { std::cell::Cell::new(0.0) };
}

// ---------------------------------------------------------------------------
// s166 (P5): decode 1 ステップの launch / copy 件数 (DENNO_DECODE_DBG=1)
//
// nsys を使わずに「1 ステップに何発カーネルを投げ、何回・何バイト転送したか」を
// 数える。既定は OFF (`DENNO_DECODE_DBG` 未設定) で、各サイトに分岐 1 回が
// 増えるだけ。数値経路・発行順・引数には一切触れない (観測のみ)。
//
// 使い方: `DENNO_DECODE_DBG=1` で serve を起動すると、decode 1 ステップごとに
//   [DECODE_DBG] step=3 launch=337 h2d=2 d2h=33
//     launch=[dno_gemv_q4_0c4=337,dno_add_rmsnorm=129,...]
//     h2d=[20480x1,512x1] d2h=[2048x32,606208x1]
// を stderr に 1 行 (続けて内訳 2 行) 出す。件数は「その step の begin〜end」で
// 数えるので、prefill で積んだ分は次の begin で捨てる (decode の数字に混ぜない)。
// ---------------------------------------------------------------------------
fn decode_dbg_on() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| std::env::var("DENNO_DECODE_DBG").ok().as_deref() == Some("1"))
}

/// (キー, 件数) の集計。キーは CUfunction かバイト数。種類は 20 程度なので
/// 線形走査で足りる (1 ステップ 500 件程度)。
type DbgTally = Vec<(usize, u64)>;

fn dbg_bump(t: &mut DbgTally, key: usize) {
    for e in t.iter_mut() {
        if e.0 == key {
            e.1 += 1;
            return;
        }
    }
    t.push((key, 1));
}

#[derive(Default)]
struct DecodeDbg {
    steps: u64,
    launches: DbgTally,
    h2d: DbgTally,
    d2h: DbgTally,
    /// s169 (P10): Q4 GEMV の (n, C) 別の件数。key = (n << 4) | C。
    gemv: DbgTally,
}

thread_local! {
    static DECODE_DBG: std::cell::RefCell<DecodeDbg> =
        std::cell::RefCell::new(DecodeDbg {
            steps: 0,
            launches: Vec::new(),
            h2d: Vec::new(),
            d2h: Vec::new(),
            gemv: Vec::new(),
        });
}

/// カーネル 1 発を数える (`CudaCtx::launch_async` の入口から)。
#[inline]
fn dbg_launch(f: CUfunction) {
    if decode_dbg_on() {
        DECODE_DBG.with(|d| dbg_bump(&mut d.borrow_mut().launches, f as usize));
    }
}

/// s169 (P10): Q4 GEMV 1 発の (出力行数 n, 列ブロック幅 C) を数える。
/// launch 形状の選択 (`DENNO_GEMV_SHAPE`) がどの投影に効いたかを、GPU 無しでも
/// 実機の stderr から読めるようにするための観測のみ (OFF は分岐 1 回)。
#[inline]
fn dbg_gemv_shape(n: usize, c: usize) {
    if decode_dbg_on() {
        DECODE_DBG.with(|d| dbg_bump(&mut d.borrow_mut().gemv, (n << 4) | (c & 0xf)));
    }
}

/// H2D 1 回を数える (バイト数で分類)。decode 経路の転送サイトから呼ぶ。
#[inline]
pub fn dbg_htod(bytes: usize) {
    if decode_dbg_on() {
        DECODE_DBG.with(|d| dbg_bump(&mut d.borrow_mut().h2d, bytes));
    }
}

/// D2H 1 回を数える。
#[inline]
pub fn dbg_d2h(bytes: usize) {
    if decode_dbg_on() {
        DECODE_DBG.with(|d| dbg_bump(&mut d.borrow_mut().d2h, bytes));
    }
}

/// CUfunction → カーネル名 (既知のものだけ・未知は "unknown")。
fn dbg_kernel_name(p: CUfunction) -> &'static str {
    let Some(ctx) = chain_ctx() else {
        return "unknown";
    };
    if p == ctx.f_quant {
        return "dno_quant_i8";
    }
    if p == ctx.f_mv {
        return "dno_gemv_i8";
    }
    if p == ctx.f_gemm {
        return "dno_gemm_i8";
    }
    if p == ctx.f_mv_q4 {
        return "dno_gemv_q4_0";
    }
    if p == ctx.f_gemm_q4 {
        return "dno_gemm_q4_0";
    }
    if let Some(f) = ctx.f_mv_q4_mr {
        if p == f {
            return "dno_gemv_q4_0mr";
        }
    }
    if let Some(fs) = ctx.f_mv_q4_c {
        const NAMES: [&str; 3] = ["dno_gemv_q4_0c2", "dno_gemv_q4_0c4", "dno_gemv_q4_0c8"];
        for (i, n) in NAMES.iter().enumerate() {
            if p == fs[i] {
                return n;
            }
        }
    }
    if p == ctx.f_swiglu {
        return "dno_swiglu";
    }
    if p == ctx.f_swiglu_int {
        return "dno_swiglu_int";
    }
    if p == ctx.f_addnorm {
        return "dno_add_rmsnorm";
    }
    if p == ctx.f_expf {
        return "dno_expf";
    }
    if p == ctx.f_attn {
        return "dno_attention";
    }
    if p == ctx.f_attn_pf {
        return "dno_attention_prefill";
    }
    if p == ctx.f_rope {
        return "dno_rope";
    }
    if p == ctx.f_rope_pf {
        return "dno_rope_pf";
    }
    if p == ctx.f_rope_b {
        return "dno_rope_b";
    }
    if p == ctx.f_gdn {
        return "dno_gdn_scan";
    }
    if p == ctx.f_gdn_chunk_pre {
        return "dno_gdn_chunk_pre";
    }
    if let Some(f) = ctx.f_gdn_chunk_pre_sm {
        if p == f {
            return "dno_gdn_chunk_pre_sm";
        }
    }
    if p == ctx.f_gdn_chunk_state {
        return "dno_gdn_chunk_state";
    }
    if p == ctx.f_gdn_chunk_scan {
        return "dno_gdn_chunk_scan";
    }
    if let Some(f) = ctx.f_gdn_chunk_scan_hoist {
        if p == f {
            return "dno_gdn_chunk_scan_hoist";
        }
    }
    if let Some(q) = q35_fns() {
        if p == q.f_matvec_f32 {
            return "dno_matvec_f32";
        }
        if p == q.f_qknorm_rope {
            return "dno_qknorm_rope_pi";
        }
        if p == q.f_gate {
            return "dno_attn_gate_mul";
        }
    }
    "unknown"
}

/// 件数の多い順に `name=count` を並べた文字列 (内訳表示用)。
fn dbg_fmt_launch(t: &DbgTally) -> String {
    let mut v: Vec<(&'static str, u64)> = t
        .iter()
        .map(|&(f, c)| (dbg_kernel_name(f as CUfunction), c))
        .collect();
    v.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
    v.iter()
        .map(|(n, c)| format!("{n}={c}"))
        .collect::<Vec<_>>()
        .join(",")
}

/// `bytes×count` をバイト数の大きい順に並べた文字列。
fn dbg_fmt_bytes(t: &DbgTally) -> String {
    let mut v: Vec<(usize, u64)> = t.to_vec();
    v.sort_by(|a, b| b.0.cmp(&a.0));
    v.iter()
        .map(|(b, c)| format!("{b}x{c}"))
        .collect::<Vec<_>>()
        .join(",")
}

/// s169 (P10): `n/C × count` を n の大きい順に並べた文字列 (Q4 GEMV の形状内訳)。
fn dbg_fmt_gemv(t: &DbgTally) -> String {
    let mut v: Vec<(usize, u64)> = t.to_vec();
    v.sort_by(|a, b| b.0.cmp(&a.0));
    v.iter()
        .map(|(k, c)| format!("{}/c{}x{}", k >> 4, k & 0xf, c))
        .collect::<Vec<_>>()
        .join(",")
}

/// ステップ開始: 前のステップ (や prefill) で積んだ分を捨てる。
fn decode_dbg_reset() {
    if !decode_dbg_on() {
        return;
    }
    DECODE_DBG.with(|d| {
        let mut d = d.borrow_mut();
        d.launches.clear();
        d.h2d.clear();
        d.d2h.clear();
        d.gemv.clear();
    });
}

/// ステップ末尾: 1 行 (＋内訳 2 行) を stderr に出す。観測のみ。
fn decode_dbg_flush() {
    if !decode_dbg_on() {
        return;
    }
    DECODE_DBG.with(|d| {
        let mut d = d.borrow_mut();
        if d.launches.is_empty() && d.h2d.is_empty() && d.d2h.is_empty() {
            return; // このステップは 1 発も投げていない (CPU 経路) — 出さない
        }
        d.steps += 1;
        let n_l: u64 = d.launches.iter().map(|e| e.1).sum();
        let n_h: u64 = d.h2d.iter().map(|e| e.1).sum();
        let n_d: u64 = d.d2h.iter().map(|e| e.1).sum();
        let lb = d.h2d.iter().map(|e| e.0 as u64 * e.1).sum::<u64>();
        let db = d.d2h.iter().map(|e| e.0 as u64 * e.1).sum::<u64>();
        eprintln!(
            "[DECODE_DBG] step={} launch={} h2d={} ({} B) d2h={} ({} B)",
            d.steps, n_l, n_h, lb, n_d, db
        );
        eprintln!("[DECODE_DBG]   launch=[{}]", dbg_fmt_launch(&d.launches));
        eprintln!(
            "[DECODE_DBG]   h2d=[{}] d2h=[{}]",
            dbg_fmt_bytes(&d.h2d),
            dbg_fmt_bytes(&d.d2h)
        );
        // s169 (P10): Q4 GEMV の (n, C) 内訳。形状選択が効いた投影がここで判る。
        if !d.gemv.is_empty() {
            eprintln!("[DECODE_DBG]   gemv=[{}]", dbg_fmt_gemv(&d.gemv));
        }
        d.launches.clear();
        d.h2d.clear();
        d.d2h.clear();
        d.gemv.clear();
    });
}

/// 段の id を (表, 行) へ畳む。chain 用の id かどうかだけ見ればよい。
#[inline]
fn chain_row(op: usize) -> Option<usize> {
    match crate::prof::split_slot(op) {
        Some((t, i)) if t == crate::prof::SPLIT_CHAIN_TABLE => Some(i),
        _ => None,
    }
}

/// 現在の段に `secs` を足す (段が 0 = 計測していないなら何もしない)。
#[inline]
fn chain_charge(secs: f64) {
    let cur = CHAIN_SEG.with(|c| c.get());
    if cur == 0 {
        return;
    }
    if let Some(i) = chain_row(cur) {
        CHAIN_ACC.with(|a| a.borrow_mut()[i] += secs);
    }
}

/// 段を `op` へ切り替える。計測していない (段 0) ときは何もしない —
/// 呼び出し側は `chain_step_begin` を打ったステップの中でだけ切り替える。
#[inline]
pub fn chain_seg(op: usize) {
    if !crate::prof::split_on() {
        return;
    }
    let cur = CHAIN_SEG.with(|c| c.get());
    if cur == 0 || chain_row(op).is_none() {
        return;
    }
    let now = Instant::now();
    let prev = CHAIN_TICK.with(|c| c.replace(Some(now)));
    if let Some(t0) = prev {
        chain_charge(now.duration_since(t0).as_secs_f64());
    }
}

/// 直前の段 (`op`) を締めて、**同じ段**の tick を打ち直す。
/// ステップ内で同じ段が続く区間 (発行の合間) の区切りに使う。計測 OFF は分岐 1 回。
#[inline]
pub fn chain_seg_mark(op: usize) {
    if !crate::prof::split_on() {
        return;
    }
    let cur = CHAIN_SEG.with(|c| c.get());
    if cur == 0 || cur != op || chain_row(op).is_none() {
        return;
    }
    let now = Instant::now();
    let prev = CHAIN_TICK.with(|c| c.replace(Some(now)));
    if let Some(t0) = prev {
        chain_charge(now.duration_since(t0).as_secs_f64());
    }
}

/// s140: 「このステップは chain 本体まで到達した」ことを表 A のサンプル数に数える。
/// 1 ステップ 1 回 (`forward_decode_chain` が段の切り替えを始める直前)。
#[inline]
pub fn chain_step_entered() {
    if !crate::prof::split_on() {
        return;
    }
    if CHAIN_SEG.with(|c| c.get()) == 0 {
        return;
    }
    crate::prof::split_tick_call(crate::prof::SPLIT_CHAIN_TABLE);
}

/// `op` の区間だけを測る (段を切り替えずに、その間の時間を `op` へ引く)。
///
/// 使いどころは「sync の中に入った 1 本のカーネル実行」— decode では
/// `cuCtxSynchronize` が直前に発行したカーネルの完了を待つ時間が支配的なので、
/// 発行直後と sync 直後に同じ tick を読み、その差を `kernel_wait` として
/// 待ち行から分離する (待ちの合計は動かない)。計測 OFF はクロック読みゼロ。
#[inline]
fn chain_mark_span(op: usize, t0: Instant) {
    if !crate::prof::split_on() {
        return;
    }
    if CHAIN_SEG.with(|c| c.get()) == 0 {
        return;
    }
    if let Some(i) = chain_row(op) {
        CHAIN_ACC.with(|a| a.borrow_mut()[i] += t0.elapsed().as_secs_f64());
    }
}

/// 計測するなら今の時刻 (呼び出し側はこれが None なら何もしない)。
/// 公開しているのは「発行したカーネルの完了待ち」を `chain_kernel` へ移すため —
/// 呼び出し側 (decode chain) が発行の直後と sync の直後に 1 回ずつ読む。
#[inline]
pub fn chain_tick() -> Option<Instant> {
    if crate::prof::split_on() {
        Some(Instant::now())
    } else {
        None
    }
}

thread_local! {
    /// 直近の `chain_sync_observed` が観測した (sync の所要秒, 直前に発行した
    /// カーネルの実行秒)。計測 OFF では None のまま = 呼び出し側は何もしない。
    static CHAIN_SIG: std::cell::Cell<Option<(f64, f64)>> = const { std::cell::Cell::new(None) };
}

/// chain の sync を分割表の観点で観測する (`chain_sync_pending` の直後に 1 回)。
///
/// `secs` = sync の所要、`kernel_secs` = 直前に発行したカーネルの tick からの経過。
/// 両方が揃っているときだけ「カーネル実行 = sync 所要のうち tick からの経過」を
/// `chain_kernel` へ移し、待ち行から同じ秒数を引く (待ちの合計は動かない)。
/// `chain_step_begin` していない (段 0) や計測 OFF では何もしない。
///
/// ここで観測した値は `chain_sig` が 1 回だけ返す (表へは呼び出し側が流す)。
pub fn chain_sync_observed(secs: f64, kernel_secs: Option<f64>) {
    if !crate::prof::split_on() {
        return;
    }
    if CHAIN_SEG.with(|c| c.get()) == 0 {
        return;
    }
    // カーネル実行は待ちを超えない (tick は sync の直前に打つので、超えるのは
    // 時計の粒度か別スレッドの割り込み) — 超えた分は待ち側に残す。
    let sig = match kernel_secs {
        Some(k) if k > 0.0 && secs > 0.0 => (secs, k.min(secs)),
        _ => (secs, 0.0),
    };
    CHAIN_SIG.with(|c| c.set(Some(sig)));
}

/// `chain_sync_observed` が観測した (sync 秒, カーネル実行秒) を 1 回だけ返す。
/// 計測 OFF / 未観測は None (呼び出し側は何もしない)。
#[inline]
pub fn chain_sig() -> Option<(f64, f64)> {
    CHAIN_SIG.with(|c| c.replace(None))
}

/// ステップ先頭: chain の計測を開き、最初の段を `CHAIN_OUTER` (embedding 用意・
/// reserve など chain の外側) にする。呼び出しは decode chain の入口 1 か所だけで、
/// 対応する `chain_step_end` がステップ末尾に 1 か所ある (失敗して途中で抜ける
/// ステップはそこまでが積まれ、以後のステップで上書きされる)。
///
/// 計測 OFF は分岐 1 回 (クロックも読まない)。
pub fn chain_step_begin() {
    // s166 (P5): 観測カウンタのリセット (env OFF は分岐 1 回) — prefill で積んだ
    // 分を decode の数字に混ぜない。
    decode_dbg_reset();
    if !crate::prof::split_on() {
        return;
    }
    CHAIN_ACC.with(|a| *a.borrow_mut() = [0.0; crate::prof::SPLIT_ROWS]);
    CHAIN_RESID.with(|c| c.set(0.0));
    CHAIN_TICK.with(|c| c.set(Some(Instant::now())));
    CHAIN_SEG.with(|c| c.set(crate::prof::CHAIN_OUTER));
}

/// ステップ末尾: 最後の段を締め、1 ステップ分を表 A へ流し込む。呼び出しは
/// `chain_step_begin` と対で 1 か所。計測 OFF は分岐 1 回。
pub fn chain_step_end() {
    // s166 (P5): 1 ステップ分の launch / copy 件数を stderr へ (env OFF は分岐 1 回)。
    decode_dbg_flush();
    if !crate::prof::split_on() {
        return;
    }
    if CHAIN_SEG.with(|c| c.get()) == 0 {
        return; // begin していない (別の経路) — 何も積まない
    }
    // 最後の段をここで締める (tick はこの 1 回だけ)
    if let Some(t0) = CHAIN_TICK.with(|c| c.replace(None)) {
        chain_charge(Instant::now().duration_since(t0).as_secs_f64());
    }
    CHAIN_SEG.with(|c| c.set(0));
    chain_step_flush();
}

/// ステップ末尾: 最後の段の区間を締めて、1 ステップ分を表 A へ流し込む。
/// 締めの tick は `chain_step_end` (呼び出し側の 1 行) の側で読む。
///
/// 「どの sync からも取れなかった待ち」(`CHAIN_RESID`) は**待ち行**へ入れる —
/// sync 区間の理解できない残余は発行ではなく待ちだから (排他の和は動かない)。
fn chain_step_flush() {
    let rows = CHAIN_ACC.with(|a| {
        let acc = &mut *a.borrow_mut();
        let rows = *acc;
        *acc = [0.0; crate::prof::SPLIT_ROWS];
        rows
    });
    let mut acc = rows;
    let resid = CHAIN_RESID.with(|c| c.replace(0.0));
    if resid > 0.0 {
        // どの sync からも取れなかった待ちは残余行 (= `CHAIN_SYNC_RESIDUAL`) へ。
        // 待ちの合計は動かない (残余も待ちとして数える)。
        acc[crate::prof::CHAIN_SYNC_RESIDUAL - crate::prof::SPLIT_CHAIN_FIRST] += resid;
    }
    crate::prof::split_flush_step(crate::prof::SPLIT_CHAIN_TABLE, &acc, 1, None);
}

/// chain の sync (`cuCtxSynchronize`) を「段」の観点で観測する。
///
/// sync の所要 `secs` と、sync の直前まで走っていた段 `prev` が分かるとき、
/// その待ちの帰属は 1 つに決まる:
///   - prev が launch 系 (`chain_launch`) … 直前に発行したカーネルの完了待ち。
///     `chain_kernel` として積み、待ち行 (`prev`) からは **同じ秒数を引く**
///     (待ちの合計は動かない = 排他の和が保たれる)。
///   - prev が既に待ち (`chain_sync_wait` / `chain_sync_resid`) … 前の sync で
///     取り切れなかった分。`chain_sync_wait` に積む。
///   - それ以外 … 待ち行へ (残余はステップ末尾でまとめて待ち行に寄せる)。
///
/// `kernel` は直前に発行した 1 本のカーネルの実行時間 (発行直後と sync 直後の
/// tick の差)。計測 OFF なら `secs` / `kernel` は読まれない (呼び出し側が None)。
#[inline]
fn chain_observe_sync(secs: f64, kernel: Option<f64>) {
    if !crate::prof::split_on() {
        return;
    }
    let prev = CHAIN_SEG.with(|c| c.get());
    if prev == 0 {
        return;
    }
    let wait_row = crate::prof::CHAIN_SYNC_WAIT - crate::prof::SPLIT_CHAIN_FIRST;
    let launch_row = crate::prof::CHAIN_LAUNCH - crate::prof::SPLIT_CHAIN_FIRST;
    let kern_row = crate::prof::CHAIN_KERNEL_WAIT - crate::prof::SPLIT_CHAIN_FIRST;
    match (prev == crate::prof::CHAIN_LAUNCH, kernel) {
        // launch 直後の sync: カーネル実行 = 待ちの本体
        (true, Some(k)) if k > 0.0 => {
            CHAIN_ACC.with(|a| {
                let mut a = a.borrow_mut();
                a[kern_row] += k;
                // 待ちの合計を二重にしないため、帰属元の launch から引く
                a[launch_row] -= k;
                if secs > k {
                    a[wait_row] += secs - k;
                }
            });
        }
        // launch 以外からの sync は待ち行へ (残余は末尾で待ち行に寄せる)
        _ => {
            if secs > 0.0 {
                CHAIN_ACC.with(|a| a.borrow_mut()[wait_row] += secs);
            }
        }
    }
}

/// P17b 統合エントリ: int8 線形層を GPU で実行するかどうかを判定し、
/// 実行するなら結果 (CPU カーネルとビット一致) を返す。
/// 戻り値 None = CPU パスを使うこと (無効/初期化失敗/実行時エラー/m>閾値)。
pub fn maybe_gpu_linear(
    uid: u64,
    a: &[f32],
    qw: &[i8],
    scale: &[f32],
    k: usize,
    n: usize,
    m: usize,
) -> Option<Vec<f32>> {
    // s63: 確保 + 書き込みの薄いラッパ (decode など呼び出し側が再利用率の低い
    // 用途向け)。prefill のホットパスは `maybe_gpu_linear_into` を使う。
    let mut out = vec![0.0f32; m * n];
    if maybe_gpu_linear_into(uid, a, qw, scale, k, n, m, &mut out) {
        Some(out)
    } else {
        None
    }
}

/// s63: `maybe_gpu_linear` の書き込み先指定版。
/// true = GPU が計算して `out` を埋めた / false = 呼び出し側が CPU パスを使うこと。
/// 判定・重みキャッシュ・フォールバック (恒久ラッチ) の規約は `maybe_gpu_linear`
/// と完全に同一で、数値経路も同一 (D2H 後に `ho` から `out` へコピーするだけ)。
pub fn maybe_gpu_linear_into(
    uid: u64,
    a: &[f32],
    qw: &[i8],
    scale: &[f32],
    k: usize,
    n: usize,
    m: usize,
    out: &mut [f32],
) -> bool {
    debug_assert_eq!(out.len(), m * n);
    // s57 (T4): 実行先ラベルの初期値 — この呼び出しが false で抜けたとき
    // 直前の true が残らないよう毎回 false から始める (計測のみ)
    set_last_linear_ran_on_gpu(false);
    // s61: 入口到達の記録 (回帰テスト用・Relaxed 加算のみ)
    LINEAR_SEAM_CALLS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if !cuda_enabled() {
        return false;
    }
    let use_gemm = m > max_m() && m >= gemm_min_m() && gemm_enabled();
    // m が GEMV 経路の上限を超えて GEMM も発動しないなら CPU へ
    if m > max_m() && !use_gemm {
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if let Err(e) = ctx.make_current() {
        tracing::error!("CUDA cuCtxSetCurrent failed, using CPU int8: {e:#}");
        GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
        return false;
    }
    let gw = match weights_for(uid, qw, scale, k, n) {
        Ok(g) => g,
        Err(e) => {
            tracing::error!("CUDA weight upload failed, using CPU int8: {e:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            return false;
        }
    };
    // P17i: m が大きい (prefill) ときは tiled GEMM、小さい (decode/batch) ときは
    // GEMV 型カーネル (固定オーバーヘッドが小さい) を使い分ける。どちらも CPU と
    // ビット一致。
    let r = if use_gemm {
        linear_gemm_into(ctx, a, gw, m, k, n, out)
    } else {
        linear_pinned(ctx, a, gw, m, k, n).map(|v| out.copy_from_slice(&v))
    };
    match r {
        Ok(()) => {
            // s57 (T4): 実行先ラベルの記録 (計測のみ・戻り値/演算には無関係)
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            // 実行時エラーは再試行せず恒久的に CPU へ (数値は同一仕様なので不変)
            tracing::error!("CUDA linear failed, falling back to CPU permanently: {e:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            false
        }
    }
}

/// s123: Q4_0 ネイティブ重みの VRAM レジストリ (キー = `Q4Linear.uid`)。
///
/// SOA で 2 本のバッファに分けて置く: `nib` = 1 ブロック 16B (uint4) を
/// n*nb 個並べたもの、`sc` = 1 ブロック 1 本の f32 スケール。
/// 1 要素あたり 4.5 bit (int8 経路の半分以下) で済む。
struct GpuWq4 {
    nib: DevBuffer,
    sc: DevBuffer,
    k: usize,
    n: usize,
}

/// s165: 連結重み (`gate_up_w` = [gate 全行 | up 全行]) の行範囲を、元の独立した
/// 重み uid のデバイス表現として扱うためのエイリアス表。
///
/// 背景 (nsys・2026-10-22): 27B q4 の FFN は **decode chain が連結 1 本
/// (`gate_up_w`)**、**prefill の Q4 経路 (`chain_mlp_prefill_q4`) が gate_w / up_w
/// の 2 本**を使うため、同じ 2×ff×e パラメータが VRAM に 2 度載っていた
/// (1 層 111.4 MB × 64 層 = 7.1 GB、H2D も同じ 7.1 GB)。ここに行範囲
/// (uid → (連結 uid, 行オフセット)) を登録すると、`weights_for_q4` は個別の
/// 重みを転送せず連結側のデバイス領域を指すビューを返す。
///
/// 数値は不変: 連結側の nib / sc は行単位で連続しており (1 行 = nb ブロック)、
/// 行オフセット ff の位置は up_w の先頭行そのもの。カーネル・引数・グリッドは
/// 従来と同一で、重みの置き場所だけが変わる。
static Q4_ALIAS: OnceLock<std::sync::Mutex<std::collections::HashMap<u64, (u64, usize)>>> =
    OnceLock::new();

fn q4_alias_table() -> &'static std::sync::Mutex<std::collections::HashMap<u64, (u64, usize)>> {
    Q4_ALIAS.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// s178 (P59): 連結重みと分割重みの**同居**を避ける (重複排除) か。既定 ON。
///
/// `DENNO_Q4_DEDUP=0` で「エイリアスを使わない」= 各 uid を個別に転送する
/// 従来動作へ戻せる。数値は経路によらず同一 (同じ重み・同じカーネル・同じ
/// 累積順) で、変わるのは VRAM と H2D の量だけ。
fn q4_dedup_enabled() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| parse_q4_dedup(std::env::var("DENNO_Q4_DEDUP").ok().as_deref()))
}

/// s178 (P59): `DENNO_Q4_DEDUP` の解釈 (純関数・テスト可能)。
/// `parse_q4_chain` と同じ規約で **`"0"` だけが off** (未設定・空・その他は on)。
fn parse_q4_dedup(raw: Option<&str>) -> bool {
    raw != Some("0")
}

/// s165: `Linear` から Q4 本体を取り出す (連結エイリアスの前提検査用)。
fn q4_of(l: &crate::quant::Linear) -> Option<&crate::quant::Q4Linear> {
    match l {
        crate::quant::Linear::Q4(x) => Some(x),
        _ => None,
    }
}

/// s165: 連結重みの行範囲割り当て (純粋関数・GPU 不要)。
///
/// `concat_k` / `concat_n` は連結側の形状、`parts` は各行範囲の (k, n)。
/// 「すべての part の k が concat_k と一致し、n の和が concat_n」のときだけ
/// 各行の先頭行オフセットを返す (満たさなければ `None` = 呼び出し側は
/// エイリアスを登録せず従来の個別転送に落ちる = fail closed)。
pub fn q4_row_alias_offsets(
    concat_k: usize,
    concat_n: usize,
    parts: &[(usize, usize)],
) -> Option<Vec<usize>> {
    if parts.is_empty() || concat_k == 0 || concat_k % 32 != 0 || concat_n == 0 {
        return None;
    }
    let mut out = Vec::with_capacity(parts.len());
    let mut off = 0usize;
    for &(k, n) in parts {
        if k != concat_k || n == 0 {
            return None;
        }
        out.push(off);
        off = off.checked_add(n)?;
    }
    if off != concat_n {
        return None;
    }
    Some(out)
}

/// s165: `concat` (行連結済みの 1 本) の行範囲を `parts` の各 uid に割り当てる。
/// 呼び出し側は「parts の k がすべて concat.k と一致し、行数の和が concat.n」を
/// 満たすときだけ呼ぶ。**前提を満たさない・Q4 でない・転送に失敗した場合は
/// 何も登録せず false を返す** → 呼び出し側は従来どおり個別転送にフォールバック
/// する (fail closed)。登録済み (既に個別に VRAM へ載っている) uid は、in-flight
/// のカーネルが読みうるため置き換えない (その層は節約なし・数値は不変)。
pub fn q4_register_row_alias(concat: &crate::quant::Linear, parts: &[&crate::quant::Linear]) -> bool {
    let Some(c) = q4_of(concat) else { return false };
    if parts.is_empty() {
        return false;
    }
    let mut qs: Vec<&crate::quant::Q4Linear> = Vec::with_capacity(parts.len());
    for p in parts {
        let Some(p) = q4_of(p) else { return false };
        qs.push(p);
    }
    q4_register_row_alias_q4(c, &qs)
}

/// s166 (P5): [`q4_register_row_alias`] の Q4 版 (decode chain の qkv 連結用)。
fn q4_register_row_alias_q4(
    c: &crate::quant::Q4Linear,
    parts: &[&crate::quant::Q4Linear],
) -> bool {
    if parts.is_empty() || !q4_dedup_enabled() {
        return false;
    }
    // 形状契約: parts はすべて Q4・k は concat と一致・行数の和が concat.n。
    let mut geom = Vec::with_capacity(parts.len());
    let mut uids = Vec::with_capacity(parts.len());
    for p in parts {
        geom.push((p.k, p.n));
        uids.push(p.uid);
    }
    let Some(rows) = q4_row_alias_offsets(c.k, c.n, &geom) else {
        return false;
    };
    let offs: Vec<(u64, usize)> = uids.into_iter().zip(rows).collect();
    // s178 (P59): 既に「連結側が載っていて parts がその行範囲」なら何もしない。
    if q4_fused_ready(c.uid, parts) {
        return true;
    }
    // s178 (P59): parts が**自分の実体として**載っているなら連結側を上げない
    // (上げると同じパラメータが VRAM に 2 重に載る = P59 で削った分が戻る)。
    // エイリアスビューとして載っている場合は実体ではないので、上の
    // `q4_fused_ready` が先に true を返してここへは来ない。
    if parts.iter().any(|p| q4_resident(p.uid)) {
        return false;
    }
    // 連結側を先にレジストリへ載せる (エイリアスの参照先が存在する状態にする)。
    if weights_for_q4(c.uid, &c.blocks, c.k, c.n).is_err() {
        return false;
    }
    let table = q4_alias_table();
    let mut t = match table.lock() {
        Ok(t) => t,
        Err(_) => return false,
    };
    for (uid, row_off) in offs {
        if uid == c.uid {
            return false;
        }
        t.entry(uid).or_insert((c.uid, row_off));
    }
    true
}

/// s166 (P5): 連結重み `fused_uid` の行範囲が `parts` に割り当て済みか
/// (行オフセットが [0, n0, n0+n1, ...] と一致するか) を照会する。
fn q4_fused_ready(fused_uid: u64, parts: &[&crate::quant::Q4Linear]) -> bool {
    let t = match q4_alias_table().lock() {
        Ok(t) => t,
        Err(_) => return false,
    };
    let mut off = 0usize;
    for p in parts {
        match t.get(&p.uid) {
            Some(&(tgt, ro)) if tgt == fused_uid && ro == off => {}
            _ => return false,
        }
        off += p.n;
    }
    true
}

/// s178 (P59): 連結重み `[tn 行 × tk 列]` の行範囲 `[row_off, row_off+n)` を
/// `[n 行 × k 列]` のビューとして切り出すための**バイト幾何** (純粋関数・GPU 不要)。
///
/// 連結側の nib は 1 行 nb (= k/32) ブロック × 16 B、sc は 1 行 nb 本 × 4 B (f32)。
/// 行は連結側で連続しているので、行オフセットはそのままバイトオフセットになる。
///
/// 契約: `k` が 32 の倍数・`tk == k`・`row_off + n <= tn` (範囲が連結側に収まる)。
/// **`<=` が要点**: 先頭の part は `row_off = 0` なので `row_off + n != tn` に
/// なり、旧実装 (`!=`) では末尾の part しかビューにならず先頭の part が VRAM へ
/// 二重に載っていた (P59 の実測で 465 本 / 22,818.6 MB)。満たさない入力は `None`
/// = 呼び出し側は通常の転送へ落ちる (fail closed)。
fn q4_view_geo(
    k: usize,
    n: usize,
    row_off: usize,
    tk: usize,
    tn: usize,
) -> Option<(usize, usize, usize, usize)> {
    if k == 0 || k % 32 != 0 || n == 0 || tk != k {
        return None;
    }
    if row_off.checked_add(n)? > tn {
        return None;
    }
    let nb = k / 32;
    let nib_off = row_off.checked_mul(nb)?.checked_mul(16)?;
    let sc_off = row_off.checked_mul(nb)?.checked_mul(4)?;
    let nib_bytes = n.checked_mul(nb)?.checked_mul(16)?;
    let sc_bytes = n.checked_mul(nb)?.checked_mul(4)?;
    Some((nib_off, nib_bytes, sc_off, sc_bytes))
}

/// s165: `uid` にエイリアスが登録されていれば、連結側のデバイス領域を指す
/// ビューを `map` に登録して返す。形状・サイズが 1 つでも食い違えば `None`
/// (呼び出し側は通常の転送へ落ちる = fail closed)。
///
/// s178 (P59): 範囲判定を [`q4_view_geo`] に切り出し、先頭の part (row_off = 0)
/// もビューになるようにした。`DENNO_Q4_DEDUP=0` では常に `None`
/// (エイリアスを使わない = 各 uid を個別に転送する従来動作)。
fn q4_alias_view(
    uid: u64,
    k: usize,
    n: usize,
    map: &mut std::collections::HashMap<u64, Box<GpuWq4>>,
) -> Option<&'static GpuWq4> {
    if !q4_dedup_enabled() || map.contains_key(&uid) {
        return None;
    }
    let (tgt, row_off) = {
        let t = q4_alias_table().lock().ok()?;
        *t.get(&uid)?
    };
    // 参照先 (連結側) がまだ転送されていなければ何もしない。
    let (nib_ptr, sc_ptr, tn, tk) = {
        let e = map.get(&tgt)?;
        (e.nib.ptr(), e.sc.ptr(), e.n, e.k)
    };
    if nib_ptr == 0 || sc_ptr == 0 {
        return None;
    }
    let (nib_off, nib_bytes, sc_off, sc_bytes) = q4_view_geo(k, n, row_off, tk, tn)?;
    // 範囲が連結側バッファ内に収まることを確認 (収まらなければ fail closed)。
    {
        let e = map.get(&tgt)?;
        if nib_off + nib_bytes > e.nib.bytes() || sc_off + sc_bytes > e.sc.bytes() {
            return None;
        }
    }
    let v = GpuWq4 {
        nib: DevBuffer::view(nib_ptr + nib_off as u64, nib_bytes),
        sc: DevBuffer::view(sc_ptr + sc_off as u64, sc_bytes),
        k,
        n,
    };
    map.insert(uid, Box::new(v));
    let e = map.get(&uid).expect("just inserted");
    Some(unsafe { std::mem::transmute::<&GpuWq4, &'static GpuWq4>(e.as_ref()) })
}

/// s123: Q4_0 重みのデバイスレジストリ (uid → nib/sc)。s166 (P5) で関数内
/// static から出した (`q4_resident` が同じ表を照会するため)。
fn q4_registry() -> &'static std::sync::Mutex<std::collections::HashMap<u64, Box<GpuWq4>>> {
    static REG: OnceLock<std::sync::Mutex<std::collections::HashMap<u64, Box<GpuWq4>>>> =
        OnceLock::new();
    REG.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// s166 (P5): `uid` が既にデバイスへ載っているか (**照会のみ・転送しない**)。
/// 連結重みを上げる前に「parts が個別に載っていないか」を確かめるために使う
/// (載っているのに連結側も上げると VRAM が 2 重になる)。ロックが毒されていたら
/// `true` = 「載っている」とみなして連結側を上げない (安全側)。
fn q4_resident(uid: u64) -> bool {
    match q4_registry().lock() {
        Ok(m) => m.contains_key(&uid),
        Err(_) => true,
    }
}

/// s169 (P10): `parts` のどれかが既に VRAM へ載っているか (**照会のみ・転送しない**)。
/// ホスト prefill 経路の q|k|v 連結エイリアス登録で「載る前に登録する」順序を
/// 守るために使う (載っているなら登録しない = VRAM を 2 重にしない)。
pub fn q4_any_resident(parts: &[&crate::quant::Linear]) -> bool {
    parts.iter().filter_map(|p| q4_of(p)).any(|p| q4_resident(p.uid))
}

/// s123: [n,k] の Q4_0 ブロック (1 ブロック 18B) を VRAM へ上げる。
/// ホスト側で SOA (nib 16B アライン / sc f32) に変換してから転送する。
/// s165: 連結重みの行範囲エイリアス (登録済み) があれば転送せずビューを返す。
fn weights_for_q4(uid: u64, blocks: &[u8], k: usize, n: usize) -> Result<&'static GpuWq4> {
    let reg = q4_registry();
    let mut map = reg.lock().expect("q4 weights registry poisoned");
    // s165: 連結重みの行範囲エイリアスが登録済みなら転送しない (数値は不変)。
    if let Some(v) = q4_alias_view(uid, k, n, &mut map) {
        return Ok(v);
    }
    if !map.contains_key(&uid) {
        let nb = k / 32;
        assert_eq!(blocks.len(), n * nb * 18, "q4: block size mismatch");
        let mut nib = vec![0u8; n * nb * 16];
        let mut sc = vec![0f32; n * nb];
        for j in 0..n {
            for b in 0..nb {
                let src = &blocks[(j * nb + b) * 18..][..18];
                sc[j * nb + b] = half::f16::from_le_bytes([src[0], src[1]]).to_f32();
                nib[(j * nb + b) * 16..][..16].copy_from_slice(&src[2..18]);
            }
        }
        let nib_dev = DevBuffer::from_slice(&nib)?;
        let sc_dev = DevBuffer::from_slice(&sc)?;
        tracing::info!(
            "CUDA q4 weight upload (uid={uid}): k={k} n={n} ({:.1} MB)",
            (nib.len() + n * nb * 4) as f64 / 1e6
        );
        map.insert(uid, Box::new(GpuWq4 { nib: nib_dev, sc: sc_dev, k, n }));
        crate::gpu_budget::note_weight_upload();
    }
    let e = map.get(&uid).expect("just inserted");
    debug_assert_eq!((e.k, e.n), (k, n), "uid 重複: 同一 uid に異なる形状 (q4)");
    Ok(unsafe { std::mem::transmute::<&GpuWq4, &'static GpuWq4>(e.as_ref()) })
}

/// P-MOE-E5: GGUF の生ブロック (Q8_0 / Q5_1 / Q4_K / Q5_K) を VRAM に常駐させる
/// レジストリ (uid → デバイスバッファ)。重みは 1 度だけ転送し、以後は GEMV だけ。
/// 27B の q4 レジストリと同じ形 (uid は `quant::next_q8_uid` で払い出す)。
struct GpuGgufW {
    buf: DevBuffer,
    ty: crate::kquant::GgmlType,
    k: usize,
    n: usize,
}

/// P46: 診断 (`DENNO_GPU_W_DBG=1`)。登録 1 本ごとに 1 行、既定は完全に無効。
fn w_dbg() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| matches!(std::env::var("DENNO_GPU_W_DBG").as_deref(), Ok("1")))
}

/// P46: GGUF 重みレジストリ (uid → デバイスバッファ + バイト上限つき LRU)。
///
/// 既定 (`DENNO_GPU_WEIGHT_MB` 未設定 = 0) は退避しない = 従来と同じ挙動。
/// 0 以外のときだけ、登録のたびに「上限」と「空き VRAM」を見て古い uid を
/// **確保の前に**解放する (`cuMemAlloc` の失敗を通常経路にしない)。
struct GgufReg {
    map: std::collections::HashMap<u64, Box<GpuGgufW>>,
    lru: crate::gpu_budget::WeightLru,
}

fn gguf_registry() -> &'static std::sync::Mutex<GgufReg> {
    static REG: OnceLock<std::sync::Mutex<GgufReg>> = OnceLock::new();
    REG.get_or_init(|| {
        std::sync::Mutex::new(GgufReg {
            map: std::collections::HashMap::new(),
            lru: crate::gpu_budget::WeightLru::new(crate::gpu_budget::weight_cap_bytes()),
        })
    })
}

/// uid の重みをレジストリから外し、VRAM を返す。戻り値は解放したバイト数。
///
/// モデルを捨てて組み直す経路 (serve-flash の prefix 不一致) で呼ぶ。これが無いと
/// 古いモデルの重みが VRAM に残り、リクエストを重ねるたびに使用量が増えて
/// 最後は dense の確保に失敗して CPU に落ちる。
///
/// 使用中 (pin) の uid でも外す: 呼ぶ側は「その重みをもう使わない」と分かっている
/// 前提 (`GgufLinear` の `Drop`)。進行中の GEMV がある状態で呼んではいけない。
pub fn gguf_unregister(uid: u64) -> u64 {
    let reg = gguf_registry();
    let Ok(mut g) = reg.lock() else {
        return 0;
    };
    let Some(w) = g.map.remove(&uid) else {
        return 0;
    };
    let bytes = g.lru.note_remove(uid);
    let (k, n, ty) = (w.k, w.n, w.ty);
    drop(w); // DevBuffer の Drop が VRAM を返す
    if w_dbg() {
        eprintln!("[gpu-w] unregister uid={uid} ty={ty:?} k={k} n={n} bytes={bytes}");
    }
    bytes
}

/// 使用中の重み 1 本。Drop で「使用中」を落とす (= 以後は退避対象になる)。
///
/// 中の参照は `'static` だが、このガードが生きている間は LRU がその uid を
/// 退避対象から外すので、指し先が解放されることはない。
struct GgufWRef {
    w: &'static GpuGgufW,
    uid: u64,
}

impl std::ops::Deref for GgufWRef {
    type Target = GpuGgufW;
    fn deref(&self) -> &GpuGgufW {
        self.w
    }
}

impl Drop for GgufWRef {
    fn drop(&mut self) {
        if let Ok(mut g) = gguf_registry().lock() {
            g.lru.unpin(self.uid);
        }
    }
}

/// GGUF ブロック 1 行のバイト数。expert GEMV が扱う 4 型だけ `Some`。
fn gguf_row_bytes(ty: crate::kquant::GgmlType, k: usize) -> Option<usize> {
    use crate::kquant::GgmlType as T;
    if k == 0 || k % ty.blck_size() != 0 {
        return None;
    }
    Some(match ty {
        T::Q8_0 => (k / 32) * 34,
        T::Q5_1 => (k / 32) * 24,
        T::Q4K => (k / 256) * 144,
        T::Q5K => (k / 256) * 176,
        _ => return None,
    })
}

/// 重みを (初回だけ) VRAM へ上げて常駐エントリを返す。`uid` は呼び出し側が
/// 安定して持つこと (同じ uid に別の形状・型を渡したらエラー)。
///
/// P46: `DENNO_GPU_WEIGHT_MB` が 0 以外なら、確保の前にバイト上限と空き VRAM を
/// 見て最終使用が最も古い uid を解放する (使用中の uid は飛ばす)。解放された
/// 重みは次に使うとき、呼び出し側が渡すホストの生ブロックから**同じバイト列で**
/// 上げ直される (転送はコピーなので GEMV の入力は 1 bit も変わらない)。
fn weights_for_gguf(
    uid: u64,
    ty: crate::kquant::GgmlType,
    blocks: &[u8],
    k: usize,
    n: usize,
) -> Result<GgufWRef> {
    let reg = gguf_registry();
    let mut g = reg
        .lock()
        .map_err(|_| anyhow::anyhow!("gguf weights registry poisoned"))?;
    // 既に載っている: 形状/型の一致だけ見て「使った」に更新し、使用中にする。
    if g.map.contains_key(&uid) {
        let e = g.map.get(&uid).expect("contains_key");
        let (ek, en, ety) = (e.k, e.n, e.ty);
        if (ek, en, ety) != (k, n, ty) {
            bail!(
                "uid 重複: 同一 uid {uid} に別の形状/型 (登録済み k={ek} n={en} ty={ety:?} / 今回 k={k} n={n} ty={ty:?})"
            );
        }
        g.lru.touch(uid);
        g.lru.pin(uid);
        let e = g.map.get(&uid).expect("pinned");
        let w = unsafe { std::mem::transmute::<&GpuGgufW, &'static GpuGgufW>(e.as_ref()) };
        return Ok(GgufWRef { w, uid });
    }
    let rb = gguf_row_bytes(ty, k)
        .ok_or_else(|| anyhow::anyhow!("gguf: 未対応の型 {ty:?} (k={k})"))?;
    let want = n
        .checked_mul(rb)
        .ok_or_else(|| anyhow::anyhow!("gguf: n * row_bytes が usize を溢れる"))?;
    if blocks.len() != want {
        bail!(
            "gguf: バイト数 {} が n * row_bytes = {} と違う (ty={ty:?}, k={k}, n={n})",
            blocks.len(),
            want
        );
    }
    // P46: 確保の前に退避する。上限 0 (既定) のときは記帳だけで 1 本も
    // 返らない = 従来と同じ経路 (空き VRAM の照会もしない)。
    let cap = crate::gpu_budget::weight_cap_bytes();
    let free_mb = if cap == 0 {
        None
    } else {
        dev_mem_mb().map(|(f, _total)| f as u64)
    };
    let ev0 = (g.lru.evicted_tensors(), g.lru.evicted_bytes());
    let victims =
        crate::gpu_budget::plan_weight_evictions(&mut g.lru, uid, want as u64, cap, free_mb);
    let mut dropped: Vec<u64> = Vec::new();
    for v in &victims {
        if g.map.remove(v).is_some() {
            dropped.push(*v);
        }
    }
    let freed = g.lru.evicted_bytes().saturating_sub(ev0.1);
    let freed_n = g.lru.evicted_tensors().saturating_sub(ev0.0);
    if freed_n > 0 {
        crate::gpu_budget::note_weight_evicted(freed_n, freed);
    }
    let buf = match DevBuffer::from_slice_tagged(blocks, crate::mem_audit::TAG_WEIGHTS) {
        Ok(b) => b,
        Err(e) => {
            // 記帳だけ進んで実体が無い状態を残さない。
            g.lru.note_remove(uid);
            return Err(e);
        }
    };
    tracing::info!(
        "CUDA gguf weight upload (uid={uid}): ty={ty:?} k={k} n={n} ({:.1} MB)",
        want as f64 / 1e6
    );
    g.map.insert(uid, Box::new(GpuGgufW { buf, ty, k, n }));
    g.lru.pin(uid);
    let resident = g.map.len();
    let used = g.lru.used_bytes();
    let evicted_tensors = g.lru.evicted_tensors();
    let evicted_bytes = g.lru.evicted_bytes();
    let w = {
        let e = g.map.get(&uid).expect("just inserted");
        unsafe { std::mem::transmute::<&GpuGgufW, &'static GpuGgufW>(e.as_ref()) }
    };
    drop(g);
    crate::gpu_budget::note_weight_upload();
    crate::gpu_budget::note_weight_upload_bytes(want as u64);
    crate::gpu_budget::note_weight_resident(resident, used);
    if w_dbg() {
        let free = match dev_mem_mb() {
            Some((f, t)) => format!("空き {f} MiB / 全 {t} MiB"),
            None => "空き 不明".to_string(),
        };
        let cap_s = if cap == 0 {
            "無制限".to_string()
        } else {
            format!("{} MiB", cap >> 20)
        };
        let ev = if dropped.is_empty() {
            String::new()
        } else {
            let list: Vec<String> = dropped.iter().take(8).map(|u| u.to_string()).collect();
            format!(" / 今回退避 {} 本 [{}] {:.1} MiB", dropped.len(), list.join(","), freed as f64 / (1 << 20) as f64)
        };
        tracing::info!(
            target: "denno_engine::gpu_w",
            "[gpu-w] uid={uid} ty={ty:?} k={k} n={n} {:.2} MB / 常駐 {} 本 {:.1} MiB / 上限 {cap_s} / 退避 計 {} 本 {:.1} MiB{ev} / {free}",
            want as f64 / 1e6,
            resident,
            used as f64 / (1 << 20) as f64,
            evicted_tensors,
            evicted_bytes as f64 / (1 << 20) as f64,
        );
    }
    Ok(GgufWRef { w, uid })
}

/// テスト用: `maybe_gpu_gguf_gemv_into` を「GPU が取った」ことにするフラグ。
///
/// 実デバイスには一切触らない (即 `true` を返すだけ)。P86 のように
/// 「GPU GEMV が呼び出しを奪ったとき CPU 経路が死ぬ」ことを、GPU の無い
