#[cfg(test)]
static GEMV_INTERCEPT_FOR_TEST: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// [`GEMV_INTERCEPT_FOR_TEST`] の間、`maybe_gpu_gguf_gemv_into` は
/// 「GPU が計算した」ことにして CPU へ落とさない。Drop で必ず戻す。
#[cfg(test)]
pub struct GemvInterceptGuard;

#[cfg(test)]
impl GemvInterceptGuard {
    /// フラグを立てる (Drop まで有効)。
    pub fn new() -> Self {
        GEMV_INTERCEPT_FOR_TEST.store(true, std::sync::atomic::Ordering::Relaxed);
        Self
    }
}

#[cfg(test)]
impl Drop for GemvInterceptGuard {
    fn drop(&mut self) {
        GEMV_INTERCEPT_FOR_TEST.store(false, std::sync::atomic::Ordering::Relaxed);
    }
}

// ---------------------------------------------------------------------------
// task 124: shared expert の gate/up を router/expert の CPU 仕事と重ねる
// ---------------------------------------------------------------------------
//
// decode の shared expert は 1 層あたり 4 本の**同期** GEMV (gate / up / down /
// gate_inp) を回し、その間 rayon のワーカーは遊んでいる (実測 6.5 ms/tok)。
// このうち gate と up の入力は層の入口の `x` だけで決まるので、router と
// 選択 expert の CPU 仕事を始める**前に**専用ストリームへ積んでおき、
// shared expert の節で 1 回だけ join する。
//
// 規約:
// - カーネル・引数・行の内積順は [`CudaCtx::moe_gemv_dev`] と同一
//   ([`CudaCtx::plan_moe_gemv`] を共有する) ので、値は今の GPU 経路と
//   1 ビットも変わらない (md5 が動いたらバグ)。
// - 積む前に「型・形・重みが VRAM にあること・カーネルが選べること」を全部
//   確かめる (all-or-nothing)。1 本でも駄目なら 1 つも積まずに空のハンドルを
//   返し、呼び出し側は従来の同期経路へ落ちる (fail closed)。
// - 入出力は専用の grow-only バッファ (thread_local)。`MOE_SCRATCH` とは
//   共有しない — 積んだまま expert の GEMV が同じスクラッチを書き換えるため。
// - 重みは in-flight の間 `GgufWRef` で pin する (LRU の退避で解放されない)。
// - join し忘れたまま捨てられたら (エラー経路) Drop が drain する。drain に
//   失敗したら以後この経路は試さない (`broken`)。バッファはモジュール所有で、
//   呼び出し側の `Vec` を指したままにはしない (解放済み領域を触らない)。
// ---------------------------------------------------------------------------

/// 重ね打ち 1 本ぶんの依頼 (重みは `GgufLinear` の生ブロックをそのまま渡す)。
pub struct SharedGemvJob<'a> {
    pub uid: u64,
    pub ty: crate::kquant::GgmlType,
    pub blocks: &'a [u8],
    pub k: usize,
    pub n: usize,
}

/// 同時に積める本数の上限 (shared expert は 2 本。余裕を見て 4)。
const SHARED_OVERLAP_MAX_JOBS: usize = 4;

static OVERLAP_BEGIN: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
static OVERLAP_TAKEN: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
static OVERLAP_JOINED: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
static OVERLAP_FAILED: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
static OVERLAP_ABORTED: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// 重ね打ち経路の計数 (プロセス通算)。テストと `DENNO_SHARED_OVERLAP` の
/// 発火確認に使う。緑 = 経路が発動した証拠ではない、の裏取り。
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct SharedOverlapStats {
    /// `shared_gemv_begin` が呼ばれた回数
    pub begin: usize,
    /// 実際に GPU へ積めた回数 (fake 経路も含む)
    pub taken: usize,
    /// join できた回数
    pub joined: usize,
    /// join に失敗した回数 (呼び出し側は CPU へ落ちる)
    pub failed: usize,
    /// join せずに捨てられた回数 (Drop が drain した)
    pub aborted: usize,
}

/// 計数を読む。
pub fn shared_overlap_stats() -> SharedOverlapStats {
    use std::sync::atomic::Ordering::Relaxed;
    SharedOverlapStats {
        begin: OVERLAP_BEGIN.load(Relaxed),
        taken: OVERLAP_TAKEN.load(Relaxed),
        joined: OVERLAP_JOINED.load(Relaxed),
        failed: OVERLAP_FAILED.load(Relaxed),
        aborted: OVERLAP_ABORTED.load(Relaxed),
    }
}

/// 計数を 0 に戻す (テスト用)。
pub fn reset_shared_overlap_stats() {
    use std::sync::atomic::Ordering::Relaxed;
    OVERLAP_BEGIN.store(0, Relaxed);
    OVERLAP_TAKEN.store(0, Relaxed);
    OVERLAP_JOINED.store(0, Relaxed);
    OVERLAP_FAILED.store(0, Relaxed);
    OVERLAP_ABORTED.store(0, Relaxed);
}

struct SharedSlotBuf {
    dout: Option<DevBuffer>,
    pin_o: Option<PinMem>,
    n: usize,
    /// テスト用の偽 GPU の結果 (本物の GPU が無い環境で join 経路を試す)。
    #[cfg(test)]
    fake: Vec<f32>,
}

impl SharedSlotBuf {
    fn new() -> Self {
        Self {
            dout: None,
            pin_o: None,
            n: 0,
            #[cfg(test)]
            fake: Vec::new(),
        }
    }
}

/// 重ね打ち用の thread_local 状態。decode は 1 スレッドなので競合しない。
struct SharedOverlapState {
    stream: Option<CopyStream>,
    /// 重みの H2D (null ストリーム) と専用ストリームの順序を取るため
    ev_ready: Option<CopyEvent>,
    /// 積んだ 1 群の完了
    ev_done: Option<CopyEvent>,
    dx: Option<DevBuffer>,
    pin_x: Option<PinMem>,
    slots: Vec<SharedSlotBuf>,
    /// in-flight の間だけ重みを pin する
    pins: Vec<GgufWRef>,
    in_flight: usize,
    /// 失敗して以後この経路を試さない (壊れた状態でバッファを再利用しない)
    broken: bool,
    #[cfg(test)]
    fake: bool,
}

impl SharedOverlapState {
    fn new() -> Self {
        Self {
            stream: None,
            ev_ready: None,
            ev_done: None,
            dx: None,
            pin_x: None,
            slots: Vec::new(),
            pins: Vec::new(),
            in_flight: 0,
            broken: false,
            #[cfg(test)]
            fake: false,
        }
    }
}

thread_local! {
    static SHARED_OVERLAP: std::cell::RefCell<SharedOverlapState> =
        std::cell::RefCell::new(SharedOverlapState::new());
}

#[cfg(test)]
static SHARED_OVERLAP_FAKE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// テスト用: 本物の GPU を使わずに「積めた」ことにする (`Drop` で戻す)。
///
/// このコンテナには GPU が無いので、join 経路 (バッファの写し先・順序) を
/// 検証するにはこれが要る。値は CPU の `expert_gemv` で作るので、ゲート off の
/// 経路と**ビット一致**するはず (同じ関数・同じ順)。
#[cfg(test)]
pub struct SharedOverlapFakeGuard;

#[cfg(test)]
impl SharedOverlapFakeGuard {
    pub fn new() -> Self {
        SHARED_OVERLAP_FAKE.store(true, std::sync::atomic::Ordering::Relaxed);
        Self
    }
}

#[cfg(test)]
impl Drop for SharedOverlapFakeGuard {
    fn drop(&mut self) {
        SHARED_OVERLAP_FAKE.store(false, std::sync::atomic::Ordering::Relaxed);
    }
}

#[cfg(test)]
static SHARED_OVERLAP_FAIL_FINISH: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// テスト用: `shared_gemv_finish` を必ず失敗させる (`Drop` で戻す)。
///
/// join に失敗したときに呼び出し側が従来の同期経路へ落ちること (値が変わらない
/// こと・abort が二重に走らないこと) を GPU 無しで確かめるためのもの。
#[cfg(test)]
pub struct SharedOverlapFailGuard;

#[cfg(test)]
impl SharedOverlapFailGuard {
    pub fn new() -> Self {
        SHARED_OVERLAP_FAIL_FINISH.store(true, std::sync::atomic::Ordering::Relaxed);
        Self
    }
}

#[cfg(test)]
impl Drop for SharedOverlapFailGuard {
    fn drop(&mut self) {
        SHARED_OVERLAP_FAIL_FINISH.store(false, std::sync::atomic::Ordering::Relaxed);
    }
}

/// in-flight の操作を drain する (join し忘れ・join 失敗の後始末)。
///
/// 戻り値 `false` は「完了を確認できなかった」。呼び出し側は `broken` を立てる。
fn shared_overlap_drain(s: &mut SharedOverlapState) -> bool {
    #[cfg(test)]
    if s.fake {
        s.in_flight = 0;
        s.fake = false;
        s.pins.clear();
        return true;
    }
    let pending = s.in_flight != 0 || !s.pins.is_empty();
    s.in_flight = 0;
    s.pins.clear();
    if !pending {
        return true;
    }
    let Some(l) = lib().ok() else {
        return false;
    };
    let Some(event_sync) = l.event_sync else {
        return false;
    };
    let ctx_sync = l.ctx_sync;
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if ctx.make_current().is_err() {
        return false;
    }
    let ev = s.ev_done.as_ref().map(|e| e.0);
    let mut ok = match ev {
        Some(ev) => (unsafe { event_sync(ev) }) == CUDA_SUCCESS,
        None => true,
    };
    if !ok {
        // ストリームの完了が取れない: デバイス全体で drain する (取りこぼし防止)。
        ok = unsafe { ctx_sync() } == CUDA_SUCCESS;
    }
    ok
}

/// 積んだ本数を持つハンドル。`shared_gemv_finish` を呼ばずに捨てると、
/// Drop が GPU を drain する (エラー経路で in-flight の操作を残さない)。
pub struct SharedPending {
    n: usize,
    /// 別スレッドへ移せない (Drop が同じスレッドの thread_local を drain するため)。
    _not_send: std::marker::PhantomData<*const ()>,
}

impl SharedPending {
    /// 何も積んでいないハンドル (ゲート off / GPU 不発 / 失敗)。
    pub fn none() -> Self {
        Self {
            n: 0,
            _not_send: std::marker::PhantomData,
        }
    }
    /// 積んだ本数 (0 = 重ね打ちしていない)。
    pub fn len(&self) -> usize {
        self.n
    }
    pub fn is_empty(&self) -> bool {
        self.n == 0
    }
}

impl Drop for SharedPending {
    fn drop(&mut self) {
        if self.n == 0 {
            return;
        }
        self.n = 0;
        OVERLAP_ABORTED.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let _ = SHARED_OVERLAP.try_with(|cell| {
            let mut s = cell.borrow_mut();
            if !shared_overlap_drain(&mut s) {
                s.broken = true;
            }
        });
    }
}

/// 依頼の検査と発行 (GPU 操作の前に全部そろえる = all-or-nothing)。
#[allow(clippy::too_many_arguments)]
fn shared_overlap_enqueue(
    s: &mut SharedOverlapState,
    ctx: &CudaCtx,
    l: &CudaLib,
    x: &[f32],
    jobs: &[SharedGemvJob<'_>],
    plans: &[MoeGemvPlan],
    pins: &[GgufWRef],
    uploaded: bool,
) -> Result<()> {
    if s.broken || s.in_flight != 0 {
        bail!(
            "重ね打ちは使わない (broken={}, in_flight={})",
            s.broken,
            s.in_flight
        );
    }
    // 1) 専用の非ブロッキングストリーム + イベント (初回だけ)。
    //    blocking で作ると legacy (null) ストリームと暗黙に同期し、expert の
    //    GPU GEMV や mix のカーネルと 1 バイトも重ならない。
    if s.stream.is_none() {
        const CU_STREAM_NON_BLOCKING: u32 = 0x01;
        const CU_EVENT_DISABLE_TIMING: u32 = 0x02;
        let (Some(stream_create), Some(event_create)) = (l.stream_create, l.event_create) else {
            bail!("cuStreamCreate / cuEventCreate が無い");
        };
        let mut st: CUstream = std::ptr::null_mut();
        if unsafe { stream_create(&mut st, CU_STREAM_NON_BLOCKING) } != CUDA_SUCCESS {
            bail!("cuStreamCreate が失敗");
        }
        let mut ev_ready: CUevent = std::ptr::null_mut();
        if unsafe { event_create(&mut ev_ready, CU_EVENT_DISABLE_TIMING) } != CUDA_SUCCESS {
            unsafe {
                if let Some(f) = l.stream_destroy {
                    let _ = f(st);
                }
            }
            bail!("cuEventCreate (ready) が失敗");
        }
        let mut ev_done: CUevent = std::ptr::null_mut();
        if unsafe { event_create(&mut ev_done, CU_EVENT_DISABLE_TIMING) } != CUDA_SUCCESS {
            unsafe {
                if let Some(f) = l.stream_destroy {
                    let _ = f(st);
                }
                if let Some(f) = l.event_destroy {
                    let _ = f(ev_ready);
                }
            }
            bail!("cuEventCreate (done) が失敗");
        }
        s.stream = Some(CopyStream(st));
        s.ev_ready = Some(CopyEvent(ev_ready));
        s.ev_done = Some(CopyEvent(ev_done));
    }
    // 2) grow-only の入出力 (MOE_SCRATCH とは別)。
    let bytes_x = x.len() * 4;
    Scratch::ensure(&mut s.dx, bytes_x)?;
    Scratch::ensure_pin(&mut s.pin_x, bytes_x)?;
    while s.slots.len() < jobs.len() {
        s.slots.push(SharedSlotBuf::new());
    }
    for (i, j) in jobs.iter().enumerate() {
        Scratch::ensure(&mut s.slots[i].dout, j.n * 4)?;
        Scratch::ensure_pin(&mut s.slots[i].pin_o, j.n * 4)?;
        s.slots[i].n = j.n;
    }

    let stream = s.stream.as_ref().expect("作成済み").0;
    let ev_ready = s.ev_ready.as_ref().expect("作成済み").0;
    let ev_done = s.ev_done.as_ref().expect("作成済み").0;
    // 入力は pinned へ写してから積む (呼び出し側の Vec を in-flight 中に指さない)。
    {
        let px = s.pin_x.as_mut().expect("ensure 済み");
        px.as_mut_slice::<f32>()[..x.len()].copy_from_slice(x);
    }
    let px_ptr = s.pin_x.as_ref().expect("ensure 済み").ptr;
    let dx = s.dx.as_ref().expect("ensure 済み").ptr();
    let (Some(event_record), Some(stream_wait_event)) = (l.event_record, l.stream_wait_event) else {
        bail!("cuEventRecord / cuStreamWaitEvent が無い");
    };
    // 3) 重みの H2D が起きた層だけ null ストリームとの順序を取る。
    if uploaded {
        if unsafe { event_record(ev_ready, std::ptr::null_mut()) } != CUDA_SUCCESS {
            bail!("cuEventRecord (ready) が失敗");
        }
        if unsafe { stream_wait_event(stream, ev_ready, 0) } != CUDA_SUCCESS {
            bail!("cuStreamWaitEvent が失敗");
        }
    }
    // 4) x の H2D → 各 GEMV の起動 → 各 D2H を 1 本のストリームに積む。
    if unsafe { (l.memcpy_htod_async)(dx, px_ptr as *const c_void, bytes_x, stream) } != CUDA_SUCCESS
    {
        bail!("cuMemcpyHtoDAsync (shared x) が失敗");
    }
    for (i, plan) in plans.iter().enumerate() {
        let dout = s.slots[i].dout.as_ref().expect("ensure 済み").ptr();
        let po = s.slots[i].pin_o.as_ref().expect("ensure 済み").ptr;
        ctx.launch_moe_gemv_on(plan, pins[i].buf.ptr, dx, dout, jobs[i].k, jobs[i].n, stream)?;
        if unsafe { (l.memcpy_dtoh_async)(po, dout, jobs[i].n * 4, stream) } != CUDA_SUCCESS {
            bail!("cuMemcpyDtoHAsync (shared {i}) が失敗");
        }
    }
    // 5) 完了イベント (join はこれだけを待つ)。
    if unsafe { event_record(ev_done, stream) } != CUDA_SUCCESS {
        bail!("cuEventRecord (done) が失敗");
    }
    Ok(())
}

/// shared expert の GPU GEMV を先に積む。
///
/// 空のハンドルが返ったら呼び出し側は従来の同期経路で計算すること。
pub fn shared_gemv_begin(x: &[f32], jobs: &[SharedGemvJob<'_>]) -> SharedPending {
    OVERLAP_BEGIN.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if jobs.is_empty() || jobs.len() > SHARED_OVERLAP_MAX_JOBS {
        return SharedPending::none();
    }
    #[cfg(test)]
    if SHARED_OVERLAP_FAKE.load(std::sync::atomic::Ordering::Relaxed) {
        return shared_gemv_begin_fake(x, jobs);
    }
    if !cuda_enabled() {
        return SharedPending::none();
    }
    let Some(ctx) = shared_ctx() else {
        return SharedPending::none();
    };
    if ctx.make_current().is_err() {
        return SharedPending::none();
    }
    let Ok(l) = lib() else {
        return SharedPending::none();
    };
    if l.stream_create.is_none()
        || l.stream_wait_event.is_none()
        || l.event_create.is_none()
        || l.event_record.is_none()
        || l.event_sync.is_none()
    {
        return SharedPending::none();
    }
    let mode = gemv_kernel_mode();
    // 計画と重み (GPU へはまだ 1 つも積まない)。
    let mut plans = Vec::with_capacity(jobs.len());
    let mut pins = Vec::with_capacity(jobs.len());
    let mut uploaded = false;
    for j in jobs {
        if j.k == 0 || j.n == 0 || j.k != x.len() || j.k % j.ty.blck_size() != 0 {
            return SharedPending::none();
        }
        let plan = match ctx.plan_moe_gemv(j.ty, j.k, j.n, mode) {
            Ok(Some(p)) => p,
            _ => return SharedPending::none(),
        };
        let existed = gguf_registry()
            .lock()
            .map(|g| g.map.contains_key(&j.uid))
            .unwrap_or(false);
        let w = match weights_for_gguf(j.uid, j.ty, j.blocks, j.k, j.n) {
            Ok(w) => w,
            Err(_) => return SharedPending::none(),
        };
        if w.buf.bytes() != j.n.saturating_mul(plan.rb) {
            return SharedPending::none();
        }
        uploaded |= !existed;
        plans.push(plan);
        pins.push(w);
    }
    SHARED_OVERLAP.with(|cell| {
        let mut s = cell.borrow_mut();
        match shared_overlap_enqueue(&mut s, ctx, l, x, jobs, &plans, &pins, uploaded) {
            Ok(()) => {
                s.pins = pins;
                s.in_flight = jobs.len();
                OVERLAP_TAKEN.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                SharedPending {
                    n: jobs.len(),
                    _not_send: std::marker::PhantomData,
                }
            }
            Err(_) => {
                let _ = shared_overlap_drain(&mut s);
                s.broken = true;
                SharedPending::none()
            }
        }
    })
}

/// 積んだ GEMV を join して `outs[i]` へ写す。
///
/// 戻り値 `false` = 「GPU の結果が取れなかった」。呼び出し側は従来の同期経路で
/// 計算し直すこと (このとき `outs` は 1 要素も書かれていない)。
pub fn shared_gemv_finish(p: &mut SharedPending, outs: &mut [&mut [f32]]) -> bool {
    let n = std::mem::replace(&mut p.n, 0);
    if n == 0 {
        return false;
    }
    // テスト用: join を必ず失敗させる (呼び出し側の切り戻し経路を試す)。
    #[cfg(test)]
    if SHARED_OVERLAP_FAIL_FINISH.load(std::sync::atomic::Ordering::Relaxed) {
        let _ = SHARED_OVERLAP.try_with(|cell| {
            let mut s = cell.borrow_mut();
            let _ = shared_overlap_drain(&mut s);
        });
        OVERLAP_FAILED.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        return false;
    }
    SHARED_OVERLAP.with(|cell| -> bool {
        let mut s = cell.borrow_mut();
        if s.in_flight != n || outs.len() != n {
            let _ = shared_overlap_drain(&mut s);
            s.broken = true;
            return false;
        }
        // テスト用の偽 GPU: 計算済みの値を書き戻すだけ (GPU には触らない)。
        #[cfg(test)]
        if s.fake {
            for (i, out) in outs.iter_mut().enumerate().take(n) {
                let v = std::mem::take(&mut s.slots[i].fake);
                let len = v.len().min(out.len());
                out[..len].copy_from_slice(&v[..len]);
            }
            s.in_flight = 0;
            s.fake = false;
            OVERLAP_JOINED.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            return true;
        }
        for (i, out) in outs.iter().enumerate().take(n) {
            if out.len() < s.slots[i].n {
                let _ = shared_overlap_drain(&mut s);
                s.broken = true;
                return false;
            }
        }
        let Some(ctx) = shared_ctx() else {
            let _ = shared_overlap_drain(&mut s);
            s.broken = true;
            return false;
        };
        if ctx.make_current().is_err() {
            let _ = shared_overlap_drain(&mut s);
            s.broken = true;
            return false;
        }
        let Some(event_sync) = lib().ok().and_then(|l| l.event_sync) else {
            let _ = shared_overlap_drain(&mut s);
            s.broken = true;
            return false;
        };
        let Some(ev) = s.ev_done.as_ref().map(|e| e.0) else {
            let _ = shared_overlap_drain(&mut s);
            s.broken = true;
            return false;
        };
        if unsafe { event_sync(ev) } != CUDA_SUCCESS {
            let _ = shared_overlap_drain(&mut s);
            s.broken = true;
            OVERLAP_FAILED.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            return false;
        }
        for (i, out) in outs.iter_mut().enumerate().take(n) {
            let len = s.slots[i].n;
            let pin = s.slots[i].pin_o.as_ref().expect("ensure 済み");
            out[..len].copy_from_slice(&pin.as_slice::<f32>()[..len]);
        }
        s.in_flight = 0;
        s.pins.clear();
        OVERLAP_JOINED.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        true
    })
}

/// テスト用の偽 GPU 経路 (GPU を 1 つも触らない)。
#[cfg(test)]
fn shared_gemv_begin_fake(x: &[f32], jobs: &[SharedGemvJob<'_>]) -> SharedPending {
    let mut vals = Vec::with_capacity(jobs.len());
    for j in jobs {
        let mut v = vec![0f32; j.n];
        if crate::model::moe_expert::expert_gemv(j.ty, j.blocks, j.k, j.n, x, &mut v).is_err() {
            return SharedPending::none();
        }
        vals.push(v);
    }
    SHARED_OVERLAP.with(|cell| {
        let mut s = cell.borrow_mut();
        while s.slots.len() < vals.len() {
            s.slots.push(SharedSlotBuf::new());
        }
        for (i, v) in vals.into_iter().enumerate() {
            s.slots[i].n = v.len();
            s.slots[i].fake = v;
        }
        s.fake = true;
        s.in_flight = jobs.len();
        OVERLAP_TAKEN.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        SharedPending {
            n: jobs.len(),
            _not_send: std::marker::PhantomData,
        }
    })
}

/// P-MOE-E5: GGUF ブロックのままの線形層 (m=1) を GPU で計算する。
///
/// 対象外の型・GPU 無効・CUDA 不調・登録失敗では `false` を返す。呼び出し側は
/// CPU 参照へ落ちること (fail closed。別経路の数値を黙って返さない)。
pub fn maybe_gpu_gguf_gemv_into(
    uid: u64,
    ty: crate::kquant::GgmlType,
    blocks: &[u8],
    k: usize,
    n: usize,
    x: &[f32],
    out: &mut [f32],
) -> bool {
    set_last_linear_ran_on_gpu(false);
    #[cfg(test)]
    if GEMV_INTERCEPT_FOR_TEST.load(std::sync::atomic::Ordering::Relaxed) {
        // テスト用: GPU が呼び出しを取った体で抜ける (out は書かない)。
        return true;
    }
    if !cuda_enabled() || gguf_row_bytes(ty, k).is_none() {
        return false;
    }
    if x.len() != k || out.len() != n {
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if let Err(e) = ctx.make_current() {
        tracing::error!("CUDA cuCtxSetCurrent failed, using CPU gguf: {e:#}");
        GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
        return false;
    }
    // devprof: 重みのアップロードは「この呼び出しで増えたバイト数」だけ数える
    // (常駐ヒットなら 0)。集計は gpu_budget が持っている。
    let prof = crate::model::devprof::on();
    let up_before = if prof {
        crate::gpu_budget::weight_upload_bytes()
    } else {
        0
    };
    let w = match weights_for_gguf(uid, ty, blocks, k, n) {
        Ok(w) => w,
        Err(e) => {
            // P-pf-arena: 同じ失敗を 1 呼び出しごとに ERROR で出すと 1 リクエストで
            // 数万行になる (実測 40,554 行)。数だけ数え、ログは「1 回目 + 1,000
            // 回ごとの進捗」に畳む。出す内容 (uid とメッセージ) は従来と同じ。
            let msg = format!("{e:#}");
            match crate::gpu_budget::note_weight_failure(uid, &msg) {
                Some(true) => tracing::error!(
                    "gguf weight register failed (uid={uid}): {msg} (同種の失敗は数えるだけ。集計はリクエスト末尾の 1 行)"
                ),
                Some(false) => {
                    let s = crate::gpu_budget::weight_upload_stats();
                    tracing::warn!("gguf weight register failed: 累計 {} 本 (最後の uid={uid})", s.failed);
                }
                None => {}
            }
            return false;
        }
    };
    match ctx.moe_gemv_dev(ty, &w.buf, x, k, n, out) {
        Ok(true) => {
            set_last_linear_ran_on_gpu(true);
            if prof {
                let up_w = crate::gpu_budget::weight_upload_bytes().saturating_sub(up_before);
                crate::model::devprof::note_bytes(k as u64 * 4 + up_w, n as u64 * 4);
            }
            true
        }
        Ok(false) => false,
        Err(e) => {
            tracing::error!("gguf gemv failed (uid={uid}): {e:#}");
            false
        }
    }
}

/// P-PF-GB: prefill 用の量子 GEMM の入口 (nt トークン一括)。
///
/// `maybe_gpu_gguf_gemv_into` のバッチ版。重みは同じレジストリ (`uid`) を使うので、
/// decode で既に載っていれば転送は起きない。`false` = CPU バッチへ落ちること。
/// `DENNO_GPU_GEMM=0` で無効化できる (A/B 用)。
///
/// CPU のバッチ演算とは **ビット一致しない** (FMA 融合 + 加算順が違う)。
/// prefill は 2026-10-28 のオペレーター指示で契約の外にある。CPU 参照と
/// 突き合わせるテストは `set_gpu_gemm_enabled(false)` で切ってから走らせること。
pub fn gpu_gemm_enabled() -> bool {
    if !GPU_GEMM_ON.load(std::sync::atomic::Ordering::Relaxed) {
        return false;
    }
    !matches!(
        std::env::var("DENNO_GPU_GEMM").ok().as_deref(),
        Some("0") | Some("off") | Some("false")
    )
}

/// テスト用: GPU GEMM を明示的に切る / 入れる。
pub fn set_gpu_gemm_enabled(on: bool) {
    GPU_GEMM_ON.store(on, std::sync::atomic::Ordering::Relaxed);
}

static GPU_GEMM_ON: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(true);

/// GPU GEMM が実際に計算を肩代わりした回数 / 落ちた回数 (プロセス通算)。
///
/// 「緑 = 経路が発動した証拠ではない」ので、実モデルの prefill で本当に
/// 通ったかをこれで数える (2026-10-28: 共有メモリ超過で全滅していたのを
/// `差 0 要素` から追った)。
static GEMM_USED: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
static GEMM_SKIPPED: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// (`使われた回数`, `CPU へ落ちた回数`)。
pub fn gpu_gemm_stats() -> (usize, usize) {
    (
        GEMM_USED.load(std::sync::atomic::Ordering::Relaxed),
        GEMM_SKIPPED.load(std::sync::atomic::Ordering::Relaxed),
    )
}

/// 落ちた理由の内訳 (添字は [`SKIP_*`] 定数)。
pub const SKIP_NAMES: [&str; 8] = [
    "off(env/flag)",
    "cuda無効",
    "nt範囲外",
    "未対応の型",
    "ctx無し",
    "重み未登録",
    "カーネル拒否",
    "実行エラー",
];
pub const SKIP_OFF: usize = 0;
pub const SKIP_NO_CUDA: usize = 1;
pub const SKIP_NT: usize = 2;
pub const SKIP_TYPE: usize = 3;
pub const SKIP_NO_CTX: usize = 4;
pub const SKIP_NO_WEIGHT: usize = 5;
pub const SKIP_KERNEL: usize = 6;
pub const SKIP_ERR: usize = 7;
static GEMM_SKIP_REASONS: [std::sync::atomic::AtomicUsize; 8] = [
    std::sync::atomic::AtomicUsize::new(0),
    std::sync::atomic::AtomicUsize::new(0),
    std::sync::atomic::AtomicUsize::new(0),
    std::sync::atomic::AtomicUsize::new(0),
    std::sync::atomic::AtomicUsize::new(0),
    std::sync::atomic::AtomicUsize::new(0),
    std::sync::atomic::AtomicUsize::new(0),
    std::sync::atomic::AtomicUsize::new(0),
];

/// 落ちた理由の内訳。
pub fn gpu_gemm_skip_reasons() -> [usize; 8] {
    let mut a = [0usize; 8];
    for (i, c) in GEMM_SKIP_REASONS.iter().enumerate() {
        a[i] = c.load(std::sync::atomic::Ordering::Relaxed);
    }
    a
}

fn skip(r: usize) -> bool {
    GEMM_SKIP_REASONS[r].fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    false
}

/// 計数を 0 に戻す (ベンチの区切り用)。
pub fn reset_gpu_gemm_stats() {
    GEMM_USED.store(0, std::sync::atomic::Ordering::Relaxed);
    GEMM_SKIPPED.store(0, std::sync::atomic::Ordering::Relaxed);
    for c in GEMM_SKIP_REASONS.iter() {
        c.store(0, std::sync::atomic::Ordering::Relaxed);
    }
}

/// 入口。計数を付けて [`gemm_try`] に渡す (再帰の内側は数えない)。
pub fn maybe_gpu_gguf_gemm_into(
    uid: u64,
    ty: crate::kquant::GgmlType,
    blocks: &[u8],
    k: usize,
    n: usize,
    x: &[f32],
    nt: usize,
    out: &mut [f32],
) -> bool {
    // devprof: 1 呼び出しぶんの時間・転送量・同期待ちを op "gemm" に積む。
    // `nt > 128` は `gemm_try` の内側で分割されるが、ここで数えるのは
    // 呼び出し側から見た 1 回ぶん (H2D = nt * k * 4, D2H = nt * n * 4)。
    let prof = crate::model::devprof::on();
    let t0 = prof.then(std::time::Instant::now);
    let up_before = if prof {
        crate::gpu_budget::weight_upload_bytes()
    } else {
        0
    };
    if prof {
        crate::model::devprof::clear();
    }
    let ok = gemm_try(uid, ty, blocks, k, n, x, nt, out);
    let c = if ok { &GEMM_USED } else { &GEMM_SKIPPED };
    c.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if let (true, Some(t0)) = (ok, t0) {
        let up_w = crate::gpu_budget::weight_upload_bytes().saturating_sub(up_before);
        let (_, _, sync_ns) = crate::model::devprof::take_pending();
        crate::model::devprof::add(
            "gemm",
            t0.elapsed().as_nanos() as u64,
            (nt * k * 4) as u64 + up_w,
            (nt * n * 4) as u64,
            sync_ns,
        );
    }
    ok
}

fn gemm_try(
    uid: u64,
    ty: crate::kquant::GgmlType,
    blocks: &[u8],
    k: usize,
    n: usize,
    x: &[f32],
    nt: usize,
    out: &mut [f32],
) -> bool {
    if !gpu_gemm_enabled() {
        return skip(SKIP_OFF);
    }
    if !cuda_enabled() {
        return skip(SKIP_NO_CUDA);
    }
    if nt <= 1 {
        return skip(SKIP_NT);
    }
    if gguf_row_bytes(ty, k).is_none() {
        return skip(SKIP_TYPE);
    }
    // カーネルは 1 起動で 128 トークンまで (GEMM_ROWS × GEMM_NTG_MAX = 16 × 8)。
    // それより大きい chunk はここで 128 ずつに割る (重みは VRAM 常駐なので
    // 読み直しは VRAM 内で済む)。
    const TILE: usize = 128;
    if nt > TILE {
        let mut t0 = 0usize;
        while t0 < nt {
            let t1 = (t0 + TILE).min(nt);
            let m = t1 - t0;
            let ok = gemm_try(
                uid,
                ty,
                blocks,
                k,
                n,
                &x[t0 * k..t1 * k],
                m,
                &mut out[t0 * n..t1 * n],
            );
            if !ok {
                return false; // 途中で落ちたら呼び出し側が CPU で全部やり直す
            }
            t0 = t1;
        }
        return true;
    }
    if nt <= 1 {
        return skip(SKIP_NT);
    }
    let Some(ctx) = shared_ctx() else {
        return skip(SKIP_NO_CTX);
    };
    if let Err(e) = ctx.make_current() {
        tracing::error!("CUDA cuCtxSetCurrent failed, using CPU gguf gemm: {e:#}");
        return skip(SKIP_ERR);
    }
    let w = match weights_for_gguf(uid, ty, blocks, k, n) {
        Ok(w) => w,
        Err(e) => {
            let msg = format!("{e:#}");
            if let Some(true) = crate::gpu_budget::note_weight_failure(uid, &msg) {
                tracing::error!("gguf weight register failed (gemm, uid={uid}): {msg}");
            }
            return skip(SKIP_NO_WEIGHT);
        }
    };
    match ctx.moe_gemm_dev(ty, &w.buf, x, nt, k, n, out) {
        Ok(true) => true,
        Ok(false) => skip(SKIP_KERNEL),
        Err(e) => {
            tracing::error!("gguf gemm failed (uid={uid}): {e:#}");
            skip(SKIP_ERR)
        }
    }
}

/// s123: Q4_0 線形層の結果を Vec で返す版 (`Linear::apply` 系から使う)。
pub fn maybe_gpu_linear_q4(
    uid: u64,
    a: &[f32],
    blocks: &[u8],
    k: usize,
    n: usize,
    m: usize,
) -> Option<Vec<f32>> {
    let mut out = vec![0.0f32; m * n];
    if maybe_gpu_linear_q4_into(uid, a, blocks, k, n, m, &mut out) {
        Some(out)
    } else {
        None
    }
}

/// s123: Q4_0 線形層の書き込み先指定版。
/// true = GPU が計算して `out` を埋めた / false = 呼び出し側が CPU パスを使うこと。
/// 判定・フォールバック (恒久ラッチ) の規約は int8 の `maybe_gpu_linear_into` と同一。
/// 数値は CPU の `matvec_rows_bt_q4_into` と同じ定義 (差は累積順のみ・R2 以内)。
pub fn maybe_gpu_linear_q4_into(
    uid: u64,
    a: &[f32],
    blocks: &[u8],
    k: usize,
    n: usize,
    m: usize,
    out: &mut [f32],
) -> bool {
    // s148 (Task B10・計測のみ): ここは **q4 で実際に線形層が走る唯一の入口**
    // (27B q4 の prefill / decode の全投影・lm_head がここを通る)。表 C の
    // `sl_lin` はこの入口から戻るまでを 1 サンプルとして数える — wrapper
    // (`lin_stage`) の内側ではなく「本当に呼ばれた回数」と一致させるため。
    // 計測 OFF は `span_begin` が `None` を返し、`span_end` は分岐 1 回で戻る。
    //
    // s151 (Task B12): 内訳 (`sl_lin_*`) は s148 で 1 call に 3 号 (入口の地 /
    // 重み登録 / ピン留め) 積まれていた。`lin_call_begin` / `lin_call_end` が
    // 「この call の other は最大 1 号」「子の和 = 全体」を保つ。
    let call_t = if crate::prof::serve_on() {
        crate::prof::count_lin_dispatch();
        crate::prof::lin_call_begin()
    } else {
        None
    };
    let r = maybe_gpu_linear_q4_into_inner(uid, a, blocks, k, n, m, out);
    crate::prof::lin_call_end(call_t);
    r
}

/// s148: [`maybe_gpu_linear_q4_into`] の本体 (計測の包みを外したもの)。
fn maybe_gpu_linear_q4_into_inner(
    uid: u64,
    a: &[f32],
    blocks: &[u8],
    k: usize,
    n: usize,
    m: usize,
    out: &mut [f32],
) -> bool {
    debug_assert_eq!(out.len(), m * n);
    set_last_linear_ran_on_gpu(false);
    LINEAR_SEAM_CALLS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if !cuda_enabled() {
        return false;
    }
    if k % 32 != 0 {
        return false;
    }
    // s123: Q4 の CPU フォールバックは単純ループで遅い (27B で秒/token 級)。
    // int8 の gemm_min_m (既定 256) は「CPU sgemm の方が速い帯域」を避けるための
    // 閾値なので、Q4 には適用せず GEMV 上限を超えたら常にタイル GEMM を使う。
    let use_gemm = m > max_m() && gemm_enabled();
    if m > max_m() && !use_gemm {
        return false;
    }
    // s148: ここから先の「入口の地のホスト時間」(デバイス取得・コンテキスト・
    // 重み登録) を `sl_lin_other` として明示する (段の和を入口の壁時計に一致させる)。
    // s151 (B12): `lin_other_push` は **1 call につき 1 号** しか積まないので、
    // 下の 3 か所で呼んでもサンプル数は 1 のまま (s148 は 3 号になっていた)。
    let entry_st = crate::prof::span_begin();
    let Some(ctx) = shared_ctx() else {
        crate::prof::lin_other_close(entry_st);
        return false;
    };
    if let Err(e) = ctx.make_current() {
        tracing::error!("CUDA cuCtxSetCurrent failed, using CPU q4: {e:#}");
        GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
        crate::prof::lin_other_close(entry_st);
        return false;
    }
    // s148: 重みのデバイス登録 (初回のみ・数 MB の H2D) とディスパッチの地の
    // ホスト時間を `sl_lin_other` として明示する (段の和を入口の壁時計に一致させる)。
    let st = crate::prof::span_begin();
    let gw = match weights_for_q4(uid, blocks, k, n) {
        Ok(g) => g,
        Err(e) => {
            let msg = format!("{e:#}");
            // この経路は 1 本失敗した時点で GPU 全体を止めるので、抑制せず必ず 1 行出す
            // (プロセスあたり 1 回しか来ない)。数えるほうは共通の集計に任せる。
            crate::gpu_budget::note_weight_failure(uid, &msg);
            tracing::error!(
                "CUDA q4 weight upload failed, using CPU permanently (この 1 本で GPU 経路全体を停止): {msg}"
            );
            crate::gpu_budget::note_gpu_broken("q4 weight upload failed");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            crate::prof::lin_other_close(st);
            crate::prof::lin_other_close(entry_st);
            return false;
        }
    };
    let r = q4_dispatch(ctx, a, gw, m, k, n, use_gemm, out);
    crate::prof::lin_other_close(st);
    crate::prof::lin_other_close(entry_st);
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            tracing::error!("CUDA q4 linear failed, falling back to CPU permanently: {e:#}");
            GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
            false
        }
    }
}

// ---------------------------------------------------------------------------
// s138 (Task B6・計測のみ): 線形ラッパ 1 call の段割り (表 B) の小道具。
// `split_stage` で tick を取り、段の切れ目で `split_mark`、最後に `split_flush`。
// 計測 OFF (`split_on()` が偽) は tick が None で、どれも分岐 1 回で戻る —
// 既定経路はクロック読みも確保もしない (挙動・数値は完全に不変)。
// ---------------------------------------------------------------------------

/// s140 (Task B6b): 線形ステージ 1 呼び出しを計測器に通す。
///
/// s138 は線形ラッパ (`linear_pinned` / `q4_dispatch_tile`) の中だけを分割して
/// いたが、serve の prefill は **GEMM 経路 (`linear_gemm_into`) と Q4 GEMV
/// (`q4_dispatch` のマルチタイル) を通る**ため、段の区間が呼び出し全体を覆って
/// いなかった (実測: 608 call / 7846 ms のバケットに対し 802 サンプル / 445.8 ms)。
/// ここでは呼び出しの**手前**で tick を打ち、戻ってきた時点の経過をバケット件数へ
/// 数える。これでタイル分割・GEMM 経路であるかに関係なく 1 call = 1 tick になり、
/// 排他の和が呼び出し全体の壁時計に一致する。
///
/// 計測 OFF (`op_on()` が偽) は分岐 1 回で `f` を素通しする (クロック読み・
/// 表への書き込みなし = 既定経路の挙動不変)。`split_on()` (テレメトリのみ) の
/// ときは表だけ積み、バケット件数は数えない (バケットは prof 専用のため)。
#[inline]
fn lin_stage<T>(op: usize, f: impl FnOnce() -> T) -> T {
    if !crate::prof::op_on() {
        return f();
    }
    let t0 = Instant::now();
    let split = crate::prof::split_on();
    if split {
        crate::prof::split_tick_call(crate::prof::SPLIT_Q4_TABLE);
    }
    let r = f();
    lin_stage_close(op, t0);
    r
}

/// s140 (Task B6b): 実行先ラベル (on_gpu) つきの `lin_stage`。`time_n_ev` が
/// 返すのと同じ `(値, GPU で走ったか)` を返すので、呼び出し側は
/// `let (r, _) = lin_stage_ev(op, || ...);` と書ける (戻り値・数値経路は不変)。
#[inline]
fn lin_stage_ev<T>(op: usize, f: impl FnOnce() -> (T, bool)) -> (T, bool) {
    if !crate::prof::op_on() {
        return f();
    }
    let t0 = Instant::now();
    let split = crate::prof::split_on();
    if split {
        crate::prof::split_tick_call(crate::prof::SPLIT_Q4_TABLE);
    }
    let (r, on_gpu) = f();
    lin_stage_close(op, t0);
    (r, on_gpu)
}

/// s140 (Task B6b): 線形呼び出し 1 回を `lin_stage` で包み、**バケットは呼び出し側が
/// 従来どおり** `prof::time_full` 等で積む形 (chain の段は per-op バケットを
/// 別の `time_full` で積んでいるため、こちらはバケットを二重に積まない)。
/// 戻り値は `f` のまま (数値経路は不変)。
#[inline]
pub fn lin_stage_tagged<T>(op: usize, f: impl FnOnce() -> T) -> T {
    if !crate::prof::op_on() {
        return f();
    }
    let t0 = Instant::now();
    let r = f();
    lin_stage_close(op, t0);
    r
}

/// `lin_stage_tagged` の締め: 分割表 1 サンプル + バケット件数 1。
#[inline]
fn lin_stage_close(op: usize, t0: Instant) {
    if crate::prof::split_on() {
        crate::prof::split_tick_call(crate::prof::SPLIT_Q4_TABLE);
    }
    let ns = t0.elapsed().as_nanos() as u64;
    if crate::prof::enabled() {
        crate::prof::count_linear_stage(op, ns, 1, true);
    }
    crate::prof::split_sample(op, ns, 0);
}

/// 段割りの開始 tick (計測 OFF は None)。
#[inline]
fn split_stage() -> Option<Instant> {
    if crate::prof::split_on() {
        Some(Instant::now())
    } else {
        None
    }
}

/// 直前の段 (`op`) の所要を表 B へ積み、次の段の tick を打ち直す。
/// `op` は「いま終わった段」— 呼び出しは段の切れ目 (確保 / copy / launch / sync
/// の直後) に置く。calls は 1 (その段が起きたら 1 回、起きなかった段は積まない)。
#[inline]
fn split_mark(t: &mut Option<Instant>, op: usize) {
    let Some(t0) = *t else { return };
    let now = Instant::now();
    let ns = now.duration_since(t0).as_nanos() as u64;
    crate::prof::split_sample(op, ns, 1);
    *t = Some(now);
}

/// 1 call 分の段割りを閉じる (残りの段の tick は捨てる)。
/// 段の値は `split_mark` が `split_sample` で直接積んでいるので、ここで表へ
/// 流し込むものは無い (時間の丸めを段ごとに 1 回で済ませるため、8〜9 段の
/// 積算器は持たない — `secs` でまとめて足すと段の数だけ丸め誤差が乗る)。
#[inline]
fn split_flush(t: &mut Option<Instant>) {
    *t = None;
}

/// s168 (P7): prefill の q4 GEMM 行タイル (**実測ノブ**)。1 タイル = 1 回の
/// `dno_gemm_q4_0` launch で、grid は (mr.div_ceil(64), n.div_ceil(128))。
/// 既定は s124 以来の 1024。`DENNO_Q4_M_TILE` で 64..=8192 の 64 の倍数を
/// 指定できる (再ビルド無しで 512 / 1024 / 2048 / 4096 を A/B するための入口)。
///
/// 中間バッファは 1 タイルあたり (行) x (列) x 4 B で、行数は端数併合を含めて
/// 最大 `tile + q4_tail_merge_below()` (既定 1024 + 16 = 1040 行)。
/// 27B (e=5120, ff=17408) の MLP で 1040 行 = CH_GA 138 MiB / CH_ACT 69 MiB /
/// CH_PFH・CH_DOWN 各 20 MiB。4096 行なら 546 MiB / 273 MiB / 80 MiB、
/// 8192 行なら 1090 MiB / 545 MiB / 160 MiB。
const Q4_M_TILE: usize = 1024;

/// [`Q4_M_TILE`] の上限。中間バッファがタイル行数に比例するので 8192 行で止める
/// (27B MLP の CH_GA は約 1.1 GiB — 13k 行を一度に置く 2.7 GiB には届かない)。
const Q4_M_TILE_MAX: usize = 8192;

/// タイル幅の刻み。`dno_gemm_q4_0` の行ブロック (Q4_GM = 64) に揃える — 途中の
/// タイルはすべて 64 の倍数行になり、grid.x が端数ブロックを出さない。
const Q4_M_TILE_STEP: usize = 64;

/// `DENNO_Q4_M_TILE` の解釈 (純粋関数)。範囲外・非数・刻み外は既定へ落とす
/// (不正な env で panic させない — `q4_gemv_c()` と同じ規約)。
fn parse_q4_m_tile(v: Option<&str>) -> usize {
    match v.and_then(|s| s.trim().parse::<usize>().ok()) {
        Some(t) if (Q4_M_TILE_STEP..=Q4_M_TILE_MAX).contains(&t) && t % Q4_M_TILE_STEP == 0 => t,
        _ => Q4_M_TILE,
    }
}

/// [`Q4_M_TILE`] の実効値 (env `DENNO_Q4_M_TILE` があればそちら)。プロセス内で
/// 1 回だけ読む (serve の起動時に env を決める運用なので、途中変更は見ない)。
fn q4_m_tile() -> usize {
    static TILE: OnceLock<usize> = OnceLock::new();
    *TILE.get_or_init(|| {
        let v = std::env::var("DENNO_Q4_M_TILE").ok();
        parse_q4_m_tile(v.as_deref())
    })
}

/// s168 (P7): 端数タイルを直前のタイルへ併合する閾値 (行)。
///
/// `max_m()` は「GEMV が GEMM より速い帯域」の上限 (既定 16) で、ファイル中の
/// 他の dispatch はこの行数以下を GEMV に回す。prefill の GEMM は 64 行ブロック
/// 単位なので、これ未満の端数を単独タイルにすると 1 launch がほぼ空回りする
/// (しかも sync 付きの経路では待ち時間が丸ごと乗る)。端数がこれ未満なら
/// 直前のタイルに足して 1 回で流す。`DENNO_CUDA_MAX_M=0` にすると併合しない
/// (併合そのものの A/B 用)。
fn q4_tail_merge_below() -> usize {
    max_m()
}

/// s168 (P7): 1 タイルが受ける最大行数 (端数併合を含む)。中間バッファはこの
/// 行数で**ループの前に**確保する — 途中で grow させると、先行 launch が読んで
/// いるバッファを解放しうる (`Scratch::ensure` は grow-only の入れ替え)。
fn q4_tile_max_rows(tile: usize) -> usize {
    tile.saturating_add(q4_tail_merge_below())
}

/// s168 (P7): `r0` から始まる次の行グループの行数 (純粋関数)。
/// 端数が [`q4_tail_merge_below`] 以下なら、その端数もこのグループに含める
/// (返り値 <= tile + tail)。行は互いに独立で 1 行の累積順は変わらないため、
/// 行のまとめ方は出力のビットを変えない (カーネル・引数・grid の作り方は同一)。
///
/// 閾値は `<=` にして [`pf_res_gate`] / [`gdn_prefill_q4_geom`] の
/// 「端数 <= max_m() は受けない」と揃えてある — ゲートが受けた n に対しては、
/// 端数タイルが単独で launch されることが無い。
fn q4_group_rows(r0: usize, m: usize, tile: usize) -> usize {
    let left = m - r0;
    let mr = tile.min(left);
    let rem = left - mr;
    if rem > 0 && rem <= q4_tail_merge_below() {
        left
    } else {
        mr
    }
}

/// s168 (Task P7): 行タイルのノブと端数併合の契約 (純粋関数・GPU 不要)。
#[cfg(test)]
mod p7_tile_tests {
    use super::*;

    /// `DENNO_Q4_M_TILE` の解釈: 既定は従来値、範囲外・刻み外・非数は既定へ。
    #[test]
    fn env_tile_parse() {
        assert_eq!(Q4_M_TILE, 1024, "既定は s124 以来の 1024 のまま");
        assert_eq!(parse_q4_m_tile(None), 1024);
        assert_eq!(parse_q4_m_tile(Some("")), 1024);
        assert_eq!(parse_q4_m_tile(Some("abc")), 1024);
        assert_eq!(parse_q4_m_tile(Some("-512")), 1024);
        assert_eq!(parse_q4_m_tile(Some("0")), 1024);
        assert_eq!(parse_q4_m_tile(Some("32")), 1024, "64 行未満は受けない");
        assert_eq!(parse_q4_m_tile(Some("96")), 1024, "64 の倍数でない");
        assert_eq!(parse_q4_m_tile(Some("999999")), 1024, "上限超え");
        assert_eq!(parse_q4_m_tile(Some(" 2048 ")), 2048, "前後の空白は許す");
        for t in [64usize, 512, 1024, 2048, 4096, 8192] {
            assert_eq!(parse_q4_m_tile(Some(&t.to_string())), t, "t={t}");
        }
        // 本番の実効値も必ず受理域に入る (panic も 0 行タイルも作らない)
        let eff = q4_m_tile();
        assert!(eff % Q4_M_TILE_STEP == 0 && eff >= Q4_M_TILE_STEP && eff <= Q4_M_TILE_MAX);
    }

    /// 行グループの契約: 重複・欠落なしで m 行を覆い、1 グループは cap 行以下。
    /// 途中のグループは必ず tile 行ちょうど (併合は最終グループだけ)、
    /// 端数 (<= tail) が単独タイルとして launch されることは無い。
    #[test]
    fn row_groups_cover_rows_exactly() {
        let tail = q4_tail_merge_below();
        for tile in [64usize, 128, 512, 1024, 2048, 4096] {
            let cap = q4_tile_max_rows(tile);
            assert_eq!(cap, tile + tail, "tile={tile}");
            for m in 1..=3000usize {
                let (mut r0, mut groups) = (0usize, 0usize);
                while r0 < m {
                    let mr = q4_group_rows(r0, m, tile);
                    assert!(mr > 0, "tile={tile} m={m} r0={r0}: 空グループ");
                    assert!(mr <= cap, "tile={tile} m={m}: {mr} 行 > cap {cap}");
                    if r0 + mr < m {
                        assert_eq!(mr, tile, "tile={tile} m={m} r0={r0}: 途中が {mr} 行");
                    } else if r0 > 0 {
                        // 最終グループ: tile ちょうど or 併合 (tile 超) or tail 超の端数
                        assert!(
                            mr >= tile || mr > tail,
                            "tile={tile} m={m}: 端数 {mr} 行 (tail {tail}) を単独 launch している"
                        );
                    }
                    r0 += mr;
                    groups += 1;
                    assert!(groups <= m, "tile={tile} m={m}: グループ数が行数を超えた");
                }
                assert_eq!(r0, m, "tile={tile} m={m}: 行が覆われていない");
            }
        }
    }

    /// 13k token の実形 (27B の prefill) で、タイル幅ごとの launch 回数と
    /// 端数併合の有無を固定する (REPORT_P7.md の表と同じ計算)。
    #[test]
    fn row_groups_at_13k_tokens() {
        let tail = q4_tail_merge_below();
        // (tile, 13,000 行のグループ数) — 端数 712 行はどの tile でも tail 超
        for (tile, want) in [(512usize, 26usize), (1024, 13), (2048, 7), (4096, 4)] {
            let mut r0 = 0usize;
            let mut n = 0usize;
            while r0 < 13_000 {
                r0 += q4_group_rows(r0, 13_000, tile);
                n += 1;
            }
            assert_eq!(n, want, "tile={tile} 13,000 行の launch 回数");
        }
        // 端数が tail 以下の形は直前のタイルへ併合され、グループ数が 1 減る
        let m = 1024 * 3 + 4;
        let mut r0 = 0usize;
        let (mut n, mut last) = (0usize, 0usize);
        while r0 < m {
            last = q4_group_rows(r0, m, 1024);
            r0 += last;
            n += 1;
        }
        if tail >= 4 {
            assert_eq!(n, 3, "端数 4 行は 3 番目のタイルへ併合 (2,048+ 行)");
            assert_eq!(last, 1024 + 4, "併合後の最終タイル行数");
        } else {
            assert_eq!(n, 4, "併合 OFF (DENNO_CUDA_MAX_M=0) では 4 グループ");
        }
    }
}

/// s123: Q4_0 の 1 層ぶん。小さい m は GEMV (1 warp = 1 行)、大きい m は
/// タイル GEMM (1 block = 16 行 x 256 列)。H2D → kernel → D2H → sync ×1。
fn q4_dispatch(
    ctx: &CudaCtx,
    a: &[f32],
    gw: &GpuWq4,
    m: usize,
    k: usize,
    n: usize,
    use_gemm: bool,
    out: &mut [f32],
) -> Result<()> {
    // s124 (P4-6): m を固定タイルに割る。`SCRATCH` は thread_local かつ grow-only
    // なので、プロンプト長そのままの m を渡すと (m*k + m*n)*4 B が GPU 経路を
    // 通ったスレッド数ぶん積み上がる (27B・10.8k token で約 11 GB になり、続く
    // リクエストが cuMemAlloc error 2 で CPU へ落ちた)。
    // 行は互いに独立で、1 行の演算順はタイル分割で変わらないため出力は bit 一致する。
    // s168 (P7): タイル幅は `DENNO_Q4_M_TILE` の実効値、端数は直前のタイルへ併合する。
    let tile = q4_m_tile();
    let lib = lib()?;
    ctx.make_current()?;
    let mut r0 = 0;
    while r0 < m {
        let mr = q4_group_rows(r0, m, tile);
        let a_t = &a[r0 * k..r0 * k + mr * k];
        let out_t = &mut out[r0 * n..r0 * n + mr * n];
        q4_dispatch_tile(ctx, lib, a_t, gw, mr, k, n, use_gemm, out_t)?;
        r0 += mr;
    }
    Ok(())
}

/// s132 (Task B1): [`q4_dispatch_tile`] の GEMV が 1 block で受ける最大行数。
/// `kernels_int8.cu` の `dno_gemv_q4_0mr` (acc[8]) と対で動く。
/// s133 以降、本番の GEMV 経路は `dno_gemv_q4_0c*` (下の [`Q4_GEMV_C`]) で、
/// `dno_gemv_q4_0mr` はビット一致の参照 (テスト) として残してある。
const Q4_MR_MAX: usize = 8;

/// s133 (Task B1, attempt 2): 列ブロック版 Q4 GEMV の C (1 回の A 読みで
/// 何列の重みを回すか)。`kernels_int8.cu` の `dno_gemv_q4_0c2/c4/c8` と対。
/// 1 MAC あたりの命令数は 1 + 1/C になる (C=1 の従来形は 2)。
/// 2 / 8 を試すときはここを変える (PTX には 3 本とも入っている)。
/// ビルドし直さずに比べるときは `DENNO_Q4_GEMV_C=2|4|8` で上書きする。
const Q4_GEMV_C: usize = 4;

/// s239 (P36): GDN pass 1 を 4 レーン版で回すか (`DENNO_GDN_LANES=4` で有効)。
///
/// 4 レーン版は W/M をレジスタ常駐にしてローカルアクセス命令を 1/4 にするが、
/// 内積が 4 部分和の木縮約になるため **旧版と bit 一致しない** (GDN は bit 一致
/// 不要契約・決定論のみ)。アンカー v6_* は GDN 層を通るので、既定にする際は
/// 再基準化が必要。よって既定は旧カーネル (off) とし、A/B 用の入口だけ用意する。
fn gdn_lanes4() -> bool {
    static L4: OnceLock<bool> = OnceLock::new();
    *L4.get_or_init(|| {
        std::env::var("DENNO_GDN_LANES")
            .ok()
            .map(|v| v.trim() == "4")
            .unwrap_or(false)
    })
}

/// P55: GDN pass 1 の状態配列 (W/M) を共有メモリへ置く版を使うか
/// (`DENNO_GDN_PRE_SM=1` で有効・既定 off)。
///
/// 数値は旧版と **ビット同一** (格納先がローカルメモリから共有メモリに変わる
/// だけで、値は f32 のまま・読み書きの順序/回数/丸めは同一)。既定 off の理由は
/// 数値ではなく occupancy で、dk=128 では 1 ブロックの smem が 129 KiB になり
/// 1 block/SM まで落ちる。P36 (4 レーン版) が同じ理由で利得を打ち消したので、
/// 実機の `[GDN_KPROF]` と cold A/B で確かめるまで既定にはしない。
fn gdn_pre_sm_enabled() -> bool {
    static SM: OnceLock<bool> = OnceLock::new();
    *SM.get_or_init(|| {
        std::env::var("DENNO_GDN_PRE_SM")
            .ok()
            .map(|v| v.trim() == "1")
            .unwrap_or(false)
    })
}

/// P55: 共有メモリ版 pass 1 の動的 smem 既定上限 (48 KiB)。`cuFuncSetAttribute`
/// による opt-in に失敗した場合の値で、dk=128 の必要量 (129 KiB) を満たさない
/// ためゲートで旧カーネルへ落ちる。
const GDN_PRE_SM_SMEM_DEFAULT: usize = 48 * 1024;

/// P55: 共有メモリ版 pass 1 が載る最大 dk。必要量 = (2*dk*dk + 2*dk + 3)*4 B
/// なので dk=128 で 132,108 B (opt-in 上限 164 KiB / 227 KiB の範囲)、
/// dk=192 では 296,652 B になり opt-in 上限を超える。27B の GDN は dk=dv=128
/// (`linear_key_head_dim`・kernel_invariants の実形状表)。dk > 128 の形は
/// 従来カーネルで回る (このゲートはそのための上限)。
const GDN_PRE_SM_MAX_DK: usize = 128;

/// P55: 共有メモリ版 pass 1 の動的 smem 必要量 (bytes)。
/// カーネル側のレイアウト W[dk][dk] | M[dk][dk] | k[dk] | v[dk] | scalars[3] と
/// 同じ式 (kernel_invariants の `gdn_kernel_shared_layout_matches_host_smem` が
/// カーネル側の宣言と対で見る)。
const fn gdn_pre_sm_smem_bytes(dk: usize) -> usize {
    (2 * dk * dk + 2 * dk + 3) * 4
}

/// P55: 共有メモリ版 pass 1 を選ぶ条件 (純粋関数・GPU 不要で検証できる)。
///
/// `env_on` = `DENNO_GDN_PRE_SM=1` / `has_fn` = PTX からカーネルを取得できたか /
/// `smem` = 必要量 / `limit` = デバイスの opt-in 上限 (失敗時は 48 KiB)。
/// 1 つでも欠けたら false = 旧カーネル。カーネル不在・opt-in 失敗・dk 過大の
/// どれでも「静かに従来経路」になることが契約。
fn gdn_pre_sm_gate(
    env_on: bool,
    has_fn: bool,
    dk: usize,
    dv: usize,
    smem: usize,
    limit: usize,
) -> bool {
    env_on && has_fn && dk == dv && (1..=GDN_PRE_SM_MAX_DK).contains(&dk) && smem <= limit
}

/// [`Q4_GEMV_C`] の実効値 (env `DENNO_Q4_GEMV_C` があればそちら)。2/4/8 以外は
/// 既定へ落とす (不正な値で panic させない)。
fn q4_gemv_c() -> usize {
    match std::env::var("DENNO_Q4_GEMV_C").ok().and_then(|v| v.parse::<usize>().ok()) {
        Some(c @ (2 | 4 | 8)) => c,
        _ => Q4_GEMV_C,
    }
}

/// [`Q4_GEMV_C`] に対応する PTX エントリの index (0 = c2, 1 = c4, 2 = c8)。
fn q4_gemv_c_index(c: usize) -> usize {
    match c {
        2 => 0,
        4 => 1,
        8 => 2,
        _ => panic!("Q4_GEMV_C must be 2, 4 or 8"),
    }
}

/// s124: [`q4_dispatch`] の 1 タイル (m <= 256) を実行する。scratch はここで
/// m <= 256 に固定されるため、プロンプトが何万 token でも増えない。
fn q4_dispatch_tile(
    ctx: &CudaCtx,
    lib: &'static CudaLib,
    a: &[f32],
    gw: &GpuWq4,
    m: usize,
    k: usize,
    n: usize,
    use_gemm: bool,
    out: &mut [f32],
) -> Result<()> {
    ctx.make_current()?;
    // s148 (Task B10・計測のみ): serve (q4) 経路の線形呼び出しの中身を段へ割る。
    // s138 の表 B は wrapper (`lin_stage` / `linear_pinned`) の内側だけを数えて
    // いたため、本番の GEMM 経路 (`q4_dispatch_tile`) の時間に届いていなかった
    // (実測: 608 call / 7,846 ms に対し 802 サンプル / 445.8 ms)。ここは本番が
    // 実際に通るタイル実装の内側で、1 タイル = 1 サンプル。計測 OFF は tick が
    // `None` で、`split_mark` / `span_end` とも分岐 1 回で戻る (クロック読みなし)。
    let mut t = split_stage();
    // s148: 表 C の段。1 タイルの中で互いに排他 (確保 / H2D / launch / D2H / sync)。
    //
    // `st` は「いま開いている段」で、閉じるたびに**開き直さない** — `span_begin` は
    // 計測 OFF で `None` を返すので、閉じた後に開き直すと (計測 ON でも) ここで
    // 落とした区間が二度と閉じられない。各段の開始は必ず次の段を閉じた直後で取る。
    // こうすると段の和が「タイル入口 → 戻り」の壁時計に一致し、閉じ漏れが
    // `sl_lin_other` (残余) ではなく**未帰属の穴**として現れない。
    let mut st = crate::prof::span_begin();
    SCRATCH.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let Scratch { x, out: dout, hx, ho, .. } = &mut *s;
        let bytes_x = m * k * 4;
        let bytes_out = m * n * 4;
        Scratch::ensure_arena(x, ARENA_KEY_Q4_X, bytes_x, crate::mem_audit::TAG_GEMM)?;
        Scratch::ensure_arena(dout, ARENA_KEY_Q4_OUT, bytes_out, crate::mem_audit::TAG_GEMM)?;
        split_mark(&mut t, crate::prof::Q4P_OUT_ALLOC);
        // s153 (Task B14): クロック読みは 1 回 (`lin_stage_taken_ns`)。読んだ ns を
        // そのまま表 C へ積むので、子の和が親 (`sl_lin`) を超えず、
        // `sl_lin_other = 全体 - 段の和` が成り立つ。
        let out_ns = crate::prof::lin_stage_taken_ns(st.take());
        crate::prof::span_end_ns(out_ns, crate::prof::SL_LIN_OUTALLOC);
        // 表 C: staging のピン留め領域の確保 (段の開始はここ)
        st = crate::prof::span_begin();
        Scratch::ensure_pin(hx, bytes_x)?;
        Scratch::ensure_pin(ho, bytes_out)?;
        split_mark(&mut t, crate::prof::Q4P_PIN_ALLOC);
        // 表 C: ピン留め確保は転送準備の一部なので `sl_lin_other` に寄せる
        // (`sl_lin_quant` は Q4 では行わない = 0 サンプルのまま)。
        // (割り当て済みの 2 本目以降は即時なので、ここは実質初回だけの時間。)
        crate::prof::lin_other_close(st.take());
        // 表 C: 活性化の staging コピー (hx ← a) から H2D 発行まで
        st = crate::prof::span_begin();
        let (dx, dout) = (x.as_ref().unwrap(), dout.as_ref().unwrap());
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        hx.as_mut_slice::<f32>()[..m * k].copy_from_slice(a);
        split_mark(&mut t, crate::prof::Q4P_H2D_STAGE);
        unsafe {
            check(
                (lib.memcpy_htod_async)(
                    dx.ptr(),
                    hx.ptr as *const c_void,
                    bytes_x,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync",
            )?;
            split_mark(&mut t, crate::prof::Q4P_H2D_ISSUE);
            let h2d_ns = crate::prof::lin_stage_taken_ns(st.take());
            crate::prof::span_end_ns(h2d_ns, crate::prof::SL_LIN_H2D);
            // 表 C: 引数の組み立て + カーネル発行 (段の開始 = H2D を閉じた直後)
            st = crate::prof::span_begin();
            let (mut pa, mut pn, mut ps, mut po) =
                (dx.ptr(), gw.nib.ptr(), gw.sc.ptr(), dout.ptr());
            let (mut mc, mut kc, mut nc) = (m as c_int, k as c_int, n as c_int);
            // s132: 1 block が受ける行数 (mr)。m = 1 は従来の 1 行 1 block 経路
            // (dno_gemv_q4_0) をそのまま通すため、mr は 2 以上でだけ使う。
            let mut mrc = (m.min(Q4_MR_MAX)) as c_int;
            let mut args_mr = vec![
                &mut pa as *mut _ as *mut c_void,
                &mut pn as *mut _ as *mut c_void,
                &mut ps as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
                &mut mrc as *mut _ as *mut c_void,
            ];
            let mut args = [
                &mut pa as *mut _ as *mut c_void,
                &mut pn as *mut _ as *mut c_void,
                &mut ps as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            if use_gemm {
                // Q4_GM=64 (m 方向) / Q4_GN=128 (n 方向)・block (16,8)
                let grid = (m.div_ceil(64) as u32, n.div_ceil(128) as u32, 1);
                ctx.launch_async(ctx.f_gemm_q4, grid, (16, 8, 1), 0, &mut args)?;
            } else if let Some(fc) = ctx.f_mv_q4_c {
                // s133 (Task B1, attempt 2): 1 block = 8 warp x C 列 = 8*C 列、
                // 1 行。1 warp が A の 32 値 (ブロック b) をレジスタに 1 回だけ
                // 読み、C 列ぶんの重みに使い回す。行ごとの累積順は 1 行 1 block
                // 経路と同一なので m = 1 もビット一致。
                // grid.x は 8*C 列を 1 ブロックで受ける形。
                // s169 (P10): C は n から選ぶ (`DENNO_GEMV_SHAPE`。既定 0 = 従来)。
                let c = gemv_c_for_n(n, gemv_sm_count(), gemv_shape_mode(), q4_gemv_c());
                let f_c = fc[q4_gemv_c_index(c)];
                let cols = 8 * c;
                let grid = (n.div_ceil(cols) as u32, m as u32, 1);
                ctx.launch_async(f_c, grid, (256, 1, 1), 0, &mut args)?;
            } else if let (Some(f_mr), 2..) = (ctx.f_mv_q4_mr, m) {
                // s132 (Task B1): 1 block = 8 列 (8 warp) x mr 行。重みは 1 回だけ
                // 読んで mr 行に使い回す (従来は grid.y = m で行ごとに再読み)。
                // mr = min(m, 8)・端数は最終 block の rows = m - i0 で落とす。
                // 列ブロック版が PTX に無いときだけここを通る (フォールバック)。
                let grid = (n.div_ceil(8) as u32, m.div_ceil(mrc as usize) as u32, 1);
                ctx.launch_async(f_mr, grid, (256, 1, 1), 0, &mut args_mr)?;
            } else {
                // 1 block = 8 行 (8 warp)・grid.x = n/8, grid.y = m
                let grid = (n.div_ceil(8) as u32, m as u32, 1);
                ctx.launch_async(ctx.f_mv_q4, grid, (256, 1, 1), 0, &mut args)?;
            }
            split_mark(&mut t, crate::prof::Q4P_KERNEL_LAUNCH);
            // 表 C: 発行段の終わり (ここまでが launch、以降は D2H と待ち)
            let launch_ns = crate::prof::lin_stage_taken_ns(st.take());
            crate::prof::span_end_ns(launch_ns, crate::prof::SL_LIN_LAUNCH);
            // 表 C: 出力 D2H の段は「発行の直前」から開く (sync 完了 + ホストコピーまで)
            st = if st.is_none() { crate::prof::span_begin() } else { st };
            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dout.ptr(), bytes_out, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync",
            )?;
            split_mark(&mut t, crate::prof::Q4P_D2H_ISSUE);
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
            ctx.sync()?;
            split_mark(&mut t, crate::prof::Q4P_SYNC_WAIT);
        }
        out.copy_from_slice(&ho.as_slice::<f32>()[..m * n]);
        split_flush(&mut t);
        // 表 C: 出力 D2H = 発行 + sync の完了待ち + ピン留め領域 → out のコピー。
        // 待ち (`SL_LIN_SYNC`) は別に取らない — D2H の中に吸収される (排他の和を保つ)。
        // `SL_LIN_SYNC` は表 C の行として予約されているが、q4 タイルでは常に 0 サンプル
        // で、その分はこの行 (D2H) に含まれる (COVERAGE には 0 として出る)。
        let d2h_ns = crate::prof::lin_stage_taken_ns(st);
        crate::prof::span_end_ns(d2h_ns, crate::prof::SL_LIN_D2H);
        Ok(())
    })
}

/// ピン留め + 非同期 1 同期パイプライン:
///   H2D(x, async) → quantize kernel → gemv kernel → D2H(out, async) → sync ×1
fn linear_pinned(
    ctx: &CudaCtx,
    a: &[f32],
    gw: &GpuW,
    m: usize,
    k: usize,
    n: usize,
) -> Result<Vec<f32>> {
    debug_assert_eq!(a.len(), m * k);
    let lib = lib()?;
    // current context はスレッドローカル → 毎回張り直す (冪端・軽量)
    ctx.make_current()?;
    // s138 (Task B6・計測のみ): 段ごとの tick (計測 OFF は None)。
    let mut t = split_stage();
    SCRATCH.with(|cell| {
        let mut s = cell.borrow_mut();
        // デストラクチャしてフィールド単位の借用にする (RefMut 経由の
        // 全体借用だと dx (不変) と hx/ho (可変) が競合するため)
        let Scratch { x, aq, asc, out, hx, ho, .. } = &mut *s;
        let bytes_x = m * k * 4;
        let bytes_out = m * n * 4;
        Scratch::ensure(x, bytes_x)?;
        Scratch::ensure(aq, m * k)?;
        Scratch::ensure(asc, m * 4)?;
        Scratch::ensure(out, bytes_out)?;
        split_mark(&mut t, crate::prof::Q4P_OUT_ALLOC);
        Scratch::ensure_pin(hx, bytes_x)?;
        Scratch::ensure_pin(ho, bytes_out)?;
        split_mark(&mut t, crate::prof::Q4P_PIN_ALLOC);
        let (dx, daq, dasc, dout) = (
            x.as_ref().unwrap(),
            aq.as_ref().unwrap(),
            asc.as_ref().unwrap(),
            out.as_ref().unwrap(),
        );
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        hx.as_mut_slice::<f32>()[..m * k].copy_from_slice(a);
        split_mark(&mut t, crate::prof::Q4P_H2D_STAGE);
        unsafe {
            check(
                (lib.memcpy_htod_async)(dx.ptr(), hx.ptr as *const c_void, bytes_x, std::ptr::null_mut()),
                "cuMemcpyHtoDAsync",
            )?;
            split_mark(&mut t, crate::prof::Q4P_H2D_ISSUE);
            let (mut px, mut paq, mut pasc) = (dx.ptr(), daq.ptr(), dasc.ptr());
            let (mut mc, mut kc) = (m as c_int, k as c_int);
            let mut args = [
                &mut px as *mut _ as *mut c_void,
                &mut paq as *mut _ as *mut c_void,
                &mut pasc as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
            ];
            ctx.launch_async(ctx.f_quant, (m as u32, 1, 1), (256, 1, 1), 256 * 4, &mut args)?;

            let (mut paqi, mut pasci, mut pw, mut psc, mut pout) =
                (daq.ptr(), dasc.ptr(), gw.w.ptr(), gw.sc.ptr(), dout.ptr());
            let (mut mc, mut kc, mut nc) = (m as c_int, k as c_int, n as c_int);
            let mut args = [
                &mut paqi as *mut _ as *mut c_void,
                &mut pasci as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut psc as *mut _ as *mut c_void,
                &mut pout as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            let total = (m * n) as u64;
            let blocks = total.div_ceil(8) as u32;
            ctx.launch_async(ctx.f_mv, (blocks, 1, 1), (256, 1, 1), 0, &mut args)?;
            split_mark(&mut t, crate::prof::Q4P_KERNEL_LAUNCH);

            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dout.ptr(), bytes_out, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync",
            )?;
            split_mark(&mut t, crate::prof::Q4P_D2H_ISSUE);
            // s65: 発行元の件数分類 (表示専用・時間は d2h_state バケット側)
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        ctx.sync()?;
        split_mark(&mut t, crate::prof::Q4P_SYNC_WAIT);
        // s138: ピン留め → 呼び出し側 Vec のコピー (sync の後・表示専用)
        let v = ho.as_slice::<f32>()[..m * n].to_vec();
        split_mark(&mut t, crate::prof::Q4P_HOST_COPY);
        crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        split_flush(&mut t);
        Ok(v)
    })
}

/// P17i: 大きい m (prefill) 用 — tiled GEMM カーネル (dno_gemm_i8) で実行。
/// パイプラインは linear_pinned と同一 (H2D → quantize → gemm → D2H → sync ×1)。
/// 整数累積は順序不変なのでタイル化しても CPU とビット一致。
fn linear_gemm(
    ctx: &CudaCtx,
    a: &[f32],
    gw: &GpuW,
    m: usize,
    k: usize,
    n: usize,
) -> Result<Vec<f32>> {
    let mut out = vec![0.0f32; m * n];
    linear_gemm_into(ctx, a, gw, m, k, n, &mut out)?;
    Ok(out)
}

/// s63: `linear_gemm` の書き込み先指定版 (数値経路は完全に同一)。
///
/// 旧実装は pinned ホストバッファ `ho` から `to_vec()` で **呼び出し毎に
/// m*n*4B の Vec を新規確保**して返していた。prefill では m*n が最大
/// 12288*4096 = 201MB (gate/up は 279MB) に達し、確保 + 初回タッチの
/// ページフォルトが 1 呼び出しあたり 168ms を消費していた (実測 21.8s /
/// prefill 46.2s)。呼び出し側が層をまたいで再利用するバッファを渡す形に
/// することで、確保そのものを無くす (D2H 先は従来どおり pinned `ho`)。
fn linear_gemm_into(
    ctx: &CudaCtx,
    a: &[f32],
    gw: &GpuW,
    m: usize,
    k: usize,
    n: usize,
    dst: &mut [f32],
) -> Result<()> {
    debug_assert_eq!(a.len(), m * k);
    debug_assert_eq!(dst.len(), m * n);
    let lib = lib()?;
    ctx.make_current()?;
    SCRATCH.with(|cell| {
        let mut s = cell.borrow_mut();
        let Scratch { x, aq, asc, out, .. } = &mut *s;
        let bytes_x = m * k * 4;
        let bytes_out = m * n * 4;
        Scratch::ensure(x, bytes_x)?;
        Scratch::ensure(aq, m * k)?;
        Scratch::ensure(asc, m * 4)?;
        Scratch::ensure(out, bytes_out)?;
        let (dx, daq, dasc, dout) = (
            x.as_ref().unwrap(),
            aq.as_ref().unwrap(),
            asc.as_ref().unwrap(),
            out.as_ref().unwrap(),
        );
        unsafe {
            // s68: H2D は呼び出し元のスライスから直接発行する。旧実装は pinned
            // staging へ `copy_from_slice` してから H2D していたため、m=5686,
            // k=4096 では 93MB のホスト間コピーが毎呼び出し余分に乗っていた。
            check(
                (lib.memcpy_htod_async)(
                    dx.ptr(),
                    a.as_ptr() as *const c_void,
                    bytes_x,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync",
            )?;
            let (mut px, mut paq, mut pasc) = (dx.ptr(), daq.ptr(), dasc.ptr());
            let (mut mc, mut kc) = (m as c_int, k as c_int);
            let mut args = [
                &mut px as *mut _ as *mut c_void,
                &mut paq as *mut _ as *mut c_void,
                &mut pasc as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
            ];
            ctx.launch_async(ctx.f_quant, (m as u32, 1, 1), (256, 1, 1), 256 * 4, &mut args)?;

            let (mut paqi, mut pasci, mut pw, mut psc, mut pout) =
                (daq.ptr(), dasc.ptr(), gw.w.ptr(), gw.sc.ptr(), dout.ptr());
            let (mut mc, mut kc, mut nc) = (m as c_int, k as c_int, n as c_int);
            let mut args = [
                &mut paqi as *mut _ as *mut c_void,
                &mut pasci as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut psc as *mut _ as *mut c_void,
                &mut pout as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            // s74: 128x256 タイル × 16x4 thread (1 thread が 8x16 出力)
            let gmx = m.div_ceil(GEMM_TILE) as u32;
            let gmy = n.div_ceil(GEMM_TILE_N) as u32;
            ctx.launch_async(ctx.f_gemm, (gmx, gmy, 1), (GEMM_BX, GEMM_BY, 1), 0, &mut args)?;

            // s68: D2H も呼び出し元のバッファへ直接書く。旧実装は pinned `ho` に
            // 落としてから `dst.copy_from_slice` していたが、pinned→heap の
            // ホスト間コピーが 279MB で 60ms (≒4.7GB/s) かかり GEMM 本体 (12ms)
            // の 5 倍を占めていた。pageable へ直接 D2H すれば 20ms で済む。
            check(
                (lib.memcpy_dtoh_async)(
                    dst.as_mut_ptr() as *mut c_void,
                    dout.ptr(),
                    bytes_out,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyDtoHAsync",
            )?;
            // s65: 発行元の件数分類 (表示専用・時間は d2h_state バケット側)
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        ctx.sync()?;
        Ok(())
    })
}

// ===========================================================================
// s49: fp32 lm_head の GPU 化 (per-op・dno_matvec_f32 流用・.cu/PTX 無変更)
// ===========================================================================
// serve 既定の fp32 モード (--quant fp32) では lm_head が Linear::F32 のまま
// (untied: output.weight / tied: embed) で CPU matvec (tensor::matvec_bt) が
// decode の主律速だった (s45 実機計測: decode 29ms/step の 46.3% = 19.6ms/step)。
// int8 モードの lm_head は P17b (maybe_gpu_linear) / C4 chain
// (chain_linear_grouped) のいずれでも既に GPU・ビット一致のため本節では触れない。
//
// 発動条件: DENNO_CUDA=1 (cuda_enabled) かつ kernels_elem.ptx に dno_matvec_f32
// が収録済み (3931b70 で再生成済み)。カーネルは C4 chain の beta/alpha 制御投影用
// dno_matvec_f32 を**そのまま**流用 (.cu/PTX 変更なし):
//   - 出力 j = blockIdx.x ごとに d を昇順で
//     s = __fadd_rn(s, __fmul_rn(h[d], row[d])) と累積 = tensor::matvec_bt の
//     `s += a[d] * row[d]` (積と加算の丸め分離・d 逐次) と**ビット一致**
//   - カーネルは block 内の全スレッドが同一計算をする実装のため block=(1,1,1)
//     で起動して冗長スレッドを排除する (chain_q35_ctl_f32 の block=(128) は
//     n=数十が前提。vocab n=151936 では 128 倍の冗長演算になる)。grid.x は
//     2^31-1 まで合法なので n>65535 もそのまま扱える (65535 ガードは chain 側
//     呼び出し規約のみでハードウェア限界ではない)。
// - 失敗時は本経路のみのスコープドラッチ (LMV32_BROKEN) で恒久 CPU フォール
//   バック (GPU_BROKEN にはしない = int8 経路への影響ゼロ)。PTX 未収録は
//   q35_fns と同一の None キャッシュ規約 (ラッチ無し・次回プロセス起動まで
//   不発動)。数値はどちらの経路でも同一 (bit 一致) なのでフォールバックは
//   出力を変えない。
// - 重みは呼び出し側が渡すモデルロード毎に一意な key (qwen35 の mid 由来) で
//   グローバル登録し 1 回だけ同期 H2D する (fp32 9B untied で ~2.4GB・初回 1 回
//   のみ。以後は h 16KB の H2D + logits 0.6MB の D2H + sync ×1/ステップ)。

/// s49: fp32 lm_head 経路のスコープド恒久ラッチ (GPU_BROKEN とは独立。
/// 本経路の失敗で int8 経路を落とさない)。
static LMV32_BROKEN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// s49: dno_matvec_f32 のハンドル (lazy fetch・未収録 PTX では None をキャッシュ
/// して恒久不発動 = q35_fns と同一規約・GPU_BROKEN にはしない)。
/// 生ハンドルの静的保持は Q35Fns と同一の規約 (所有権移動なし・driver が
/// スレッド安全に管理) で Send/Sync を与える。
#[derive(Clone, Copy)]
struct Lmv32Fn(CUfunction);
unsafe impl Send for Lmv32Fn {}
unsafe impl Sync for Lmv32Fn {}

/// dno_matvec_f32 のハンドルキャッシュ。s49 (fp32 lm_head) と task 69 (MoE
/// ルータ) が**同じカーネル**を共有するので 1 本にまとめてある。
static MATVEC_F32_FNS: OnceLock<Option<Lmv32Fn>> = OnceLock::new();

/// `dno_matvec_f32` のハンドル (未収録 PTX では None をキャッシュして恒久不発動・
/// ラッチはしない)。カーネルは 1 行 = 1 ブロックで k を昇順に逐次加算し、
/// `mul.rn.f32` + `add.rn.f32` のみ (fma 0 個・ftz 0 個) を PTX で確認済み。
fn matvec_f32_fn(ctx: &CudaCtx) -> Option<CUfunction> {
    MATVEC_F32_FNS
        .get_or_init(|| {
            let lib = lib().ok()?;
            let mut f: CUfunction = std::ptr::null_mut();
            let r = unsafe {
                (lib.module_get_function)(
                    &mut f,
                    ctx.module_elem,
                    b"dno_matvec_f32\0".as_ptr() as *const c_char,
                )
            };
            if r != 0 {
                None
            } else {
                Some(Lmv32Fn(f))
            }
        })
        .as_ref()
        .map(|h| h.0)
}

/// task 121: `dno_matvec_f32_r` (s169 の並列リダクション版) のハンドル。hc mix
/// GPU 経路の長い行 (k >= n) 用。[`matvec_f32_fn`] と同一の lazy fetch 規約で、
/// 未収録 PTX では None をキャッシュする (GPU_BROKEN にはしない = 呼び出し側が
/// 逐次版に落ちるだけ)。生ハンドルの静的保持は Lmv32Fn / Q35Fns と同一の規約
/// (所有権移動なし・driver がスレッド安全に管理) で Send/Sync を与える。
#[derive(Clone, Copy)]
struct Lmv32RFn(CUfunction);
unsafe impl Send for Lmv32RFn {}
unsafe impl Sync for Lmv32RFn {}

static MATVEC_F32_R_FNS: OnceLock<Option<Lmv32RFn>> = OnceLock::new();

/// `dno_matvec_f32_r` のハンドル (未収録 PTX では None)。1 行 = 1 ブロックで
/// k を blockDim スレッドに分割して strided 加算し、warp shuffle の固定木
/// (o = 16,8,4,2,1) → warp 合計を warp id 昇順に加算して縮約する (atomic 無し =
/// 実行ごとに同一結果)。逐次版 `dno_matvec_f32` とは丸め順が違うため bit 一致は
/// しない。launch は grid=(n,1,1) / block=(256,1,1) (s169 の
/// chain_q35_ctl_f32 と同一幾何)。
fn matvec_f32_r_fn(ctx: &CudaCtx) -> Option<CUfunction> {
    MATVEC_F32_R_FNS
        .get_or_init(|| {
            let lib = lib().ok()?;
            let mut f: CUfunction = std::ptr::null_mut();
            let r = unsafe {
                (lib.module_get_function)(
                    &mut f,
                    ctx.module_elem,
                    b"dno_matvec_f32_r\0".as_ptr() as *const c_char,
                )
            };
            if r != 0 {
                None
            } else {
                Some(Lmv32RFn(f))
            }
        })
        .as_ref()
        .map(|h| h.0)
}

