/// s49: fp32 重み (lm_head / tied embed) のデバイスキャッシュ。key はモデル
/// ロード毎に一意 (qwen35 の mid 由来)。無ければ同期 H2D でアップロードし
/// 初回 1 回のみ走る (eviction 無し = P17b 重みレジストリと同一方針)。
static LMV32_W: OnceLock<std::sync::Mutex<std::collections::HashMap<u64, DevBuffer>>> =
    OnceLock::new();

/// s49: fp32 lm_head の matvec (m==1) を GPU で実行する (CPU とビット一致)。
/// 戻り値 None = CPU パスを使うこと (無効/PTX 未収録/実行時エラー)。
/// key: モデルロード毎に一意 (untied と tied で別値にすること)。
pub fn maybe_gpu_matvec_f32(
    key: u64,
    w: &[f32],
    a: &[f32],
    k: usize,
    n: usize,
) -> Option<Vec<f32>> {
    use std::collections::HashMap;
    use std::sync::atomic::Ordering as AO;
    use std::sync::Mutex;
    if !cuda_enabled() || LMV32_BROKEN.load(AO::Relaxed) {
        return None;
    }
    if k == 0
        || n == 0
        || w.len() != k * n
        || a.len() != k
        || k > i32::MAX as usize
        || n > i32::MAX as usize
    {
        return None;
    }
    let ctx = shared_ctx()?;
    if let Err(e) = ctx.make_current() {
        tracing::error!("CUDA cuCtxSetCurrent failed (fp32 lm_head), using CPU: {e:#}");
        LMV32_BROKEN.store(true, AO::Relaxed);
        return None;
    }
    // カーネルハンドル (lazy fetch・None キャッシュ = PTX 未収録はラッチ無し)
    let f = matvec_f32_fn(ctx)?;
    // 重みアップロード (初回 1 回・同期。他スレッドとの二重アップロード防止に
    // ロック内で行う)
    let reg = LMV32_W.get_or_init(|| Mutex::new(HashMap::new()));
    let wp = {
        let mut map = match reg.lock() {
            Ok(g) => g,
            Err(_) => {
                tracing::error!("CUDA fp32 lm_head weight registry poisoned, using CPU");
                LMV32_BROKEN.store(true, AO::Relaxed);
                return None;
            }
        };
        match map.get(&key) {
            Some(b) if b.bytes() == w.len() * 4 => b.ptr(),
            _ => match DevBuffer::from_slice_tagged(w, crate::mem_audit::TAG_LMHEAD) {
                Ok(buf) => {
                    tracing::info!(
                        "CUDA fp32 lm_head weight upload: k={k} n={n} ({:.1} MB)",
                        (k * n * 4) as f64 / 1e6
                    );
                    let p = buf.ptr();
                    map.insert(key, buf);
                    p
                }
                Err(e) => {
                    tracing::error!(
                        "CUDA fp32 lm_head weight upload failed, using CPU permanently: {e:#}"
                    );
                    LMV32_BROKEN.store(true, AO::Relaxed);
                    return None;
                }
            },
        }
    };
    // 実行: H2D(h) → dno_matvec_f32 → D2H(out) → sync ×1 (linear_pinned と同一)
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            tracing::error!("CUDA lib load failed (fp32 lm_head), using CPU: {e:#}");
            LMV32_BROKEN.store(true, AO::Relaxed);
            return None;
        }
    };
    let r = SCRATCH.with(|cell| -> Result<Vec<f32>> {
        let mut s = cell.borrow_mut();
        let Scratch { x, out, hx, ho, .. } = &mut *s;
        let bytes_x = k * 4;
        let bytes_out = n * 4;
        Scratch::ensure(x, bytes_x)?;
        Scratch::ensure(out, bytes_out)?;
        Scratch::ensure_pin(hx, bytes_x)?;
        Scratch::ensure_pin(ho, bytes_out)?;
        let (dx, dout) = (x.as_ref().unwrap(), out.as_ref().unwrap());
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        hx.as_mut_slice::<f32>()[..k].copy_from_slice(a);
        unsafe {
            check(
                (lib.memcpy_htod_async)(dx.ptr(), hx.ptr as *const c_void, bytes_x, std::ptr::null_mut()),
                "cuMemcpyHtoDAsync",
            )?;
            let (mut ph, mut pw, mut po) = (dx.ptr(), wp, dout.ptr());
            let (mut kc, mut nc) = (k as c_int, n as c_int);
            let mut args = [
                &mut ph as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            // 1 block = 1 出力 (カーネルが block 内全スレッドで同一計算するため
            // block=(1,1,1)。grid.x は 2^31-1 まで合法 = vocab 規模もそのまま)
            ctx.launch_async(f, (n as u32, 1, 1), (1, 1, 1), 0, &mut args)?;
            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dout.ptr(), bytes_out, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync",
            )?;
            // s65: 発行元の件数分類 (表示専用・時間は d2h_state バケット側)
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        ctx.sync()?;
        crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LOGITS);
        Ok(ho.as_slice::<f32>()[..n].to_vec())
    });
    match r {
        Ok(out) => Some(out),
        Err(e) => {
            tracing::error!("CUDA fp32 lm_head matvec failed, using CPU permanently: {e:#}");
            LMV32_BROKEN.store(true, AO::Relaxed);
            None
        }
    }
}

// ===========================================================================
// task 69: Flash-Next の MoE ルータ (ffn_gate_inp, f32 512x2560) を GPU へ
// ===========================================================================
// 前提 (main の実測・118 tok / DENNO_Q4_PROFILE=1): router = 1,962.7 ms =
// 16.6 ms/token。48 層 x (512 行 x k=2560) の f32 GEMV = 63 MMAC/token で、
// CPU の実効 3.8 GMAC/s は f32 の帯域 (重み 250 MB/token・50 GB/s なら 5 ms)
// からも大きく外れている。
//
// カーネルは新規に作らず、s49 の fp32 lm_head と同じ `dno_matvec_f32` を流用する
// (.cu / PTX は 1 バイトも変えない = このコンテナでは PTX を再生成できない):
//   - 1 行 = 1 ブロック (grid=(n,1,1))・k を d=0..k-1 の昇順に
//     `s = __fadd_rn(s, __fmul_rn(h[d], row[d]))`
//   - PTX を確認: `mul.rn.f32` + `add.rn.f32` のみ。`fma.rn` 0 個・`.ftz` 0 個
//     (非正規化も保存)。加算の連鎖は d の昇順そのもの (4 倍展開でも鎖は直列)。
//   - CPU 側 (GgufLinear の F32 経路) は同じ 4 バイトを `f32::from_le_bytes` で
//     開き、`acc += row[i] * x[i]` を i 昇順で 1 要素ずつ丸める (FMA 無し・行並列
//     でも行内の順序は不変)。同じ演算列なので**ビット一致**する。
//
// 重みは GGUF ブロックのレジストリと同じ LRU を共有する (`DENNO_GPU_WEIGHT_MB`
// の枠は 1 本。48 層 x 5.2 MB = 250 MB)。枠が足りない・GPU が無い・確保に
// 失敗した場合は全部 CPU 参照へ落ちる (fail-closed・panic しない)。

/// task 69: ルータ GPU 経路のスコープド恒久ラッチ (他の GPU 経路へ波及させない)。
static ROUTER_GPU_BROKEN: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// task 69: ルータ GPU の入口に入った回数 (テスト専用)。
///
/// 「ゲートを足したが分岐が通っていない」を GPU 無しで検出するために、
/// `cuda_enabled()` の判定より**前**で数える (`moe_ffn_quant` → `GgufLinear::gemv`
/// → ここ、の配線が生きていることの証拠)。
#[cfg(test)]
static ROUTER_GPU_ATTEMPTS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);

#[cfg(test)]
pub(crate) fn router_gpu_attempts() -> usize {
    ROUTER_GPU_ATTEMPTS.load(std::sync::atomic::Ordering::Relaxed)
}

#[cfg(test)]
pub(crate) fn router_gpu_attempts_reset() {
    ROUTER_GPU_ATTEMPTS.store(0, std::sync::atomic::Ordering::Relaxed);
}

/// task 127: ルータ GPU のカーネル選択 (純関数・GPU 無しで検証可)。
///
/// ルータ (`ffn_gate_inp`) の実形は 2560 -> 512 の f32 GEMV で、**k >= n の長い行**。
/// 逐次版 `dno_matvec_f32` は 1 ブロック = 1 行・`block=(1,1,1)` なので並列度が
/// 行数 n=512 しかなく、1 スレッドが k=2560 を昇順に舐める。task 69 の却下
/// (2026-10-31) はこの形のまま測っていた。`_r` は 1 ブロック = 1 行のまま
/// block 256 で k をスレッド分割し、warp shuffle の固定木で縮約する
/// (atomic 無し = 実行ごとに同一結果)。丸め順が変わるので CPU の逐次累積とは
/// ビット一致しない ([`mix_use_reduce_kernel`] と同じ扱い・速度優先)。
/// `has_r` は PTX に `_r` が無いとき false となり逐次版に落ちる (fail closed)。
fn router_use_reduce_kernel(k: usize, n: usize, has_r: bool) -> bool {
    has_r && n > 0 && k >= n
}

/// task 127: `DENNO_ROUTER_GPU_REDUCE` の解釈 (純関数)。**既定 on**、明示的な
/// 偽値だけ off。
///
/// ルータ GPU 経路の中だけで効く (`DENNO_ROUTER_GPU` 自体が既定 off なので、
/// 何も設定しないプロセスのモデル挙動は変わらない)。`DENNO_ROUTER_GPU=1` +
/// `DENNO_ROUTER_GPU_REDUCE=0` で逐次版 (task 69 と同じ丸め) に戻せる。
fn router_gpu_reduce_from_value(v: Option<&str>) -> bool {
    match v {
        Some(s) => !matches!(
            s.trim().to_ascii_lowercase().as_str(),
            "0" | "off" | "false" | "no"
        ),
        None => true,
    }
}

/// ルータ GPU 経路で `_r` を使ってよいか (`DENNO_ROUTER_GPU_REDUCE`、既定 on)。
fn router_gpu_reduce_enabled() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        router_gpu_reduce_from_value(std::env::var("DENNO_ROUTER_GPU_REDUCE").ok().as_deref())
    })
}

/// task 127: `_r` を選んだことをプロセスで 1 回だけログる (lab のログで分岐の
/// 発火を確認するため。`router=` の数値だけでは逐次版との区別が付かない)。
static ROUTER_GPU_REDUCE_LOGGED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// task 69: ルータ用スクラッチ。lm_head の `Scratch` と分ける (形が違うので
/// 同じ枠を使うと毎回作り直しになる)。x = [k] f32・out = [n] f32。
struct RouterScratch {
    x: Option<DevBuffer>,
    out: Option<DevBuffer>,
    hx: Option<PinMem>,
    ho: Option<PinMem>,
}

thread_local! {
    static ROUTER_SC: std::cell::RefCell<RouterScratch> = std::cell::RefCell::new(RouterScratch {
        x: None,
        out: None,
        hx: None,
        ho: None,
    });
}

/// task 69: f32 重みを (初回だけ) VRAM へ上げて常駐エントリを返す。
///
/// レジストリは GGUF ブロックと同じ (`gguf_registry`)。予算・退避・使用中ピン・
/// 失敗時の会計は `weights_for_gguf` と同一の規約で、違うのは行の単位
/// (k * 4 バイト固定) だけ。
fn weights_for_f32(uid: u64, bytes: &[u8], k: usize, n: usize) -> Result<GgufWRef> {
    use crate::kquant::GgmlType as T;
    let reg = gguf_registry();
    let mut g = reg
        .lock()
        .map_err(|_| anyhow::anyhow!("gguf weights registry poisoned"))?;
    if g.map.contains_key(&uid) {
        let e = g.map.get(&uid).expect("contains_key");
        let (ek, en, ety) = (e.k, e.n, e.ty);
        if (ek, en, ety) != (k, n, T::F32) {
            bail!(
                "uid 重複: 同一 uid {uid} に別の形状/型 (登録済み k={ek} n={en} ty={ety:?} / 今回 k={k} n={n} ty=F32)"
            );
        }
        g.lru.touch(uid);
        g.lru.pin(uid);
        let e = g.map.get(&uid).expect("pinned");
        let w = unsafe { std::mem::transmute::<&GpuGgufW, &'static GpuGgufW>(e.as_ref()) };
        return Ok(GgufWRef { w, uid });
    }
    let want = n
        .checked_mul(k)
        .and_then(|v| v.checked_mul(4))
        .ok_or_else(|| anyhow::anyhow!("f32: n * k * 4 が usize を溢れる"))?;
    if bytes.len() != want {
        bail!(
            "f32: バイト数 {} が n * k * 4 = {} と違う (k={k}, n={n})",
            bytes.len(),
            want
        );
    }
    // P46 と同じ: 確保の前に上限と空き VRAM を見て古い uid を解放する。
    let cap = crate::gpu_budget::weight_cap_bytes();
    let free_mb = if cap == 0 {
        None
    } else {
        dev_mem_mb().map(|(f, _total)| f as u64)
    };
    let ev0 = (g.lru.evicted_tensors(), g.lru.evicted_bytes());
    let victims =
        crate::gpu_budget::plan_weight_evictions(&mut g.lru, uid, want as u64, cap, free_mb);
    let mut dropped: Vec<u64> = Vec::new();
    for v in &victims {
        if g.map.remove(v).is_some() {
            dropped.push(*v);
        }
    }
    let freed = g.lru.evicted_bytes().saturating_sub(ev0.1);
    let freed_n = g.lru.evicted_tensors().saturating_sub(ev0.0);
    if freed_n > 0 {
        crate::gpu_budget::note_weight_evicted(freed_n, freed);
    }
    // 生バイトのスライスは 4 バイト整列を保証しない (`Vec<u8>` / mmap の途中) ので、
    // CPU と同じ `from_le_bytes` で f32 に開いてから上げる (値は 1 bit も変わらない)。
    let mut host: Vec<f32> = Vec::with_capacity(k * n);
    for c in bytes.chunks_exact(4) {
        host.push(f32::from_le_bytes([c[0], c[1], c[2], c[3]]));
    }
    let buf = match DevBuffer::from_slice_tagged(&host, crate::mem_audit::TAG_ROUTER) {
        Ok(b) => b,
        Err(e) => {
            g.lru.note_remove(uid);
            return Err(e);
        }
    };
    tracing::info!(
        "CUDA f32 weight upload (uid={uid}): router k={k} n={n} ({:.1} MB)",
        want as f64 / 1e6
    );
    g.map.insert(uid, Box::new(GpuGgufW { buf, ty: T::F32, k, n }));
    g.lru.pin(uid);
    let resident = g.map.len();
    let used = g.lru.used_bytes();
    let w = {
        let e = g.map.get(&uid).expect("just inserted");
        unsafe { std::mem::transmute::<&GpuGgufW, &'static GpuGgufW>(e.as_ref()) }
    };
    drop(g);
    crate::gpu_budget::note_weight_upload();
    crate::gpu_budget::note_weight_upload_bytes(want as u64);
    crate::gpu_budget::note_weight_resident(resident, used);
    if w_dbg() {
        let free = match dev_mem_mb() {
            Some((f, t)) => format!("空き {f} MiB / 全 {t} MiB"),
            None => "空き 不明".to_string(),
        };
        let ev = if dropped.is_empty() {
            String::new()
        } else {
            format!(
                " / 今回退避 {} 本 {:.1} MiB",
                dropped.len(),
                freed as f64 / (1 << 20) as f64
            )
        };
        tracing::info!(
            target: "denno_engine::gpu_w",
            "[gpu-w] uid={uid} f32 router k={k} n={n} {:.2} MB / 常駐 {} 本 {:.1} MiB{ev} / {free}",
            want as f64 / 1e6,
            resident,
            used as f64 / (1 << 20) as f64,
        );
    }
    Ok(GgufWRef { w, uid })
}

/// task 69: ルータ f32 重みの常駐エントリを解放する (`GgufLinear::drop` から)。
/// 載っていない uid・量子化型の uid は触らない。
pub fn unregister_f32_weights(uid: u64) {
    let Ok(mut g) = gguf_registry().lock() else {
        return;
    };
    let is_f32 = g
        .map
        .get(&uid)
        .map(|e| e.ty == crate::kquant::GgmlType::F32)
        .unwrap_or(false);
    if is_f32 {
        g.map.remove(&uid);
        let freed = g.lru.note_remove(uid);
        if freed > 0 {
            crate::gpu_budget::note_weight_resident(g.map.len(), g.lru.used_bytes());
        }
    }
}

/// task 69: ルータ (f32・m=1) を GPU で計算して `out` に書く。
///
/// `false` = 呼び出し側は CPU 参照で計算すること (GPU 無効・PTX 未収録・予算外・
/// 実行時エラー)。逐次版 `dno_matvec_f32` のときは CPU 経路とビット一致するので
/// どちらに落ちても出力は変わらない。task 127 で既定は並列リダクション版
/// `dno_matvec_f32_r` (丸め順が違う = ビット一致しない・決定論は保つ。
/// `DENNO_ROUTER_GPU_REDUCE=0` で逐次版に戻る)。
pub fn maybe_gpu_router_gemv_into(
    uid: u64,
    bytes: &[u8],
    k: usize,
    n: usize,
    x: &[f32],
    out: &mut [f32],
) -> bool {
    use std::sync::atomic::Ordering as AO;
    #[cfg(test)]
    ROUTER_GPU_ATTEMPTS.fetch_add(1, AO::Relaxed);
    if !cuda_enabled() || ROUTER_GPU_BROKEN.load(AO::Relaxed) {
        return false;
    }
    if k == 0
        || n == 0
        || x.len() != k
        || out.len() != n
        || bytes.len() != k.saturating_mul(n).saturating_mul(4)
        || k > i32::MAX as usize
        || n > i32::MAX as usize
    {
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if let Err(e) = ctx.make_current() {
        tracing::error!("CUDA cuCtxSetCurrent failed (router f32), using CPU: {e:#}");
        ROUTER_GPU_BROKEN.store(true, AO::Relaxed);
        return false;
    }
    // カーネルハンドル (未収録 PTX は None をキャッシュ = ラッチしない)。
    // task 127: ルータは k=2560 >= n=512 の長い行なので、`_r` (1 ブロック = 1 行・
    // block 256・固定木縮約) が選べるならそちらを使う。逐次版は 1 ブロック =
    // 1 スレッドで並列度が行数 n しかない (task 69 の却下はこの形だった)。
    // `_r` が未収録 / `DENNO_ROUTER_GPU_REDUCE=0` なら逐次版に落ちる (fail closed)。
    let f_seq = matvec_f32_fn(ctx);
    let f_red = matvec_f32_r_fn(ctx);
    let use_reduce = router_gpu_reduce_enabled() && router_use_reduce_kernel(k, n, f_red.is_some());
    if !use_reduce && f_seq.is_none() {
        return false;
    }
    let prof = crate::model::devprof::on();
    let up_before = if prof {
        crate::gpu_budget::weight_upload_bytes()
    } else {
        0
    };
    let w = match weights_for_f32(uid, bytes, k, n) {
        Ok(w) => w,
        Err(e) => {
            tracing::error!(
                "router f32 weight register failed (uid={uid}), using CPU permanently: {e:#}"
            );
            ROUTER_GPU_BROKEN.store(true, AO::Relaxed);
            return false;
        }
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            tracing::error!("CUDA lib load failed (router f32), using CPU: {e:#}");
            ROUTER_GPU_BROKEN.store(true, AO::Relaxed);
            return false;
        }
    };
    let r = ROUTER_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let RouterScratch {
            x: dx,
            out: dout,
            hx,
            ho,
        } = &mut *s;
        let bytes_x = k * 4;
        let bytes_out = n * 4;
        Scratch::ensure(dx, bytes_x)?;
        Scratch::ensure(dout, bytes_out)?;
        Scratch::ensure_pin(hx, bytes_x)?;
        Scratch::ensure_pin(ho, bytes_out)?;
        let (dx, dout) = (dx.as_ref().unwrap(), dout.as_ref().unwrap());
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        hx.as_mut_slice::<f32>()[..k].copy_from_slice(x);
        unsafe {
            check(
                (lib.memcpy_htod_async)(
                    dx.ptr(),
                    hx.ptr as *const c_void,
                    bytes_x,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync",
            )?;
            let (mut ph, mut pw, mut po) = (dx.ptr(), w.buf.ptr(), dout.ptr());
            let (mut kc, mut nc) = (k as c_int, n as c_int);
            let mut args = [
                &mut ph as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            // task 127: 長い行 (k >= n) は `_r` (1 ブロック = 1 行・block 256 で
            // k を分割し warp shuffle の固定木で縮約・決定論)、それ以外と
            // ゲート off は従来どおり逐次版 (カーネルが block 内全スレッドで
            // 同一計算するため block=(1,1,1))。grid.x は 2^31-1 まで合法。
            let (mv_fn, mv_thr): (CUfunction, u32) = if use_reduce {
                (f_red.expect("use_reduce は has_r=true を要求する"), 256)
            } else {
                (f_seq.expect("use_reduce=false は逐次版のハンドルを要求する"), 1)
            };
            if use_reduce && !ROUTER_GPU_REDUCE_LOGGED.swap(true, AO::Relaxed) {
                tracing::info!(
                    "[router-gpu] dno_matvec_f32_r を使用 (block 256・k={k} n={n})"
                );
            }
            ctx.launch_async(mv_fn, (n as u32, 1, 1), (mv_thr, 1, 1), 0, &mut args)?;
            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dout.ptr(), bytes_out, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync",
            )?;
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        // task 155: 待つのは null ストリームのぶんだけ (重ね打ち中の shared
        // expert のサイドストリームは待たない)。イベントが無ければ従来どおり。
        sync_default_or_ctx(ctx, router_fused_enabled())?;
        out.copy_from_slice(&ho.as_slice::<f32>()[..n]);
        Ok(())
    });
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            if prof {
                let up_w = crate::gpu_budget::weight_upload_bytes().saturating_sub(up_before);
                crate::model::devprof::note_bytes(k as u64 * 4 + up_w, n as u64 * 4);
            }
            true
        }
        Err(e) => {
            tracing::error!("CUDA router f32 gemv failed, using CPU permanently: {e:#}");
            ROUTER_GPU_BROKEN.store(true, AO::Relaxed);
            false
        }
    }
}

// ===========================================================================
// task 110: hc mix (hc_down / hc_up) の BF16 GEMV を GPU へ (decode 96 回/token)
// ===========================================================================
// 実測 (メインセッション 2026-11-02、swift15 IQ3_S、DENNO_MIX_KPROF=1): decode
// mix 47.1 ms/tok の 91% が hc_down / hc_up の BF16 GEMV。down = [10240->320] /
// up = [320->10240]、48 層 x 2 = 96 回/token、重み 630 MB/token を CPU が読む
// 帯域律速 (316 MMAC/token で 42.9 ms = 7.4 GMAC/s)。
//
// カーネルは新規に作らず、s49 / task 69 と同じ `dno_matvec_f32` を流用する
// (.cu / PTX は 1 バイトも変えない。BF16 を直接読むカーネルは現行 PTX に無い):
//   - 1 行 = 1 ブロック (grid=(n,1,1)・block=(1,1,1))・k 昇順の直列加算。
//     PTX は `mul.rn.f32` + `add.rn.f32` のみ (fma.rn 0 個・.ftz 0 個)。
//   - CPU 参照は `kquant::dequant_row_into` (BF16 -> f32 は上位 16bit 複製 =
//     情報落ちなし) + 1 行の `acc += row[i] * x[i]` (i 昇順・積と加算の丸め分離)。
//     同じ演算列なので**ビット一致**する (task 92 の AVX2 融合カーネルも
//     「積を i 昇順で逐次加算・FMA 無し」で classic とビット一致済み)。
//   - BF16 のまま VRAM に載せられない (カーネルは f32 を読む) ため f32 に展開
//     して常駐する (630 MB BF16 -> 1,260 MB f32。BF16 -> f32 は情報落ちなしで
//     値は不変)。展開は初回の GPU 呼び出しで 1 回だけ。
//   - 常駐は s49 (LMV32_W) と同じ**専用レジストリ** (eviction 無し・uid key)。
//     gguf_registry (DENNO_GPU_WEIGHT_MB) にも expert LRU (DENNO_EXPERT_VRAM_MB)
//     にも乗らないので、ルータ / lm_head / expert と枠を奪い合わない。
//   - 失敗時 (VRAM 足りない等) は CPU へフォールバックして warning を 1 行だけ
//     出す (MIX_GPU_BROKEN ラッチ。2 回目以降は warn 無しで静かに CPU に落ちる)。
//     cuda_enabled() が false (GPU 無し・DENNO_CUDA 未設定) は正常フォール
//     バックなので warn を出さない。

/// task 110: hc mix BF16 経路のスコープド恒久ラッチ (s49 / task 69 とは独立。
/// 本経路の失敗で他の GPU 経路を落とさない)。
static MIX_GPU_BROKEN: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// task 110: hc mix BF16 経路の入口に入った回数 (テスト専用)。
/// 「ゲートを足したが分岐が通っていない」を GPU 無しで検出するために、
/// `cuda_enabled()` の判定より**前**で数える (task 69 の ROUTER_GPU_ATTEMPTS
/// と同じ流儀)。
#[cfg(test)]
static MIX_GPU_ATTEMPTS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);

/// task 110: [`MIX_GPU_ATTEMPTS`] を読む (テスト専用)。
#[cfg(test)]
pub(crate) fn mix_gpu_attempts() -> usize {
    MIX_GPU_ATTEMPTS.load(std::sync::atomic::Ordering::Relaxed)
}

/// task 110: hc mix BF16 経路の失敗 warning (1 行だけ。ラッチは swap で 1 回保証)。
fn mix_gpu_broken_once(msg: &str) {
    let prev = MIX_GPU_BROKEN.swap(true, std::sync::atomic::Ordering::Relaxed);
    if !prev {
        tracing::warn!("CUDA hc mix BF16 GPU disabled, using CPU: {msg}");
    }
}

/// task 110: BF16 重みを f32 に展開する (行ごとに [`crate::kquant::dequant_row_into`]
/// を通す = BF16 -> f32 変換の定義を 1 か所に保つ。BF16 は f32 の上位 16bit なので
/// 情報落ちは無い)。
fn mix_expand_bf16(bytes: &[u8], k: usize, n: usize) -> Vec<f32> {
    let rb = k * 2;
    let mut out = vec![0f32; k * n];
    let mut row = vec![0f32; k];
    for r in 0..n {
        crate::kquant::dequant_row_into(
            crate::kquant::GgmlType::Bf16,
            &bytes[r * rb..(r + 1) * rb],
            &mut row,
        );
        out[r * k..(r + 1) * k].copy_from_slice(&row);
    }
    out
}

/// task 110: 展開済み f32 重みの常駐エントリ (s49 の LMV32_W と同じ方針:
/// eviction 無し・uid key。解放は [`mix_gpu_unregister`] が `GgufLinear::drop` から)。
///
/// task 152: `bf16 == true` のときは `buf` が **BF16 の生バイト** (k*n*2 B) で、
/// カーネルは `dno_matvec_bf16*` / `dno_gemm_bf16_mt` を使う。f32 展開しないので
/// 常駐が半分になる (lab t149c の w:mix_f32 2,425 MiB のうち約 1,200 MiB が戻る)。
struct MixGpuW {
    buf: DevBuffer,
    k: usize,
    n: usize,
    bf16: bool,
}

/// task 152: 常駐重みのポインタ (モードは呼び出し側が先に決めている)。
#[derive(Clone, Copy)]
struct MixW {
    ptr: CUdeviceptr,
}

/// task 152: `DENNO_MIX_BF16` の解釈 (純関数)。明示的な真値だけ on。
/// 既定は [`MIX_BF16_DEFAULT`] (lab の採否で決める)。
fn mix_bf16_from_value(v: Option<&str>, default_on: bool) -> bool {
    match v.map(|s| s.trim().to_ascii_lowercase()) {
        Some(s) if matches!(s.as_str(), "1" | "true" | "on" | "yes") => true,
        Some(s) if matches!(s.as_str(), "0" | "false" | "off" | "no") => false,
        _ => default_on,
    }
}

/// task 152: BF16 のまま読むカーネルを使うか (`DENNO_MIX_BF16`)。
fn mix_bf16_enabled() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        mix_bf16_from_value(std::env::var("DENNO_MIX_BF16").ok().as_deref(), MIX_BF16_DEFAULT)
    })
}

static MIX_GPU_W: OnceLock<std::sync::Mutex<std::collections::HashMap<u64, MixGpuW>>> =
    OnceLock::new();

/// task 110: hc mix 用スクラッチ。ルータの RouterScratch と分ける (mix down は
/// x=41KB/out=1.3KB、up は x=1.3KB/out=41KB と交互に来るが grow-only なので
/// 41KB x 2 で固定)。decode は 1 スレッド直列だが thread_local にする理由は同じ。
struct MixGpuScratch {
    x: Option<DevBuffer>,
    /// task 138: チェーン経路の down 出力 (lo_apply 済み) を device に置く場所。
    lo: Option<DevBuffer>,
    out: Option<DevBuffer>,
    /// task 150: chain2 の hc_mixed 出力 ([e]) を device に置く場所。
    mixed: Option<DevBuffer>,
    hx: Option<PinMem>,
    ho: Option<PinMem>,
}

thread_local! {
    static MIX_GPU_SC: std::cell::RefCell<MixGpuScratch> =
        std::cell::RefCell::new(MixGpuScratch {
            x: None,
            lo: None,
            out: None,
            mixed: None,
            hx: None,
            ho: None,
        });
}

/// task 121: mix GPU で並列リダクション版 (`dno_matvec_f32_r`) に切り替える
/// 「長い行」の閾値 (k >= n × この比)。実測 (swift15-abl IQ3_S・128 tok・main) では
/// down (k=10240, n=320) が 281 us/行列とほぼ直列 (1 ブロック = 1 行で k を 1
/// スレッドが舐めるため並列度が n しかない) で、up (k=320, n=10240) は 55
/// us/行列と n 側に並列度が足りている。比 1.0 = k が n 以上なら `_r` を使う。
const MIX_REDUCE_MIN_RATIO: f64 = 1.0;

/// task 121: mix GPU matvec のカーネル選択 (純関数・GPU 無しで検証可)。
/// true = `dno_matvec_f32_r` (block 256・k をスレッド分割して warp shuffle の
/// 固定木で縮約・決定論) / false = `dno_matvec_f32` (block 1・k 逐次)。
/// 長い行 (k >= n × [`MIX_REDUCE_MIN_RATIO`]) だけ `_r` にする。短い行は並列度が
/// 行数 n 側にあり逐次版で十分 (これを `_r` に変えると up が遅くなる)。
/// 縮退形 (n == 0) は安全側で逐次版 (実際は呼び出し側の形状検査が先に弾く)。
/// `has_r` は PTX に `_r` が無いとき false となり逐次版に落ちる (fail closed・
/// エラーにはしない)。[`fast_reduce_enabled`] (DENNO_FAST_REDUCE) には依存しない
/// (mix の長い行はオペレーター方針で bit 一致契約の外 = 速度優先・決定論のみ)。
fn mix_use_reduce_kernel(k: usize, n: usize, has_r: bool) -> bool {
    has_r && n > 0 && (k as f64) >= (n as f64) * MIX_REDUCE_MIN_RATIO
}

/// task 110 (task 121 で長い行を並列リダクション版に): hc mix BF16 (m==1) の
/// GEMV を GPU で実行する。
///
/// 戻り値 false = CPU パスを使うこと (GPU 無効・PTX 未収録・形状不一致・確保失敗・
/// 実行エラー)。数値は短い行 (k < n) が CPU 経路とビット一致するので、そちらは
/// どちらに落ちても出力は変わらない。長い行 (k >= n、[`mix_use_reduce_kernel`])
/// は s169 の並列リダクション版 `dno_matvec_f32_r` (block 256・warp shuffle の
/// 固定木) を使い、丸め順が CPU の逐次累積と違うためビット一致は**しない**
/// (実行ごとの決定論は保つ。オペレーター方針: 速度優先)。uid は `GgufLinear` の
/// もの (モデルロード毎に一意) で、そのまま常駐レジストリの key にする。bytes は
/// BF16 の生バイト (k * n * 2)。
///
/// ゲート (`DENNO_MIX_GPU`、既定 off) の判定は呼び出し側 (qwen4exp の
/// hc_mix_quant_fast) が持つ。
pub fn maybe_gpu_mix_bf16_into(
    uid: u64,
    bytes: &[u8],
    k: usize,
    n: usize,
    x: &[f32],
    out: &mut [f32],
) -> bool {
    use std::sync::atomic::Ordering as AO;
    #[cfg(test)]
    MIX_GPU_ATTEMPTS.fetch_add(1, AO::Relaxed);
    if !cuda_enabled() {
        return false;
    }
    if MIX_GPU_BROKEN.load(AO::Relaxed) {
        return false;
    }
    if k == 0
        || n == 0
        || x.len() != k
        || out.len() != n
        || bytes.len() != k.saturating_mul(n).saturating_mul(2)
        || k > i32::MAX as usize
        || n > i32::MAX as usize
    {
        mix_gpu_broken_once(&format!(
            "shape mismatch (k={k}, n={n}, bytes={} / want {})",
            bytes.len(),
            k.saturating_mul(n).saturating_mul(2)
        ));
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        mix_gpu_broken_once("shared_ctx() is None");
        return false;
    };
    if let Err(e) = ctx.make_current() {
        mix_gpu_broken_once(&format!("cuCtxSetCurrent: {e:#}"));
        return false;
    }
    // カーネルハンドル (lazy fetch)。未収録 PTX は 1 行 warn して CPU に落とす。
    // task 152: `DENNO_MIX_BF16=1` かつ BF16 カーネルが PTX にあれば、重みを f32 に
    // 展開せず BF16 のまま読む (常駐が半分)。無ければ従来の f32 展開経路。
    let want_bf16 = mix_bf16_enabled() && matvec_bf16_fn(ctx).is_some();
    let (f_seq, f_red) = if want_bf16 {
        (matvec_bf16_fn(ctx), matvec_bf16_r_fn(ctx))
    } else {
        (matvec_f32_fn(ctx), matvec_f32_r_fn(ctx))
    };
    let Some(f) = f_seq else {
        mix_gpu_broken_once("kernels_elem.ptx に dno_matvec_f32 が無い (PTX 再生成が必要)");
        return false;
    };
    // task 121: 長い行 (k >= n) は s169 の並列リダクション版 (`dno_matvec_f32_r`)
    // を使う。逐次版は 1 ブロック = 1 行で k を 1 スレッドが舐めるため、down
    // (k=10240, n=320) のような形で並列度が足りない (実測 281 us/行列・ほぼ DRAM
    // 律速に達しない)。`_r` は DENNO_FAST_REDUCE と無関係にこの経路だけで選ぶ
    // (mix の長い行はオペレーター方針で bit 一致契約の外)。PTX に `_r` が無ければ
    // (Option が None) 逐次版に落ちる = 失敗にはしない (fail closed)。
    let fr = f_red;
    let use_reduce = mix_use_reduce_kernel(k, n, fr.is_some());
    // 重みの展開 + 常駐 (初回 1 回・同期 H2D)。ロック内で二重アップロード防止。
    let wp = match mix_gpu_weight(uid, bytes, k, n, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("hc mix 重みの常駐に失敗: {e:#}"));
            return false;
        }
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            mix_gpu_broken_once(&format!("CUDA lib load failed: {e:#}"));
            return false;
        }
    };
    let r = MIX_GPU_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let MixGpuScratch {
            x: dx,
            out: dout,
            hx,
            ho,
            ..
        } = &mut *s;
        let bytes_x = k * 4;
        let bytes_out = n * 4;
        Scratch::ensure(dx, bytes_x)?;
        Scratch::ensure(dout, bytes_out)?;
        Scratch::ensure_pin(hx, bytes_x)?;
        Scratch::ensure_pin(ho, bytes_out)?;
        let (dx, dout) = (dx.as_ref().unwrap(), dout.as_ref().unwrap());
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        hx.as_mut_slice::<f32>()[..k].copy_from_slice(x);
        unsafe {
            check(
                (lib.memcpy_htod_async)(
                    dx.ptr(),
                    hx.ptr as *const c_void,
                    bytes_x,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync",
            )?;
            let (mut ph, mut pw, mut po) = (dx.ptr(), wp, dout.ptr());
            let (mut kc, mut nc) = (k as c_int, n as c_int);
            let mut args = [
                &mut ph as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            // task 121: 長い行は `_r` (1 ブロック = 1 行・block 256 で k を分割し
            // warp shuffle の固定木で縮約・決定論)、短い行は従来どおり逐次版
            // (カーネルが block 内全スレッドで同一計算するため block=(1,1,1)。
            // grid.x は 2^31-1 まで合法)。
            let (mv_fn, mv_thr): (CUfunction, u32) = if use_reduce {
                (fr.expect("use_reduce は has_r=true を要求する"), 256)
            } else {
                (f, 1)
            };
            ctx.launch_async(mv_fn, (n as u32, 1, 1), (mv_thr, 1, 1), 0, &mut args)?;
            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dout.ptr(), bytes_out, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync",
            )?;
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        ctx.sync()?;
        out.copy_from_slice(&ho.as_slice::<f32>()[..n]);
        Ok(())
    });
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            mix_gpu_broken_once(&format!("hc mix BF16 matvec failed: {e:#}"));
            false
        }
    }
}

/// task 145: `dno_gemm_f32_mt` (f32 重み × m トークンの GEMM) のハンドル。
///
/// kernels_elem.ptx に未収録なら None をキャッシュする (呼び出し側は CPU の
/// バッチ経路へ落ちるだけで、失敗にはしない = fail closed)。
#[derive(Clone, Copy)]
struct LgemmMtFn(CUfunction);
unsafe impl Send for LgemmMtFn {}
unsafe impl Sync for LgemmMtFn {}

static GEMM_F32_MT_FNS: OnceLock<Option<LgemmMtFn>> = OnceLock::new();

fn gemm_f32_mt_fn(ctx: &CudaCtx) -> Option<CUfunction> {
    GEMM_F32_MT_FNS
        .get_or_init(|| {
            let lib = lib().ok()?;
            let mut f: CUfunction = std::ptr::null_mut();
            let r = unsafe {
                (lib.module_get_function)(
                    &mut f,
                    ctx.module_elem,
                    b"dno_gemm_f32_mt\0".as_ptr() as *const c_char,
                )
            };
            if r != 0 {
                None
            } else {
                Some(LgemmMtFn(f))
            }
        })
        .as_ref()
        .map(|h| h.0)
}

/// task 145 のカーネル幾何 (kernels_elem.cu の `dno_gemm_f32_mt` と 1:1)。
pub const GEMM_MT_ROWS: usize = 16;
/// 1 ブロックが担当するトークン数。
pub const GEMM_MT_TOKS: usize = 32;

/// task 145: prefill の hc mix (BF16 重み) を **m トークンまとめて** GPU で回す。
///
/// `out[t * n + r] = dot(bf16 を f32 展開した行 r, xs[t])`。
/// 重みは decode の mix GPU 経路と**同じ常駐バッファ** ([`mix_gpu_weight`]) を
/// 使うので、既に載っていれば転送は起きない。1 呼び出し = H2D 1 回 + 起動 1 回 +
/// 同期 1 回 + D2H 1 回。数値は FMA + タイル順なので CPU の mul+add 逐次とは
/// ビット一致しない (prefill のバッチ行列積は速度優先の契約)。
///
/// `false` = GPU でやらなかった (呼び出し側は CPU バッチへ)。
pub fn maybe_gpu_mix_bf16_batch_into(
    uid: u64,
    bytes: &[u8],
    k: usize,
    n: usize,
    xs: &[f32],
    nt: usize,
    out: &mut [f32],
) -> bool {
    if !cuda_enabled() || MIX_GPU_BROKEN.load(std::sync::atomic::Ordering::Relaxed) {
        return false;
    }
    if k == 0
        || n == 0
        || nt < 2
        || xs.len() != nt * k
        || out.len() != nt * n
        || bytes.len() != k.saturating_mul(n).saturating_mul(2)
        || k > i32::MAX as usize
        || n > i32::MAX as usize
        || nt > i32::MAX as usize
    {
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if let Err(e) = ctx.make_current() {
        mix_gpu_broken_once(&format!("cuCtxSetCurrent (batch): {e:#}"));
        return false;
    }
    // task 152: BF16 カーネルがあれば重みを BF16 のまま置く (常駐が半分)。
    let want_bf16 = mix_bf16_enabled() && gemm_bf16_mt_fn(ctx).is_some();
    let f = if want_bf16 {
        gemm_bf16_mt_fn(ctx)
    } else {
        gemm_f32_mt_fn(ctx)
    };
    let Some(f) = f else {
        // PTX 未収録 (PTX=elem の再生成待ち)。ラッチはしない。
        return false;
    };
    let wp = match mix_gpu_weight(uid, bytes, k, n, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("batch の重み常駐に失敗: {e:#}"));
            return false;
        }
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            mix_gpu_broken_once(&format!("CUDA lib load failed (batch): {e:#}"));
            return false;
        }
    };
    let r = MIX_GPU_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let MixGpuScratch {
            x: dx, out: dout, ..
        } = &mut *s;
        let bytes_x = nt * k * 4;
        let bytes_out = nt * n * 4;
        Scratch::ensure(dx, bytes_x)?;
        Scratch::ensure(dout, bytes_out)?;
        let (dx, dout) = (dx.as_ref().unwrap(), dout.as_ref().unwrap());
        // s68 の実測 (pinned 経由 + memcpy は pageable 直の 4 倍遅い) に従い、
        // ホスト側のコピーを挟まず呼び出し元のスライス / 出力先へ直接発行する。
        dx.copy_from(xs)?;
        unsafe {
            let (mut pw, mut px, mut po) = (wp, dx.ptr(), dout.ptr());
            let (mut nt_c, mut k_c, mut n_c) = (nt as c_int, k as c_int, n as c_int);
            let mut args = [
                &mut pw as *mut _ as *mut c_void,
                &mut px as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut nt_c as *mut _ as *mut c_void,
                &mut k_c as *mut _ as *mut c_void,
                &mut n_c as *mut _ as *mut c_void,
            ];
            let grid = (
                ((n + GEMM_MT_ROWS - 1) / GEMM_MT_ROWS) as u32,
                ((nt + GEMM_MT_TOKS - 1) / GEMM_MT_TOKS) as u32,
                1,
            );
            ctx.launch_async(f, grid, (GEMM_MT_ROWS as u32, 16, 1), 0, &mut args)?;
            ctx.sync()?;
            // D2H は同期コピーで `out` へ直接 (中間 Vec / pinned を作らない)。
            check(
                (lib.memcpy_dtoh)(
                    out.as_mut_ptr() as *mut c_void,
                    dout.ptr(),
                    bytes_out,
                ),
                "cuMemcpyDtoH (mix batch)",
            )?;
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        Ok(())
    });
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            mix_gpu_broken_once(&format!("hc mix BF16 batch GEMM failed: {e:#}"));
            false
        }
    }
}


// ---------------------------------------------------------------------------
// task 154: prefill のデバイス常駐 mix 連鎖 (`DENNO_PF_RESIDENT`)
// ---------------------------------------------------------------------------
//
// 狙い: hc mix 1 回ごとの往復 (res H2D → down GEMM → lo D2H → lo H2D → up GEMM →
// gate D2H → ホストで norm/silu/gating) を、デバイス上の 1 連鎖に置き換える。
// 入力 `res` はチャンク開始時に 1 回だけ上げ、以後は層をまたいでデバイスに置く
// (`pf_upload_res` / `pf_download_res` は呼び出し側が層の境界でだけ使う)。
//
// 使うカーネル:
//   dno_pf_rmsgroup / dno_pf_lo / dno_pf_mixed / dno_pf_inj / dno_pf_combine
//   (kernels_pf.cu、PTX は `bash build_ptx.sh pf`) と、既存の
//   dno_gemm_bf16_mt (k=hc_dim→low_rank と low_rank→hc_dim と hc_dim→hc)。
//
// 数値: 要素演算は CPU 参照と 1 演算 1 丸めで一致するように書いてある
// (二乗和は i 昇順の逐次)。GEMM は task 145 のバッチ mix と同じ
// `dno_gemm_bf16_mt` なので、`DENNO_MIX_BATCH_GPU=1` のときの値と一致する。

struct PfKernels {
    #[allow(dead_code)]
    module: CUmodule,
    rmsgroup: CUfunction,
    lo: CUfunction,
    mixed: CUfunction,
    inj: CUfunction,
    combine: CUfunction,
}

// 生ハンドル (CudaCtx / MoeBatchKernels と同じ規約)。
unsafe impl Send for PfKernels {}
unsafe impl Sync for PfKernels {}

const PF_NAMES: [&[u8]; 5] = [
    b"dno_pf_rmsgroup\0",
    b"dno_pf_lo\0",
    b"dno_pf_mixed\0",
    b"dno_pf_inj\0",
    b"dno_pf_combine\0",
];

/// task 154: 常駐連鎖の PTX。lab t154e が `PTX=pf` で `kernels_pf.cu` から
/// 再生成したものをそのまま収録した (5 本の entry を含む)。
///
/// `include_bytes!` にする理由: 既定 on の経路なので、実行時にクレート配下の
/// `kernels/` が無い配置でも黙って CPU へ落ちないようにする (task 151 の
/// `kernels_exp_iq_pf.ptx` はファイル読みだが、あちらは既定 on の判断が後追い)。
const PTX_PF: &[u8] = include_bytes!("../kernels/kernels_pf.ptx");

/// `DENNO_PF_PTX` があればそのイメージ、無ければコミット済みの [`PTX_PF`]。
fn pf_ptx_image() -> Option<Vec<u8>> {
    match std::env::var("DENNO_PF_PTX") {
        Ok(p) if !p.is_empty() => {
            let path = std::path::Path::new(&p);
            match std::fs::read(path) {
                Ok(b) => Some(b),
                Err(e) => {
                    tracing::info!(
                        "[pf] PTX が読めない ({}): {e} → CPU 経路",
                        path.display()
                    );
                    None
                }
            }
        }
        _ => Some(PTX_PF.to_vec()),
    }
}

/// カーネル一式を読む (初回だけ。失敗は None を焼き付ける = 二度と試さない)。
fn pf_kernels() -> Option<&'static PfKernels> {
    static K: OnceLock<Option<PfKernels>> = OnceLock::new();
    K.get_or_init(|| {
        let mut image = pf_ptx_image()?;
        image.push(0);
        let lib = lib().ok()?;
        let mut module: CUmodule = std::ptr::null_mut();
        unsafe {
            if (lib.module_load_data)(&mut module, image.as_ptr() as *const c_void) != CUDA_SUCCESS {
                tracing::info!("[pf] cuModuleLoadData 失敗 → CPU 経路");
                return None;
            }
        }
        let mut fns: [CUfunction; 5] = [std::ptr::null_mut(); 5];
        for (i, name) in PF_NAMES.iter().enumerate() {
            unsafe {
                if (lib.module_get_function)(&mut fns[i], module, name.as_ptr() as *const c_char)
                    != CUDA_SUCCESS
                {
                    tracing::info!(
                        "[pf] PTX に {} が無い → CPU 経路",
                        String::from_utf8_lossy(&name[..name.len() - 1])
                    );
                    return None;
                }
            }
        }
        Some(PfKernels {
            module,
            rmsgroup: fns[0],
            lo: fns[1],
            mixed: fns[2],
            inj: fns[3],
            combine: fns[4],
        })
    })
    .as_ref()
}

/// 連鎖 1 回ぶんの失敗を 1 度だけ記録する (以降は CPU 経路に固定)。
static PF_BROKEN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

fn pf_fail(msg: &str) -> bool {
    if !PF_BROKEN.swap(true, std::sync::atomic::Ordering::Relaxed) {
        tracing::info!("[pf] {msg} → 以降の prefill は CPU 経路");
    }
    false
}

/// 形状と作業域。層をまたいで再利用する (grow-only)。
struct PfDev {
    res: Option<DevBuffer>,   // [nt][hc][e]
    xn: Option<DevBuffer>,    // [nt][hc][e]
    lo: Option<DevBuffer>,    // [nt][low_rank]
    gate: Option<DevBuffer>,  // [nt][hc][e]
    mixed: Option<DevBuffer>, // [nt][e]
    inj: Option<DevBuffer>,   // [nt][hc]
    bo: Option<DevBuffer>,    // [nt][e]
    gamma: Option<DevBuffer>, // [hc][e]
    nt: usize,
    hc: usize,
    e: usize,
    lr: usize,
}

impl PfDev {
    const fn new() -> Self {
        Self {
            res: None,
            xn: None,
            lo: None,
            gate: None,
            mixed: None,
            inj: None,
            bo: None,
            gamma: None,
            nt: 0,
            hc: 0,
            e: 0,
            lr: 0,
        }
    }
}

thread_local! {
    static PF_DEV: std::cell::RefCell<PfDev> = const { std::cell::RefCell::new(PfDev::new()) };
}

/// task 154: チャンクぶんの作業域を用意する。`false` で CPU 経路へ。
///
/// 直前の `res` の中身は保証しない (呼び出し側が `pf_upload_res` で入れる)。
pub fn pf_begin(nt: usize, hc: usize, e: usize, lr: usize) -> bool {
    if PF_BROKEN.load(std::sync::atomic::Ordering::Relaxed) {
        return false;
    }
    if nt == 0 || hc == 0 || e == 0 || lr == 0 || hc * e > (1 << 20) {
        return false;
    }
    if pf_kernels().is_none() {
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return pf_fail("CUDA context が無い");
    };
    if ctx.make_current().is_err() {
        return pf_fail("cuCtxSetCurrent 失敗");
    }
    if gemm_bf16_mt_fn(ctx).is_none() && gemm_f32_mt_fn(ctx).is_none() {
        return pf_fail("GEMM カーネルが PTX に無い");
    }
    let r = PF_DEV.with(|cell| -> anyhow::Result<()> {
        let mut d = cell.borrow_mut();
        if d.nt != nt || d.hc != hc || d.e != e || d.lr != lr {
            // 形が変わったら全部作り直す (古い領域を流用しない)。
            d.res = None;
            d.bo = None;
            d.mixed = None;
            d.inj = None;
            d.nt = nt;
            d.hc = hc;
            d.e = e;
            d.lr = lr;
        }
        let hc_dim = hc * e;
        Scratch::ensure_tagged(&mut d.res, nt * hc_dim * 4, crate::mem_audit::TAG_OTHER)?;
        Scratch::ensure_tagged(&mut d.xn, nt * hc_dim * 4, crate::mem_audit::TAG_OTHER)?;
        Scratch::ensure_tagged(&mut d.lo, nt * lr * 4, crate::mem_audit::TAG_OTHER)?;
        Scratch::ensure_tagged(&mut d.gate, nt * hc_dim * 4, crate::mem_audit::TAG_OTHER)?;
        Scratch::ensure_tagged(&mut d.mixed, nt * e * 4, crate::mem_audit::TAG_OTHER)?;
        Scratch::ensure_tagged(&mut d.inj, nt * hc * 4, crate::mem_audit::TAG_OTHER)?;
        Scratch::ensure_tagged(&mut d.bo, nt * e * 4, crate::mem_audit::TAG_OTHER)?;
        Scratch::ensure_tagged(&mut d.gamma, hc_dim * 4, crate::mem_audit::TAG_OTHER)?;
        Ok(())
    });
    match r {
        Ok(()) => true,
        Err(e) => pf_fail(&format!("作業域の確保に失敗: {e:#}")),
    }
}

/// task 154: チャンクの残差 (`[nt][hc][e]`) をデバイスへ置く。
pub fn pf_upload_res(res: &[f32]) -> bool {
    PF_DEV.with(|cell| -> bool {
        let d = cell.borrow();
        match d.res.as_ref() {
            Some(b) if b.bytes() >= res.len() * 4 => b.copy_from(res).is_ok(),
            _ => false,
        }
    })
}

/// task 154: デバイスの残差をホストへ戻す (`res` は [nt][hc][e])。
pub fn pf_download_res(out: &mut [f32]) -> bool {
    PF_DEV.with(|cell| -> bool {
        let d = cell.borrow();
        match d.res.as_ref() {
            Some(b) if b.bytes() >= out.len() * 4 => match b.to_vec::<f32>(out.len()) {
                Ok(v) => {
                    out.copy_from_slice(&v);
                    true
                }
                Err(_) => false,
            },
            _ => false,
        }
    })
}

/// task 154: 残差の **1 行だけ** をホストへ戻す (層の出口フック用)。
///
/// `t` はチャンク内のトークン番号、`out` は `[hc*e]`。
pub fn pf_download_res_row(t: usize, hc_dim: usize, out: &mut [f32]) -> bool {
    if out.len() != hc_dim {
        return false;
    }
    PF_DEV.with(|cell| -> bool {
        let d = cell.borrow();
        match d.res.as_ref() {
            Some(b) if b.bytes() >= (t + 1) * hc_dim * 4 => {
                let bytes = hc_dim * 4;
                let src = b.ptr() + (t * hc_dim * 4) as u64;
                match lib() {
                    Ok(l) => unsafe {
                        check(
                            (l.memcpy_dtoh)(
                                out.as_mut_ptr() as *mut c_void,
                                src,
                                bytes,
                            ),
                            "cuMemcpyDtoH (res row)",
                        )
                        .is_ok()
                    },
                    Err(_) => false,
                }
            }
            _ => false,
        }
    })
}

/// task 154: デバイスの `mixed` (`[nt][n_embd]`) をホストへ戻す。
pub fn pf_take_mixed(out: &mut [f32]) -> bool {
    PF_DEV.with(|cell| -> bool {
        let d = cell.borrow();
        match d.mixed.as_ref() {
            Some(b) if b.bytes() >= out.len() * 4 => match b.to_vec::<f32>(out.len()) {
                Ok(v) => {
                    out.copy_from_slice(&v);
                    true
                }
                Err(_) => false,
            },
            _ => false,
        }
    })
}

/// F32 の重み (hc mix の inject など) の常駐表。`mix_gpu_weight` は BF16 専用なので
/// F32 はそのままのバイト列を置く (1 本 40 KB)。
static PF_F32_W: OnceLock<Mutex<std::collections::HashMap<u64, DevBuffer>>> = OnceLock::new();

/// 常駐した重み 1 本の種類 (どの GEMM カーネルで叩くか)。
#[derive(Clone, Copy, PartialEq, Eq)]
enum PfWKind {
    /// `dno_gemm_bf16_mt` (BF16 のまま)。
    Bf16,
    /// `dno_gemm_f32_mt` (f32 に展開済み / 元から F32)。
    F32,
    /// `dno_gemm_q8_0` 系 (`f_gemm_q` の添字, 1 行の生バイト数, 量子ブロック長)。
    Quant(usize, usize, usize),
}

/// 重み 1 本を常駐させる。
///
/// - BF16: [`mix_gpu_weight`] (task 152。`want_bf16` が偽なら f32 に展開)
/// - F32:  そのままのバイト列 (40 KB 級の inject 用)
/// - Q8_0 / Q5_1 / Q4K / Q5K: [`weights_for_gguf`] (量子のまま)
/// - それ以外: `None` (呼び出し側は層を進める前に従来経路へ)
fn pf_weight(l: PfLin<'_>, want_bf16: bool) -> Option<(CUdeviceptr, PfWKind)> {
    use crate::kquant::GgmlType as T;
    match l.ty {
        T::Bf16 => {
            if l.blocks.len() != l.k.saturating_mul(l.n).saturating_mul(2) {
                return None;
            }
            match mix_gpu_weight(l.uid, l.blocks, l.k, l.n, want_bf16) {
                Ok(w) => Some((
                    w.ptr,
                    if want_bf16 { PfWKind::Bf16 } else { PfWKind::F32 },
                )),
                Err(e) => {
                    tracing::info!("[pf] 重みの常駐に失敗 (uid={}): {e:#}", l.uid);
                    None
                }
            }
        }
        T::F32 => {
            let want = l.k.checked_mul(l.n)?.checked_mul(4)?;
            if l.blocks.len() != want {
                return None;
            }
            let reg = PF_F32_W.get_or_init(|| Mutex::new(std::collections::HashMap::new()));
            let mut m = match reg.lock() {
                Ok(g) => g,
                Err(_) => return None,
            };
            if let Some(b) = m.get(&l.uid) {
                return Some((b.ptr(), PfWKind::F32));
            }
            let b = DevBuffer::from_slice_tagged(l.blocks, crate::mem_audit::TAG_OTHER).ok()?;
            let p = b.ptr();
            m.insert(l.uid, b);
            Some((p, PfWKind::F32))
        }
        ty => {
            let (slot, blk) = match ty {
                T::Q8_0 => (0, 32usize),
                T::Q5_1 => (1, 32usize),
                T::Q4K => (2, 256usize),
                T::Q5K => (3, 256usize),
                _ => return None,
            };
            if l.k % blk != 0 {
                return None;
            }
            let rb = gguf_row_bytes(ty, l.k)?;
            if l.blocks.len() != l.n.checked_mul(rb)? {
                return None;
            }
            match weights_for_gguf(l.uid, ty, l.blocks, l.k, l.n) {
                Ok(w) => Some((w.buf.ptr(), PfWKind::Quant(slot, rb, blk))),
                Err(e) => {
                    tracing::info!("[pf] 量子重みの常駐に失敗 (uid={}): {e:#}", l.uid);
                    None
                }
            }
        }
    }
}

/// task 154: mix の 1 行列 (`GgufLinear` の素性)。
#[derive(Clone, Copy)]
pub struct PfLin<'a> {
    /// `GgufLinear::uid` (常駐の鍵)。
    pub uid: u64,
    /// 重みの量子型 (BF16 だけ受ける)。
    pub ty: crate::kquant::GgmlType,
    /// 生の重みバイト列。
    pub blocks: &'a [u8],
    /// 入力次元。
    pub k: usize,
    /// 出力次元。
    pub n: usize,
}

/// task 154: hc mix の 1 段 (norm → down → lo → up → mixed → inject) をデバイスで回し、
/// `mixed` (と inject 列) をデバイスに残す。
///
/// 成功したら `pf_take_mixed` で `[nt][n_embd]` を取れる。`false` は CPU 経路へ。
/// `res` は呼び出し側が `pf_upload_res` で入れたものを使う。
#[allow(clippy::too_many_arguments)]
pub fn pf_mix(
    norm: &[f32],
    down: PfLin<'_>,
    up: PfLin<'_>,
    inject: PfLin<'_>,
    nt: usize,
    hc: usize,
    e: usize,
    lr: usize,
    eps: f32,
) -> bool {
    if PF_BROKEN.load(std::sync::atomic::Ordering::Relaxed) {
        return false;
    }
    let hc_dim = hc * e;
    if norm.len() != hc_dim
        || down.k != hc_dim
        || down.n != lr
        || up.k != lr
        || up.n != hc_dim
        || inject.k != hc_dim
        || inject.n != hc
    {
        return pf_fail("mix の形が違う");
    }
    let Some(k) = pf_kernels() else {
        return false;
    };
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if ctx.make_current().is_err() {
        return pf_fail("cuCtxSetCurrent 失敗");
    }
    let f_bf16 = gemm_bf16_mt_fn(ctx);
    let f_f32 = gemm_f32_mt_fn(ctx);
    let want_bf16 = mix_bf16_enabled() && f_bf16.is_some();
    if f_f32.is_none() {
        return pf_fail("f32 GEMM カーネルが無い");
    }
    let Some((pd, pd_k)) = pf_weight(down, want_bf16) else {
        return false;
    };
    let Some((pu, pu_k)) = pf_weight(up, want_bf16) else {
        return false;
    };
    let Some((pi, pi_k)) = pf_weight(inject, want_bf16) else {
        return false;
    };
    let r = PF_DEV.with(|cell| -> Result<(), String> {
        let d = cell.borrow();
        if nt > d.nt || hc != d.hc || e != d.e || lr != d.lr {
            return Err(format!(
                "作業域の形が違う (要求 nt={nt} hc={hc} e={e} lr={lr} / 確保 nt={} hc={} e={} lr={})",
                d.nt, d.hc, d.e, d.lr
            ));
        }
        let (Some(res), Some(xn), Some(lo), Some(gate), Some(mixed), Some(inj), Some(gamma)) = (
            d.res.as_ref(),
            d.xn.as_ref(),
            d.lo.as_ref(),
            d.gate.as_ref(),
            d.mixed.as_ref(),
            d.inj.as_ref(),
            d.gamma.as_ref(),
        ) else {
            return Err("作業域が無い".into());
        };
        gamma.copy_from(norm).map_err(|e| format!("norm H2D: {e:#}"))?;
        let inv_hc = 1.0f32 / hc as f32;
        let mut rows = (nt * hc) as i32;
        let (mut pr, mut px, mut pl, mut pg, mut pm, mut pj, mut pw) =
            (res.ptr(), xn.ptr(), lo.ptr(), gate.ptr(), mixed.ptr(), inj.ptr(), gamma.ptr());
        // 1. grouped RMS norm (res → xn)
        {
            let (mut e_c, mut hc_c) = (e as i32, hc as i32);
            let mut eps_c = eps;
            let mut args = [
                &mut pr as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut px as *mut _ as *mut c_void,
                &mut rows as *mut _ as *mut c_void,
                &mut e_c as *mut _ as *mut c_void,
                &mut hc_c as *mut _ as *mut c_void,
                &mut eps_c as *mut _ as *mut c_void,
            ];
            unsafe {
                ctx.launch_async(k.rmsgroup, (rows as u32, 1, 1), (128, 1, 1), 0, &mut args)
                    .map_err(|e| format!("rmsgroup launch: {e:#}"))?;
            }
        }
        // 2. down GEMM (xn → lo)
        let gemm = |w: CUdeviceptr,
                    x: CUdeviceptr,
                    y: CUdeviceptr,
                    kk: usize,
                    nn: usize,
                    kind: PfWKind|
         -> Result<(), String> {
            match kind {
                PfWKind::Bf16 | PfWKind::F32 => {
                    let f = if kind == PfWKind::Bf16 {
                        f_bf16.ok_or_else(|| "bf16 GEMM カーネルが無い".to_string())?
                    } else {
                        f_f32.ok_or_else(|| "f32 GEMM カーネルが無い".to_string())?
                    };
                    let (mut pw, mut px, mut py) = (w, x, y);
                    let (mut nt_c, mut k_c, mut n_c) = (nt as c_int, kk as c_int, nn as c_int);
                    let mut args = [
                        &mut pw as *mut _ as *mut c_void,
                        &mut px as *mut _ as *mut c_void,
                        &mut py as *mut _ as *mut c_void,
                        &mut nt_c as *mut _ as *mut c_void,
                        &mut k_c as *mut _ as *mut c_void,
                        &mut n_c as *mut _ as *mut c_void,
                    ];
                    let grid = (
                        ((nn + GEMM_MT_ROWS - 1) / GEMM_MT_ROWS) as u32,
                        ((nt + GEMM_MT_TOKS - 1) / GEMM_MT_TOKS) as u32,
                        1,
                    );
                    unsafe {
                        ctx.launch_async(f, grid, (GEMM_MT_ROWS as u32, 16, 1), 0, &mut args)
                            .map_err(|e| format!("gemm launch: {e:#}"))?;
                    }
                }
                PfWKind::Quant(slot, rb, blk) => {
                    // 量子 GEMM は 1 起動 128 トークンまで (`moe_gemm_dev` と同じ)。
                    let f = ctx
                        .f_gemm_q
                        .ok_or_else(|| "量子 GEMM カーネルが無い".to_string())?[slot];
                    const ROWS: usize = 16;
                    const NTG_MAX: usize = 8;
                    if kk % blk != 0 {
                        return Err("量子 GEMM のブロック形が合わない".into());
                    }
                    let shmem = (ROWS * blk * 4) as u32;
                    let mut t0 = 0usize;
                    while t0 < nt {
                        let m = (nt - t0).min(ROWS * NTG_MAX);
                        let xo = (t0 * kk * 4) as u64;
                        let yo = (t0 * nn * 4) as u64;
                        let (mut pw, mut px, mut py) = (w, x + xo, y + yo);
                        let (mut m_c, mut ni_c, mut no_c, mut rb_c) =
                            (m as c_int, kk as c_int, nn as c_int, rb as c_int);
                        let mut args = [
                            &mut pw as *mut _ as *mut c_void,
                            &mut px as *mut _ as *mut c_void,
                            &mut py as *mut _ as *mut c_void,
                            &mut m_c as *mut _ as *mut c_void,
                            &mut ni_c as *mut _ as *mut c_void,
                            &mut no_c as *mut _ as *mut c_void,
                            &mut rb_c as *mut _ as *mut c_void,
                        ];
                        let grid = (((nn + ROWS - 1) / ROWS) as u32, 1, 1);
                        unsafe {
                            ctx.launch_async(f, grid, (ROWS as u32, 16, 1), shmem, &mut args)
                                .map_err(|e| format!("q gemm launch: {e:#}"))?;
                        }
                        t0 += m;
                    }
                }
            }
            Ok(())
        };
        gemm(pd, px, pl, hc_dim, lr, pd_k)?;
        // 3. lo apply (in-place, nt*low_rank 要素)
        {
            let mut total = (nt * lr) as i64;
            let mut inv_c = inv_hc;
            let grid = ((nt * lr).div_ceil(256)) as u32;
            let mut args = [
                &mut pl as *mut _ as *mut c_void,
                &mut total as *mut _ as *mut c_void,
                &mut inv_c as *mut _ as *mut c_void,
            ];
            unsafe {
                ctx.launch_async(k.lo, (grid, 1, 1), (256, 1, 1), 0, &mut args)
                    .map_err(|e| format!("lo launch: {e:#}"))?;
            }
        }
        // 4. up GEMM (lo → gate)
        gemm(pu, pl, pg, lr, hc_dim, pu_k)?;
        // 5. mixed (xn, gate → mixed)
        {
            let (mut e_c, mut hc_c) = (e as i32, hc as i32);
            let mut inv_c = inv_hc;
            let grid = ((e.div_ceil(256)) as u32, nt as u32, 1);
            let mut args = [
                &mut px as *mut _ as *mut c_void,
                &mut pg as *mut _ as *mut c_void,
                &mut pm as *mut _ as *mut c_void,
                &mut e_c as *mut _ as *mut c_void,
                &mut hc_c as *mut _ as *mut c_void,
                &mut inv_c as *mut _ as *mut c_void,
            ];
            unsafe {
                ctx.launch_async(k.mixed, grid, (256, 1, 1), 0, &mut args)
                    .map_err(|e| format!("mixed launch: {e:#}"))?;
            }
        }
        // 6. inject GEMM (xn → inj) + 1/hc
        gemm(pi, px, pj, hc_dim, hc, pi_k)?;
        {
            let mut n_c = (nt * hc) as i32;
            let mut inv_c = inv_hc;
            let mut args = [
                &mut pj as *mut _ as *mut c_void,
                &mut n_c as *mut _ as *mut c_void,
                &mut inv_c as *mut _ as *mut c_void,
            ];
            let grid = ((nt * hc).div_ceil(256)) as u32;
            unsafe {
                ctx.launch_async(k.inj, (grid, 1, 1), (256, 1, 1), 0, &mut args)
                    .map_err(|e| format!("inj launch: {e:#}"))?;
            }
        }
        ctx.sync().map_err(|e| format!("sync: {e:#}"))?;
        Ok(())
    });
    match r {
        Ok(()) => true,
        Err(e) => pf_fail(&e),
    }
}

/// task 154: hc combine (`res[i] += bo * (2*sigmoid(inj))`) をデバイスで回す。
///
/// `bo` は `[nt][n_embd]` (attn / ffn の出力)。`inj` は直前の [`pf_mix`] が残した
/// デバイス上の値をそのまま使う。
pub fn pf_combine(bo: &[f32], nt: usize, hc: usize, e: usize) -> bool {
    if PF_BROKEN.load(std::sync::atomic::Ordering::Relaxed) {
        return false;
    }
    if bo.len() != nt * e {
        return pf_fail("combine の bo 長が違う");
    }
    let Some(k) = pf_kernels() else {
        return false;
    };
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if ctx.make_current().is_err() {
        return pf_fail("cuCtxSetCurrent 失敗");
    }
    let r = PF_DEV.with(|cell| -> Result<(), String> {
        let d = cell.borrow();
        if nt > d.nt || hc != d.hc || e != d.e {
            return Err(format!("combine の形が違う (nt={nt} hc={hc} e={e})"));
        }
        let (Some(res), Some(dbo), Some(inj)) =
            (d.res.as_ref(), d.bo.as_ref(), d.inj.as_ref())
        else {
            return Err("作業域が無い".into());
        };
        dbo.copy_from(bo).map_err(|e| format!("bo H2D: {e:#}"))?;
        let (mut pr, mut pb, mut pj) = (res.ptr(), dbo.ptr(), inj.ptr());
        let (mut e_c, mut hc_c) = (e as i32, hc as i32);
        let grid = ((e.div_ceil(256)) as u32, (nt * hc) as u32, 1);
        let mut args = [
            &mut pr as *mut _ as *mut c_void,
            &mut pb as *mut _ as *mut c_void,
            &mut pj as *mut _ as *mut c_void,
            &mut e_c as *mut _ as *mut c_void,
            &mut hc_c as *mut _ as *mut c_void,
        ];
        unsafe {
            ctx.launch_async(k.combine, grid, (256, 1, 1), 0, &mut args)
                .map_err(|e| format!("combine launch: {e:#}"))?;
        }
        ctx.sync().map_err(|e| format!("sync: {e:#}"))?;
        Ok(())
    });
    match r {
        Ok(()) => true,
        Err(e) => pf_fail(&e),
    }
}

/// task 154: 連鎖の作業域を解放する (VRAM を返す。prefill の終端で呼ぶ)。
pub fn pf_release() {
    PF_DEV.with(|cell| {
        let mut d = cell.borrow_mut();
        *d = PfDev::new();
    });
}

/// task 154: 連鎖が 1 度でも失敗したか (テスト・診断用)。
pub fn pf_broken() -> bool {
    PF_BROKEN.load(std::sync::atomic::Ordering::Relaxed)
}

/// task 154: テスト用にラッチを戻す。
#[cfg(test)]
pub fn pf_reset_for_test() {
    PF_BROKEN.store(false, std::sync::atomic::Ordering::Relaxed);
    pf_release();
}

/// task 152: BF16 のまま読む mix カーネルの既定値 (**on**)。
///
/// lab t152b の g22 条件で採否 OK (`REPORT_P152.md`)。`w:mix_f32` 2,425 MiB ->
/// `w:mix_bf16` 1,213 MiB、md5 は全条件 SAME (f32 版と同じ演算列)。
/// `DENNO_MIX_BF16=0` で従来の f32 展開経路に戻せる。
const MIX_BF16_DEFAULT: bool = true;

/// `MIX_GPU_W` の登録・形状検査・初回の同期 H2D を 1 箇所にまとめたもの
/// ([`maybe_gpu_mix_bf16_into`] と同じ規約)。uid は `GgufLinear` のもの。
///
/// task 152: `want_bf16` のときは生バイト (BF16) をそのまま上げる。既に逆の
/// モードで載っている uid を要求されたら **エラー**にする (黙って別解釈の
/// バイト列で計算しない。呼び出し側は CPU へ落ちる)。
fn mix_gpu_weight(uid: u64, bytes: &[u8], k: usize, n: usize, want_bf16: bool) -> Result<MixW> {
    let reg = MIX_GPU_W.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()));
    let mut map = match reg.lock() {
        Ok(g) => g,
        Err(_) => bail!("hc mix weight registry poisoned"),
    };
    match map.get(&uid) {
        Some(w) if w.k == k && w.n == n && w.bf16 == want_bf16 => Ok(MixW {
            ptr: w.buf.ptr(),
        }),
        Some(_) => bail!("uid 重複: uid={uid} に別の形状/モード (k={k}, n={n}, bf16={want_bf16})"),
        None => {
            let (buf, tag) = if want_bf16 {
                match DevBuffer::from_slice_tagged(bytes, crate::mem_audit::TAG_MIX_BF16) {
                    Ok(b) => (b, crate::mem_audit::TAG_MIX_BF16),
                    Err(e) => bail!("BF16 のままの mix 重みを VRAM に置けない: {e:#}"),
                }
            } else {
                let host = mix_expand_bf16(bytes, k, n);
                match DevBuffer::from_slice_tagged(&host, crate::mem_audit::TAG_MIX_F32) {
                    Ok(b) => (b, crate::mem_audit::TAG_MIX_F32),
                    Err(e) => bail!("f32 展開重みの VRAM 確保に失敗: {e:#}"),
                }
            };
            tracing::info!(
                "[mix-gpu] uid={uid} bf16 mix k={k} n={n} {:.1} MB ({}・常駐)",
                buf.bytes() as f64 / 1e6,
                if want_bf16 { "BF16 のまま" } else { "f32 展開済み" }
            );
            let p = buf.ptr();
            debug_assert_eq!(
                tag,
                if want_bf16 {
                    crate::mem_audit::TAG_MIX_BF16
                } else {
                    crate::mem_audit::TAG_MIX_F32
                }
            );
            map.insert(uid, MixGpuW { buf, k, n, bf16: want_bf16 });
            Ok(MixW { ptr: p })
        }
    }
}

/// task 138: `DENNO_MIX_UP_REDUCE` の値を解釈する (純関数・テスト用)。
/// **既定 on** で、明示的な偽値だけ切る (切ると逐次版 = 従来の丸め順)。
fn mix_up_reduce_from_value(v: Option<&str>) -> bool {
    match v {
        Some(s) => !matches!(
            s.trim().to_ascii_lowercase().as_str(),
            "0" | "off" | "false" | "no"
        ),
        None => true,
    }
}

/// task 138: チェーン経路の up GEMV に並列リダクション版 (`dno_matvec_f32_r`)
/// を使う (`DENNO_MIX_UP_REDUCE`、**既定 on**。`=0` で逐次版に戻る)。
/// up の形は k < n (320 x 5120) で、逐次版は 1 ブロック 1 スレッドのため
/// 並列度が n 側にしか無い。lab t138b の実測で mix の同期待ちが
/// 6.42 → 4.65 ms/tok になった (丸め順が変わるが決定論は保つ)。
fn mix_up_reduce_enabled() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| {
        mix_up_reduce_from_value(std::env::var("DENNO_MIX_UP_REDUCE").ok().as_deref())
    })
}

/// task 138: hc mix (BF16) の **down → lo_apply → up を 1 回の同期に畳む**。
///
/// 従来は down GEMV (H2D + kernel + D2H + sync)、ホストで `hc_lo_apply`、
/// up GEMV (H2D + kernel + D2H + sync) の 2 往復だった。down の出力
/// (`low_rank` 本) はそのまま lo_apply の入力なので、silu を畳んだ
/// [`matvec_f32_r_silu`] (`dno_matvec_f32_r_silu`) で down を書き、その出力を
/// デバイス上で up に渡す。丸めは GPU 経路の現行と同じ (dno_expf は glibc expf
/// のビット一致実装) なので logits は従来経路とビット一致する。
///
/// 戻り値 `false` = 従来の 2 往復経路を使うこと (GPU 無効・PTX 未収録・形状不一致・
/// 確保失敗・実行エラー)。`x` は `[k1]`、`out` は `[n2]`。
#[allow(clippy::too_many_arguments)]
pub fn maybe_gpu_mix_bf16_chain_into(
    down_uid: u64,
    down_bytes: &[u8],
    k1: usize,
    n1: usize,
    up_uid: u64,
    up_bytes: &[u8],
    _k2: usize,
    n2: usize,
    inv_hc: f32,
    x: &[f32],
    out: &mut [f32],
) -> bool {
    use std::sync::atomic::Ordering as AO;
    if !cuda_enabled() || MIX_GPU_BROKEN.load(AO::Relaxed) {
        return false;
    }
    if k1 == 0
        || n1 == 0
        || n2 == 0
        || n1 != _k2
        || x.len() != k1
        || out.len() != n2
        || k1 < n1
        || down_bytes.len() != k1.saturating_mul(n1).saturating_mul(2)
        || up_bytes.len() != n1.saturating_mul(n2).saturating_mul(2)
        || k1 > i32::MAX as usize
        || n1 > i32::MAX as usize
        || n2 > i32::MAX as usize
    {
        return false;
    }
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if let Err(e) = ctx.make_current() {
        mix_gpu_broken_once(&format!("cuCtxSetCurrent: {e:#}"));
        return false;
    }
    // down は silu 込みの並列リダクション版。未収録 PTX は従来経路へ (ラッチしない)。
    // task 152: BF16 カーネルがあれば重みは BF16 のまま (常駐が半分)。
    let want_bf16 = mix_bf16_enabled() && matvec_bf16_r_silu_fn(ctx).is_some();
    let f_down = if want_bf16 {
        matvec_bf16_r_silu_fn(ctx)
    } else {
        matvec_f32_r_silu_fn(ctx)
    };
    let Some(f_down) = f_down else {
        return false;
    };
    let up_reduce = mix_up_reduce_enabled();
    let f_up = if up_reduce {
        if want_bf16 {
            matvec_bf16_r_fn(ctx)
        } else {
            matvec_f32_r_fn(ctx)
        }
    } else if want_bf16 {
        matvec_bf16_fn(ctx)
    } else {
        matvec_f32_fn(ctx)
    };
    let Some(f_up) = f_up else {
        return false;
    };
    let up_thr: u32 = if up_reduce { 256 } else { 1 };
    let wp1 = match mix_gpu_weight(down_uid, down_bytes, k1, n1, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("down 重みの常駐に失敗: {e:#}"));
            return false;
        }
    };
    let wp2 = match mix_gpu_weight(up_uid, up_bytes, n1, n2, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("up 重みの常駐に失敗: {e:#}"));
            return false;
        }
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            mix_gpu_broken_once(&format!("CUDA lib load failed: {e:#}"));
            return false;
        }
    };
    let r = MIX_GPU_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let MixGpuScratch {
            x: dx,
            lo: dlo,
            out: dout,
            mixed: _,
            hx,
            ho,
        } = &mut *s;
        let bytes_x = k1 * 4;
        let bytes_lo = n1 * 4;
        let bytes_out = n2 * 4;
        Scratch::ensure(dx, bytes_x)?;
        Scratch::ensure(dlo, bytes_lo)?;
        Scratch::ensure(dout, bytes_out)?;
        Scratch::ensure_pin(hx, bytes_x)?;
        Scratch::ensure_pin(ho, bytes_out)?;
        let (dx, dlo, dout) = (
            dx.as_ref().unwrap(),
            dlo.as_ref().unwrap(),
            dout.as_ref().unwrap(),
        );
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        hx.as_mut_slice::<f32>()[..k1].copy_from_slice(x);
        unsafe {
            check(
                (lib.memcpy_htod_async)(
                    dx.ptr(),
                    hx.ptr as *const c_void,
                    bytes_x,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync (mix chain)",
            )?;
            // down + lo_apply (silu 込み) → lo はデバイスに残る。
            let (mut ph, mut pw, mut po) = (dx.ptr(), wp1, dlo.ptr());
            let (mut kc, mut nc) = (k1 as c_int, n1 as c_int);
            let mut invc = inv_hc;
            let mut args = [
                &mut ph as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
                &mut invc as *mut _ as *mut c_void,
            ];
            ctx.launch_async(f_down, (n1 as u32, 1, 1), (256, 1, 1), 0, &mut args)?;
            // up: 入力は lo_apply 済みの lo (同じ既定ストリームなので順序保証)。
            let (mut ph2, mut pw2, mut po2) = (dlo.ptr(), wp2, dout.ptr());
            let (mut kc2, mut nc2) = (n1 as c_int, n2 as c_int);
            let mut args2 = [
                &mut ph2 as *mut _ as *mut c_void,
                &mut pw2 as *mut _ as *mut c_void,
                &mut po2 as *mut _ as *mut c_void,
                &mut kc2 as *mut _ as *mut c_void,
                &mut nc2 as *mut _ as *mut c_void,
            ];
            ctx.launch_async(
                f_up,
                (n2 as u32, 1, 1),
                (up_thr, 1, 1),
                0,
                &mut args2,
            )?;
            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dout.ptr(), bytes_out, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync (mix chain)",
            )?;
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        ctx.sync()?;
        out.copy_from_slice(&ho.as_slice::<f32>()[..n2]);
        Ok(())
    });
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            mix_gpu_broken_once(&format!("hc mix chain failed: {e:#}"));
            false
        }
    }
}

/// task 150: `dno_hc_mixed_f32` (hc_mixed の device 版) を PTX から取る。
/// 未収録 (旧 PTX) は `None` を返し、呼び出し側は従来経路へ落ちる (ラッチしない)。
fn hc_mixed_f32_fn(ctx: &CudaCtx) -> Option<CUfunction> {
    struct HcMixedFn(CUfunction);
    unsafe impl Send for HcMixedFn {}
    unsafe impl Sync for HcMixedFn {}
    static FN: OnceLock<Option<HcMixedFn>> = OnceLock::new();
    FN.get_or_init(|| {
        let lib = lib().ok()?;
        let mut f: CUfunction = std::ptr::null_mut();
        let r = unsafe {
            (lib.module_get_function)(
                &mut f,
                ctx.module_elem,
                b"dno_hc_mixed_f32\0".as_ptr() as *const c_char,
            )
        };
        if r != 0 {
            None
        } else {
            Some(HcMixedFn(f))
        }
    })
    .as_ref()
    .map(|h| h.0)
}

/// task 150: hc mix の **down → lo_apply → up → hc_mixed** を 1 回の同期に畳む。
///
/// task 138 の [`maybe_gpu_mix_bf16_chain_into`] は up までを GPU で閉じ、`hc_mixed`
/// (ストリームごとの sigmoid と加算) はホストで計算していた。ここでは `hc_mixed` も
/// device の `dno_hc_mixed_f32` で閉じ、ホストへ返すのは `mixed[e]` だけにする
/// (従来は `gate[hc*e]` を返してホストで計算 = D2H も 4 倍)。
///
/// 丸めは CPU の `hyper::hc_mixed_into_par` と同一 (dno_expf + `__f*_rn`・要素独立)
/// なので値はビット一致する。戻り値 `false` = 従来経路を使うこと (GPU 無効・PTX
/// 未収録・形状不一致・確保失敗・実行エラー)。
///
/// `x` は `[k1]` (= `[hc][e]`)、`out` は `[e]`。
#[allow(clippy::too_many_arguments)]
pub fn maybe_gpu_mix_bf16_chain2_into(
    down_uid: u64,
    down_bytes: &[u8],
    k1: usize,
    n1: usize,
    up_uid: u64,
    up_bytes: &[u8],
    k2: usize,
    n2: usize,
    inv_hc: f32,
    e: usize,
    x: &[f32],
    out: &mut [f32],
) -> bool {
    use std::sync::atomic::Ordering as AO;
    if !cuda_enabled() || MIX_GPU_BROKEN.load(AO::Relaxed) {
        return false;
    }
    if k1 == 0
        || n1 == 0
        || n2 == 0
        || e == 0
        || k2 != n1
        || n2 % e != 0
        || n2 / e > 64
        || x.len() != k1
        || out.len() != e
        || n2 != k1
        || k1 < n1
        || down_bytes.len() != k1.saturating_mul(n1).saturating_mul(2)
        || up_bytes.len() != n1.saturating_mul(n2).saturating_mul(2)
        || k1 > i32::MAX as usize
        || n1 > i32::MAX as usize
        || n2 > i32::MAX as usize
        || e > i32::MAX as usize
    {
        return false;
    }
    let hc = n2 / e;
    let Some(ctx) = shared_ctx() else {
        return false;
    };
    if let Err(e) = ctx.make_current() {
        mix_gpu_broken_once(&format!("cuCtxSetCurrent: {e:#}"));
        return false;
    }
    let Some(f_mixed) = hc_mixed_f32_fn(ctx) else {
        return false;
    };
    // task 152: BF16 カーネルがあれば重みは BF16 のまま (常駐が半分)。
    let want_bf16 = mix_bf16_enabled() && matvec_bf16_r_silu_fn(ctx).is_some();
    let f_down = if want_bf16 {
        matvec_bf16_r_silu_fn(ctx)
    } else {
        matvec_f32_r_silu_fn(ctx)
    };
    let Some(f_down) = f_down else {
        return false;
    };
    let up_reduce = mix_up_reduce_enabled();
    let f_up = if up_reduce {
        if want_bf16 {
            matvec_bf16_r_fn(ctx)
        } else {
            matvec_f32_r_fn(ctx)
        }
    } else if want_bf16 {
        matvec_bf16_fn(ctx)
    } else {
        matvec_f32_fn(ctx)
    };
    let Some(f_up) = f_up else {
        return false;
    };
    let up_thr: u32 = if up_reduce { 256 } else { 1 };
    let wp1 = match mix_gpu_weight(down_uid, down_bytes, k1, n1, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("down 重みの常駐に失敗: {e:#}"));
            return false;
        }
    };
    let wp2 = match mix_gpu_weight(up_uid, up_bytes, n1, n2, want_bf16) {
        Ok(w) => w.ptr,
        Err(e) => {
            mix_gpu_broken_once(&format!("up 重みの常駐に失敗: {e:#}"));
            return false;
        }
    };
    let lib = match lib() {
        Ok(l) => l,
        Err(e) => {
            mix_gpu_broken_once(&format!("CUDA lib load failed: {e:#}"));
            return false;
        }
    };
    const MIXED_THREADS: usize = 256;
    let r = MIX_GPU_SC.with(|cell| -> Result<()> {
        let mut s = cell.borrow_mut();
        let MixGpuScratch {
            x: dx,
            lo: dlo,
            out: dout,
            mixed: dm,
            hx,
            ho,
        } = &mut *s;
        Scratch::ensure(dx, k1 * 4)?;
        Scratch::ensure(dlo, n1 * 4)?;
        Scratch::ensure(dout, n2 * 4)?;
        Scratch::ensure(dm, e * 4)?;
        Scratch::ensure_pin(hx, k1 * 4)?;
        Scratch::ensure_pin(ho, e * 4)?;
        let (dx, dlo, dout, dm) = (
            dx.as_ref().unwrap(),
            dlo.as_ref().unwrap(),
            dout.as_ref().unwrap(),
            dm.as_ref().unwrap(),
        );
        let (hx, ho) = (hx.as_mut().unwrap(), ho.as_mut().unwrap());
        hx.as_mut_slice::<f32>()[..k1].copy_from_slice(x);
        unsafe {
            check(
                (lib.memcpy_htod_async)(
                    dx.ptr(),
                    hx.ptr as *const c_void,
                    k1 * 4,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync (mix chain2)",
            )?;
            // down + lo_apply (silu 込み) → lo はデバイスに残る。
            let (mut ph, mut pw, mut po) = (dx.ptr(), wp1, dlo.ptr());
            let (mut kc, mut nc) = (k1 as c_int, n1 as c_int);
            let mut invc = inv_hc;
            let mut args = [
                &mut ph as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
                &mut invc as *mut _ as *mut c_void,
            ];
            ctx.launch_async(f_down, (n1 as u32, 1, 1), (256, 1, 1), 0, &mut args)?;
            // up: 入力は lo_apply 済みの lo (同じ既定ストリームなので順序保証)。
            let (mut ph2, mut pw2, mut po2) = (dlo.ptr(), wp2, dout.ptr());
            let (mut kc2, mut nc2) = (n1 as c_int, n2 as c_int);
            let mut args2 = [
                &mut ph2 as *mut _ as *mut c_void,
                &mut pw2 as *mut _ as *mut c_void,
                &mut po2 as *mut _ as *mut c_void,
                &mut kc2 as *mut _ as *mut c_void,
                &mut nc2 as *mut _ as *mut c_void,
            ];
            ctx.launch_async(f_up, (n2 as u32, 1, 1), (up_thr, 1, 1), 0, &mut args2)?;
            // hc_mixed: xn (= dx) と gate (= dout) から mixed を作る。
            let (mut px, mut pg, mut pm) = (dx.ptr(), dout.ptr(), dm.ptr());
            let (mut ec, mut hcc) = (e as c_int, hc as c_int);
            let mut invc2 = inv_hc;
            let mut args3 = [
                &mut px as *mut _ as *mut c_void,
                &mut pg as *mut _ as *mut c_void,
                &mut pm as *mut _ as *mut c_void,
                &mut ec as *mut _ as *mut c_void,
                &mut hcc as *mut _ as *mut c_void,
                &mut invc2 as *mut _ as *mut c_void,
            ];
            let grid = (e.div_ceil(MIXED_THREADS).max(1) as u32, 1, 1);
            ctx.launch_async(
                f_mixed,
                grid,
                (MIXED_THREADS as u32, 1, 1),
                0,
                &mut args3,
            )?;
            check(
                (lib.memcpy_dtoh_async)(ho.ptr, dm.ptr(), e * 4, std::ptr::null_mut()),
                "cuMemcpyDtoHAsync (mix chain2)",
            )?;
            crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
        }
        ctx.sync()?;
        out.copy_from_slice(&ho.as_slice::<f32>()[..e]);
        Ok(())
    });
    match r {
        Ok(()) => {
            set_last_linear_ran_on_gpu(true);
            true
        }
        Err(e) => {
            mix_gpu_broken_once(&format!("hc mix chain2 failed: {e:#}"));
            false
        }
    }
}

/// task 110: hc mix BF16 展開重みの常駐を解放する (`GgufLinear::drop` から)。
/// 載っていない uid は触らない。MIX_GPU_W が未初期化 (一度も GPU に載せていない)
/// なら何もしない。
pub fn mix_gpu_unregister(uid: u64) {
    let Some(reg) = MIX_GPU_W.get() else {
        return;
    };
    if let Ok(mut map) = reg.lock() {
        map.remove(&uid);
    }
}

// ===========================================================================
// P17d: decode chain (隠れ状態デバイス常駐 + 要素演算融合)
// ===========================================================================
// solo decode (n==1) の 1 ステップを
//   埋め込み H2D → [rmsnorm(+residual) → qkv → (CPU: rope/attention) →
//   o_proj → rmsnorm(+residual) → gate/up → swiglu → down] ×層数
//   → final norm(+residual) → lm_head → logits D2H
// のデバイス常駐パイプラインで実行する。
// - 線形カーネル (f_quant / f_mv) と重みレジストリは P17b/c と同一 → ビット一致
// - rmsnorm / swiglu は CPU と同一の演算順序 (expf は glibc e_expf を f64 演算
//   で完全再現した dno_expf) → ビット一致
// - 同期は層あたり 1 回 (qkv の D2H 待ち)。CPU attention の間 GPU は次層の
//   FFN チェーンを先読み実行する
// - どのステップで失敗しても GPU_BROKEN → 呼び出し側が従来 CPU 経路で forward
//   をやり直す (k/v 書き込みは冪等・advance は最後に 1 回なので安全)

/// デバイス常駐スロット (ChainScratch.bufs のインデックス)
pub const CH_X: usize = 0; // residual stream [m*e]
pub const CH_H: usize = 1; // rmsnorm 出力 [m*e]
pub const CH_QKV: usize = 2; // qkv 連結出力 [m*(qn+2*kvn)] (q|k|v の列ブロック)
pub const CH_ATT: usize = 3; // attention 出力 (o_proj 入力) [m*(heads*dh)]
pub const CH_O: usize = 4; // o_proj 出力 [m*(heads*dh)]
pub const CH_GA: usize = 5; // gate/up 出力 [m*2ff] (2 回 GEMM = gate 前半/up 後半・1 回 GEMM = 行内 [gate|up])
pub const CH_ACT: usize = 6; // swiglu 出力 [m*ff]
pub const CH_DOWN: usize = 7; // down 出力 [m*e]
pub const CH_LOGITS: usize = 8; // lm_head 出力 [m*vocab]
// C4 (qwen35): QK-Norm + partial interleaved rope 済み q [heads*dh]。
// llama chain と異なり qkv 出力が head ごと [q|gate] 融合のため、attention へ渡す
// q は別スロットに分離して書く (chain_q35_qknorm_rope)。
pub const CH_Q35_Q: usize = 9;
/// s70: prefill FFN チェーンの入力 (CH_H は attention/decode が使うため分ける)
pub const CH_PFH: usize = 10;
/// s165 (P2): prefill の残差ストリーム (h) を層の間ずっと保持するスロット。
/// `dno_add_rmsnorm` の x そのもので、残差加算は**次の rmsnorm の proj 引数**に
/// 融合される (PTX に単独の add カーネルは無い)。層をまたいで内容が変わるのは
/// rmsnorm の add と、prefill 開始時の H2D / フォールバック時の D2H だけ。
pub const CH_PF_RES: usize = 11;
const CH_SLOTS: usize = 12;

// P17j: prefill attention カーネルのタイル定数 (kernels_elem.cu の PF_BQ/PF_BK
// と同期すること)。BQ=行タイル・BK=key タイル。
// P17k ステップ 7 修正: ステップ 4 でカーネルを 48/8→(実験 64/8) に変えた際に
// ここが 16/32 のまま残り、①grid が約 4 倍過剰 (i0 >= n の無効ブロックがフルの
// time ループを回す) ②sh_f も 16/32 基準で、カーネルの必要量を下回ると
// smem 領域外書きになり error 700 (不正アドレス) になっていた —
// 「~43KB 以上で error 700」の正体はこの不一致。64/8 (43.8KB) に統一。
const ATTN_PF_BQ: usize = 64;
const ATTN_PF_BK: usize = 8;

// s48 (C1-a): dno_attention_prefill の動的 smem。カーネル側は extern __shared__
// の静的宣言が無く launch 時の sharedMemBytes をそのまま使うため、48KB 既定上限は
// ホスト側ゲートだけの制約だった。qwen35 (dh=256) は 1 ブロック 84.8KB を要求し
// 48KB を超えるため、モジュールロード時に cuFuncSetAttribute
// (CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES) で opt-in して引き上げる。
// 実機で opt-in 不可 (デバイスの opt-in 上限 < 必要量・古い driver でシンボル無し等)
// の場合も致命的ではない: 上限は 48KB のまま = qwen35 prefill attention は
// attn_prefill_gpu_supported ゲートで静かに CPU へフォールバックし、llama (dh=128
// = 43.8KB) は従来どおり発動する。.cu / PTX は無変更 (C1-b のタイル縮小が必要に
// なった場合のみ .cu 変更 + PTX 再生成が発生する)。
const ATTN_PF_SMEM_DEFAULT: usize = 48 * 1024;
/// CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES
const CU_FUNC_ATTR_MAX_DYNAMIC_SHARED_SIZE_BYTES: c_int = 8;
/// CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN
const CU_DEV_ATTR_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN: c_int = 97;
static ATTN_PF_DYN_SMEM: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(ATTN_PF_SMEM_DEFAULT);

/// s169 (P10): デバイスの SM 数 (GEMV の launch 形状を n から選ぶため)。
/// CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT。取得できなければ 0 のまま =
/// 形状選択は従来どおりの固定 C に落ちる (数値・発行順は不変)。
const CU_DEV_ATTR_MULTIPROCESSOR_COUNT: c_int = 16;
static GEMV_SM_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// s169 (P10): SM 数 (0 = 不明)。`DENNO_GEMV_SHAPE` の形状選択だけが読む。
pub fn gemv_sm_count() -> usize {
    GEMV_SM_COUNT.load(std::sync::atomic::Ordering::Relaxed)
}

/// s169 (P10): GEMV の列ブロック幅 C の選び方 (`DENNO_GEMV_SHAPE`)。
///   0 (既定) = 従来どおり `q4_gemv_c()` の固定 C
///   1 = n が小さい投影 (block 数が SM 数に対して足りない) だけ C=2
///   2 = 常に C=2
///   3 = 小さい投影は C=2 / 大きい投影は C=8 / 中間は固定 C
/// どの値でも**列 (出力行) ごとの k 方向の縮約順は不変** — C は 1 block が
/// 何列をまとめて受けるかだけを変える (既存テスト
/// `cuda_q4_gemv_cols_matches_single_row` が c2/c4/c8 の bit 一致を検証している)。
fn gemv_shape_mode() -> u32 {
    static MODE: OnceLock<u32> = OnceLock::new();
    *MODE.get_or_init(|| {
        match std::env::var("DENNO_GEMV_SHAPE").ok().and_then(|v| v.parse::<u32>().ok()) {
            Some(m @ (1 | 2 | 3)) => m,
            _ => 0,
        }
    })
}

/// s169 (P10): 純関数 — n 行の Q4 GEMV を blocks = ceil(n / (8*C)) で割るときの
/// C を選ぶ。`sm` は SM 数 (0 = 不明 → 常に `base`)。
///
/// 根拠: `dno_gemv_q4_0c{C}` は blockDim = 256 固定 (8 warp が 8*C 列を受ける)
/// なので、並列度は block 数 = ceil(n / (8*C)) だけで決まる。RTX 5090
/// (170 SM) では n = 5120 の投影が 160 block = 0.94 block/SM になり、1 SM
/// あたり 8 warp (= 64 スロットの 12.5%) しか埋まらない。C=2 にすると同じ
/// 重みバイト数を 2 倍の block で読む (総 DRAM バイト数は不変・列ごとの縮約順も
/// 不変) ので、この帯だけ並列度を上げる。
fn gemv_c_for_n(n: usize, sm: usize, mode: u32, base: usize) -> usize {
    if sm == 0 || n == 0 {
        return base;
    }
    // C=4 で 2 block/SM を割れない大きさ = 並列度が足りない帯
    let small = 64 * sm;
    // C=4 で 8 block/SM を超える大きさ = 十分に詰まっている帯
    let large = 128 * sm;
    match mode {
        1 => {
            if n < small {
                2
            } else {
                base
            }
        }
        2 => 2,
        3 => {
            if n < small {
                2
            } else if n >= large {
                8
            } else {
                base
            }
        }
        _ => base,
    }
}

/// dno_attention_prefill が許容する動的 smem の上限 (bytes)。既定 48KB・
/// CudaCtx 生成時の opt-in (cuFuncSetAttribute) 成功時はデバイスの opt-in 上限。
pub fn attn_pf_dynamic_smem_limit() -> usize {
    ATTN_PF_DYN_SMEM.load(std::sync::atomic::Ordering::Relaxed)
}

/// dno_attention_prefill の動的 smem 必要量 (float 数)。
/// q_sm [BQ][dh+1] + k_sm [BK][dh+1] + v_sm [BK][dh+1] + s_sm [BQ*BK]
/// + corr_sm [BQ] + mnew_sm [BQ] (kernels_elem.cu と同期すること)。
fn attn_pf_sh_f(dh: usize) -> usize {
    (ATTN_PF_BQ + 2 * ATTN_PF_BK) * (dh + 1) + ATTN_PF_BQ * ATTN_PF_BK + 2 * ATTN_PF_BQ
}

struct ChainScratch {
    bufs: Vec<Option<DevBuffer>>,
    pin_x: Option<PinMem>,  // x / att アップロード用 (使用間に必ず sync が挟まる)
    pin_dn: Option<PinMem>, // ダウンロード用
    aq: Option<DevBuffer>,  // int8 カーネル用スクラッチ (chain 専用)
    attn_q: Option<DevBuffer>,  // P17g: attention q アップロード用
    attn_sc: Option<DevBuffer>, // P17g: attention scores スクラッチ [heads*t_total]
    attn_pf_q: Option<DevBuffer>, // P17j: prefill attention q アップロード用 [n*heads*dh]
    rope_tab: Option<DevBuffer>,  // P17h: rope cos/sin テーブル [cos(half)|sin(half)]
    rope_bias: Option<DevBuffer>, // P17h: qkv bias パック [qb|kb|vb]
    pin_rope: Option<PinMem>,     // P17h: rope テーブル/... ステップ 1 回のアップロード用
    pin_pf: Option<PinMem>,       // P17k: prefill attention q の pinned ステージング用
    kv_stage: Option<PinMem>,     // P17h: k/v の非同期 D2H ステージング [n_layers][k|v]
    // P17k ステップ 5: qkv→rope→attention デバイス連続化用 (prefill)
    qkv_x: Option<DevBuffer>,     // GEMM 入力 h [n, e] fp32
    qkv_aq: Option<DevBuffer>,    // GEMM 入力量子化 [n, e] int8
    qkv_asc: Option<DevBuffer>,   // GEMM 入力スケール [n] f32
    qkv_pf: Option<DevBuffer>,    // GEMM 出力 [n, qn+kn+vn] (q/k/v 連結・行-major)
    qkv_q: Option<DevBuffer>,     // rope 後 q [n, heads*dh] (attention 入力)
    rope_tab_pf: Option<DevBuffer>, // rope テーブル [n, dh] (行 i = pos0+i の cos|sin)
    pin_qkv: Option<PinMem>,      // h / rope テーブル / bias アップロード用 pinned
    // B3: b>1 バッチ decode の rope (batch_rope_qk)
    br_q: Option<DevBuffer>,      // [b, heads*dh] f32 (in-place rope)
    br_k: Option<DevBuffer>,      // [b, kv_dim] f32 (in-place rope)
    br_tab: Option<DevBuffer>,    // [b, dh] f32 テーブル (行 i = poss[i] の [cos|sin])
    br_pin_qk: Option<PinMem>,    // q/k の H2D/D2H ステージング (sync を挟むので再利用安全)
    br_pin_tab: Option<PinMem>,   // テーブル H2D ステージング
    br_tab_key: Vec<usize>,       // テーブルキャッシュキー (poss・完全一致)
    br_tab_dh: usize,             // テーブルキャッシュキー (dh)
    br_tab_theta: f32,            // テーブルキャッシュキー (theta・bits 比較)
    br_tab_valid: bool,           // dev 上のテーブルがキャッシュキーと一致するか
    // P17h: ステップ内で sync が無くなるため pinned は (層×用途) ごとに専用化する
    // (async H2D の DMA 完了前にホストが上書きする競合を避ける)。id は呼び出し側が
    // 層番号と用途から一意に採番する。
    pins: Vec<Option<PinMem>>,
    // C4: qwen35 chain
    // rope テーブル [cos(n_rot/2) | sin(n_rot/2)] + 転送元 pinned
    q35_tab: Option<DevBuffer>,
    q35_pin_tab: Option<PinMem>,
    /// fp32 重みのデバイスキャッシュ (beta/alpha 制御投影・QK-Norm q/k norm)。
    /// Linear::F32 / Vec<f32> には uid が無いため (model_id, layer, tag) でキー化
    /// する。model_id はロード毎に採番されるため、モデル再ロードで誤キャッシュに
    /// なることはない。
    q35_w_cache: std::collections::HashMap<(u64, usize, u8), DevBuffer>,

    /// s165: rmsnorm 重みのデバイス常駐キャッシュ (`chain_rmsnorm_cached`)。
    /// キーは (model_id, pin_id = 層×用途)。decode chain が 1 ステップに 129 回
    /// 同じ重みを上げ直していた分を初回 1 回にする。
    rms_w: std::collections::HashMap<(u64, usize), DevBuffer>,
    // s167 (P6): GDN prefill の h2 D2H を qkv/z GEMM と重ねるための一式。
    // `DENNO_PF_OVERLAP=1` のときだけ作られる (フラグ OFF では None のまま =
    // 従来の同期 D2H と同一経路・未使用ストリームを残さない)。
    h2_stream: Option<CopyStream>,  // 非ブロッキングの専用コピーストリーム
    h2_ev_ready: Option<CopyEvent>, // main stream の rmsnorm 完了 (発行前の順序付け)
    h2_ev_done: Option<CopyEvent>,  // コピーストリームの D2H 完了 (join)
    pin_h2: Option<PinMem>,         // D2H の宛先 (pinned・grow-only)
    h2_pending: bool,               // 発行済みで未 join の D2H があるか
    // s246 (P46): full 層 att の D2H/H2D と sigmoid ゲートを重ねるための
    // チャンク完了イベント (既定ストリーム・grow-only・層をまたいで再利用)。
    pipe_ev: Vec<CopyEvent>,
    // s247 (P47): full_qk (q/k 射影) の D2H 宛先 = pinned staging (grow-only)。
    // 1 本のプールを q/k の 2 スライスに割り、層をまたいで使い回す (確保は
    // リクエスト最初の full 層で 1 回だけ)。寿命の契約は `PfQkView` を参照。
    pin_pf_qkv: Option<PinMem>,
    // s250 (P53): full_qk の q の D2H を k/v の GEMM と重ねるための一式。
    // h2 の一式 (s167/P6) とは別に持つ — h2 の join 契約 (`h2_pending`) と
    // 混ぜると、同じストリーム上で h2 のコピーと q のコピーが直列化する。
    qk_stream: Option<CopyStream>,  // 非ブロッキングの専用コピーストリーム
    qk_ev_q: Option<CopyEvent>,     // q の GEMM 完了 (発行前の順序付け)
}

thread_local! {
    static CHAIN: std::cell::RefCell<ChainScratch> = std::cell::RefCell::new(ChainScratch {
        bufs: (0..CH_SLOTS).map(|_| None).collect(),
        pin_x: None,
        pin_dn: None,
        aq: None,
        attn_q: None,
        attn_sc: None,
        attn_pf_q: None,
        rope_tab: None,
        rope_bias: None,
        pin_rope: None,
        pin_pf: None,
        kv_stage: None,
        qkv_x: None,
        qkv_aq: None,
        qkv_asc: None,
        qkv_pf: None,
        qkv_q: None,
        rope_tab_pf: None,
        pin_qkv: None,
        br_q: None,
        br_k: None,
        br_tab: None,
        br_pin_qk: None,
        br_pin_tab: None,
        br_tab_key: Vec::new(),
        br_tab_dh: 0,
        br_tab_theta: 0.0,
        br_tab_valid: false,
        pins: Vec::new(),
        q35_tab: None,
        q35_pin_tab: None,
        q35_w_cache: std::collections::HashMap::new(),

        rms_w: std::collections::HashMap::new(),
        h2_stream: None,
        h2_ev_ready: None,
        h2_ev_done: None,
        pin_h2: None,
        h2_pending: false,
        pipe_ev: Vec::new(),
        pin_pf_qkv: None,
        qk_stream: None,
        qk_ev_q: None,

    });
}

fn chain_err(e: anyhow::Error) -> anyhow::Error {
    tracing::error!("cuda chain failed (falling back to CPU): {e:#}");
    eprintln!("cuda chain failed (falling back to CPU): {e:#}");
    GPU_BROKEN.store(true, std::sync::atomic::Ordering::Relaxed);
    e
}

fn chain_fail(e: anyhow::Error) -> Option<()> {
    chain_err(e);
    None
}

/// Result を Option に変換しつつ GPU_BROKEN をマークする
fn ok<T>(r: Result<T, anyhow::Error>) -> Option<T> {
    match r {
        Ok(v) => Some(v),
        Err(e) => {
            chain_err(e);
            None
        }
    }
}

/// B1: prefill デバイス常駐チェーン (`LlamaQwen2::forward_prefill_gpu`) を発動して
/// よいかの事前ゲート (カーネル制約の mirror)。チェーンは all-or-nothing (途中失敗
/// → forward 全体を従来経路でやり直し) なので、構造的に確実に失敗する形状は
/// 開始前に弾く (GPU_BROKEN ラッチの無駄な発火防止)。
/// - `e` (hidden): dno_add_rmsnorm が動的 shmem = e*4 を使う (≤48KB)
/// - `dh`/`t_total`: dno_attention_prefill の制約 (chain_attention_prefill_dev と同一)
pub fn prefill_chain_gpu_supported(e: usize, dh: usize, t_total: usize) -> bool {
    if e == 0 || e * 4 > 48 * 1024 {
        return false;
    }
    if dh < ATTN_PF_BQ || dh > 1024 || t_total == 0 || t_total > 65535 {
        return false;
    }
    // s48 (C1-a): 48KB 固定 → opt-in 済み上限 (既定は 48KB・llama dh=128 は不変)
    if attn_pf_sh_f(dh) * 4 > attn_pf_dynamic_smem_limit() {
        return false;
    }
    true
}

/// s48 (C1): qwen35 prefill の full attention を GPU バッチ (dno_attention_prefill
/// 1 発) にしてよいかの事前ゲート。構造的に確実に失敗する形状を開始前に弾き、
/// GPU_BROKEN ラッチの無駄な発火を防ぐ (llama B1 の prefill_chain_gpu_supported
/// と同一の趣旨)。qwen35 forward_prefill の Full 分岐から呼ばれる。
/// - 発動ゲート: `n >= gemm_min_m()` (既定 256) — 短文 (1b 含む m≤255) は CPU
///   attend のまま bit 不変 (アンカー温存・`maybe_gpu_linear` の GEMM 発動帯域と
///   一致させる設計)
/// - `DENNO_GPU_ATTN=0` で全経路現行に戻る (escape hatch 流用・新 env は作らない)
/// - 動的 smem: dh=256 は 84.8KB で 48KB 既定上限を超える → CudaCtx 生成時の
///   cuFuncSetAttribute opt-in が成功している場合だけ true (失敗なら false =
///   CPU attend フォールバック・llama は影響を受けない)
pub fn attn_prefill_gpu_supported(n: usize, dh: usize, t_total: usize) -> bool {
    attn_prefill_gpu_supported_min(n, dh, t_total, gemm_min_m())
}

/// task 135: 行数の下限だけを呼び出し側が決められる版。
///
/// qwen4exp の prefill attention は attention 専用の下限
/// [`ATTN_Q4_PF_MIN_ROWS`] を使う (`gemm_min_m()` は GEMM の帯域しきい値で、
/// attention のカーネル制約ではない)。qwen35 は従来どおり
/// [`attn_prefill_gpu_supported`] (= この関数を `gemm_min_m()` で呼ぶ) を通るので
/// 挙動は変わらない。
pub fn attn_prefill_gpu_supported_min(
    n: usize,
    dh: usize,
    t_total: usize,
    min_rows: usize,
) -> bool {
    if !cuda_enabled() || !gpu_attention_enabled() {
        return false;
    }
    if !attn_prefill_shape_ok(n, dh, t_total, min_rows) {
        return false;
    }
    // opt-in の結果 (ATTN_PF_DYN_SMEM) は CudaCtx 生成時に確定する。ここまで到達
    // したということは cuda 有効なので、未初期化ならここで生成する (直後の
    // chain_attention_prefill 内部でも生成されるため前倒しで生成するだけ = 新規
    // の副作用は無い)。生成失敗なら CPU フォールバック (GPU_BROKEN にはしない)。
    if shared_ctx().is_none() {
        return false;
    }
    true
}

/// [`attn_prefill_gpu_supported_min`] の純関数部分 (env もデバイスも読まない)。
///
/// `min_rows` だけが差し替え可能で、それ以外 (n > 0・t_total >= n・dh の範囲・
/// 動的 smem の上限) は従来のゲートと同一。
pub(crate) fn attn_prefill_shape_ok(
    n: usize,
    dh: usize,
    t_total: usize,
    min_rows: usize,
) -> bool {
    if n == 0 || t_total == 0 || n < min_rows || t_total < n {
        return false;
    }
    if dh < ATTN_PF_BQ || dh > 1024 {
        return false;
    }
    if attn_pf_sh_f(dh) * 4 > attn_pf_dynamic_smem_limit() {
        return false;
    }
    true
}

/// B1: GEMM 経路 (dno_gemm_i8) が発動する m か。maybe_gpu_ffn / maybe_gpu_oproj /
/// chain_qkv_rope_prefill の内部ゲートと同一条件 (チェーン途中で失敗させないため
/// 呼び出し側が事前確認する)。
pub fn gemm_path_active(m: usize) -> bool {
    m > max_m() && m >= gemm_min_m() && gemm_enabled()
}

fn chain_ctx() -> Option<&'static CudaCtx> {
    if !cuda_enabled() {
        return None;
    }
    let ctx = shared_ctx()?;
    if let Err(e) = ctx.make_current() {
        chain_err(anyhow::anyhow!("cuCtxSetCurrent: {e:#}"));
        return None;
    }
    Some(ctx)
}

fn chain_ensure_buf(slot: usize, bytes: usize) -> Result<(), anyhow::Error> {
    CHAIN.with(|cell| {
        let mut s = cell.borrow_mut();
        // P58-3: prefill の一時バッファは arena から切り出す。同じキー・同じ
        // サイズ以下なら同じオフセットが返るので、リクエストごとの
        // cuMemAlloc / cuMemFree が消える。arena 無効・失敗時は従来の個別確保
        // (fail-open・数値不変)。
        Scratch::ensure_arena(
            &mut s.bufs[slot],
            ARENA_KEY_CHAIN + slot as u32,
            bytes,
            crate::mem_audit::TAG_CHAIN,
        )
            .map_err(chain_err)
    })
}

/// ホストデータをスロットへアップロード (async、同期はしない)。
/// 呼び出し間に sync が挟まる (qkv download) ので pinned バッファの再利用は安全。
pub fn chain_upload(slot: usize, data: &[f32], cols: usize, m: usize) -> Option<()> {
    let _ = chain_ctx()?;
    let bytes = m.checked_mul(cols)?.checked_mul(4)?;
    if data.len() != m * cols {
        return chain_fail(anyhow::anyhow!("chain_upload: size mismatch"));
    }
    ok(chain_ensure_buf(slot, bytes))?;
    CHAIN.with(|cell| -> Option<()> {
        let mut s = cell.borrow_mut();
        ok(Scratch::ensure_pin(&mut s.pin_x, bytes))?;
        let buf = s.bufs[slot].as_ref().unwrap().ptr();
        let pin = s.pin_x.as_mut().unwrap();
        pin.as_mut_slice::<f32>()[..m * cols].copy_from_slice(data);
        let lib = ok(lib())?;
        unsafe {
            ok(check(
                (lib.memcpy_htod_async)(buf, pin.ptr as *const c_void, bytes, std::ptr::null_mut()),
                "cuMemcpyHtoDAsync (chain)",
            ))
        }?;
        // s166 (P5): 観測のみ
        dbg_htod(bytes);
        Some(())
    })
}

/// s55 (T1 step2・計測専用): デフォルトストリームの同期を 1 回打つだけの関数。
/// `chain_download` が内部で行う `ctx.sync()` と**同一の API 呼び出し**
/// (`cuCtxSynchronize`) を、本番 D2H を発行する前に別計測点として観測するための
/// 入口。同期以外の副作用は無く (バッファ確保・転送の発行をしない)、呼んでも
/// 数値経路には触れない。呼び出し側 (qwen35 decode) は `prof::enabled()` が真の
/// ときだけこれを呼ぶ — 本番経路 (非 prof) からは決して到達しない。
pub fn chain_sync_pending() -> Option<()> {
    let ctx = chain_ctx()?;
    ok(ctx.sync())
}

/// 最終 logits の戻しは decode 1 ステップ 1 回の最大 D2H。発行元の件数分類は
/// `prof::chain_download_site` (純関数) がスロットから決める (従来はすべて
/// `D2H_SRC_OTHER` に落ちていた — s108)。
/// s88 (Step 1): 発行点ごとの時間 (表示専用)。計測 OFF では時刻を読まない。
/// ここで件数も一緒に積むので、内側では `mark_d2h_src` を呼ばない
/// (呼ぶと calls が 2 倍になる)。
pub fn chain_download(slot: usize, len: usize) -> Option<Vec<f32>> {
    let site = crate::prof::chain_download_site(slot);
    let t_site = if crate::prof::d2h_src_on() {
        Some(std::time::Instant::now())
    } else {
        None
    };
    let r = chain_download_inner(slot, len);
    match t_site {
        Some(t) => crate::prof::mark_d2h_src_ns(site, t.elapsed().as_nanos() as u64),
        // 計測 OFF: 従来どおり件数だけ (実際は `mark_d2h_src` 側も no-op)。
        None => crate::prof::mark_d2h_src(site),
    }
    r
}

fn chain_download_inner(slot: usize, len: usize) -> Option<Vec<f32>> {
    let ctx = chain_ctx()?;
    let bytes = len.checked_mul(4)?;
    ok(chain_ensure_buf(slot, bytes))?;
    CHAIN.with(|cell| -> Option<Vec<f32>> {
        let buf = cell.borrow().bufs[slot].as_ref()?.ptr();
        // s69: pinned `pin_dn` に落としてから `to_vec` すると同じ領域を 2 度
        // 書くことになる (93MB で約 20ms)。出力 Vec の未初期化領域へ直接
        // D2H し、全要素をコピーが埋めてから set_len する。
        let mut out: Vec<f32> = Vec::with_capacity(len);
        {
            let lib = ok(lib())?;
            unsafe {
                ok(check(
                    (lib.memcpy_dtoh_async)(
                        out.as_mut_ptr() as *mut c_void,
                        buf,
                        bytes,
                        std::ptr::null_mut(),
                    ),
                    "cuMemcpyDtoHAsync (chain)",
                ))?;
            }
        }
        ok(ctx.sync())?;
        unsafe { out.set_len(len) }
        // s166 (P5): 観測のみ
        dbg_d2h(bytes);
        Some(out)
    })
}

/// スロット内の要素オフセット `elem_off` から `len` 個の f32 をダウンロード
/// (D2H + 同期)。B1: prefill チェーンの最終 norm 出力 (CH_H の最終行のみ)
/// 取得用 — [n, e] 全行の D2H を避ける。呼び出し時点でスロットには
/// (elem_off + len) 個分のデータが存在することを前提とする (不足時は None)。
/// 発行元の件数分類は `prof::chain_download_site` (logits 以外は `D2H_SRC_LINEAR`
/// — 活性化の一部を戻す点で linear 系の部分コピーと同類)。
pub fn chain_download_at(slot: usize, elem_off: usize, len: usize) -> Option<Vec<f32>> {
    // s88 (Step 1): 発行点ごとの時間 (表示専用・計測 OFF はクロック読みなし)。
    let t_site = if crate::prof::d2h_src_on() {
        Some(std::time::Instant::now())
    } else {
        None
    };
    let r = chain_download_at_inner(slot, elem_off, len);
    let site = crate::prof::chain_download_site(slot);
    match t_site {
        Some(t) => crate::prof::mark_d2h_src_ns(site, t.elapsed().as_nanos() as u64),
        None => crate::prof::mark_d2h_src(site),
    }
    r
}

fn chain_download_at_inner(slot: usize, elem_off: usize, len: usize) -> Option<Vec<f32>> {
    let ctx = chain_ctx()?;
    let bytes = len.checked_mul(4)?;
    let need = elem_off.checked_mul(4)?.checked_add(bytes)?;
    if !CHAIN.with(|cell| {
        cell.borrow()
            .bufs
            .get(slot)
            .map_or(false, |b| b.as_ref().map_or(false, |b| b.bytes() >= need))
    }) {
        return None;
    }
    CHAIN.with(|cell| -> Option<Vec<f32>> {
        let buf = cell.borrow().bufs[slot].as_ref()?.ptr() + (elem_off * 4) as CUdeviceptr;
        // s69: chain_download と同じ理由で出力 Vec へ直接 D2H する。
        let mut out: Vec<f32> = Vec::with_capacity(len);
        {
            let lib = ok(lib())?;
            unsafe {
                ok(check(
                    (lib.memcpy_dtoh_async)(
                        out.as_mut_ptr() as *mut c_void,
                        buf,
                        bytes,
                        std::ptr::null_mut(),
                    ),
                    "cuMemcpyDtoHAsync (chain download at)",
                ))?;
            }
        }
        ok(ctx.sync())?;
        unsafe { out.set_len(len) }
        // s166 (P5): 観測のみ
        dbg_d2h(bytes);
        Some(out)
    })
}

/// out = rmsnorm(x [+ residual]) — residual スロットを指定すると x += p を先に
/// 行う (o_proj / down 出力の残差加算と融合)。CPU tensor::rmsnorm とビット一致。
/// grid = m ブロック、平方和は thread 0 が CPU と同一の逐次順で計算。
/// `pin_id` は w アップロード用 pinned の専用スロット (P17h: ステップ内に sync が
/// 無いため層×用途で一意に採番する — async H2D の DMA 完了前の上書き競合回避)。
pub fn chain_rmsnorm(
    w: &[f32],
    eps: f32,
    add_slot: Option<usize>,
    out_slot: usize,
    cols: usize,
    m: usize,
    pin_id: usize,
) -> Option<()> {
    chain_rmsnorm_slot(CH_X, w, eps, add_slot, out_slot, cols, m, pin_id)
}

/// s165 (P2): 入力スロットを指定できる rmsnorm。カーネル (`dno_add_rmsnorm`)・
/// grid・block・動的 shmem・引数の並びは [`chain_rmsnorm`] と 1 つも変わらず、
/// 違うのは x のポインタだけ — したがって出力は `chain_rmsnorm` とビット一致する
/// (prefill の残差常駐経路が `CH_PF_RES` を読むために使う)。
pub fn chain_rmsnorm_slot(
    x_slot: usize,
    w: &[f32],
    eps: f32,
    add_slot: Option<usize>,
    out_slot: usize,
    cols: usize,
    m: usize,
    pin_id: usize,
) -> Option<()> {
    let ctx = chain_ctx()?;
    if w.len() != cols {
        return chain_fail(anyhow::anyhow!("chain_rmsnorm: w size mismatch"));
    }
    let wb = cols * 4;
    ok(chain_ensure_buf(out_slot, m * cols * 4 + wb))?; // 末尾 wb バイトは w の作業領域
    CHAIN.with(|cell| -> Option<()> {
        let mut s = cell.borrow_mut();
        // w は呼び出しごとの専用 pinned から非同期アップロード (6KB 程度)。
        if s.pins.len() <= pin_id {
            while s.pins.len() <= pin_id {
                s.pins.push(None);
            }
        }
        let wsrc = {
            ok(Scratch::ensure_pin(&mut s.pins[pin_id], wb))?;
            let pin = s.pins[pin_id].as_mut().unwrap();
            pin.as_mut_slice::<f32>()[..cols].copy_from_slice(w);
            pin.ptr as *const c_void
        };
        let out_buf = s.bufs[out_slot].as_ref().unwrap();
        let wdev = out_buf.ptr() + (m * cols * 4) as u64; // バッファ末尾に置く
        let xptr = s.bufs[x_slot].as_ref()?.ptr();
        let pptr = match add_slot {
            Some(sl) => s.bufs[sl].as_ref().unwrap().ptr(),
            None => 0, // NULL → 単純 rmsnorm
        };
        let optr = out_buf.ptr();
        let lib = ok(lib())?;
        unsafe {
            ok(check(
                (lib.memcpy_htod_async)(wdev, wsrc, wb, std::ptr::null_mut()),
                "cuMemcpyHtoDAsync (chain rmsnorm w)",
            ))?;
        }
        // s166 (P5): 観測のみ (この経路は decode chain では使わない — 0 回が期待値)
        dbg_htod(wb);
        let (mut px, mut pp, mut pw, mut po) = (xptr, pptr, wdev, optr);
        let (mut mc, mut ec) = (cols as c_int, eps);
        let mut args = [
            &mut px as *mut _ as *mut c_void,
            &mut pp as *mut _ as *mut c_void,
            &mut pw as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut mc as *mut _ as *mut c_void,
            &mut ec as *mut _ as *mut c_void,
        ];
        ok(unsafe {
            ctx.launch_async(ctx.f_addnorm, (m as u32, 1, 1), (256, 1, 1), cols as u32 * 4, &mut args)
        })
    })
}

/// s165: [`chain_rmsnorm`] の**重み常駐**版 (decode chain 専用)。
///
/// `chain_rmsnorm` は呼び出しごとに `w` (e×4 = 20,480 B) を pinned から
/// 非同期 H2D する。decode chain は 1 ステップに 2×64+1 = 129 回呼ぶので、
/// 同じ重みを毎ステップ 129 回 (2.6 MB) 上げ直していた — nsys の
/// 「20,480 B × 25,872」がこれで、重みが変化しない以上まったくの無駄。
///
/// ここでは `(key, pin_id)` でデバイス常駐させ、**初回だけ**転送する
/// (`q35_w_dev` の (model_id, layer, tag) と同じ方針)。`key` はモデル
/// ロード毎に一意な `mid`、`pin_id` は呼び出し側が層×用途で一意に採番する
/// (P17h 規約) ので、ヒット = 同じ重み。サイズが変わったら作り直す。
///
/// 数値は `chain_rmsnorm` と同一: 同じカーネル (`dno_add_rmsnorm`)、同じ引数、
/// 同じ重みバイト列で、変わるのは重みの置き場所だけ。重みの転送は
/// `DevBuffer::from_slice` (同期 H2D) で行うが、これは (key, pin_id) ごとに
/// 1 回だけで、以降のステップは 0 回。
pub fn chain_rmsnorm_cached(
    w: &[f32],
    eps: f32,
    add_slot: Option<usize>,
    out_slot: usize,
    cols: usize,
    m: usize,
    pin_id: usize,
    key: u64,
) -> Option<()> {
    let ctx = chain_ctx()?;
    if w.len() != cols {
        return chain_fail(anyhow::anyhow!("chain_rmsnorm_cached: w size mismatch"));
    }
    let wb = cols * 4;
    ok(chain_ensure_buf(out_slot, m.checked_mul(cols)?.checked_mul(4)?))?;
    CHAIN.with(|cell| -> Option<()> {
        let mut s = cell.borrow_mut();
        let stale = match s.rms_w.get(&(key, pin_id)) {
            Some(b) => b.bytes() != wb,
            None => true,
        };
        if stale {
            let buf = ok(DevBuffer::from_slice_tagged(w, crate::mem_audit::TAG_CHAIN))?;
            s.rms_w.insert((key, pin_id), buf);
        }
        let wdev = s.rms_w.get(&(key, pin_id))?.ptr();
        let xptr = s.bufs[CH_X].as_ref()?.ptr();
        let pptr = match add_slot {
            Some(sl) => s.bufs.get(sl)?.as_ref()?.ptr(),
            None => 0, // NULL → 単純 rmsnorm
        };
        let optr = s.bufs.get(out_slot)?.as_ref()?.ptr();
        let (mut px, mut pp, mut pw, mut po) = (xptr, pptr, wdev, optr);
        let (mut mc, mut ec) = (cols as c_int, eps);
        let mut args = [
            &mut px as *mut _ as *mut c_void,
            &mut pp as *mut _ as *mut c_void,
            &mut pw as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut mc as *mut _ as *mut c_void,
            &mut ec as *mut _ as *mut c_void,
        ];
        ok(unsafe {
            ctx.launch_async(ctx.f_addnorm, (m as u32, 1, 1), (256, 1, 1), cols as u32 * 4, &mut args)
        })
    })
}

/// スロット内の f32 を int8 量子化して grouped GEMV (デバイス内完結)。
/// H2D/D2H/同期なし。f_quant / f_mv / 重みレジストリは P17b/c と同一 → ビット一致。
pub fn chain_linear_grouped(
    parts: &[&Quant8Linear],
    in_slot: usize,
    out_slot: usize,
    m: usize,
) -> Option<()> {
    let ctx = chain_ctx()?;
    if m > max_m() {
        return None;
    }
    let k = parts[0].k;
    let n: usize = parts.iter().map(|p| p.n).sum();
    let uids: Vec<u64> = parts.iter().map(|p| p.uid).collect();
    let gw = ok(weights_for_group(&uids, parts, k, n))?;
    ok(chain_ensure_buf(in_slot, m * k * 4))?;
    ok(chain_ensure_buf(out_slot, m * n * 4))?;
    CHAIN.with(|cell| -> Option<()> {
        let mut s = cell.borrow_mut();
        ok(Scratch::ensure(&mut s.aq, m * k))?;
        let iptr = s.bufs[in_slot].as_ref().unwrap().ptr();
        let optr = s.bufs[out_slot].as_ref().unwrap().ptr();
        let aq = s.aq.as_ref().unwrap().ptr();
        // asc は per-op SCRATCH を共有 (同一スレッド内なので競合しない)
        SCRATCH.with(|c2| -> Option<()> {
            let mut s2 = c2.borrow_mut();
            ok(Scratch::ensure(&mut s2.asc, m * 4))?;
            let asc = s2.asc.as_ref().unwrap().ptr();
            let (mut px, mut paq, mut pasc) = (iptr, aq, asc);
            let (mut mc, mut kc) = (m as c_int, k as c_int);
            let mut args = [
                &mut px as *mut _ as *mut c_void,
                &mut paq as *mut _ as *mut c_void,
                &mut pasc as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
            ];
            ok(unsafe { ctx.launch_async(ctx.f_quant, (m as u32, 1, 1), (256, 1, 1), 256 * 4, &mut args) })?;
            let (mut paqi, mut pasci, mut pw, mut psc, mut po) =
                (aq, asc, gw.w.ptr(), gw.sc.ptr(), optr);
            let (mut mc, mut kc, mut nc) = (m as c_int, k as c_int, n as c_int);
            let mut args = [
                &mut paqi as *mut _ as *mut c_void,
                &mut pasci as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut psc as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            ok(unsafe { ctx.launch_async(ctx.f_mv, (n as u32, 1, 1), (128, 1, 1), 0, &mut args) })
        })
    })
}

/// s157 (Task B20 段階 1): Q4_0 重みの grouped GEMV を**デバイス常駐バッファ同士**で
/// 発行する (enqueue のみ・同期なし・ホストスライスなし)。
///
/// `chain_linear_grouped` (int8) と対になる入口。重みは `weights_for_q4` の VRAM
/// レジストリ (nib / sc) をそのまま使い、カーネルは per-op 経路
/// (`q4_dispatch_tile`) と**同一の `dno_gemv_q4_0c{C}`・同一引数・同一グリッド**で
/// 起動する — 変わるのは「いつ同期するか」だけで、数値経路は 1 bit も変えない。
///
/// 出力は `parts` の順に連結する (`chain_linear_grouped` の重み連結と同じ並び)。
/// `parts` は k が揃っていること・k が Q4 ブロック (32) の倍数であることが前提。
pub fn chain_linear_q4_device(
    parts: &[&crate::quant::Q4Linear],
    in_slot: usize,
    out_slot: usize,
    m: usize,
) -> Option<()> {
    let ctx = chain_ctx()?;
    if parts.is_empty() || m > max_m() {
        return None;
    }
    let k = parts[0].k;
    if parts.iter().any(|p| p.k != k) || k % 32 != 0 {
        return None;
    }
    let n_tot: usize = parts.iter().map(|p| p.n).sum();
    // 重みは初回だけ転送する (以降はレジストリから引く = ホスト側の確保なし)。
    let mut gws = Vec::with_capacity(parts.len());
    for p in parts {
        gws.push(ok(weights_for_q4(p.uid, &p.blocks, p.k, p.n))?);
    }
    ok(chain_ensure_buf(in_slot, m * k * 4))?;
    ok(chain_ensure_buf(out_slot, m * n_tot * 4))?;
    // per-op 経路と同じ列ブロック版 (m = 1 の decode も同じカーネル)。
    // `q4_gemv_c()` は env を毎回読む — per-op 経路は 1 step に数回だが、chain は
    // 層ループの中で 1 step に数百回呼ばれるので、ここで 1 回だけ読んで使い回す。
    static C: OnceLock<usize> = OnceLock::new();
    let base_c = *C.get_or_init(q4_gemv_c);
    // s169 (P10): 列ブロック幅 C は**投影ごと**に選ぶ (`DENNO_GEMV_SHAPE`)。
    // 既定 0 は従来どおり全投影で同じ C = 挙動不変。C は 1 block が受ける列数
    // だけを変えるので、列ごとの k 方向の縮約順 (lane が受けるブロック昇順 ->
    // shfl 木) は C に依存しない = どの C でもビット一致 (c2/c4/c8 の一致は
    // 既存テスト `cuda_q4_gemv_cols_matches_single_row` が見ている)。
    let shape = gemv_shape_mode();
    let sm = gemv_sm_count();
    let fc_all = ctx.f_mv_q4_c?;
    CHAIN.with(|cell| -> Option<()> {
        let s = cell.borrow();
        let iptr = s.bufs[in_slot].as_ref()?.ptr();
        let optr = s.bufs[out_slot].as_ref()?.ptr();
        let mut off = 0usize;
        for (p, gw) in parts.iter().zip(gws.iter()) {
            let (mut pa, mut pn, mut ps, mut po) =
                (iptr, gw.nib.ptr(), gw.sc.ptr(), optr + (off * 4) as u64);
            let (mut mc, mut kc, mut nc) = (m as c_int, k as c_int, p.n as c_int);
            let mut args = [
                &mut pa as *mut _ as *mut c_void,
                &mut pn as *mut _ as *mut c_void,
                &mut ps as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            // s169 (P10): 投影ごとに C を選ぶ (既定 0 は base_c = 従来と同一)。
            let c = gemv_c_for_n(p.n, sm, shape, base_c);
            let f_c = fc_all[q4_gemv_c_index(c)];
            let grid = (p.n.div_ceil(8 * c) as u32, m as u32, 1);
            ok(unsafe { ctx.launch_async(f_c, grid, (256, 1, 1), 0, &mut args) })?;
            dbg_gemv_shape(p.n, c);
            off += p.n;
        }
        Some(())
    })
}

/// s166 (P5): qkv (+z) 投影を**連結重み 1 本**の GEMV 1 回で回す。
///
/// 背景 (nsys・2026-10-22 の decode 1 ステップ): `dno_gemv_q4_0c4` は 337 発で、
/// 内訳は 48 GDN 層 × 5 + 16 full 層 × 6 + lm_head 1 = 337 (実測 336)。
/// 1 層あたり 5/6 発になるのは **qkv グループが part ごとに別 launch** だから
/// (full: q|k|v の 3 発、GDN: qkv|z の 2 発)。FFN の gate/up は P3 で 1 本の
/// 連結重みにまとまって 1 発なので、同じ扱いを qkv にも広げると 337 -> 257 発。
///
/// 数値は不変: `dno_gemv_q4_0c{C}` は出力 32 列を 1 block が受ける形で、列
/// (= 出力行) ごとに独立。行の並びが [q|k|v] のまま変わらないので、1 回の
/// launch で計算しても part ごとの launch と同じビット列になる (gate_up と
/// 同じ論法)。カーネル・引数・グリッドの形も [`chain_linear_q4_device`] と同一。
///
/// メモリ: 連結重みの行範囲は [`q4_register_row_alias`] で parts に割り当てる
/// (parts は連結側のビューになる = VRAM は増えない)。**parts が既に個別に
/// VRAM へ載っている場合は連結側を上げない** (2 重になるため)。前提が崩れたら
/// per-part の従来経路にそのまま落ちる (fail closed・数値は同一)。
pub fn chain_linear_q4_fused(
    fused: &crate::quant::Q4Linear,
    parts: &[&crate::quant::Q4Linear],
    in_slot: usize,
    out_slot: usize,
    m: usize,
) -> Option<()> {
    // 形状契約 (満たさなければ従来の per-part 経路 = 数値は同一)
    let mut ok_shape = !parts.is_empty() && fused.k != 0 && fused.k % 32 == 0 && fused.n != 0;
    let mut sum = 0usize;
    if ok_shape {
        for p in parts {
            if p.k != fused.k {
                ok_shape = false;
                break;
            }
            match sum.checked_add(p.n) {
                Some(s) => sum = s,
                None => {
                    ok_shape = false;
                    break;
                }
            }
        }
        ok_shape = ok_shape && sum == fused.n;
    }
    if !ok_shape {
        return chain_linear_q4_device(parts, in_slot, out_slot, m);
    }
    if !q4_fused_ready(fused.uid, parts) {
        // まだ割り当てていない: parts が個別に載っていなければ連結側を上げて割り当てる。
        // 載っているなら諦める (連結側を上げると VRAM が 2 重になる)。
        if parts.iter().any(|p| q4_resident(p.uid)) {
            return chain_linear_q4_device(parts, in_slot, out_slot, m);
        }
        if !q4_register_row_alias_q4(fused, parts) || !q4_fused_ready(fused.uid, parts) {
            return chain_linear_q4_device(parts, in_slot, out_slot, m);
        }
    }
    chain_linear_q4_device(&[fused], in_slot, out_slot, m)
}

/// s157 (Task B20 段階 1): 27B q4 の decode を chain 経路で回すか。
/// `DENNO_GPU_Q4_CHAIN=0` で従来の per-op 経路 (1 step に約 392 回の D2H) に戻せる。
/// 既定は chain (デバイス常駐・同期は step 末尾の logits 1 回)。
pub fn q4_chain_enabled() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| parse_q4_chain(std::env::var("DENNO_GPU_Q4_CHAIN").ok().as_deref()))
}

/// s157 (Task B20 段階 1): `DENNO_GPU_Q4_CHAIN` の解釈 (純関数・テスト可能)。
/// **`"0"` だけが off** — 未設定・空・その他の値は既定の on (従来の per-op 経路へ
/// 戻すのは明示的な 0 だけ。タイポで静かに経路が変わるのを避ける)。
pub fn parse_q4_chain(raw: Option<&str>) -> bool {
    raw != Some("0")
}

/// s157 (Task B20 段階 1): chain 経路の線形呼び出し (**int8 / q4 の両対応**)。
///
/// 1 グループは全部 int8 か全部 q4 のどちらか (混在は受けない → `None` を返して
/// 呼び出し側が per-op 経路へ委譲する)。どちらの経路も enqueue のみで同期しない。
pub fn chain_linear(
    parts: &[&crate::quant::Linear],
    in_slot: usize,
    out_slot: usize,
    m: usize,
) -> Option<()> {
    if parts.is_empty() {
        return None;
    }
    if parts.iter().all(|p| p.quant8().is_some()) {
        let q: Vec<&Quant8Linear> = parts.iter().filter_map(|p| p.quant8()).collect();
        return chain_linear_grouped(&q, in_slot, out_slot, m);
    }
    if parts
        .iter()
        .all(|p| matches!(p, crate::quant::Linear::Q4(_)))
    {
        let q: Vec<&crate::quant::Q4Linear> = parts
            .iter()
            .map(|p| match p {
                crate::quant::Linear::Q4(x) => x,
                _ => unreachable!("all() で Q4 のみ確認済み"),
            })
            .collect();
        return chain_linear_q4_device(&q, in_slot, out_slot, m);
    }
    None
}

/// swiglu: ga スロットの [gate|up] から act = (g/(1+exp(-g)))*u を計算
/// (デバイス内完結)。CPU silu_inplace + gate[i] *= up[i] とビット一致。
pub fn chain_swiglu(ga_slot: usize, act_slot: usize, ff: usize, m: usize) -> Option<()> {
    let ctx = chain_ctx()?;
    ok(chain_ensure_buf(act_slot, m * ff * 4))?;
    CHAIN.with(|cell| -> Option<()> {
        let s = cell.borrow();
        let gaptr = s.bufs[ga_slot].as_ref().unwrap().ptr();
        let optr = s.bufs[act_slot].as_ref().unwrap().ptr();
        let (mut pg, mut pu, mut po) = (gaptr, gaptr + (ff as u64) * 4, optr);
        let mut tc = (m * ff) as c_int;
        let mut args = [
            &mut pg as *mut _ as *mut c_void,
            &mut pu as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut tc as *mut _ as *mut c_void,
        ];
        let grid = ((m * ff) as u32).div_ceil(256);
        ok(unsafe { ctx.launch_async(ctx.f_swiglu, (grid, 1, 1), (256, 1, 1), 0, &mut args) })
    })
}

/// s70: prefill 用の grouped int8 GEMM。`chain_linear_grouped` は decode 用に
/// `m > max_m()` で諦めて GEMV カーネルを起動するが、prefill は m が大きく
/// 128x128 タイルの GEMM を使う必要がある。数値は同じカーネル・同じ整数累積
/// なので CPU 経路とビット一致。
fn chain_gemm_grouped_pf(
    parts: &[&crate::quant::Quant8Linear],
    in_slot: usize,
    out_slot: usize,
    m: usize,
) -> Option<()> {
    let ctx = chain_ctx()?;
    if parts.is_empty() || m == 0 {
        return None;
    }
    let k = parts[0].k;
    let n: usize = parts.iter().map(|p| p.n).sum();
    let uids: Vec<u64> = parts.iter().map(|p| p.uid).collect();
    let gw = ok(weights_for_group(&uids, parts, k, n))?;
    ok(chain_ensure_buf(in_slot, m.checked_mul(k)?.checked_mul(4)?))?;
    ok(chain_ensure_buf(out_slot, m.checked_mul(n)?.checked_mul(4)?))?;
    CHAIN.with(|cell| -> Option<()> {
        let mut s = cell.borrow_mut();
        ok(Scratch::ensure(&mut s.aq, m * k))?;
        let iptr = s.bufs[in_slot].as_ref().unwrap().ptr();
        let optr = s.bufs[out_slot].as_ref().unwrap().ptr();
        let aq = s.aq.as_ref().unwrap().ptr();
        SCRATCH.with(|c2| -> Option<()> {
            let mut s2 = c2.borrow_mut();
            ok(Scratch::ensure(&mut s2.asc, m * 4))?;
            let asc = s2.asc.as_ref().unwrap().ptr();
            let (mut px, mut paq, mut pasc) = (iptr, aq, asc);
            let (mut mc, mut kc) = (m as c_int, k as c_int);
            let mut args = [
                &mut px as *mut _ as *mut c_void,
                &mut paq as *mut _ as *mut c_void,
                &mut pasc as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
            ];
            ok(unsafe { ctx.launch_async(ctx.f_quant, (m as u32, 1, 1), (256, 1, 1), 256 * 4, &mut args) })?;
            let (mut paqi, mut pasci, mut pw, mut psc, mut po) =
                (aq, asc, gw.w.ptr(), gw.sc.ptr(), optr);
            let (mut mc, mut kc, mut nc) = (m as c_int, k as c_int, n as c_int);
            let mut args = [
                &mut paqi as *mut _ as *mut c_void,
                &mut pasci as *mut _ as *mut c_void,
                &mut pw as *mut _ as *mut c_void,
                &mut psc as *mut _ as *mut c_void,
                &mut po as *mut _ as *mut c_void,
                &mut mc as *mut _ as *mut c_void,
                &mut kc as *mut _ as *mut c_void,
                &mut nc as *mut _ as *mut c_void,
            ];
            let gmx = m.div_ceil(GEMM_TILE) as u32;
            let gmy = n.div_ceil(GEMM_TILE_N) as u32;
            ok(unsafe { ctx.launch_async(ctx.f_gemm, (gmx, gmy, 1), (GEMM_BX, GEMM_BY, 1), 0, &mut args) })
        })
    })
}

/// s70: 行内 [gate|up] 連結レイアウト (width = 2*ff) の swiglu。m > 1 でも
/// 使えるのは `dno_swiglu_int` 側 (`dno_swiglu` は gate/up がブロック分離の
/// 前提なので m=1 専用)。演算列は CPU の `gv / (1+exp(-gv)) * uv` と同一。
pub fn chain_swiglu_rows(ga_slot: usize, act_slot: usize, ff: usize, m: usize) -> Option<()> {
    let ctx = chain_ctx()?;
    if ff == 0 || m == 0 {
        return None;
    }
    ok(chain_ensure_buf(act_slot, m.checked_mul(ff)?.checked_mul(4)?))?;
    CHAIN.with(|cell| -> Option<()> {
        let s = cell.borrow();
        let gaptr = s.bufs[ga_slot].as_ref()?.ptr();
        let optr = s.bufs[act_slot].as_ref()?.ptr();
        let (mut pg, mut po) = (gaptr, optr);
        let mut ffc = ff as c_int;
        let mut width = (2 * ff) as c_int;
        let mut tc = (m * ff) as i64;
        let mut args = [
            &mut pg as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut ffc as *mut _ as *mut c_void,
            &mut width as *mut _ as *mut c_void,
            &mut tc as *mut _ as *mut c_void,
        ];
        let grid = ((m * ff) as u64).div_ceil(256) as u32;
        ok(unsafe { ctx.launch_async(ctx.f_swiglu_int, (grid, 1, 1), (256, 1, 1), 0, &mut args) })
    })
}


/// s163: prefill の FFN を **Q4 重みでも** デバイス常駐で通す
/// (`chain_mlp_prefill` の Q4 版)。旧経路は 1 層あたり
///   H2D h2 (m*e*4) + D2H gate (m*ff*4) + D2H up (m*ff*4)
///   + H2D hh (m*ff*4) + D2H down (m*e*4)
/// の 5 往復 (m=13000, e=5120, ff=17408 で 1 層 約 5.4 GB) していた。
/// 新経路は H2D h2 + D2H down の 2 往復だけで、中間の gate/up/act は
/// デバイス上に留まる。
///
/// ビット一致: q4 GEMM は per-op 経路と同一カーネル (`dno_gemm_q4_0`)・同一
/// グリッド・同一引数で、行ごとに独立 (m の分割は 1 行の累積順を変えない)。
/// swiglu は `dno_swiglu` (CPU の `g/(1+exp(-g))*u` と同一演算列)。
/// したがってタイル分割しても出力は従来経路とビット一致する。
///
/// メモリ: 行タイル `CH_MLP_TILE_Q4` ごとに処理するので、チェーンバッファは
/// タイル分だけで済む (13000 行を一度に置くと ff 中間 3 枚で 2.7 GB になる)。
pub fn chain_mlp_prefill_q4(
    gate: &crate::quant::Linear,
    up: &crate::quant::Linear,
    down: &crate::quant::Linear,
    x: &[f32],
    m: usize,
    li: usize,
    out: &mut [f32],
) -> Option<()> {
    let e = gate_dims_in(gate)?;
    if x.len() < m.checked_mul(e)? || out.len() < m.checked_mul(e)? {
        return None;
    }
    chain_mlp_prefill_q4_impl(
        PfGu::Split(gate, up),
        down,
        PfSrc::Host(x),
        PfSink::Host(out),
        m,
        li,
    )
}

/// s173 (P14): [`chain_mlp_prefill_q4`] の**連結重み**版 (ホスト入出力)。
///
/// `gate_up` は `Layer::gate_up_w` = [gate 全行 | up 全行] の行連結 1 本。
/// 1 タイルあたりの launch は「gate|up の 1 回の GEMM + swiglu + down」の
/// 3 発になる (従来は gate / up が別で 4 発)。
///
/// 前提 (すべて Q4・形の整合・`gate_up` が gate/up の行範囲として登録済み) は
/// [`pf_ffn_fused_ready`] で確認する。満たさないときは `None` を返す =
/// 呼び出し側は 2 回呼び出しの [`chain_mlp_prefill_q4`] へ落ちる (fail closed)。
pub fn chain_mlp_prefill_q4_fused(
    gate_up: &crate::quant::Linear,
    down: &crate::quant::Linear,
    x: &[f32],
    m: usize,
    li: usize,
    out: &mut [f32],
) -> Option<()> {
    let e = down_dims_out(down)?;
    if x.len() < m.checked_mul(e)? || out.len() < m.checked_mul(e)? {
        return None;
    }
    chain_mlp_prefill_q4_impl(
        PfGu::Fused(gate_up),
        down,
        PfSrc::Host(x),
        PfSink::Host(out),
        m,
        li,
    )
}

/// s165 (P2): FFN チェーンの入出力をデバイス常駐で回す版。入力は `CH_PFH`
/// (rmsnorm 出力・先頭から m 行)、出力は `CH_DOWN` — 転送も同期も 0 回で、
/// 後続の残差加算 (次の rmsnorm の proj) が同じストリームで読む。
/// カーネル・タイル幅・引数は [`chain_mlp_prefill_q4`] と同一 (数値不変)。
pub fn chain_mlp_prefill_q4_dev(
    gate: &crate::quant::Linear,
    up: &crate::quant::Linear,
    down: &crate::quant::Linear,
    m: usize,
    li: usize,
) -> Option<()> {
    chain_mlp_prefill_q4_impl(
        PfGu::Split(gate, up),
        down,
        PfSrc::Slot,
        PfSink::Slot,
        m,
        li,
    )
}

/// s173 (P14): [`chain_mlp_prefill_q4_dev`] の**連結重み**版。
///
/// 入力は `CH_PFH`・出力は `CH_DOWN` のまま (転送 0 回) で、違うのは
/// 「gate と up を 1 回の GEMM で `CH_GA` の行内連結 [gate|up] へ書く」点だけ。
/// 続く swiglu は行内レイアウト用の `dno_swiglu_int` になる (演算列は
/// `dno_swiglu` と同一 = CPU の `silu(g)*u` とビット一致)。
///
/// ビット一致の根拠: `dno_gemm_q4_0` の出力 `out[i*n + j]` は k 方向の
/// 累積だけで決まり、n は行ストライドと境界判定にしか使われない
/// (`j0 = blockIdx.y * 128`)。したがって n=2ff の 1 回呼び出しは、
/// n=ff の 2 回呼び出しと**同じ値**を、行内 [gate|up] の並びで書く。
pub fn chain_mlp_prefill_q4_dev_fused(
    gate_up: &crate::quant::Linear,
    down: &crate::quant::Linear,
    m: usize,
    li: usize,
) -> Option<()> {
    chain_mlp_prefill_q4_impl(
        PfGu::Fused(gate_up),
        down,
        PfSrc::Slot,
        PfSink::Slot,
        m,
        li,
    )
}

/// [`chain_mlp_prefill_q4`] の入力次元 (k)。Q4 以外は None。
fn gate_dims_in(w: &crate::quant::Linear) -> Option<usize> {
    match w {
        crate::quant::Linear::Q4(q) => Some(q.k),
        _ => None,
    }
}

/// [`chain_mlp_prefill_q4_fused`] の出力次元 (e = down.n)。Q4 以外は None。
fn down_dims_out(w: &crate::quant::Linear) -> Option<usize> {
    match w {
        crate::quant::Linear::Q4(q) => Some(q.n),
        _ => None,
    }
}

/// s173 (P14): FFN を **1 回の gate|up GEMM** で通せるか (GPU を触らない事前検査)。
///
/// 条件: gate_up / gate / up / down がすべて Q4・形の整合 (`gate_up` が
/// [gate 全行 | up 全行]・k = e・n = 2*ff)・**gate/up が連結側の行範囲として
/// 登録済み** ([`q4_register_row_alias`])。
///
/// 最後の条件は VRAM/H2D を増やさないためのもの: 未登録のまま連結重みを使うと
/// 2*ff*e を別途転送することになる (登録済みなら `weights_for_q4` は連結側の
/// 既存デバイス領域を指すビューを返す)。満たさないときは呼び出し側は従来の
/// 2 回呼び出し経路のまま = fail closed。
pub fn pf_ffn_fused_ready(
    gate_up: &crate::quant::Linear,
    gate: &crate::quant::Linear,
    up: &crate::quant::Linear,
    down: &crate::quant::Linear,
) -> bool {
    if !pf_ffn_fused_enabled() {
        return false;
    }
    let (Some(c), Some(g), Some(u), Some(d)) =
        (q4_of(gate_up), q4_of(gate), q4_of(up), q4_of(down))
    else {
        return false;
    };
    if !ffn_fused_shape_ok(c, g, u, d) {
        return false;
    }
    q4_fused_ready(c.uid, &[g, u])
}

/// s173 (P14): FFN の gate|up を 1 回の GEMM に畳むか (既定 ON)。
///
/// `DENNO_PF_FFN_FUSED=0` で従来の 2 回呼び出しへ戻す — A/B 用のスイッチで、
/// **数値は経路によらず同一** (カーネル・累積順・タイル幅は不変)。
fn pf_ffn_fused_enabled() -> bool {
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| parse_pf_ffn_fused(std::env::var("DENNO_PF_FFN_FUSED").ok().as_deref()))
}

/// s173 (P14): `DENNO_PF_FFN_FUSED` の解釈 (純関数・テスト可能)。
/// `parse_q4_chain` と同じ規約で、**`"0"` だけが off** (未設定・空・その他は on)。
fn parse_pf_ffn_fused(raw: Option<&str>) -> bool {
    raw != Some("0")
}

/// s173 (P14): [`pf_ffn_fused_ready`] の**形状だけ**の契約 (純粋関数・GPU と
/// エイリアス表に触らない)。
///
/// `gate_up` = [gate 全行 | up 全行]・k = e・n = 2*ff・`down` = [ff, e]。
/// ここが崩れると連結重みの行範囲が別の重みを指す (数値が変わる) ので、
/// 満たさない入力はすべて false (= 従来の 2 回呼び出しへフォールバック)。
fn ffn_fused_shape_ok(
    c: &crate::quant::Q4Linear,
    g: &crate::quant::Q4Linear,
    u: &crate::quant::Q4Linear,
    d: &crate::quant::Q4Linear,
) -> bool {
    if c.k != g.k || c.k != u.k || c.n != g.n + u.n {
        return false;
    }
    // ff = g.n = u.n = down.k、e = c.k = down.n、連結幅 = 2*ff
    d.k == g.n && d.n == c.k && c.n == 2 * d.k
}

/// s173 (P14): FFN の gate/up の与え方。
///
/// `Split` は従来どおり別々の重みで 2 回の GEMM (`CH_GA` の前半/後半へ)、
/// `Fused` は [gate 全行 | up 全行] の連結重み 1 本で 1 回の GEMM
/// (`CH_GA` へ行内 [gate|up] で書く)。GEMM の k 方向累積順は両者で同一。
enum PfGu<'a> {
    Split(&'a crate::quant::Linear, &'a crate::quant::Linear),
    Fused(&'a crate::quant::Linear),
}

/// s165 (P2): prefill チェーンの入力の出所。
/// `Host` は従来どおりホスト slice をタイルごとに H2D、`Slot` は
/// 「既にデバイスに居る」ことを表す — 消えるのは転送だけで、カーネル・grid・
/// 引数・演算列は 1 つも変わらない (行ごとに独立なので bit 一致)。
enum PfSrc<'a> {
    Host(&'a [f32]),
    /// `CH_PFH` の先頭から m 行 (rmsnorm 出力) をそのまま読む
    Slot,
}

/// s165 (P2): prefill チェーンの出力先。`Slot` はデバイス常駐バッファ
/// (`CH_DOWN` / `CH_O`) に書き、D2H と同期を行わない。
enum PfSink<'a> {
    Host(&'a mut [f32]),
    Slot,
}

/// [`chain_mlp_prefill_q4`] の本体 (gate/up の与え方と入出力の出所を差し替える)。
fn chain_mlp_prefill_q4_impl(
    gu_src: PfGu<'_>,
    down: &crate::quant::Linear,
    src: PfSrc<'_>,
    mut sink: PfSink<'_>,
    m: usize,
    li: usize,
) -> Option<()> {
    use crate::quant::Linear;
    if !cuda_enabled()
        || !gemm_enabled()
        || m < gemm_min_m()
        || GPU_BROKEN.load(std::sync::atomic::Ordering::Relaxed)
    {
        return None;
    }
    let ctx = chain_ctx()?;
    let du = match down {
        Linear::Q4(c) => c,
        _ => return None,
    };
    // s173 (P14): gate/up の重みとレイアウト。`Fused` では 1 本の連結重みで
    // gate|up を 1 回の GEMM にまとめる (ff は down.k、e は down.n から取る)。
    let (e, ff, gw1, gw2) = match gu_src {
        PfGu::Split(gate, up) => {
            let (gu, uu) = match (gate, up) {
                (Linear::Q4(a), Linear::Q4(b)) => (a, b),
                _ => return None,
            };
            let e = gu.k;
            let ff = gu.n;
            if uu.k != e || uu.n != ff || du.k != ff || du.n != e {
                return None;
            }
            let gw1 = weights_for_q4(gu.uid, &gu.blocks, gu.k, gu.n).ok()?;
            let gw2 = weights_for_q4(uu.uid, &uu.blocks, uu.k, uu.n).ok()?;
            (e, ff, gw1, Some(gw2))
        }
        PfGu::Fused(gate_up) => {
            let c = match gate_up {
                Linear::Q4(x) => x,
                _ => return None,
            };
            let e = du.n;
            let ff = du.k;
            if c.k != e || ff == 0 || c.n != 2 * ff {
                return None;
            }
            let gw1 = weights_for_q4(c.uid, &c.blocks, c.k, c.n).ok()?;
            (e, ff, gw1, None)
        }
    };
    let gw3 = weights_for_q4(du.uid, &du.blocks, du.k, du.n).ok()?;
    if m == 0 {
        return None;
    }
    if let PfSrc::Host(x) = src {
        if x.len() < m * e {
            return None;
        }
    }
    if let PfSink::Host(out) = &sink {
        if out.len() < m * e {
            return None;
        }
    }
    // Slot 出力は CH_DOWN の行オフセットへ書くので、全行ぶんの領域を要求する
    // (タイルごとの ensure は 1 タイル分しか保証しない)。
    if matches!(sink, PfSink::Slot) {
        ok(chain_ensure_buf(CH_DOWN, m.checked_mul(e)?.checked_mul(4)?))?;
    }
    // s168 (P7): タイル幅は `DENNO_Q4_M_TILE` の実効値、端数は直前のタイルへ併合。
    // 中間バッファは 1 タイルの**最大**行数 (`q4_tile_max_rows`) でループの前に
    // 確保する — 併合されるのは最終タイルだけなので、ループ内で grow させると
    // 先行 launch が読んでいるバッファを解放しうる。
    let tile = q4_m_tile();
    let cap = q4_tile_max_rows(tile).min(m);
    ok(chain_ensure_buf(CH_PFH, cap * e * 4))?;
    ok(chain_ensure_buf(CH_GA, cap * 2 * ff * 4))?;
    ok(chain_ensure_buf(CH_ACT, cap * ff * 4))?;
    ok(chain_ensure_buf(CH_DOWN, cap * e * 4))?;
    let _ = li;
    let mut r0 = 0usize;
    while r0 < m {
        let mr = q4_group_rows(r0, m, tile);
        debug_assert!(mr <= cap, "tile group {mr} > cap {cap}");
        // 出力先 (Host のときだけ D2H する)。生ポインタで持って CHAIN の
        // クロージャに渡す (Vec の再借用を避ける)。
        let dst: Option<*mut f32> = match &mut sink {
            PfSink::Host(out) => Some(out[r0 * e..].as_mut_ptr()),
            PfSink::Slot => None,
        };
        CHAIN.with(|cell| -> Option<()> {
            let s = cell.borrow();
            let pga = s.bufs[CH_GA].as_ref()?.ptr();
            let pact = s.bufs[CH_ACT].as_ref()?.ptr();
            // 出力の書き先: Host はタイル先頭 (D2H で呼び出し元の行へ)、
            // Slot は CH_DOWN の該当行 (デバイス常駐・行オフセットへ書く)。
            let pdown = match &sink {
                PfSink::Host(_) => s.bufs[CH_DOWN].as_ref()?.ptr(),
                PfSink::Slot => s.bufs[CH_DOWN].as_ref()?.ptr() + (r0 * e * 4) as u64,
            };
            let up_off = (mr * ff * 4) as u64;
            // 1) 入力: Host ならタイルを H2D、Slot なら CH_PFH の該当行を直接読む
            let pin = match &src {
                PfSrc::Host(x) => {
                    let buf = s.bufs[CH_PFH].as_ref()?.ptr();
                    let lib = lib().ok()?;
                    unsafe {
                        ok(check(
                            (lib.memcpy_htod_async)(
                                buf,
                                x[r0 * e..].as_ptr() as *const c_void,
                                mr * e * 4,
                                std::ptr::null_mut(),
                            ),
                            "cuMemcpyHtoDAsync (mlp prefill q4)",
                        ))?
                    }
                    buf
                }
                PfSrc::Slot => s.bufs[CH_PFH].as_ref()?.ptr() + (r0 * e * 4) as u64,
            };
            // 2) gate → CH_GA 前半 / up → CH_GA 後半 / 3) swiglu / 4) down
            // s173 (P14): 連結重みがあるときは gate|up を**1 回の GEMM**で
            // CH_GA へ行内 [gate|up] で書く (launch 4 -> 3)。続く swiglu は
            // 行内レイアウト用の `dno_swiglu_int` (演算列は `dno_swiglu` と同一)。
            pf_phase(PF_PH_FFN_GATE);
            crate::prof::time_layer(crate::prof::GATE_UP, li, || -> Option<()> {
                match gw2 {
                    Some(gw_up) => {
                        chain_gemm_q4_pf(gw1, pin, pga, mr, e, ff)?;
                        chain_gemm_q4_pf(gw_up, pin, pga + up_off, mr, e, ff)
                    }
                    None => chain_gemm_q4_pf(gw1, pin, pga, mr, e, 2 * ff),
                }
            })?;
            pf_phase(PF_PH_SWIGLU);
            crate::prof::time_layer(crate::prof::SWIGLU, li, || -> Option<()> {
                match gw2 {
                    Some(_) => chain_swiglu_split(pga, pga + up_off, pact, mr * ff),
                    None => chain_swiglu_int_at(pga, pact, ff, mr * ff),
                }
            })?;
            pf_phase(PF_PH_FFN_DOWN);
            crate::prof::time_layer(crate::prof::DOWN, li, || -> Option<()> {
                chain_gemm_q4_pf(gw3, pact, pdown, mr, ff, e)
            })?;
            // 5) down のタイルだけ D2H (呼び出し元バッファへ直接)。
            //    Slot 出力では CH_DOWN に残したまま次段 (rmsnorm の add) に渡す。
            if let Some(dstp) = dst {
                let lib = lib().ok()?;
                unsafe {
                    ok(check(
                        (lib.memcpy_dtoh_async)(
                            dstp as *mut c_void,
                            pdown,
                            mr * e * 4,
                            std::ptr::null_mut(),
                        ),
                        "cuMemcpyDtoHAsync (mlp prefill q4)",
                    ))?
                }
                crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
                ok(ctx.sync())?;
            }
            Some(())
        })?;
        r0 += mr;
    }
    Some(())
}

/// [`chain_mlp_prefill_q4`] の 1 タイル分 GEMM (per-op 経路と同一カーネル・
/// 同一グリッド・同一引数)。a/out はデバイスポインタ。
fn chain_gemm_q4_pf(
    gw: &GpuWq4,
    a: u64,
    out: u64,
    m: usize,
    k: usize,
    n: usize,
) -> Option<()> {
    let ctx = chain_ctx()?;
    unsafe {
        let (mut pa, mut pn, mut ps, mut po) = (a, gw.nib.ptr(), gw.sc.ptr(), out);
        let (mut mc, mut kc, mut nc) = (m as c_int, k as c_int, n as c_int);
        let mut args = [
            &mut pa as *mut _ as *mut c_void,
            &mut pn as *mut _ as *mut c_void,
            &mut ps as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut mc as *mut _ as *mut c_void,
            &mut kc as *mut _ as *mut c_void,
            &mut nc as *mut _ as *mut c_void,
        ];
        let grid = (m.div_ceil(64) as u32, n.div_ceil(128) as u32, 1);
        ok(ctx.launch_async(ctx.f_gemm_q4, grid, (16, 8, 1), 0, &mut args))
    }
}

/// gate / up が別バッファにある swiglu (`dno_swiglu`)。
fn chain_swiglu_split(gate: u64, up: u64, out: u64, total: usize) -> Option<()> {
    let ctx = chain_ctx()?;
    unsafe {
        let (mut pg, mut pu, mut po) = (gate, up, out);
        let mut tc = total as c_int;
        let mut args = [
            &mut pg as *mut _ as *mut c_void,
            &mut pu as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut tc as *mut _ as *mut c_void,
        ];
        let grid = (total as u64).div_ceil(256) as u32;
        ok(ctx.launch_async(ctx.f_swiglu, (grid, 1, 1), (256, 1, 1), 0, &mut args))
    }
}

/// s173 (P14): 行内 [gate|up] レイアウト (`width = 2*ff`) の swiglu を生ポインタで
/// 起動する (`dno_swiglu_int`)。[`chain_swiglu_rows`] のスロット版と同じカーネル・
/// 同じ引数で、CHAIN を借りている最中 (タイルループ内) から呼べるようにしたもの。
/// 演算列は `dno_swiglu` と同一 (`dno_expf` + `__fdiv_rn` + `__fadd_rn` +
/// `__fmul_rn`) なので、CPU の `silu(g)*u` とビット一致。
fn chain_swiglu_int_at(ga: u64, out: u64, ff: usize, total: usize) -> Option<()> {
    let ctx = chain_ctx()?;
    if ff == 0 || total == 0 {
        return None;
    }
    unsafe {
        let (mut pg, mut po) = (ga, out);
        let mut ffc = ff as c_int;
        let mut width = (2 * ff) as c_int;
        let mut tc = total as i64;
        let mut args = [
            &mut pg as *mut _ as *mut c_void,
            &mut po as *mut _ as *mut c_void,
            &mut ffc as *mut _ as *mut c_void,
            &mut width as *mut _ as *mut c_void,
            &mut tc as *mut _ as *mut c_void,
        ];
        let grid = (total as u64).div_ceil(256) as u32;
        ok(ctx.launch_async(ctx.f_swiglu_int, (grid, 1, 1), (256, 1, 1), 0, &mut args))
    }
}

/// s70: prefill の FFN (rmsnorm 済み x → gate/up → swiglu → down → ホスト) を
/// デバイス常駐で通す。活性化の往復が
///   旧: H2D 47MB + D2H 140MB + H2D 47MB + D2H 47MB
///   新: H2D 47MB + D2H 47MB
/// になる (m=2843, e=4096, ff=6144 の場合)。GEMM/swiglu は CPU 経路と
/// ビット一致 (同一カーネル・同一整数累積・同一 f32 演算列)。
///
/// s80 (T7b-1): 引数の gate/up を 1 本の連結重み (`gate_up_w`, 行順
/// [gate 全行 | up 全行]) にまとめた。dno_gemm_i8 は行ごとに独立で
/// n を 256 列タイルで舐めるだけなので、1 呼び出しでも n が 2ff になるだけで
/// 各出力は 2 回呼び出しと同一 (スケールは行ごと・パート境界 = ff)。
pub fn chain_mlp_prefill(
    gate_up_w: &crate::quant::Quant8Linear,
    down_w: &crate::quant::Quant8Linear,
    x: &[f32],
    m: usize,
    li: usize,
    out: &mut [f32],
) -> Option<()> {
    if !cuda_enabled() || !gemm_enabled() || m < gemm_min_m() || GPU_BROKEN.load(std::sync::atomic::Ordering::Relaxed) {
        return None;
    }
    let e = down_w.n;
    // s80 (T7b-1): gate_up はロード時に連結済みの 1 本 (行順 [gate | up])。
    // ff は連結幅の半分 = パートの境界。
    if gate_up_w.n % 2 != 0 || gate_up_w.k != e {
        return None;
    }
    let ff = gate_up_w.n / 2;
    if m == 0 || x.len() < m * e || out.len() < m * e || down_w.k != ff {
        return None;
    }
    let ctx = chain_ctx()?;
    let _ = li;
    // 1) rmsnorm 済み x を H2D (pinned staging を挟まず直接)
    ok(chain_ensure_buf(CH_PFH, m.checked_mul(e)?.checked_mul(4)?))?;
    CHAIN.with(|cell| -> Option<()> {
        let buf = cell.borrow().bufs[CH_PFH].as_ref()?.ptr();
        let lib = lib().ok()?;
        unsafe {
            ok(check(
                (lib.memcpy_htod_async)(
                    buf,
                    x.as_ptr() as *const c_void,
                    m * e * 4,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyHtoDAsync (mlp prefill)",
            ))
        }
    })?;
    // 2) gate/up → 3) swiglu  → 4) down (全て非同期・最後に 1 回だけ同期)
    // 計測時のみ段ごとに同期して内訳を取る (同期は数値に影響しない)。
    crate::prof::time_layer(crate::prof::GATE_UP, li, || -> Option<()> {
        chain_gemm_grouped_pf(&[gate_up_w], CH_PFH, CH_GA, m)?;
        if crate::prof::enabled() {
            ok(ctx.sync())?;
        }
        Some(())
    })?;
    crate::prof::time_layer(crate::prof::SWIGLU, li, || -> Option<()> {
        chain_swiglu_rows(CH_GA, CH_ACT, ff, m)?;
        if crate::prof::enabled() {
            ok(ctx.sync())?;
        }
        Some(())
    })?;
    crate::prof::time_layer(crate::prof::DOWN, li, || -> Option<()> {
        chain_gemm_grouped_pf(&[down_w], CH_ACT, CH_DOWN, m)
    })?;
    // 5) D2H は呼び出し元のバッファへ直接
    CHAIN.with(|cell| -> Option<()> {
        let buf = cell.borrow().bufs[CH_DOWN].as_ref()?.ptr();
        let lib = lib().ok()?;
        unsafe {
            ok(check(
                (lib.memcpy_dtoh_async)(
                    out.as_mut_ptr() as *mut c_void,
                    buf,
                    m * e * 4,
                    std::ptr::null_mut(),
                ),
                "cuMemcpyDtoHAsync (mlp prefill)",
            ))
        }
    })?;
    crate::prof::mark_d2h_src(crate::prof::D2H_SRC_LINEAR);
    ok(ctx.sync())?;
    Some(())
}

// ---------------------------------------------------------------------------
// P17g: GPU KV ミラー + decode attention (exactness 緩和・ユーザー承認)。
//
// ホスト KvCache は CPU 経路・snapshot/prefix cache の正として残し、decode
// chain で使う K/V のコピーをデバイス側に保持する (per-session ミラー)。
// ミラーはホストキャッシュの行 [0..len) と常に同一内容に保たれる
// (不足行は次回の chain_attention で一括 H2D)。ミラー破損/ロールバック/
// エビクト時も len 比較で自動再シードされるため、ホストが正・ミラーは従。
// メモリ上限 `DENNO_GPU_KV_MB` (既定 2048MB — P58-1 で 8192 から引き下げ。
// 27B 本番で既定のままだとミラーが約 1 GB 常駐し VRAM 枯渇を起こした) を超えると
// LRU でエビクト (必要時に再シード)。実使用量は起動時と各リクエスト完了時に
// `gpu kv mirror: N entries, X MB / limit Y MB` として info ログに出る。
//
// 注意: attention のみ exactness 契約が緩和されている (CPU と GPU で累積順が
// 異なり出力ビットは一致しない)。線形層 (int8) / expf / swiglu / rmsnorm は
// 従来どおりビット一致。`DENNO_GPU_ATTN=0` で無効化 (CPU attention・
// ビット一致経路に戻る)。

/// GPU attention の有効フラグ (既定 ON・`DENNO_GPU_ATTN=0` で無効)。
/// テストから差し替え可能にするため AtomicBool。
static GPU_ATTN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(true);
static GPU_ATTN_INIT: std::sync::OnceLock<()> = std::sync::OnceLock::new();

/// GPU attention が有効か (既定 ON・`DENNO_GPU_ATTN=0` で無効 — P17h から
/// forward_decode_gpu (solo chain) からも参照するため pub)
pub fn gpu_attention_enabled() -> bool {
    GPU_ATTN_INIT.get_or_init(|| {
        if std::env::var("DENNO_GPU_ATTN").ok().as_deref() == Some("0") {
            GPU_ATTN.store(false, std::sync::atomic::Ordering::Relaxed);
        }
    });
    GPU_ATTN.load(std::sync::atomic::Ordering::Relaxed)
}

/// テスト用: GPU attention の ON/OFF を直接差し替える (戻り値は設定前の値)
#[doc(hidden)]
pub fn set_gpu_attention_enabled(on: bool) -> bool {
    GPU_ATTN_INIT.get_or_init(|| {});
    GPU_ATTN.swap(on, std::sync::atomic::Ordering::Relaxed)
}

struct KvMirror {
    /// (k, v) デバイスバッファ per layer。各 [cap, kv_dim] f32
    layers: Vec<(Option<DevBuffer>, Option<DevBuffer>)>,
    cap: usize,
    /// layer ごとにミラー済みの行数 (ホスト cache.len() との差分を H2D する)
    len: Vec<usize>,
    /// ミラー行が同期しているホスト KV コンテンツの世代 (s41)。
    /// KvCache::epoch() と一致するときだけ行 [0..len) / GDN 状態を再利用してよい。
    /// 不一致 (同一スロットで reset/restore → 別会話で再 prefill) なら with_mirror_ext
    /// が全層の len と gdn_pos を無効化する (s35 の 2b 2 値分岐の修正)。
    epoch: u64,
    /// C4 (qwen35): GDN 状態ミラー。GDN 層のみ Some (full attention 層は None)。
    /// 状態サイズはコンテキスト長に依存しないため cap 成長の影響を受けない。
    gdn: Vec<Option<GdnDev>>,
    /// GDN ミラーが同期している位置 (層ごと・cache.len() 相当)。Some(pos0) なら
    /// seed 不要。層ごとに持つ (層ごとの seed 判定を独立させる — 1 層でも
    /// gdn_pos を共有すると残り層が全て再 seed になってしまう)。
    gdn_pos: Vec<Option<usize>>,
    /// s50: 遅延 GDN 状態フラッシュの pending。decode chain は GDN の新状態
    /// (conv/ssm) をステップ毎にホストへ戻さず GPU ミラーを権威のままにする
    /// (ステップ毎 D2H が decode の支配項だったため)。Some(pos) = 最後に遅延した
    /// decode ステップの pos0+1 (正常完了後は cache.len() と一致)。Some の間は
    /// ホスト GDN 状態が古い可能性があり、chain_q35_gdn_flush_pending が
    /// 「ホスト状態が実際に必要になる時点」(prefill 開始前・CPU フォールバック時)
    /// でミラーから回復する。pending 保持中のミラーは LRU エビクト対象外
    /// (フラッシュ前にデータが失われると回復不能になるため)。
    gdn_pending: Option<usize>,
    /// s141b (Task B7c): 層ごとの「ホスト `KvCache::gdn` がデバイスより古い可能性が
    /// ある」フラグ。decode chain はステップ毎にホストへ戻さない (s50 から) ので、
    /// 一度でも scan を走らせた層はここが真になる。真の層はホストを seed に使っては
    /// ならない = `chain_q35_gdn_scan` の seed はデバイス正本から D2D で取る。
    /// ホストを読む側は `chain_q35_gdn_flush_pending` (= 本フラグのある層だけ D2H)
    /// か `KvCache::flush_gdn_device_state` を通ってから読むこと。
    /// ミラーに面 0 を書き直した層 (seed 直後) は偽に戻る。
    gdn_stale: Vec<bool>,
}

/// C4 (qwen35): GDN 状態 (conv + SSM) のデバイスミラー 1 層分。
/// dno_gdn_scan は in/out に別ポインタを要求する (nv > nk のとき複数ブロックが
/// 同一 conv チャネルを共有するため in==out エイリアスは不正) — ping-pong 2 面で
/// 「cur を読み、1-cur に書き、cur を交換」する。
struct GdnDev {
    conv: [Option<DevBuffer>; 2], // 各 [conv_dim, cs] f32
    ssm: [Option<DevBuffer>; 2],  // 各 [nv, dk, dv] f32
    cur: usize,
}

impl GdnDev {
    fn bytes(&self) -> usize {
        self.conv
            .iter()
            .chain(self.ssm.iter())
            .map(|b| b.as_ref().map(|b| b.bytes()).unwrap_or(0))
            .sum()
    }
}

impl KvMirror {
    fn bytes(&self) -> usize {
        self.layers
            .iter()
            .map(|(k, v)| {
                k.as_ref().map(|b| b.bytes()).unwrap_or(0)
                    + v.as_ref().map(|b| b.bytes()).unwrap_or(0)
            })
            .sum::<usize>()
            + self.gdn.iter().flatten().map(|g| g.bytes()).sum::<usize>()
    }
}

static KV_MIRRORS: std::sync::OnceLock<std::sync::Mutex<Vec<(u64, KvMirror, std::time::Instant)>>> =
    std::sync::OnceLock::new();

/// GPU KV ミラーの上限 (MiB) の既定値。P58-1: 8192 → 2048。
///
/// 実測 (27B Q4_0・本番 serve): 既定 8192 MiB のままだとミラーが約 1 GB を常駐し、
/// 18,670 token のリクエスト後に VRAM が 30,932 MiB まで達して `cuMemAlloc` 失敗
/// (要求 779 MiB / 空き 315 MiB) → CPU フォールバック → サーバ固着を 3 回起こした。
/// `DENNO_GPU_KV_MB=1024` に下げるだけで 29,918 MiB に収まった (1,014 MB 減)。
/// ミラーは KV の複製 (ホストが正) なので、上限を下げて evict が増えても出力は
/// 変わらない — evict されたミラーは次の使用時にホストから再シードされる。
const DEFAULT_GPU_KV_LIMIT_MB: usize = 2048;

/// `DENNO_GPU_KV_MB` の解釈 (純関数。env を読まないのでテストから直接叩ける)。
/// 未設定・不正値は [`DEFAULT_GPU_KV_LIMIT_MB`]。
fn gpu_kv_limit_bytes_from(v: Option<usize>) -> usize {
    v.unwrap_or(DEFAULT_GPU_KV_LIMIT_MB) * 1024 * 1024
}

fn gpu_kv_limit_bytes() -> usize {
    gpu_kv_limit_bytes_from(
        std::env::var("DENNO_GPU_KV_MB")
            .ok()
            .and_then(|v| v.parse::<usize>().ok()),
    )
}

/// P58-1: ミラー 1 本のエビクト判定用メタデータ (ホスト側の値だけ)。
/// 実バッファを持たないので、LRU の判定と上限の効き方は GPU 無しでテストできる。
#[derive(Debug, Clone, Copy)]
struct MirrorMeta {
    key: u64,
    bytes: usize,
    last: std::time::Instant,
    /// GDN 遅延フラッシュ pending (エビクト禁止 — 未フラッシュの状態が唯一のコピー)
    pending: bool,
}

/// 上限超過分を LRU で落とし、落とした key を古い順に返す (純関数)。
///
/// 契約:
/// - 自分 (`keep_key`) は落とさない (これから使うミラー)。
/// - `pending` のミラーは落とさない (ホストより新しい GDN 状態の唯一のコピー)。
/// - 落とせる相手が無ければ止まる (上限超過のまま続くが、データは失わない)。
/// - ミラーは KV の複製なので、ここで落としても出力は変わらない (再シード)。
fn lru_evict_keys(entries: &mut Vec<MirrorMeta>, limit: usize, keep_key: u64) -> Vec<u64> {
    let mut evicted = Vec::new();
    let mut total: usize = entries.iter().map(|e| e.bytes).sum();
    while total > limit && entries.len() > 1 {
        let vic = entries
            .iter()
            .enumerate()
            .filter(|(_, e)| e.key != keep_key && !e.pending)
            .min_by_key(|(_, e)| e.last)
            .map(|(i, _)| i);
        let Some(vic) = vic else {
            break;
        };
        total -= entries[vic].bytes;
        evicted.push(entries.swap_remove(vic).key);
    }
    evicted
}

/// P58-1: ミラーの実使用量 (エントリ数, 合計バイト数, 上限バイト数)。
/// 合計は [`KvMirror::bytes`] (K/V の実バッファ + GDN 状態) の和。
/// 診断用なのでロックが取れない場合は None (呼び出し側を止めない)。
pub fn gpu_kv_mirror_stats() -> Option<(usize, usize, usize)> {
    let mirrors = KV_MIRRORS.get_or_init(|| std::sync::Mutex::new(Vec::new()));
    let ms = mirrors.lock().ok()?;
    let used = ms.iter().map(|(_, m, _)| m.bytes()).sum();
    Some((ms.len(), used, gpu_kv_limit_bytes()))
}

/// P58-1: ミラー使用量を 1 行ログる (起動時・各リクエスト完了時)。
/// MB は切り上げ (使用量が 0 でないのに 0 MB と出るのを避ける)。
pub fn log_gpu_kv_mirror_usage() {
    if let Some((entries, used, limit)) = gpu_kv_mirror_stats() {
        const MB: usize = 1024 * 1024;
        tracing::info!(
            "gpu kv mirror: {} entries, {} MB / limit {} MB",
            entries,
            used.div_ceil(MB),
            limit / MB
        );
    }
}

fn kv_mirror_cap(t_total: usize, old_cap: usize) -> usize {
    // s128 (P4-7): 1,024 行刻みで切り上げる。以前は next_power_of_two だったため
    // 10,880 token で 16,384 行 (= 必要量の 1.51 倍) を確保していた。
    // cap 成長は全層の再シードを伴うので、刻みは 1,024 行 (27B で 134 MB) に固定し、
    // 必要量を超えるときは一気に必要量まで上げる (リクエスト内で再成長しない)。
    let need = t_total.div_ceil(1024) * 1024;
    need.max(old_cap + 1024).max(1024)
}

/// P17g/P17h 共通: KV ミラーの取得/生成 + cap 成長 + LRU エビクト。
/// `f` はミラーロック保持中に呼ばれ (行同期 + ポインタ抽出を行う)、
/// `have` はミラーが持っている行数 (rollback で t_total を超えていれば 0)。
/// 呼び出し側が m.len[li] を確定させる (t_total を正として使う — cache.advance
/// は forward の最後なので host len はまだ進んでいない)。
fn with_mirror<T>(
    key: u64,
    li: usize,
    n_layers: usize,
    t_total: usize,
    kv_dim: usize,
    epoch: u64,
    f: impl FnOnce(&mut KvMirror, usize) -> Option<T>,
) -> Option<T> {
    with_mirror_ext(key, li, n_layers, t_total, kv_dim, epoch, true, f)
}

/// C4: with_mirror の拡張版。`alloc_kv = false` で KV cap 成長をスキップする
/// (qwen35 の GDN 層は KV を使わないため、GDN 層の呼び出しで全層分の KV ミラー
/// バッファを確保しない — 27B では数 GB 規模の無駄を避ける)。GDN 層は
/// m.layers[li] / m.len[li] を触らず gdn/gdn_pos のみを使う。
fn with_mirror_ext<T>(
    key: u64,
    li: usize,
    n_layers: usize,
    t_total: usize,
    kv_dim: usize,
    epoch: u64,
    alloc_kv: bool,
    f: impl FnOnce(&mut KvMirror, usize) -> Option<T>,
) -> Option<T> {
    let mirrors = KV_MIRRORS.get_or_init(|| std::sync::Mutex::new(Vec::new()));
    let mut ms = ok(mirrors.lock().map_err(|e| anyhow::anyhow!("{e}")))?;
    let now = std::time::Instant::now();
    match ms.iter().position(|(k, _, _)| *k == key) {
        Some(i) => {
            ms[i].2 = now;
        }
        None => {
            ms.push((
                key,
                KvMirror {
                    layers: (0..n_layers).map(|_| (None, None)).collect(),
                    cap: 0,
                    len: vec![0; n_layers],
                    epoch,
                    gdn: (0..n_layers).map(|_| None).collect(),
                    gdn_pos: vec![None; n_layers],
                    gdn_pending: None,
                    gdn_stale: vec![false; n_layers],
                },
                now,
            ));
        }
    };
    // エビクト: 上限超過で LRU (自分は除外)。s50: GDN 遅延フラッシュ pending 中の
    // ミラーは除外 — エビクトすると未フラッシュの GDN 状態 (ホストより新しい唯一の
    // コピー) が失われ回復不能になる。pending は次の prefill / CPU フォールバックの
    // 冒頭でフラッシュして解除されるため、上限超過は高々 1 リクエスト分の遅延。
    // P58-1: 判定は純関数 `lru_evict_keys` に切り出した (ホスト側のメタデータだけで
    // LRU と上限の効き方をテストできる)。ここでは落とす key を ms から除去するだけ。
    let mut meta: Vec<MirrorMeta> = ms
        .iter()
        .map(|(k, m, t)| MirrorMeta {
            key: *k,
            bytes: m.bytes(),
            last: *t,
            pending: m.gdn_pending.is_some(),
        })
        .collect();
    let evicted = lru_evict_keys(&mut meta, gpu_kv_limit_bytes(), key);
    if !evicted.is_empty() {
        ms.retain(|(k, _, _)| !evicted.contains(k));
    }
    // 除去で添字が動くので引き直す (自分はエビクト対象外なので必ず見つかる)。
    let idx = ms.iter().position(|(k, _, _)| *k == key)?;
    let m = &mut ms[idx].1;
    if li >= m.layers.len() {
        return None; // n_layers 不一致 (起こらないはず)
    }
    // s41: コンテンツ世代の検証。同一 kv_id (スロット) でホスト cache が reset /
    // restore され別会話の KV で再 prefill された場合、ミラーの行 [0..len) と
    // GDN 状態は前会話のものなので全層無効化する (次回の層呼び出しで全行再 seed)。
    // 旧実装は「len > t_total なら rollback」という収縮検出のみで、同一スロットに
    // 短い会話の後に長い別会話が来ると 0 < len ≤ t_total の古い行を正規行として
    // 使ってしまい (fresh 初回は len=0 で必ず再 seed・同長以上の次会話は rollback
    // ガードで再 seed)、短→長の切替直後の 1 リクエストだけ出力が変わる 2 値分岐
    // を生んでいた。
    if m.epoch != epoch {
        m.len.iter_mut().for_each(|l| *l = 0);
        m.gdn_pos.iter_mut().for_each(|p| *p = None);
        // s141b: 行/位置を捨てるのと同じく、ホスト遅延フラグも落とす (次の seed は
        // 位置不一致で必ず走り、そこで改めて判定し直す)。
        m.gdn_stale.iter_mut().for_each(|s| *s = false);
        // s50: 世代が変わった = ホストが reset/restore で正に戻っている。遅延
        // pending は前会話のデータを指すため破棄 (chain_q35_gdn_flush_pending が
        // no-op になり、ホスト状態をそのまま使う)。
        m.gdn_pending = None;
        m.epoch = epoch;
    }
    // cap 成長 (全レイヤ realloc + len リセット → 各レイヤ次回使用時に再シード)。
    // alloc_kv = false (GDN 専用呼び出し) ではスキップ — cap/len は使わない。
    if alloc_kv && m.cap < t_total {
        let newcap = kv_mirror_cap(t_total, m.cap);
        // s128 (P4-7): ここで全層分を確保しない。以前は 1 層の prefill で
        // n_layers 本ずつ確保しており、27B では KV を書かない GDN 層 48 本 x K/V
        // まで常駐していた (10,880 token で 8.1 GB)。
        // cap が伸びた時点で既存バッファの行内容は捨てる (Scratch::ensure は
        // 新しいバッファを確保する) ため len は全層 0 に戻し、各層のバッファは
        // その層を使うときに下の ensure で確保する。
        m.cap = newcap;
        m.len.iter_mut().for_each(|l| *l = 0);
    }
    if alloc_kv {
        // 使う層の分だけ確保する (grow-only・容量は cap 行で固定)
        let bytes = m.cap * kv_dim * 4;
        let before = m.layers[li].0.as_ref().map(|b| b.bytes()).unwrap_or(0);
        ok(Scratch::ensure_tagged(
            &mut m.layers[li].0,
            bytes,
            crate::mem_audit::TAG_KV_MIRROR,
        ))?;
        ok(Scratch::ensure_tagged(
            &mut m.layers[li].1,
            bytes,
            crate::mem_audit::TAG_KV_MIRROR,
        ))?;
        if before < bytes {
            // バッファを伸ばした = 行内容は失われた (ensure は新規確保) → 全再シード
            m.len[li] = 0;
        }
    }
    let have = if m.len[li] > t_total { 0 } else { m.len[li] };
    f(m, have)
}

/// decode chain 用 GPU attention。q (CPU 側で rope 済み [heads*dh]) と
/// ホスト KvCache (現在レイヤの行は呼び出し側が書き込み済み) を受け取り、
/// ミラーを同期して attention カーネルを起動し、結果を CH_ATT に書く。
/// 戻り None = CPU attention にフォールバック (forward 全体を従来経路で再実行)。
#[allow(clippy::too_many_arguments)]
pub fn chain_attention(
    key: u64,
    li: usize,
    n_layers: usize,
    q: &[f32],
    cache: &crate::kv_cache::KvCache,
    t_total: usize,
    group: usize,
    dh: usize,
    kv_dim: usize,
    scale: f32,
) -> Option<()> {
    if !gpu_attention_enabled() {
        return None;
    }
    let ctx = chain_ctx()?;
    let heads = q.len() / dh;
    if heads == 0 || group == 0 || dh == 0 || dh > 1024 || t_total == 0 || t_total > cache.max_len()
    {
        return None;
    }
    let mut kv_dim_c = kv_dim as c_int;
    let mut t_c = t_total as c_int;
    let mut group_c = group as c_int;
    let mut dh_c = dh as c_int;

    // CH_ATT は後続の o_proj 入力そのもの (chain_upload を省略)
    ok(chain_ensure_buf(CH_ATT, heads * dh * 4))?;

    // ミラーの取得/生成 + レイヤ li の行同期。ポインタはロック解放前に抽出する。
    let (mut kptr, mut vptr) =
        with_mirror(key, li, n_layers, t_total, kv_dim, cache.epoch(), |m, have| {
        // 行同期: ミラーが持っている [0..have) とホストの [0..t_total) を突き合わせ。
        // ホストの行 pos0 は呼び出し側が既に書き込み済み。
        // ロールバック (restore/reset) で have > t_total になったら全再シード (have=0)。
        let (kc_ref, vc_ref) = cache.kv_bufs_ref(li);
        if have < t_total {
            let kb = m.layers[li].0.as_ref().unwrap();
            let vb = m.layers[li].1.as_ref().unwrap();
            ok(kb.copy_from_at(have * kv_dim * 4, &kc_ref[have * kv_dim..t_total * kv_dim]))?;
            ok(vb.copy_from_at(have * kv_dim * 4, &vc_ref[have * kv_dim..t_total * kv_dim]))?;
        }
        m.len[li] = t_total;
        Some((
            m.layers[li].0.as_ref().unwrap().ptr(),
            m.layers[li].1.as_ref().unwrap().ptr(),
        ))
    })?;

    // q / scores スクラッチ (スレッドローカル — chain は 1 スレッド 1 セッション)
    CHAIN.with(|cell| -> Option<()> {
        let mut s = cell.borrow_mut();
        ok(Scratch::ensure_tagged(
            &mut s.attn_q,
            q.len() * 4,
            crate::mem_audit::TAG_CHAIN,
        ))?;
        ok(Scratch::ensure_tagged(
            &mut s.attn_sc,
            heads * t_total * 4,
            crate::mem_audit::TAG_CHAIN,
        ))?;
        ok(s.attn_q.as_ref().unwrap().copy_from(q))?;
        let mut qptr = s.attn_q.as_ref().unwrap().ptr();
        let mut scptr = s.attn_sc.as_ref().unwrap().ptr();
        let mut aptr = s.bufs[CH_ATT].as_ref().unwrap().ptr();
        let mut scale_c = scale;
        let mut args: Vec<*mut c_void> = vec![
            &mut qptr as *mut _ as *mut c_void,
            &mut kptr as *mut _ as *mut c_void,
            &mut vptr as *mut _ as *mut c_void,
            &mut aptr as *mut _ as *mut c_void,
            &mut scptr as *mut _ as *mut c_void,
            &mut kv_dim_c as *mut _ as *mut c_void,
            &mut t_c as *mut _ as *mut c_void,
            &mut group_c as *mut _ as *mut c_void,
            &mut dh_c as *mut _ as *mut c_void,
            &mut scale_c as *mut _ as *mut c_void,
        ];
        ok(unsafe {
            ctx.launch_async(
                ctx.f_attn,
                (heads as u32, 1, 1),
                (dh as u32, 1, 1),
                (dh * 4) as u32,
                &mut args,
            )
        })
    })
}

// ---------------------------------------------------------------------------
// task 133: qwen4exp (Flash-Next) の full attention (decode) を GPU で回す
//
// 設計:
// - ホストの `AttnCache` が正。GPU 側は層ごとの K/V 行の複製 (ミラー) を持つ。
// - CPU prefill の間はミラーを触らない。**最初の decode トークン**で層ごとに
//   履歴 `[0..len)` を 1 回だけ H2D する (遅延シード)。以降は 1 トークン 1 行。
// - ミラーは `AttnCache::id()` で引き、層ごとの内容世代 `gen` が変わった層だけ
//   全行 H2D し直す。`AttnCache` は `clear` / `clear_all` / `truncate_layer` で
//   gen を進めるので、prefix reuse / model reuse (`reset`) / spec rollback の
//   どれでも古い行を attention に使わない。
// - cap は 1,024 行単位の倍々。成長時は旧バッファから D2D で行を温存する
//   (再シードしない)。65,536 行 x 512 x 4 B x 2 (K/V) x 12 層 = 3,072 MiB。
// - カーネルは既存の `dno_attention` (kernels_elem.cu)。.cu / .ptx は触らない。
// - GPU が無い・カーネルの制約に合わない・確保/転送/起動に失敗したときは
//   `None` を返し、呼び出し側は CPU 経路へ落ちる (fail closed)。ここで
//   `GPU_BROKEN` は立てない — attention だけの問題で他の GPU 経路
//   (GEMV / mix / router / expert) を巻き込まない。
//
// 実測 (lab t133b, swift15-abl IQ3_S, PROFILE=1, off -> on):
//   decode ms/tok: a/b 81 -> 80、c2000_cold 122 -> 96、c2000_turn2 124 -> 95、
//   c8000_cold 210 -> 121、c8000_turn2 208 -> 121 (prefill は ±1.8% 以内)。
//   6 プロンプトの出力 md5 は off と同一。1 層 1 呼び出しの内訳は
//   28 tok で 84 us、3,954 で 637 us、14,018 で 2.09 ms
//   (14k はカーネル待ち 2.03 ms が支配的。1 head = 1 block で占有率が低い)。
// ---------------------------------------------------------------------------

/// `DENNO_Q4_GPU_ATTN` の既定。lab t133b (最終コード) で a/b 81 -> 80、
/// c2000 122/124 -> 96/95、c8000 210/208 -> 121/121、md5 は 6 本とも同一。
/// 短いプロンプトは MIN で CPU のままなので既定 on。
const Q4_GPU_ATTN_DEFAULT: bool = true;
/// `DENNO_Q4_GPU_ATTN_MIN` の既定 (この KV 本数未満は CPU 経路のまま)。
/// 実測の交叉は約 23 token (推定: 1 呼び出しの固定費 79 us x 12 → 0.95 ms/token と
/// 短 context の CPU scan 1.04 ms/token が 28 token 付近で並ぶ)。
/// 短いプロンプト (lab の a/b = 28/33) を確実に CPU のままにするため 64 にする。
const Q4_GPU_ATTN_MIN_DEFAULT: usize = 64;
/// ミラー上限の既定 (MiB)。65,536 行をフルに使って 3,072 MiB。
const Q4_GPU_ATTN_MIRROR_MB_DEFAULT: usize = 3584;

/// task 134: `DENNO_Q4_GPU_ATTN_PF` の既定 (prefill の full attention を GPU へ)。
///
/// lab t134a (SCENARIO=depth) で c2000 cold prefill 134.83 -> 110.59 s (-18.0%)、
/// c2000 turn2 +0.7%、短いプロンプト 0.0%、decode -1.2%、md5 は 4 本とも同一。
/// lab t134b (SCENARIO=depth8k) で c2000 cold -18.1%、c8000 cold
/// 758.94 -> 379.20 s (-50.0%)、c8000 turn2 2.53 -> 2.53 s (+0.0%)、decode 不変、
/// errors 0、text sane。md5 は c8000 の 2 本だけ DIFF (GPU attention の丸め順で
/// greedy が動いた。c2000 と短文は同一)。目標 (c2000 15% / c8000 35%) を
/// 満たしたので既定 on。
const Q4_GPU_ATTN_PF_DEFAULT: bool = true;
/// task 135: attention 自身の構造上の下限 (1 チャンクの行数)。
///
/// 従来は `attn_prefill_gpu_supported` が `gemm_min_m()` (既定 256) を借りて
/// いたため、next turn の 19 行チャンクや長い prefill の尾チャンク (194 / 242 行)
/// が CPU に落ちていた。GEMM の 256 は「CPU sgemm の方が速い帯域」の話で、
/// attention のカーネル制約ではない (制約は dh >= ATTN_PF_BQ と smem だけ)。
///
/// lab t135a / t135b (depth, depth8k) の実測: 8 行で next turn prefill が
/// c2000 1.41 -> 1.03 s、c8000 2.53 -> 1.10 s (19 行・14k 文脈で 1 層 127 ms ->
/// 10 ms)、cold prefill も尾チャンクが乗って -3.3% / -3.9%。decode と短い
/// プロンプトはノイズ内 (±2%)、md5 は 6 本とも同一。7 行以下は CPU に残す。
const ATTN_Q4_PF_MIN_ROWS: usize = 8;

/// `DENNO_Q4_GPU_ATTN_PF_MIN` の既定 = 1 チャンクの行数の下限。
///
/// task 135: カーネルの構造上の下限を `gemm_min_m()` (256) から attention 専用の
/// [`ATTN_Q4_PF_MIN_ROWS`] へ移した。qwen35 は従来の
/// `attn_prefill_gpu_supported` (n >= gemm_min_m()) のまま。
/// 実測は [`ATTN_Q4_PF_MIN_ROWS`] の doc と REPORT_P135.md。
const Q4_GPU_ATTN_PF_MIN_DEFAULT: usize = ATTN_Q4_PF_MIN_ROWS;
/// `DENNO_Q4_GPU_ATTN_PF_MIN_KV` の既定 = 文脈長 (t_total) の下限。
/// 短いプロンプト (数百 token) は CPU のままにする。
const Q4_GPU_ATTN_PF_MIN_KV_DEFAULT: usize = 512;

/// `DENNO_Q4_GPU_ATTN` の解釈 (純関数・env を読まない)。
fn parse_q4_gpu_attn(v: Option<&str>) -> bool {
    match v.map(str::trim) {
        Some("0") | Some("off") | Some("false") => false,
        Some("1") | Some("on") | Some("true") => true,
        _ => Q4_GPU_ATTN_DEFAULT,
    }
}

/// `DENNO_Q4_GPU_ATTN_MIN` の解釈 (純関数)。未設定・不正値は既定。
fn parse_q4_gpu_attn_min(v: Option<&str>) -> usize {
    v.and_then(|s| s.trim().parse::<usize>().ok())
        .unwrap_or(Q4_GPU_ATTN_MIN_DEFAULT)
}

/// `DENNO_Q4_ATTN_MIRROR_MB` の解釈 (純関数)。未設定・不正値は既定。
fn q4_attn_mirror_limit_from(v: Option<usize>) -> usize {
    v.unwrap_or(Q4_GPU_ATTN_MIRROR_MB_DEFAULT) * 1024 * 1024
}

fn q4_attn_mirror_limit_bytes() -> usize {
    q4_attn_mirror_limit_from(
        std::env::var("DENNO_Q4_ATTN_MIRROR_MB")
            .ok()
            .and_then(|v| v.trim().parse::<usize>().ok()),
    )
}

#[cfg(test)]
static Q4_ATTN_FORCE: std::sync::atomic::AtomicI8 = std::sync::atomic::AtomicI8::new(-1);
#[cfg(test)]
static Q4_ATTN_MIN_FORCE: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(usize::MAX);

/// テスト用: env を介さず q4 GPU attention の ON/OFF を差し替える
/// (`None` で env の解釈に戻す)。
#[cfg(test)]
#[doc(hidden)]
pub fn set_q4_gpu_attn_for_test(on: Option<bool>) {
    Q4_ATTN_FORCE.store(match on {
        Some(true) => 1,
        Some(false) => 0,
        None => -1,
    }, std::sync::atomic::Ordering::Relaxed);
}

/// テスト用: `DENNO_Q4_GPU_ATTN_MIN` を差し替える (`None` で env の解釈に戻す)。
#[cfg(test)]
#[doc(hidden)]
pub fn set_q4_gpu_attn_min_for_test(min: Option<usize>) {
    Q4_ATTN_MIN_FORCE.store(min.unwrap_or(usize::MAX), std::sync::atomic::Ordering::Relaxed);
}

/// q4 full attention の GPU 経路が有効か (`DENNO_Q4_GPU_ATTN`)。
///
/// `DENNO_GPU_ATTN=0` は [`gpu_attention_enabled`] 側で見る (両方 ON のときだけ
/// 発動する)。
fn q4_gpu_attn_enabled() -> bool {
    #[cfg(test)]
    {
        let f = Q4_ATTN_FORCE.load(std::sync::atomic::Ordering::Relaxed);
        if f >= 0 {
            return f == 1;
        }
    }
    static ON: OnceLock<bool> = OnceLock::new();
    *ON.get_or_init(|| parse_q4_gpu_attn(std::env::var("DENNO_Q4_GPU_ATTN").ok().as_deref()))
}

/// この KV 本数未満では CPU 経路のまま (`DENNO_Q4_GPU_ATTN_MIN`)。
